window.__D("text/zohar-hebrew-translation/c006",{"p":[[9522011270,"<p>שָׁנוּ רַבּוֹתֵינוּ, כָּל נִשְׁמָתָן שֶׁל צַדִּיקִים לְמַעְלָה, בְּעֵדֶן הֵן. וּמַה מִּמַּה שֶּׁיּוֹרֵד מֵעֵדֶן יִשְׂגֶּא הַחָכְמָה בָּעוֹלָם - לָעוֹמְדִים בּוֹ וְנֶהֱנִים מֵהֲנָאוֹתָיו וְכִסּוּפָיו עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>אָמַר רַבִּי יִצְחָק, כֵּיוָן שֶׁהַנְּשָׁמָה זוֹכָה לִכָּנֵס בְּשַׁעֲרֵי יְרוּשָׁלַיִם שֶׁל מַעְלָה, מִיכָאֵ\"ל הַשַּׂר הַגָּדוֹל הוֹלֵךְ עִמָּהּ וּמַקְדִּים לָהּ שָׁלוֹם. מַלְאֲכֵי הַשָּׁרֵת תְּמֵהִים בָּהּ וְשׁוֹאֲלִים עָלֶיהָ (שיר ג) מִי זֹאת עֹלָה מִן הַמִּדְבָּר. מִי זֹאת עֹלָה בֵּין הָעֶלְיוֹנָה מֵהַגּוּף הֶחָרֵב שֶׁדּוֹמֶה לְהֶבֶל, שֶׁכָּתוּב (תהלים קמד) אָדָם לַהֶבֶל דָּמָה. הוּא מֵשִׁיב וְאוֹמֵר, (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי. אַחַת הִיא - מְיֻחֶדֶת הִיא. אַחַת הִיא לְאִמָּהּ - לְאִמָּהּ זוֹ הִיא כִּסֵּא הַכָּבוֹד שֶׁהִיא אֵם לַנְּשָׁמָה וְיוֹלֶדֶת לָהּ, שֶׁנִּגְזְרָה מִמֶּנָּה.</p>\n<p>רָאוּהָ בָנוֹת וַיְאַשְּׁרוּהָ - אֵלּוּ שְׁאָר הַנְּשָׁמוֹת שֶׁהֵן בְּמַעֲלָתָן לְמַעְלָה, וְהֵם הַנִּקְרָאוֹת בְּנוֹת יְרוּשָׁלַיִם. אָמַר רַבִּי יוֹסֵי, הִנֵּה חָזַרְנוּ עַל מַה שֶּׁאָמַרְנוּ - אֵלּוּ נִקְרָאוֹת בְּנוֹת יְרוּשָׁלַיִם, וְהָאֲחֵרוֹת נִקְרָאוֹת בְּנוֹת לוֹט. רָאוּהָ בָנוֹת וַיְאַשְּׁרוּהָ - שְׁאָר הַנְּשָׁמוֹת מְשַׁבְּחוֹת לָהּ וְאוֹמְרוֹת שָׁלוֹם בּוֹאֵךְ. מְלָכוֹת וּפִילַגְשִׁים - מְלָכוֹת אֵלּוּ הָאָבוֹת שֶׁהֵם מְלָכוֹת, וּפִילַגְשִׁים הֵם גֵּרֵי הַצֶּדֶק. כֻּלָּם מְשַׁבְּחוֹת וּמְקַלְּסוֹת אוֹתָהּ עַד שֶׁנִּכְנֶסֶת לְמַעְלָה, וַאֲזַי הַנְּשָׁמָה בְּמַעֲלָתָהּ וּמִתְקַיֶּמֶת אֲרִיכוּת יָמִים. זֶהוּ שֶׁכָּתוּב וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים. נִכְנַס בַּאֲרִיכוּת יָמִים לָעוֹלָם הַבָּא.</p>\n<p>רַבִּי אַבָּא הַזָּקֵן קָם עַל רַגְלָיו וְאָמַר, מְנוּחָה וְשָׁלוֹם עֲצָמוֹת יִהְיוּ לְךְ, רַבִּי שִׁמְעוֹן, שֶׁהֶחֱזַרְתָּ עֲטָרָה לְיָשְׁנָהּ. שֶׁשָּׁנִינוּ בַּבָּרַיְתָא הָרִאשׁוֹנָה, שֶׁכֵּיוָן שֶׁהַנְּשָׁמָה הִיא בִּשְׁלֵמוּתָהּ בְּמָקוֹם עֶלְיוֹן (לזמן אחר נכנסים), לֹא שָׁבָה לַגּוּף, אֶלָּא נִבְרָאוֹת מִמֶּנָּה נְשָׁמוֹת אֲחֵרוֹת שֶׁיּוֹצְאוֹת מִמֶּנָּה, וְהִיא נִשְׁאֶרֶת בְּקִיּוּם, עַד שֶׁבָּא רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי וְדָרַשׁ, וּמָה אִם בָּעוֹלָם הַזֶּה שֶׁהוּא הֶבֶל, וְהַגּוּף שֶׁהוּא טִפָּה סְרוּחָה, נִכְנֶסֶת בּוֹ אוֹתָהּ הַנְּשָׁמָה - לֶעָתִיד לָבא שֶׁיִּצָּרְפוּ כֻלָּם וְיִהְיֶה הַגּוּף מֻבְחָר בְּקִיּוּם וְתַשְׁלוּם יוֹתֵר, אֵינוֹ דִין לְהִכָּנֵס אוֹתָהּ הַנְּשָׁמָה בּוֹ בְּכָל הַתַּשְׁלוּמִים וְהָעִלּוּיִים שֶׁבָּהּ?</p>\n<p>אָמַר רַבִּי אָחָא, אוֹתָהּ הַנְּשָׁמָה (בו בכל התשלומים והעלויים שבה) מַמָּשׁ, וְאוֹתוֹ הַגּוּף מַמָּשׁ עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲמִידָן בְּקִיּוּמָן לֶעָתִיד לָבא, אֲבָל שְׁנֵיהֶם יִהְיוּ שְׁלֵמִים בְּתַשְׁלוּם הַדַּעַת לְהַשִּׂיג מַה שֶּׁלֹּא הִשִּׂיגוּ בָּעוֹלָם הַזֶּה.</p>\n<p>וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים וְגוֹ'. רַבִּי בּוֹ אָמַר רַבִּי יוֹחָנָן, (באותם הימים) בְּאוֹתוֹ עוֹלָם שֶׁהוּא יָמִים, וְלֹא בָּעוֹלָם הַזֶּה שֶׁהוּא לַיְלָה. אָמַר רַבִּי יַעֲקֹב, בְּאוֹתָם הָעוֹלָמוֹת שֶׁהֵם יָמִים, בְּאוֹתָם הַהֲנָאוֹת וְהַכִּסּוּפִים שֶׁהוּא נוֹחֵל. וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. בְּאוֹתָהּ הַמִּשְׂרָה (נ\"א: המעשר) שֶׁנָּתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְּׁמוֹ, שֶׁהִיא אוֹת הֵ\"א, שֶׁבָּהּ נִבְרָא הָעוֹלָם.</p>\n<p>וְלָמַדְנוּ, אָמַר רַבִּי יוֹחָנָן, מטטרו\"ן שַׂר הַפְּנִים, שֶׁהוּא נַעַר עֶבֶד מֵרַבּוֹ הָאָדוֹן הַמּוֹשֵׁל עָלָיו, מְמֻנֶּה עַל הַנְּשָׁמָה בְּכָל יוֹם לְהַסְפִּיק לָהּ מֵאוֹתוֹ הָאוֹר שֶׁנִּצְטַוָּה, וְהוּא עָתִיד לָקַחַת חֶשְׁבּוֹן פֶּתֶק בְּבָתֵּי הַקְּבָרוֹת מִדּוּמָה, וּלְהַרְאוֹת אוֹתוֹ לִפְנֵי רַבּוֹ, וְהוּא עָתִיד לַעֲשׂוֹת שְׂאוֹר אוֹתוֹ הָעֶצֶם תַּחַת הָאָרֶץ, לְתַקֵּן אֶת הַגּוּפוֹת וּלְקַיְּמָם בִּשְׁלֵמוּת שֶׁל גּוּף בְּלִי הַנְּשָׁמָה, (בזמן) שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׁלַח אוֹתָהּ לִמְקוֹמָהּ.</p>\n<p>אָמַר רַבִּי יִצְחָק, בְּאוֹתָהּ שָׁעָה מַה כָּתוּב? וַיֹּאמֶר אַבְרָהָם אֶל עַבְדּוֹ זְקַן בֵּיתוֹ הַמּוֹשֵׁל וְגוֹ'. מַהוּ אֶל עַבְדּוֹ? אִם בַּחָכְמָה הַזּוֹ נִסְתַּכֵּל, מַה זֶּה אֶל עַבְדּוֹ? אָמַר רַבִּי נְהוֹרַאי, לֹא נִסְתַּכֵּל אֶלָּא בְּמַה שֶּׁאָמַר עַבְדּוֹ, עַבְדּוֹ שֶׁל מָקוֹם, (זקן ביתו) הַקָּרוֹב לַעֲבוֹדָתוֹ, וּמִי הוּא? זֶה מטטרו\"ן, כְּפִי שֶׁאָמַרְנוּ. שֶׁהוּא עָתִיד לְיַפּוֹת אֶת הַגּוּף בְּבָתֵּי הַקְּבָרוֹת.</p>\n<p>זְהִוּ שֶׁכָּתוּב וַיֹּאמֶר אַבְרָהָם אֶל עָבְדּוֹ, זֶה מטטרו\"ן עַבְדּוֹ שֶׁל מָקוֹם. זְקַן בֵּיתוֹ, שֶׁהוּא תְחִלַּת בְּרִיּוֹתָיו שֶׁל מָקוֹם. הַמֹּשֵׁל בְּכָל אֲשֶׁר לוֹ, שֶׁנָּתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מֶמְשָׁלָה עַל כָּל צִבְאוֹתָיו.</p>\n<p>וְלָמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן אָמַר רַבִּי יוֹסֵי אָמַר רַב, כָּל צִבְאוֹתָיו שֶׁל אוֹתוֹ עֶבֶד נוֹטְלִים אוֹר וְנֶהֱנִים מִזִּיו הַנְּשָׁמָה. שֶׁלָּמַדְנוּ, אוֹר הַנְּשָׁמָה לָעוֹלָם הַבָּא גָּדוֹל מֵאוֹר הַכִּסֵּא. וַהֲרֵי מֵהַכִּסֵּא נִטְּלָה הַנְּשָׁמָה? אֶלָּא זֶה לְפִי הָרָאוּי לוֹ, וְזֶה לְפִי הָרָאוּי לוֹ. רַב נַחְמָן אָמַר, גָּדוֹל מֵאוֹר הַכִּסֵּא מַמָּשׁ, שֶׁכָּתוּב (יחזקאל א) דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. מַה זֶּה עָלָיו? עַל זָהֳרוֹ.</p>\n<p>וּכְשֶׁהוּא הוֹלֵךְ לַעֲשׂוֹת שְׁלִיחוּתוֹ, כָּל צִבְאוֹתָיו וְהַמֶּרְכָּבָה שֶׁלּוֹ נִזּוֹנִים מֵאוֹתוֹ הַזֹּהַר. זֶהוּ שֶׁהַנְּשָׁמָה אוֹמֶרֶת לוֹ, (שכתוב) שִׂים נָא יָדְךְ, כְּלוֹמַר סִיעָתְךְ. תַּחַת יְרֵכִי - זֶהוּ אוֹר הַנִּשְׁפָּע מִן הַנְּשָׁמָה עֲלֵיהֶם.</p>\n<p>אָמַר רַבִּי יְהוּדָה בְּרַבִּי שָׁלוֹם, כָּךְ קִבַּלְנוּ, בְּשָׁעָה שֶׁזֶּה הוֹלֵךְ בִּשְׁלִיחוּתוֹ שֶׁל מָקוֹם, הַקָּדוֹשׁ בָּרוּךְ הוּא מֵנִיעַ כָּל צִבְאוֹתָיו שֶׁל מַעְלָה בְּאוֹת אַחַת מִשְּׁמוֹ. אָמַר רַב הוּנָא, כָּךְ יְרֵכִ\"י בְּגִימַטְרִיָּא רָ\"ם. כְּלוֹמַר, הַנְּשָׁמָה אוֹמֶרֶת שִׂים נָא יָדְךְ, סִיעָתְךְ, תַּחַת מַעֲלָתוֹ שֶׁל רָם וְנִשָּׂא הַמּוֹשֵׁל עַל הַכֹּל. וּלְאַחַר שֶׁצִּוָּה סִיעַת הָעֶלְיוֹנִים תַּחַת יָדוֹ, אֲנִי מַשְׁבִּיעֲךְ שְׁבוּעָה גְדוֹלָה בּוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, אֱלֹהֵי הַשָּׁמַיִם וֵאלֹהֵי הָאָרֶץ - הוֹאִיל וְאָמַר בַּה' שֶׁהוּא הַכֹּל, לָמָּה נֶאֱמַר אֱלֹהֵי הַשָּׁמַיִם? אָמַר רַבִּי יְהוּדָה, שֶׁהוּא אָדוֹן עַל הַכֹּל. בְּבַת אַחַת וּבְרֶגַע אֶחָד הוּא מֵנִיעַ לַכֹּל, וְכֻלָּם כְּאַיִן נֶגְדּוֹ. רַבִּי יִצְחָק אוֹמֵר עַל שְׁתַּיִם אוֹתִיּוֹת מִשְּׁמוֹ, לְהוֹרוֹת שֶׁהוּא הַכֹּל וְאֵין אַחֵר בִּלְתּוֹ.</p>\n<p>וְאַשְׁבִּיעָךָ בַּה' אֱלֹהֵי הַשָּׁמַיִם וֵאלֹהֵי הָאָרֶץ. אָמַר רַב הוּנָא, וְאִם הָיִיתִי עִמָּהֶם שֶׁל בַּעֲלֵי הַבָּרַיְתָא כְּשֶׁגִּלּוּ הַסּוֹד הַזֶּה, לֹא נִפְרָד הָיִיתִי מֵהֶם כָּךְ, שֶׁהֲרֵי אֲנִי רוֹאֶה עֳמָקִים רַבִּים בְּפִיהֶם שֶׁגִּלּוּ וְלֹא רְאוּיִים לְכָל אָדָם. בֹּא רְאֵה, שְׁבוּעַת הַבְּרִית הַזּוֹ נִשְׁבַּעַת הַנְּשָׁמָה, שֶׁכָּתוּב אֲשֶׁר לֹא תִקַּח אִשָּׁה לִבְנִי.</p>\n<p>אָמַר רַבִּי יִצְחָק, מִכָּאן מַשְׁמָע, שֶׁהוֹאִיל וְאַתָּה הוֹלֵךְ בִּשְׁלִיחוּת זוֹ, לֹא תִקַּח אִשָּׁה לִבְנִי. כְּלוֹמַר שֶׁלֹּא תִקַּח גּוּף לִבְנִי (לבניני) לְהִכָּנֵס בְּגוּף אַחֵר, בְּגוּף זָר, בְּגוּף שֶׁאֵינוֹ רָאוּי לוֹ, אֶלָּא בְּהַהוּא מַמָּשׁ שֶׁהוּא שֶׁלִּי, בְּהַהוּא מַמָּשׁ שֶׁיָּצָאתִי מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב כִּי אִם אֶל אַרְצִי וְאֶל מוֹלַדְתִּי תֵּלֵךְ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מַהוּ וְלָקַחְתָּ אִשָּׁה לִבְנִי לְיִצְחָק? אָמַר רַבִּי יִצְחָק, אוֹתוֹ הַגּוּף שֶׁנִּצְטַעֵר עִמִּי בְּאוֹתוֹ הָעוֹלָם וְלֹא הָיָה לוֹ הֲנָאָה וְכִסּוּף בּוֹ מִפְּנֵי יִרְאַת קוֹנוֹ, אוֹתוֹ הַגּוּף מַמָּשׁ תִּקַּח לִצְחַק עִמּוֹ בְּשִׂמְחַת הַצַּדִּיקִים הַזּוֹ, לִצְחַק עִמּוֹ בְּשִׂמְחַת הַקָּדוֹשׁ בָּרוּךְ הוּא, לִצְחַק עִמּוֹ שֶׁעַכְשָׁו עֵת שְׂחוֹק בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב (תהלים קכו) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וְגוֹ'.</p>\n<p>אָמַר רַבִּי יְהוּדָה בַּר יִצְחָק, בּא תִשְׁמַע, אֵין מַלְאָךְ אֶחָד עוֹשֶׂה אֶלָּא שְׁלִיחוּת אַחַת, וְלֹא שְׁתֵּי שְׁלִיחֻיּוֹת בְּבַת אַחַת. וְלָמַדְנוּ, אָמַר רַבִּי אַבָּא, מַלְאָךְ אֶחָד, אֲשֶׁר קֶסֶת הַסּוֹפֵר בְּמָתְנָיו, עָתִיד לְהַרְשִׁים כָּל אֶחָד וְאֶחָד עַל מִצְחוֹ, וּלְאַחַר כֵּן הַשַּׂר הַגָּדוֹל הוֹלֵךְ לְתַקֵּן כָּל אֶחָד וְאֶחָד וּלְהַעֲמִידוֹ לְקַבֵּל נִשְׁמָתוֹ. זֶהוּ שֶׁכָּתוּב הוּא יִשְׁלַח מַלְאָכוֹ לְפָנֶיךְ וְלָקַחְתָּ אִשָּׁה. מַה זֶּה לְפָנֶיךְ? לִפְנֵי שְׁלִיחוּתְךְ.</p>\n<p>רַבִּי (אלעזר) אֱלִיעֶזֶר הָלַךְ לִרְאוֹת אֶת רַבָּן יוֹחָנָן בֶּן זַכַּאי רַבּוֹ, וְאוֹתוֹ הַיּוֹם הָיָה רֹאשׁ חֹדֶשׁ. כְּשֶׁהִגִּיעַ אֵלָיו, אָמַר לוֹ, הַבְּאֵר שֶׁמְּנֻקֶּה מִכָּל טִנֹּפֶת, וּמְמַלְּאִים אוֹתוֹ וְנוֹבֵעַ מִשֶּׁלּוֹ יוֹתֵר, מָה רוֹצֶה כָּאן?</p>\n<p>אָמַר לוֹ, חַיָּב אָדָם לְהַקְבִּיל פְּנֵי רַבּוֹ. אָמַר לוֹ, לֹא כָּךְ אָמַרְתִּי, אֶלָּא אֲנִי רוֹאֶה בְפָנֶיךְ שֶׁדָּבָר חָדָשׁ יֵשׁ אֶצְלְךְ מֵאוֹתָם הָעֲמֻקִּים שֶׁאַתָּה עָתִיד לִשְׁאֹל.</p>\n<p>אָמַר לוֹ, רָאִיתִי אֶת הָאוֹר הָרִאשׁוֹן הַזֶּה שֶׁמַּסְעוֹתָיו עֲשָׂרָה, וְנוֹסֵעַ בַּעֲשָׂרָה, וּבַסּוֹד שֶׁל עֲשָׂרָה מַנְהִיג אֶת הַכֹּל, וּבָאוֹתִיּוֹת שֶׁל עֲשָׂרָה עוֹשֶׂה אֶת מַעֲשָׂיו. וְלָמַדְנוּ, עֲשָׂרָה פְתָקִים, עֲשָׂרָה מַפְתְּחוֹת שֶׁל בֵּית חוֹלִים בְּיָדוֹ, וַעֲשָׂרָה פְתָקִים נוֹטֵל בְּגַן עֵדֶן לְהַתְקִין אֶרֶץ עַל גּוּפוֹת הַצַּדִּיקִים.</p>\n<p>אָמַר לוֹ, אֱלִיעֶזֶר בְּנִי, הָיִיתָ רוֹאֶה יוֹתֵר מִמַּלְאָךְ קָדוֹשׁ שֶׁל הָעוֹלָם, בַּעֲשָׂרָה נִבְרָא, בַּעֲשָׂרָה מֻנְהָג. בַּעֲשָׂרָה הַכִּסֵּא הַקָּדוֹשׁ. בַּעֲשָׂרָה הַתּוֹרָה, הוּא בַּעֲשָׂרָה מַסְעוֹתָיו. בַּעֲשָׂרָה עוֹלָמוֹת. עֶלְיוֹנִים (בעשרה). וְאֶחָד עֶלְיוֹן עַל הַכֹּל בָּרוּךְ הוּא.</p>\n<p>וְאֹמַר לְךְ דָּבָר, דַּעְתּוֹ שֶׁל בַּעַל הַמִּשְׁנָה הָיְתָה בָּזֶה. מַה כָּתוּב? וַיִּקַּח הָעֶבֶד עֲשָׂרָה גְמַלִּים מִגְּמַלֵּי אֲדנָיו וַיֵּלֶךְ. אָמַר לוֹ, רַבִּי, זָכִיתִי לַפָּסוּק הַזֶּה, אֲבָל וְכָל טוּב אֲדנָיו בְּיָדוֹ מַהוּ? אָמַר לוֹ, הוּא שְׁמוֹ שֶׁל רַבּוֹ שֶׁהָלַךְ אֵלָיו לְהַכְנִיסוֹ וּלְהַנְהִיג (ולהגן) אוֹתוֹ. אָמַר, זֶהוּ וַדַּאי, כִּי שְׁמִי בְּקִרְבּוֹ.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי אַבָּהוּ, בֹּא רְאֵה, מִי שֶׁיּוֹדֵעַ אֶת שְׁמוֹ עַל בֻּרְיוֹ, יוֹדֵעַ שֶׁהוּא וּשְׁמוֹ אֶחָד, הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁמוֹ אֶחָד, שֶׁכָּתוּב (זכריה יד) ה' אֶחָד וְגוֹ'. (כלם) כְּלוֹמַר, הַשֵּׁם וְהוּא אֶחָד.</p>\n<p>אָמַר רַבִּי אַבָּא, יֵשׁ לְהִסְתַּכֵּל בַּפָּרָשָׁה הַזּוֹ: וַיַּבְרֵךְ הַגְּמַלִּים מִחוּץ לָעִיר אֶל בְּאֵר הַמָּיִם. אָמַר רַבִּי אַבָּא, מִחוּץ לָעִיר - זֶהוּ בֵּית הַקְּבָרוֹת. אֶל בְּאֵר הַמָּיִם - שֶׁלָּמַדְנוּ, הַנִּקְדָּמִים בְּבָתֵּי הַקְּבָרוֹת - אוֹתָם שֶׁנָּשְׂאוּ וְנָתְנוּ בַּתּוֹרָה. שֶׁהֲרֵי שָׁנִינוּ, כְּשֶׁנִּכְנַס אָדָם לַקֶּבֶר, מַה שֶּׁשָּׁאֲלוּ אוֹתוֹ בַּתְּחִלָּה - אִם קָבַע עִתִּים לַתּוֹרָה, שֶׁכָּתוּב (ישעיה לג) וְהָיָה אֱמוּנַת עִתֶּךְ וְגוֹ'. וּכְשֶׁיֵּצֵא, אֵינוֹ דִּין (לקימם) לַהֲקִימָם בַּתְּחִלָּה.</p>\n<p>אָמַר רַבִּי אַבָּא, לְעֵת עֶרֶב - זֶהוּ יוֹם שִׁשִּׁי, שֶׁהוּא עֶרֶב הַשַּׁבָּת, שֶׁאָז הַזְּמַן לְהַעֲמִיד אֶת הַמֵּתִים. מַה מַּשְׁמָע? שֶׁשָּׁנִינוּ. שֵׁשֶׁת אַלְפֵי שָׁנִים הוּא הָעוֹלָם, וְהוּא אֶלֶף הַשִּׁשִּׁי שֶׁהוּא סִיּוּם הַכֹּל. וְהַיְנוּ לְעֵת עֶרֶב, זְמַן סִיּוּם הַכֹּל. לְעֵת צֵאת הַשּּׁאֲבֹת - אֵלּוּ הֵם תַּלְמִידֵי חֲכָמִים הַשּׁוֹאֲבִים מֵימֶיהָ שֶׁל תּוֹרָה, שֶׁהוּא עֵת לָצֵאת וּלְהִתְנַעֵר מִן הֶעָפָר.</p>\n<p>וְאָמַר רַבִּי אַבָּא, עוֹד יֵשׁ לָדַעַת, שֶׁשָּׁנִינוּ, אוֹתָם הַמִּתְעַסְּקִים לָדַעַת אֶת בּוֹרְאָם בָּעוֹלָם הַזֶּה וְנִשְׁמָתָם בְּתַשְׁלוּמָהּ לָעוֹלָם הַבָּא, זָכוּ לָצֵאת מִשְּׁבוּעוֹת הַנְּשָׁמָה, הוֹלֵךְ לָדַעַת מִי הוּא גוּפָהּ מַמָּשׁ וּמַה הוּא. הִנֵּה אָנֹכִי נִצָּב עַל עֵין הַמָּיִם, אַף עַל גַּב שֶׁתַּלְמִיד חָכָם הוּא, הוֹלֵךְ אַחַר הַתַּשְׁלוּם, שֶׁכָּתוּב וְהָיָה הָעַלְמָה הַיֹּצֵאת לִשְׁאֹב וְאָמַרְתִּי אֵלֶיהָ הַשְׁקִינִי נָא מְעַט מַיִם מִכַּדֵּךְ - אֱמֹר לִי רֶמֶז יְדִיעָתוֹ מִמַּה שֶּׁהִשַּׂגְתָּ.</p>\n<p>וְאָמְרָה אֵלַי גַּם אַתָּה שְׁתֵה - אַף אַתָּה עֶבֶד (כמוך) כָּמוֹנִי, וְלֹא נִתְחַלֵּף לִי (על) יְדִיעָתְךְ בִּידִיעָתוֹ שֶׁל מָקוֹם בָּרוּךְ הוּא, וְצָרִיךְ אַתָּה לְהַשִּׂיג, שֶׁאַתָּה נִבְרָא כָּמוֹנִי.</p>\n<p>וְגַם לִגְמַלֶּיךְ אֶשְׁאָב - כְּלוֹמַר, יְדִיעַת הַשָּׂגָתִי שֶׁלֹּא הִשִּׂיגוּ סִיעָתְךְ, וְיָדַעְתִּי כִּי מַעֲלָה יֵשׁ לִי עָלֶיךְ וְהֵיאַךְ נִבְרָא אַתָּה מִזִּיו הַנָּתוּן אֶצְלְךְ. אִם הוּא אוֹמֵר סִימָן זֶה יְהִי מָסוּר בְּיָדִי עַל כָּל דְּבָרִים אֵלּוּ, וְאֵדַע שֶׁהִיא הָאִשָּׁה, הוּא הַגּוּף מֵאוֹתָהּ הַנְּשָׁמָה, הַשְּׁבוּעָה שֶׁהִשְׁבִּיעַנִי.</p>\n<p>וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְגוֹ'. רַבִּי יִצְחָק אָמַר רַבִּי יְהוּדָה, בְּעוֹד שֶׁכָּל הָעִנְיָנִים הוּא רוֹצֶה לְנַסּוֹת עַל הַגּוּף, מַה כָּתוּב? וְהִנֵּה רִבְקָה יצֵאת, זֶהוּ הַגּוּף קָדוֹשׁ שֶׁנִּתְעַסֵּק בְּדִבְרֵי תוֹרָה וְכִתֵּת גּוּפוֹ לְהַשִּׂיג וְלָדַעַת אֶת קוֹנוֹ. אֲשֶׁר יֵלְּדָה לִבְתוּאֵל - אָמַר רַב יְהוּדָה, בִּתּוֹ שֶׁל אֵל. בֶּן מִלְכָּה - בֶּן מַלְכָּהּ שֶׁל עוֹלָם. אֵשֶׁת נָחוֹר אֲחִי אַבְרָהָם - חֶבְרַת הַשֵּׂכֶל, גּוּף שֶׁנִּדְבָּק בַּשֵּׂכֶל, וְהִיא אַח הַנְּשָׁמָה. וְכַדָּהּ עַל שִׁכְמָהּ - מַשָּׂא הַחָכְמָה עָלֶיהָ.</p>\n<p>וַיָּרָץ הָעֶבֶד לִקְרָאתָהּ - זֶה מטטרו\"ן. וַיֹּאמֶר הַגְמִיאִינִי מְעַט מַיִם מִכַּדֵּךְ - אֱמֹר לִי רֶמֶז חָכְמָה בִּידִיעַת בּוֹרַאֲךְ מִמַּה שֶּׁעָסַקְתָּ בָּעוֹלם שֶׁיָּצָאתָ מִמֶּנּוּ. אָמַר רַבִּי אַבָּא, כְּמוֹ שֶׁפֵּרַשְׁנוּ, אַחַר כָּל זֶה מַה כָּתוּב? וָאָשִׂם הַנֶּזֶם עַל אַפָּהּ וְהַצְּמִידִים עַל יָדֶיהָ. אָמַר רַבִּי אַבָּא, אוֹתָם הָעֲצָמוֹת שֶׁנִּפְזְרוּ לְכָאן וּלְכָאן, הוּא צוֹמֵד אוֹתָם וְשׁוֹקְלָם זֶה עַל זֶה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נח) וְעַצְמֹתֶיךְ יַחֲלִיץ. אָמַר רַבִּי אַבָּא, בְּאוֹתָהּ שָׁעָה אוֹתוֹ הַגּוּף עוֹמֵד בְּאֶרֶץ יִשְׂרָאֵל, וְשָׁם נִכְנָס בּוֹ נִשְׁמָתוֹ.</p>\n<p>אָמַר רַבִּי יוֹחָנָן, מִי מוֹלִיךְ הַגּוּף לְאֶרֶץ יִשְׂרָאֵל? אָמַר רַבִּי זֵירָא, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה מְחִלּוֹת תַּחַת הָאָרֶץ, וְהֵם מִתְגַּלְגְּלִים וְהוֹלְכִים לְאֶרֶץ יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (שם כו) וָאָרֶץ רְפָאִים תַּפִּיל.</p>\n<p>אָמַר רַבִּי יִצְחָק, גַּבְרִיאֵ\"ל מוֹלִיךְ אוֹתָם לְאֶרֶץ יִשְׂרָאֵל, מִנַּיִן לָנוּ? שֶׁכָּתוּב (בראשית כד) הֲתֵלְכִי עִם הָאִישׁ הַזֶּה, וְכָתוּב שָׁם (דניאל ט) וְהָאִישׁ גַּבְרִיאֵל. אָמַר רַבִּי יוֹסֵי, מַהוּ שֶׁכָּתוּב וּלְרִבְקָה אָח וּשְׁמוֹ לָבָן? אָמַר רַבִּי יִצְחָק, אֵין יֵצֶר הָרָע בָּטֵל מִן הָעוֹלָם. אַף עַל פִּי שֶׁכֻּלּוֹ לֹא נִמְצָא - קְצָתוֹ נִמְצָא.</p>\n<p>בֹּא רְאֵה, בַּתְּחִלָּה כְּשֶׁהָיָה מֻטָּל בָּעוֹלָם הַזֶּה, נִקְרָא לוֹט. לָעוֹלָם הַבָּא (יבדל) יִבָּטֵל מִן הָעוֹלָם, אֲבָל (לעתיד לבא) לֹא כֻּלּוֹ, וְנִקְרָא לָבָן, לֹא מְנֵוּל כְּבָרִאשׁוֹנָה, אֶלָּא כְּמִי שֶׁרוֹחֵץ מִנִּוּוּלוֹ. לָמָּה צָרִיךְ לָבָן? אָמַר רַבִּי שִׁמְעוֹן, לַעֲשׂוֹת פְּרִיָּה וּרְבִיָּה צָרִיךְ. שֶׁאָמַר רַבִּי שִׁמְעוֹן, אִם אֵין יֵצֶר הָרָע נִמְצָא, פְּרִיָּה וּרְבִיָּה אֵינוֹ מָצוּי.</p>\n<p>בֹּא תִשְׁמַע, כֵּיוָן שֶׁהַגּוּף נִבְנֶה וְעוֹמֵד בְּקִיּוּמוֹ, מַה כָּתוּב? וַיְשַׁלְּחוּ אֶת רִבְקָה אֲחֹתָם וְגוֹ'. מַה זֶּה וְאֶת מֵנִקְתָּהּ? זֶה כֹּחַ הַתְּנוּעָה. רַבִּי יִצְחָק אָמַר, זֶה כֹּחַ הַגּוּף.</p>\n<p>רַבִּי אַבָּהוּ פָּתַח בַּפָּסוּק הַזֶּה, (שיר ד) אִתִּי מִלְּבָנוֹן כַּלָּה אִתִּי מִלְּבָנוֹן תָּבֹאִי וְגוֹ'. אָמַר רַבִּי אַבָּהוּ, כֵּיוָן שֶׁהַגּוּף נִבְנֶה עַל קִיּוּמוֹ וּמְבִיאִין אוֹתוֹ לְקַבֵּל נִשְׁמָתוֹ לְאֶרֶץ יִשְׂרָאֵל, הַנְּשָׁמָה מַמְתֶּנֶת אֵלָיו וְיוֹצֵאת לִקְרָאתוֹ, כְּמוֹ שֶׁנֶּאֱמַר וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה. זֶהוּ שֶׁכָּתוּב אִתִּי מִלְּבָנוֹן כַּלָּה, זוֹ הִיא הַנְּשָׁמָה. תָּשׁוּרִי מֵרֹאשׁ אֲמָנָה, הַיְנוּ שֶׁכָּתוּב וַיִּשָּׂא עֵינָיו וַיַּרְא.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם הַנְּשָׁמָה הִיא, יָפֶה אַבְרָהָם כְּפִי שֶׁאָמַרְנוּ. אֲבָל מַה זֶּה יִצְחָק? אָמַר רַבִּי אַבָּהוּ, הִנֵּה הַחֲבֵרִים אָמְרוּ שֶׁעַכְשָׁו נִקְרָא יִצְחָק עַל שֵׁם הַשִּׂמְחָה הָרַבָּה שֶׁבָּעוֹלָם.</p>\n<p>אָמַר רַבִּי אַבָּהוּ, בַּתְּחִלָּה נִקְרֵאת הַנְּשָׁמָה אַבְרָהָם וְהַגּוּף שָׂרָה. עַכְשָׁו נִקְרֵאת הַנְּשָׁמָה יִצְחָק וְהַגּוּף רִבְקָה. שָׁנִינוּ בַּמִּשְׁנָה, אָמַר רַבִּי שִׁמְעוֹן, אַרְבָּעִים יוֹם קֹדֶם קִיּוּם הַגּוּף מַמְתֶּנֶת הַנְּשָׁמָה לַגּוּף בְּאֶרֶץ יִשְׂרָאֵל. בְּאֵיזֶה מָקוֹם? בִּמְקוֹם הַמִּקְדָּשׁ.</p>\n<p>אָמַר רַבִּי אַבָּהוּ, בּא רְאֵה, וַיִּקַּח אֶת רִבְקָה וַתְּהִי לוֹ לְאִשָּׁה וַיֶּאֱהָבֶהָ וַיִּנָּחֵם יִצְחָק אַחֲרֵי אִמּוֹ. אוֹהֵב אֶת אוֹתוֹ הַגּוּף וּמִתְנַחֵם עִמּוֹ, וְהוּא עֵת לִשְׂחֹק וְהַחֶדְוָה בָּעוֹלָם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, הֲרֵי כָּל הַפָּרָשָׁה הַזּוֹ הִתְבָּרְרָה לָנוּ, אֲבָל לֹא יָכֹלְנוּ לָדַעַת מַהוּ. וַיֹּסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה. וּלְשִׁקּוּל הַדַּעַת כָּל הַפָּרָשָׁה הַזּוֹ לִסְתֹּר.</p>\n<p>כְּשֶׁבָּא רַב דִּימִי, אָמַר, הַפָּרָשָׁה הַזּוֹ שָׁמַעְתִּי וְלֹא נִזְכַּרְתִּי. אָמְרוּ שֶׁעֶלְיוֹנִים תַּקִּיפִים לֹא זִמְּנוּהָ לְגַלּוֹת, וְאָנוּ מַה נֹּאמַר? קָם רַבִּי יְהוּדָה וְאָמַר, מִישִׁיבַת חֲבֵרֵינוּ בַּעֲלֵי הַמִּשְׁנָה גְּלוּיָה.</p>\n<p>קָמוּ וְהָלְכוּ הוּא וְרַבִּי יֵיסָא וְרַבִּי חִיָּיא. מָצְאוּ אֶת רַבִּי אֶלְעָזָר בְּרַבִּי שִׁמְעוֹן, וְהָיָה מְגַלֶּה אֶת סוֹדוֹת הַתְּפִלִּין. נִכְנְסוּ לְפָנָיו וְאָמְרוּ, בַּמֶּה מִתְעַסֵּק מַר? אָמַר לָהֶם, אֶת טַעַם הַתְּפִלִּין אָמַרְתִּי, שֶׁהֲרֵי אַשְׁרֵי הָאִישׁ שֶׁמֵּנִיחַ תְּפִלִּין וְיוֹדֵעַ אֶת הַטַּעַם שֶׁלָּהֶן.</p>\n<p>אָמְרוּ, אִם נוֹחַ לִפְנֵי מַר, יֹאמַר לָנוּ הַדָּבָר. אָמְרוּ, שָׁמַעְנוּ מֵאָבִיךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בְּאַהֲבָה רַבָּה שֶׁהָיְתָה לוֹ עִם יִשְׂרָאֵל אָמַר לָהֶם לַעֲשׂוֹת לוֹ בֵּית מִשְׁכָּן כְּמוֹ הַמֶּרְכָּבָה הָעֶלְיוֹנָה שֶׁלְּמַעְלָה, וְיָבִיא אֶת דִּיּוּרוֹ עִמָּהֶם. זֶהוּ שֶׁכָּתוּב (שמות כה) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם. וְשָׁמַעְנוּ מֵאָבִיךְ, שֶׁכָּאן סָתוּם הַטַּעַם שֶׁל הַתְּפִלִּין בַּפָּסוּק הַזֶּה.</p>\n<p>אָמַר לוֹ, בּא רְאֵה, כְּמוֹ הָעֶלְיוֹן נַעֲשָׂה הַמִּקְדָּשׁ בְּמַרְכְּבוֹתָיו הַקְּדוֹשׁוֹת, וְאַחַר כָּךְ הִשְׁרָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת דִּיּוּרוֹ עִמָּהֶם כָּעִנְיָן הַזֶּה. וּכְמוֹ כֵן הִתְעוֹרְרוּ הַחֲבֵרִים בַּעֲלֵי הַמִּשְׁנָה בְּטַעַם הַתְּפִלִּין, שֶׁיִּהְיֶה אוֹתוֹ הָאִישׁ דֻּגְמָא שֶׁל הַמֶּרְכָּבוֹת הָעֶלְיוֹנוֹת, מֶרְכָּבָה תַחְתּוֹנָה מֶרְכָּבָה עֶלְיוֹנָה, לְהָבִיא אֶת מַלְכוּתוֹ וְיַשְׁרֶה דִיּוּרוֹ עָלָיו.</p>\n<p>וְשָׁנִינוּ, יֵשׁ בּוֹ סוֹדוֹת עֶלְיוֹנִים וְדֻגְמָתָם, וְיֵשׁ בּוֹ שָׁלֹשׁ מֶרְכָּבוֹת, דֻּגְמַת הָעֶלְיוֹנִים הַקְּדוֹשִׁים סוֹדוֹת שֶׁל שָׁלֹשׁ אוֹתִיּוֹת שֶׁל הַשֵּׁמוֹת הַקְּדוֹשִׁים, שְׁלֹשָׁה עוֹלָמוֹת, מֶרְכָּבוֹת שָׁלֹשׁ אוֹתִיּוֹת, אַרְבַּע פָּרָשִׁיּוֹת שׁוֹלֵט עַל אַרְבַּע. וְעַל כֵּן סוֹד הַשִּׁי\"ן שֶׁל שְׁלֹשָׁה כְתָרִים, וְשִׁי\"ן שֶׁל אַרְבָּעָה כְתָרִים, שְׁלֹשָׁה מְלָכִים שׁוֹלְטִים בַּגּוּף, תְּפִלִּין עָלָיו, הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה. אֵלּוּ תְּפִלִּין שֶׁל רֹאשׁ. הַתְּפִלִּין שֶׁל זְרוֹעַ אַרְבַּע פָּרָשִׁיּוֹת.</p>\n<p>הַלֵּב רוֹכֵב, דֻּגְמָא שֶׁל הַמֶּרְכָּבָה הַתַּחְתּוֹנָה, וְהַתַּחְתּוֹן רוֹכֵב. עוֹד שָׁנִינוּ, זֶה הָרֶכֶב שֶׁל הַזְּרוֹעַ לְמַטָּה. וְהַלֵּב רוֹכֵב, דֻּגְמָא שֶׁהוּא לְמַטָּה, וְנִמְסְרוּ בְיָדוֹ לְהַכְנִיס אוֹתָם כָּל חֵילוֹת הַשָּׁמַיִם. כָּךְ הַלֵּב רוֹכֵב לְמַטָּה, וְנִמְסְרוּ בְיָדוֹ כָּל אֵיבְרֵי הַגּוּף.</p>\n<p>וּמֵעָלָיו אַרְבַּע פָּרָשִׁיּוֹת עַל הַמֹּחַ, שֶׁהוּא הָרֹאשׁ. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא שַׁלִּיט עֶלְיוֹן, הַמֶּלֶךְ מֵהַכֹּל. (ורוח) וְסוֹד הַחָכְמָה הַזּוֹ הוּא כְּמוֹ שֶׁהַמִּקְדָּשׁ, שֶׁכָּתוּב וַעֲשֵׂה כְּרוּב אֶחָד מִקָּצָה מִזֶּה וּכְרוּב אֶחָד מִקָּצָה. וַעֲלֵיהֶם דִּיּוּר הַמֶּלֶךְ בְּאַרְבַּע אוֹתִיּוֹת שְׁתֵּי מֶרְכָּבוֹת.</p>\n<p>וּכְמוֹ זֶה הַלֵּב וְהַמֹּחַ, הַלֵּב מִכָּאן וְהַמֹּחַ מִכָּאן, וַעֲלֵיהֶם מְדוֹרוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאַרְבַּע (ארבע) פָּרָשִׁיּוֹת. אָמַר רַבִּי אֶלְעָזָר, מִכָּאן וָהָלְאָה סוֹדוֹת הַכְּתָרִים, הָאוֹתִיּוֹת וְהַפָּרָשִׁיּוֹת בְּגוּפָם וּבִרְצוּעוֹתֵיהֶם. הֲלָכָה לְמֹשֶׁה מִסִּינַי וְהָרֶמֶז שֶׁלָּהֶם הִתְגַּלָּה, וְהַטַּעַם שֶׁל הַכֹּל בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת (הרחמים).</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִלְמָלֵא לֹא בָאתִי אֶלָּא עֲבוּר הַסּוֹד הַזֶּה - דַּי לִי. אָמְרוּ לוֹ, אַשְׁרֵי חֶלְקְךְ בָּעוֹלָם הַבָּא, שֶׁכָּל רָז אֵינוֹ אָנוּס לְךְ. אָמְרוּ לוֹ, בָּאנוּ לִפְנֵי מַר לָדַעַת אֶת סוֹד הַפָּסוּק הַזֶּה, וַיֹּסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה.</p>\n<p>אָמַר, פֵּרוּשׁ שֶׁל הַפָּסוּק הַזֶּה כְּמוֹ שֶׁגִּלּוּ חֲבֵרֵינוּ בַּעֲלֵי הַמִּשְׁנָה, שֶׁכַּאֲשֶׁר הַנְּשָׁמָה תָּבוֹא בְּאוֹתוֹ הַגּוּף הַקָּדוֹשׁ שֶׁלָּהּ, הִנֵּה הַדְּבָרִים הָיוּ עַל הָרְשָׁעִים שֶׁיָּקוּמוּ וְיַכְשִׁירוּ אֶת מַעֲשֵׂיהֶם, וְיִתֵּן לָהֶם מִזִּיו כְּבוֹדוֹ שֶׁיֵּדְעוּ וְיָשׁוּבוּ וְיִזְכּוּ זְכוּת שְׁלֵמָה.</p>\n<p>וּכְשֶׁרָאָה אֶת זֶה שְׁלֹמֹה, הָיָה (תמה הרבה) הַרְבֵּה וְאָמַר, (קהלת ח) וּבְכֵן רָאִיתִי רְשָׁעִים קְבֻרִים וָבָאוּ וּמִמְּקוֹם קָדוֹשׁ יְהַלֵּכוּ, שֶׁיָּבֹאוּ וְיִחְיוּ מִמְּקוֹם קָדוֹשׁ. וְשָׁנִינוּ, אָמַר רַבִּי אַבָּא אָמַר רַבִּי יוֹחָנָן, כָּתוּב (ירמיה ג) הֲיַהֲפֹךְ כּוּשִׁי עוֹרוֹ וְנָמֵר חֲבַרְבֻּרֹתָיו. כָּךְ הָרְשָׁעִים שֶׁלֹּא זָכוּ לָשׁוּב בָּעוֹלָם הַזֶּה וּלְהַקְטִיר מַעֲשִׂים טוֹבִים, לְעוֹלָם לֹא יַקְטִירוּ בָּעוֹלָם הַבָּא. רְאֵה מַה כָּתוּב, וַיֹּסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה, וְשֶׁרוֹצֶה לַעֲשׂוֹת לָהֶם נְשָׁמָה לְגוּפָם וּלְקָרְבָם בִּתְשׁוּבָה, כְּמוֹ שֶׁנֶּאֱמַר וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, בּא רְאֵה מַה כָּתוּב, וַתֵּלֶד לוֹ אֶת זִמְרָן וְאֶת יָקְשָׁן. הַרְבֵּה מַעֲשִׂים רָעִים עַד שֶׁנִּגְרָשִׁים מִן הָעוֹלָם, שֶׁכָּתוּב וַיְשַׁלְּחֵם מֵעַל יִצְחָק בְּנוֹ. וַעֲלֵיהֶם נֶאֱמַר (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ וְגוֹ'. וְעַל הָאֲחֵרִים נֶאֱמַר וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ וְגוֹ'.</p>\n<p>אָמַר רַבִּי יְהוּדָה, זֶה מַשְׁמָע עַל הַפָּרָשָׁה, וּמַשְׁמָע שֶׁאוֹתוֹ זְמַן (נקרא) (אבד) שֵׁם (הנשמה) אַבְרָהָם, וּבִמְקוֹמוֹ נִקְרֵאת יִצְחָק, כְּפִי שֶׁאָמַרְנוּ. זֶהוּ שֶׁכָּתוּב וַיְהִי אַחֲרֵי מוֹת אַבְרָהָם וַיְבָרֶךְ אֱלֹהִים אֶת יִצְחָק בְּנוֹ וַיֵּשֶׁב יִצְחָק עִם בְּאֵר לַחַי רֹאִי. עִם יְדִיעַת הַחַי שֶׁהוּא חַי הָעוֹלָמִים, לָדַעַת וּלְהַשִּׂיג מַה שֶּׁלֹּא הִשִּׂיג בָּעוֹלָם הַזֶּה. זֶהוּ שֶׁכָּתוּב (ישעיה יא) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת ה'. (עד כאן מדרש הנעלם)</p>\n<p>רַבִּי יִצְחָק פָּתַח וְאָמַר, (קהלת יב) וְיָשֹׁב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם, נָטַל עֲפָרוֹ מִמְּקוֹם הַמִּקְדָּשׁ, וּבָנָה אֶת גּוּפוֹ מֵאַרְבַּעַת הַצְּדָדִים שֶׁל הָעוֹלָם, שֶׁכֻּלָּם נָתְנוּ לוֹ כֹּחַ. אַחַר כָּךְ הֵרִיק עָלָיו רוּחַ חַיִּים, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים וְגוֹ'. אַחַר כָּךְ קָם וְיָדַע שֶׁהוּא מִמַּעְלָה וּמַטָּה, וְאָז נִדְבַּק וְיָדַע אֶת הַחָכְמָה הָעֶלְיוֹנָה.</p>\n<p>כְּמוֹ זֶה כָּל אָדָם שֶׁבָּעוֹלָם הוּא כָּלוּל מִמַּעְלָה וּמַטָּה, וְכָל אוֹתָם שֶׁיּוֹדְעִים לְהִתְקַדֵּשׁ בָּעוֹלָם הַזֶּה כָּרָאוּי, כְּשֶׁמּוֹלִידִים בֵּן, מוֹשְׁכִים עָלָיו רוּחַ קְדֻשָּׁה מֵהַמָּקוֹם שֶׁכָּל הַקְּדוֹשִׁים יוֹצְאִים מִמֶּנּוּ, וְאֵלּוּ נִקְרָאִים בָּנִים לַקָּבָּ\"ה. מִשּׁוּם שֶׁהַגּוּף נַעֲשָׂה בִּקְדֻשָּׁה כָּרָאוּי, כָּךְ גַּם נוֹתְנִים לוֹ רוּחַ מִמָּקוֹם עֶלְיוֹן קָדוֹשׁ כָּרָאוּי, וַהֲרֵי זֶה נִתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁעָתִיד אָדָם לָתֵת חֶשְׁבּוֹן מַעֲשָׂיו טֶרֶם יָצָא מִן הָעוֹלָם, אוֹתוֹ הַיּוֹם הוּא יוֹם הַחֶשְׁבּוֹן שֶׁגּוּף וּנְשָׁמָה נוֹתְנִים חֶשְׁבּוֹן. אַחַר כָּךְ הַנְּשָׁמָה נִפְרֶדֶת מִמֶּנּוּ, וְהַגּוּף שָׁב לָאָרֶץ, וְהַכֹּל שָׁב לִמְקוֹמוֹ שֶׁנִּלְקַח מִשָּׁם, וַהֲרֵי פֵּרְשׁוּהָ. עַד הַזְּמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַחֲיוֹת מֵתִים, הַכֹּל גָּנוּז לְפָנָיו.</p>\n<p>וְאוֹתוֹ גוּף מַמָּשׁ וְאוֹתָהּ נְשָׁמָה מַמָּשׁ עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָשִׁיב לָעוֹלָם כְּמוֹ מִקֹּדֶם וּלְחַדֵּשׁ אֶת פְּנֵי הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה כו) יִחְיוּ מֵתֶיךְ נְבֵלָתִי יְקוּמוּן. וְאוֹתָהּ הַנְּשָׁמָה מַמָּשׁ גְּנוּזָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְשָׁבָה לִמְקוֹמָהּ כְּפִי דַרְכָּהּ, כְּמוֹ שֶׁנֶּאֱמַר וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. וּבִזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַחֲיוֹת מֵתִים, עָתִיד הוּא לְהָרִיק טַל מֵרֹאשׁוֹ עֲלֵיהֶם, וּבְאוֹתוֹ הַטַּל כֻּלָּם יָקוּמוּ מֵהֶעָפָר.</p>\n<p>זְהִוּ שֶׁכָּתוּב (שם) כִּי טַל אוֹרוֹת טַלֶּךְ. מַה זֶּה טַל אוֹרוֹת? אוֹרוֹת מַמָּשׁ מֵאוֹתָם הָאוֹרוֹת שֶׁל מַעְלָה שֶׁבָּהֶם עָתִיד לְהָרִיק חַיִּים לָעוֹלָם, מִשּׁוּם שֶׁעֵץ הַחַיִּים יָרִיק חַיִּים שֶׁלֹּא פוֹסְקִים לְעוֹלָמִים. שֶׁהֲרֵי עַכְשָׁו פּוֹסְקִים מִשּׁוּם שֶׁהַנָּחָשׁ הָרָע הַזֶּה שׁוֹלֵט וְהַלְּבָנָה מִתְכַּסָּה. וּמִשּׁוּם כָּךְ כִּבְיָכוֹל פּוֹסְקִים מֵימָיו, וְהַחַיִּים לֹא שׁוֹלְטִים בָּעוֹלָם כָּרָאוּי.</p>\n<p>וּבְאוֹתוֹ זְמַן אוֹתוֹ יֵצֶר הָרָע, שֶׁהוּא הַנָּחָשׁ הָרָע, יִסְתַּלֵּק מִן הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲבִיר אוֹתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ. וְאַחַר שֶׁהוּא יָעֳבַר מִן הָעוֹלָם, הַלְּבָנָה לֹא תִתְכַּסֶּה. וְהַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, לֹא יִפָּסְקוּ מַעְיָנָיו. וְאָז כָּתוּב (ישעיה ל) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים וְגוֹ'.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, אִם תֹּאמַר שֶׁכָּל הַגּוּפוֹת שֶׁל הָעוֹלָם יָקוּמוּ וְיִתְעוֹרְרוּ מִן הֶעָפָר - אוֹתָם הַגּוּפוֹת שֶׁנִּטְּעוּ בִּנְשָׁמָה אַחַת מַה יִּהְיֶה מֵהֶם? אָמַר רַבִּי יוֹסֵי, אוֹתָם הַגּוּפוֹת שֶׁלֹּא זָכוּ וְלֹא הִצְלִיחוּ, הֲרֵי הֵם כְּלֹא הָיוּ. כְּמוֹ שֶׁהָיוּ עֵץ יָבֵשׁ בָּעוֹלָם הַהוּא, כָּךְ גַּם בְּאוֹתוֹ הַזְּמַן. וְהַגּוּף הָאַחֲרוֹן שֶׁנִּנְטַע וְהִצְלִיחַ וְנָטַל שָׁרָשָׁיו כָּרָאוּי יָקוּם.</p>\n<p>וְעָלָיו כָּתוּב (ירמיה יז) וְהָיָה כְּעֵץ שָׁתוּל עַל מַיִם וְגוֹ' וְהָיָה עָלֵהוּ רַעֲנָן וְגוֹ'. שֶׁעָשָׂה פֵּרוֹת וְנָטַע שָׁרָשִׁים וְהִצְלִיחַ כָּרָאוּי. וְעַל אוֹתוֹ גוּף רִאשׁוֹן שֶׁלֹּא עָשָׂה פֵּרוֹת וְלֹא נָטַע שָׁרָשִׁים (ולא זכה ולא הצליח), כָּתוּב (שם) וְהָיָה כְּעַרְעָר בָּעֲרָבָה וְלֹא יִרְאֶה כִּי יָבוֹא טוֹב וְגוֹ'. כִּי יָבוֹא טוֹב - זוֹ תְּחִיַּת הַמֵּתִים.</p>\n<p>וְיָאִיר אוֹתוֹ הָאוֹר שֶׁעָתִיד לְהָאִיר לַצַּדִּיקִים שֶׁהָיָה גָנוּז לְפָנָיו מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, שֶׁכָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וְאָז עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת הַמֵּתִים, וְכָתוּב (מלאכי ג) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וְגוֹ'. וְאָז יִתְגַּבֵּר הַטּוֹב בָּעוֹלָם, וְאוֹתוֹ שֶׁנִּקְרָא רַע יַעֲבֹר מִן הָעוֹלָם, כְּמוֹ שֶׁאָמַרְנוּ, וְאָז אוֹתָם הַגּוּפִים הָרִאשׁוֹנִים יִהְיוּ כְּלֹא הָיוּ.</p>\n<p>אָמַר רַבִּי יִצְחָק, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָרִיק עַל אוֹתָם הַגּוּפִים רוּחוֹת אֲחֵרוֹת, וְאִם זוֹכִים בָּהֶם - יָקוּמוּ בָּעוֹלָם כָּרָאוּי, וְאִם לֹא - יִהְיוּ אֵפֶר תַּחַת רַגְלֵי הַצַּדִּיקִים, שֶׁכָּתוּב (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ וְגוֹ', וְהַכֹּל יוּקַם וְיִוָּעֵד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם כֻּלָּם בְּמִנְיָן, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מ) הַמּוֹצִיא בְמִסְפָּר צְבָאָם וְגוֹ'.</p>\n<p>בֹּא רְאֵה, הֲרֵי נֶאֱמַר, כָּל אוֹתָם הַמֵּתִים שֶׁבְּאֶרֶץ יִשְׂרָאֵל יָקוּמוּ בָּרִאשׁוֹנָה, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְעוֹרֵר עֲלֵיהֶם וְיָקִים אוֹתָם. עֲלֵיהֶם כָּתוּב יִחְיוּ מֵתֶיךְ. אֵלּוּ הֵם שֶׁבְּאֶרֶץ יִשְׂרָאֵל. נְבֵלָתִי יְקוּמוּן - אֵלּוּ הֵם שֶׁבְּתוֹךְ אֲרָצוֹת אֲחֵרוֹת, שֶׁלֹּא כְתוּבָה בָהֶם תְּחִיָּה, אֶלָּא קִימָה. שֶׁהֲרֵי רוּחַ הַחַיִּים לֹא תִשְׁרֶה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל הַקְּדוֹשָׁה, וּמִשּׁוּם כָּךְ כָּתוּב בָּהֶם יִחְיוּ מֵתֶיךְ, וְאוֹתָם שֶׁבַּחוּץ יִבְרָא הַגּוּף שֶׁלָּהֶם, וְיָקוּמוּ גוּף בְּלִי רוּחַ. אַחַר כָּךְ יִתְגַּלְגְּלוּ תַּחַת הֶעָפָר עַד שֶׁיַּגִּיעוּ לְאֶרֶץ יִשְׂרָאֵל, וְשָׁם יְקַבְּלוּ נְשָׁמָה, וְלֹא בִּרְשׁוּת אַחֶרֶת, כְּדֵי שֶׁיִּתְקַיְּמוּ בָּעוֹלָם כָּרָאוּי.</p>\n<p>רַבִּי אֶלְעָזָר וְרַבִּי יֵיסָא הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד וְעוֹסְקִים בַּתּוֹרָה. אָמַר רַבִּי אֶלְעָזָר, בֹּא רְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַחֲיוֹת אֶת הַמֵּתִים, כָּל אוֹתָם הַנְּשָׁמוֹת שֶׁיִּתְעוֹרְרוּ לְפָנָיו, כֻּלָּם עוֹמְדוֹת דְּמֻיּוֹת דְּמֻיּוֹת לְפָנָיו, בְּאוֹתָהּ דְּמוּת מַמָּשׁ שֶׁהָיוּ בָּעוֹלָם הַזֶּה, וְיוֹרִיד אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְיִקְרָא לָהֶם בְּשֵׁמוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שם) לְכֻלָּם בְּשֵׁם יִקְרָא. וְכָל נְשָׁמָה תִּכָּנֵס לִמְקוֹמָהּ, וְיָקוּמוּ בְּקִיּוּם בָּעוֹלָם כָּרָאוּי, וְאָז יִהְיֶה הָעוֹלָם שָׁלֵם. וְעַל אוֹתוֹ הַזְּמַן כָּתוּב (שם כה) וְחֶרְפַּת עַמּוֹ יָסִיר וְגוֹ'. מַה זֶּה וְחֶרְפַּת עַמּוֹ יָסִיר? זֶה יֵצֶר הָרָע שֶׁמַּחְשִׁיךְ אֶת פְּנֵי הַבְּרִיּוֹת וְשׁוֹלֵט בָּהֶם.</p>\n<p>אָמַר רַבִּי יוסֵי, הֲרֵי רָאִינוּ, כָּל זְמַן שֶׁאָדָם עוֹמֵד בָּרוּחַ הַזּוֹ - אֵינוֹ טָמֵא. יָצְאָה נִשְׁמָתוֹ מִמֶּנּוּ - הוּא טָמֵא. אָמַר לוֹ, וַדַּאי שֶׁזֶּה כָּךְ, וְכָךְ נֶאֱמַר, שֶׁהֲרֵי אוֹתוֹ יֵצֶר הָרָע, כְּשֶׁנּוֹטֵל אֶת הָרוּחַ שֶׁל הָאָדָם, הוּא מְטַמֵּא אוֹתוֹ, וְנִשְׁאָר גּוּף טָמֵא. וּשְׁאָר עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, כְּשֶׁהֵם בְּחַיֵּיהֶם הֵם טְמֵאִים, שֶׁהֲרֵי יֵשׁ לָהֶם נְשָׁמוֹת מִצַּד הַטֻּמְאָה, וּכְשֶׁמִּתְרוֹקֶנֶת מִמֶּנּוּ אוֹתָהּ טֻמְאָה, נִשְׁאָר הַגּוּף בְּלִי טֻמְאָה כְּלָל.</p>\n<p>מִשּׁוּם כָּךְ מִי שֶׁנִּדְבָּק בְּאִשָּׁה שֶׁל שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדַת כוֹכָבִים וּמַזָּלוֹת, הוּא נִטְמָא, וְאוֹתוֹ בֵּן שֶׁיִּוָּלֵד לוֹ יְקַבֵּל עָלָיו רוּחַ שֶׁל טֻמְאָה. וְאִם תֹּאמַר, הֲרֵי מִצַּד אָבִיו הוּא בָּא מִיִּשְׂרָאֵל, לָמָּה יְקַבֵּל עָלָיו רוּחַ טֻמְאָה? בֹּא רְאֵה, שֶׁהֲרֵי בָּרִאשׁוֹנָה נִטְמָא אָבִיו בְּשָׁעָה שֶׁנִּדְבַּק עִם אוֹתָהּ אִשָּׁה שֶׁהִיא טְמֵאָה, וְכֵיוָן שֶׁהָאָב נִטְמָא בְּאוֹתָהּ אִשָּׁה שֶׁהִיא טְמֵאָה, כָּל שֶׁכֵּן שֶׁאוֹתוֹ הַבֵּן שֶׁנּוֹלַד מִמֶּנָּה יְקַבֵּל עָלָיו רוּחַ טֻמְאָה. וְלֹא עוֹד, אֶלָּא שֶׁעָבַר עַל הַתּוֹרָה, שֶׁכָּתוּב (שמות לד) כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר, כִּי ה' קַנָּא שְׁמוֹ, מִשּׁוּם שֶׁהוּא מְקַנֵּא עַל בְּרִית הַקֹּדֶשׁ הַזּוֹ.</p>"],[9522011271,"<p>אָמַר רַבִּי אֶלְעָזָר, בֹּא רְאֵה, שֶׁהֲרֵי נֶאֱמַר שֶׁכֵּיוָן שֶׁיָּדַע אַבְרָהָם אָבִינוּ חָכְמָה, רָצָה לְהִפָּרֵד מִכָּל שְׁאָר הָעַמִּים וְלֹא לְהִדָּבֵק בָּהֶם, וּמִשּׁוּם כָּךְ כָּתוּב: וְאַשְׁבִּיעֲךְ בַּה' אֱלֹהֵי הַשָּׁמַיִם וֵאלֹהֵי הָאָרֶץ אֲשֶׁר לֹא תִקַּח אִשָּׁה לִבְנִי מִבְּנוֹת הַכְּנַעֲנִי וְגוֹ'. מִבְּנוֹת הַכְּנַעֲנִי וַדַּאי. (מה) סוֹד הוּא, כְּמוֹ שֶׁנֶּאֱמַר (מלאכי ב) וּבָעַל בַּת אֵל נֵכָר. אֲשֶׁר אָנֹכִי יוֹשֵׁב בְּקִרְבּוֹ, אָנֹכִי בִּמְדֻיָּק. כָּתוּב כָּאן אֲשֶׁר אָנֹכִי, וְכָתוּב שָׁם (ישעיה מד) אָנֹכִי עָשִׂיתִי אֶרֶץ. וְכָל זֶה כְּדֵי לֹא לְהִטָּמֵא עִמָּהֶם.</p>\n<p>בֹּא רְאֵה, מִי שֶׁמַּכְנִיס אֶת הַבְּרִית הַקְּדוֹשָׁה הַזּוֹ בָּאִשָּׁה הַהִיא שֶׁל שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, גּוֹרֵם לְטַמֵּא מָקוֹם אַחֵר, וְעַל זֶה כָּתוּב (משלי ל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ וְגוֹ'. וְאַף עַל גַּב שֶׁהִשְׁבִּיעַ אוֹתוֹ בַּבְּרִית הַזּוֹ, לֹא בָטַח בּוֹ אַבְרָהָם, עַד שֶׁהִתְפַּלֵּל תְּפִלָּתוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר, ה' אֱלֹהֵי הַשָּׁמַיִם וְגוֹ', הוּא יִשְׁלַח מַלְאָכוֹ. וַדַּאי זֶה מַלְאַךְ הַבְּרִית כְּדֵי שֶׁיִּשְׁמֹר הַבְּרִית הַזּוֹ וְלֹא יִטָּמֵא בֵּין אוֹתָם הָעַמִּים.</p>\n<p>רַק אֶת בְּנִי לֹא תָשֵׁב שָׁמָּה. מָה הַטַּעַם? מִשּׁוּם שֶׁיָּדַע אַבְרָהָם שֶׁהִנֵּה בְּכֻלָּם לֹא הָיָה מִי שֶׁהִכִּיר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, רַק הוּא לְבַדּוֹ, וְלֹא רָצָה שֶׁיִּהְיֶה מְדוֹרוֹ שֶׁל יִצְחָק בֵּינֵיהֶם, אֶלָּא שֶׁיִּהְיֶה מְדוֹרוֹ עִמּוֹ, וְיִצְחָק יִלְמַד מִמֶּנּוּ תָּמִיד אֶת דֶּרֶךְ הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא יִסְטֶה יָמִינָה וּשְׂמֹאלָה, וְעַל כֵּן לֹא רָצָה אַבְרָהָם שֶׁמְּדוֹרוֹ שֶׁל יִצְחָק יִהְיֶה שָׁם.</p>\n<p>אָמַר רַבִּי יֵיסָא, וַדַּאי שֶׁזְּכוּתוֹ שֶׁל אַבְרָהָם הָיְתָה לִפְנֵי הָעֶבֶד הַהוּא, שֶׁהַיּוֹם הַהוּא יָצָא, וּבְאוֹתוֹ הַיּוֹם הִגִּיעַ לְעֵין הַמַּיִם, שֶׁכָּתוּב וָאָבֹא הַיּוֹם אֶל הָעָיִן. וְהִנֵּה פֵּרְשׁוּהָ.</p>"],[9522011272,"<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים קיט) גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךְ. כַּמָּה טִפְּשִׁים הָאֲנָשִׁים שֶׁלֹּא יוֹדְעִים וְלֹא מִסְתַּכְּלִים לְהִשְׁתַּדֵּל בַּתּוֹרָה, מִשּׁוּם שֶׁהַתּוֹרָה כָּל הַחַיִּים וְכָל הַחֵרוּת וְכָל הַטּוֹב בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. (החרות ההיא של העולם הזה ושל הבא היא) (נ\"א: החרות ההיא של העולם הבא היא החיים בעולם הזה) הַחַיִּים הֵם בָּעוֹלָם הַזֶּה, שֶׁיִּזְכּוּ לְיָמִים שְׁלֵמִים בָּעוֹלָם הַזֶּה, כְּמוֹ שֶׁנֶּאֱמַר (שמות כג) אֶת מִסְפַּר יָמֶיךְ אֲמַלֵּא. וּלְיָמִים אֲרֻכִּים בָּעוֹלָם הַבָּא, מִשּׁוּם שֶׁהֵם חַיִּים שְׁלֵמִים, הֵם חַיִּים שֶׁל שִׂמְחָה, חַיִּים בְּלִי עַצְבוּת, חַיִּים שֶׁהֵם חַיִּים. חֵרוּת בָּעוֹלָם הַזֶּה, חֵרוּת שֶׁל הַכֹּל. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, אֵין יְכוֹלִים לִשְׁלֹט עָלָיו כָּל הָעַמִּים שֶׁל הָעוֹלָם.</p>\n<p>וְאִם תֹּאמַר, אוֹתָם בְּנֵי הַשְּׁמָד? גְּזֵרָה הִיא מִלְמַעְלָה, כְּמוֹ רַבִּי עֲקִיבָא וַחֲבֵרָיו, וְכָךְ עָלְתָה בְּמַחֲשָׁבָה. חֵרוּת שֶׁל מַלְאַךְ הַמָּוֶת שֶׁלֹּא יָכוֹל לִשְׁלֹט עָלָיו, וְכָךְ זֶה וַדַּאי. שֶׁאִם אָדָם הָיָה נִדְבָּק בְּעֵץ הַחַיִּים, שֶׁהִיא הַתּוֹרָה, לֹא הָיָה גוֹרֵם מָוֶת לוֹ וּלְכָל הָעוֹלָם. וּמִשּׁוּם כָּךְ, כְּשֶׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹרָה לְיִשְׂרָאֵל, מַה כָּתוּב בָּהּ? חָרוּת עַל הַלֻּחֹת, וַהֲרֵי פֵּרְשׁוּהָ. וְאִלְמָלֵא הֵם לֹא חָטְאוּ וְעָזְבוּ אֶת עֵץ הַחַיִּים, לֹא הָיוּ גוֹרְמִים מָוֶת לָעוֹלָם כְּבַתְּחִלָּה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר, (תהלים פב) אֲנִי אָמַרְתִּי אֱלֹהִים אַתֶּם וּבְנֵי עֶלְיוֹן כֻּלְּכֶם. חִבַּלְתֶּם אֶת עַצְמְכֶם - אָכֵן כְּאָדָם תְּמוּתוּן וְגוֹ'. וְעַל כֵּן, כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, אֵין יָכוֹל לִשְׁלֹט עָלָיו הַנָּחָשׁ הָרָע הַהוּא שֶׁהֶחְשִׁיךְ אֶת הָעוֹלָם.</p>\n<p>אָמַר רַבִּי יֵיסָא, אִם כָּךְ, לָמָּה מֹשֶׁה מֵת? שֶׁאִם כָּךְ, כֵּיוָן שֶׁלֹּא חָטָא - לֹא יָמוּת! (ולמה ימות)? אָמַר לוֹ, וַדַּאי מֵת, אֲבָל לֹא שָׁלַט בּוֹ אָמַרְנוּ, אֶלָּא לֹא מֵת עַל יָדוֹ וְלֹא נִטְמָא בּוֹ, וְלֹא מֵת וַדַּאי. אֶלָּא נִדְבַּק בַּשְּׁכִינָה וְהָלַךְ לְחַיֵּי עוֹלָם.</p>\n<p>וְזְהִ נִקְרָא חַי, כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁכָּתוּב (שמואל ב כג) וּבְנָיָהוּ בֶּן יְהוֹיָדָע בֶּן אִישׁ חַי וְגוֹ'. וְעַל כֵּן, כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, יֵשׁ לוֹ חֵרוּת מִן הַכֹּל בָּעוֹלָם הַזֶּה מִשִּׁעְבּוּד שֶׁל שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. חֵרוּת בָּעוֹלָם הַבָּא, מִשּׁוּם שֶׁלֹּא יִתְבְּעוּ מִמֶּנּוּ דִּין בָּעוֹלָם הַהוּא כְּלָל.</p>\n<p>בֹּא רְאֵה כַּמָּה סוֹדוֹת עֶלְיוֹנִים יֵשׁ בַּתּוֹרָה, מִשּׁוּם כָּךְ כָּתוּב (משלי ג) יְקָרָה הִיא מִפְּנִינִים. כַּמָּה גְנָזִים טְמוּנִים יֵשׁ בָּהּ. וְעַל כֵּן, כְּשֶׁהִסְתַּכֵּל דָּוִד בָּרוּחַ שֶׁל הַחָכְמָה וְיָדַע כַּמָּה נִפְלָאוֹת יוֹצְאִים מִן הַתּוֹרָה. פָּתַח וְאָמַר (תהלים קיט) גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךְ.</p>"],[9522011273,"<p>בֹּא רְאֵה, וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְהִנֵּה רִבְקָה יֹצֵאת. יֹצֵאת? בָּאָה הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה יצֵאת? שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹצִיא אוֹתָהּ מִכָּל אוֹתָם בְּנֵי הָעִיר, שֶׁכֻּלָּם רְשָׁעִים, וְהִיא יוֹצֵאת מֵהַכְּלָל שֶׁלָּהֶם. וַתֵּרֶד הָעַיְנָה כָּתוּב בְּהֵ\"א, סוֹד הוּא שֶׁפָּגְשָׁה שָׁם אֶת בְּאֵר מִרְיָם, וּמִשּׁוּם כָּךְ כָּתוּב הָעַיְנָה בְּהֵ\"א, וְעָלוּ לָהּ הַמַּיִם.</p>\n<p>דָּבָר אַחֵר וְהִנֵּה רִבְקָה יֹצֵאת, כַּכָּתוּב יֹצְאֹת לִשְׁאֹב מָיִם. לָמָּה יוֹצְאוֹת וְלֹא הוֹלְכוֹת וְלֹא בָאוֹת? אֶלָּא מִשּׁוּם שֶׁטְּמוּנוֹת הָיוּ כָּל הַיּוֹם, וּבְאוֹתָהּ שָׁעָה יוֹצְאוֹת לִשְׁאֹב מַיִם. וְסִימָן לָקַח בְּיָדוֹ.</p>\n<p>בֹּא רְאֵה, כְּשֶׁהִגִּיעַ הָעֶבֶד לְחָרָן וּמָצָא אֶת רִבְקָה לְעֵת עֶרֶב, הָיָה זְמַן תְּפִלַּת הַמִּנְחָה. בְּאוֹתָהּ שָׁעָה שֶׁהִגִּיעַ יִצְחָק לְהִתְפַּלֵּל תְּפִלַּת מִנְחָה, בְּאוֹתָהּ שָׁעָה הִגִּיעַ הָעֶבֶד אֶל רִבְקָה. וּבַשָּׁעָה הַהִיא שֶׁהִגִּיעַ יִצְחָק לִתְפִלַּת מִנְחָה כְּבַתְּחִלָּה, הִגִּיעָה רִבְקָה אֵלָיו, שֶׁהַכֹּל יִמָּצֵא בִּמְקוֹמוֹ שֶׁצָּרִיךְ כָּרָאוּי, וְהַכֹּל הִגִּיעַ בְּסוֹד הַחָכְמָה, וְעַל כֵּן בָּא הָעֶבֶד לִבְאֵר הַמַּיִם, סוֹד הַכָּתוּב (שיר ד) מַעְיַן גַּנִּים בְּאֵר מַיִם חַיִּים וְנוֹזְלִים מִן לְבָנוֹן. וּבֵאַרְנוּהוּ, וְהַכֹּל הוּא סוֹד.</p>"],[9522011274,"<p>רַבִּי שִׁמְעוֹן בָּא לִטְבֶרְיָה וְהָיָה עִמּוֹ רַבִּי אַבָּא. אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אַבָּא, נֵלֵךְ, שֶׁהֲרֵי אָנוּ רָאִינוּ שֶׁאִישׁ אֶחָד יַגִּיעַ כָּעֵת אֵלֵינוּ וּדְבָרִים חֲדָשִׁים בְּפִיו, וְהֵם דִּבְרֵי תוֹרָה. אָמַר רַבִּי אַבָּא, הִנֵּה יָדַעְתִּי שֶׁבְּכָל מָקוֹם שֶׁמַּר הוֹלֵךְ, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵחַ לוֹ מַלְאָכִים טָסִים בִּכְנָפַיִם לְהִשְׁתַּעֲשֵׁעַ בּוֹ.</p>\n<p>בְּעוֹדָם הוֹלְכִים, הֵרִים רַבִּי שִׁמְעוֹן אֶת עֵינָיו, וְרָאָה אִישׁ שֶׁהָיָה רָץ וְהוֹלֵךְ. יָשְׁבוּ רַבִּי שִׁמְעוֹן וְרַבִּי אַבָּא. כְּשֶׁהִגִּיעַ אֲלֵיהֶם, אָמַר לוֹ רַבִּי שִׁמְעוֹן, מִי אַתָּה? אָמַר לוֹ, אֲנִי יְהוּדִי, וּבָאתִי מִקַּפּוֹטְקִיָּא, וַאֲנִי הָלַכְתִּי לְסִתְרוֹ (לאהל) שֶׁל בַּר יוֹחַאי, שֶׁנִּמְנוּ הַחֲבֵרִים בִּדְבָרִים יְדוּעִים וּשְׁלָחוּנִי אֵלָיו. אָמַר לוֹ, אֱמֹר בְּנִי. אָמַר לוֹ, אַתָּה בַּר יוֹחַאי? אָמַר לוֹ, אֲנִי בַּר יוֹחַאי.</p>\n<p>אָמַר לוֹ, הֲרֵי אָמַרְנוּ שֶׁלֹּא יַפְסִיק אָדָם בִּתְפִלָּתוֹ בֵּינוֹ לְבֵין הַכֹּתֶל, כַּכָּתוּב (ישעיה לח) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וְגוֹ'. וּמִי שֶׁמִּתְפַּלֵּל, אָסוּר לַעֲבֹר אַרְבַּע אַמּוֹת סָמוּךְ לוֹ, וּבֵאֲרוּ לְאַרְבַּע הָאַמּוֹת הַלָּלוּ לְכָל צַד, פְּרָט לְפָנָיו. וְאָמְרוּ שֶׁלֹּא יִתְפַּלֵּל אָדָם מֵאֲחוֹרֵי רַבּוֹ וְכוּ', וְנִמְנוּ בְּכָל הַדְּבָרִים הַלָּלוּ.</p>\n<p>פָּתַח וְאָמַר, (תהלים לט) שִׁמְעָה תְפִלָּתִי ה' וְשַׁוְעָתִי הַאֲזִינָה אֶל דִּמְעָתִי אַל תֶּחֱרַשׁ. מָה הַטַּעַם שִׁמְעָה וְלֹא שְׁמַע? בְּמָקוֹם אֶחָד כָּתוּב שְׁמַע ה' וְחָנֵּנִי וְגוֹ', וּבְמָקוֹם אַחֵר שִׁמְעָה. אֶלָּא בְּכָל מָקוֹם לִפְעָמִים שְׁמַע לְזָכָר, וְלִפְעָמִים שִׁמְעָה לִנְקֵבָה. שִׁמְעָה - כְּמוֹ שֶׁנֶּאֱמַר (שם יז) שִׁמְעָה ה' צֶדֶק וְגוֹ'. שְׁמַע - כְּמוֹ שֶׁנֶּאֱמַר (שם ל) שְׁמַע ה' וְחָנֵּנִי, (משלי א) שְׁמַע בְּנִי, (דברים כז) הַסְכֵּת וּשְׁמַע.</p>\n<p>וְכָאן שִׁמְעָה תְפִלָּתִי ה', מִשּׁוּם שֶׁזֶּה (שהיא) הַדַּרְגָּה שֶׁמְּקַבֶּלֶת כָּל הַתְּפִלּוֹת שֶׁל הָעוֹלָם. וַהֲרֵי שָׁנִינוּ שֶׁעוֹשֶׂה מֵהֶם עֲטָרָה וְשָׂם אוֹתָהּ בְּרֹאשׁ שֶׁל צַדִּיק חַי הָעוֹלָמִים, שֶׁכָּתוּב (משלי י) בְּרָכוֹת לְרֹאשׁ צַדִּיק, וְעַל כֵּן שִׁמְעָה תְפִלָּתִי ה'.</p>\n<p>שִׁמְעָה תְפִלָּתִי ה' - זוֹ תְפִלָּה שֶׁבְּלַחַשׁ. וְשַׁוְעָתִי הַאֲזִינָה - זוֹ תְפִלָּה שֶׁאָדָם מֵרִים קוֹלוֹ בְּצָרָתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שמות ב) וַתַּעַל שַׁוְעָתָם אֶל הָאֱלֹהִים. וּמַה זֶּה שַׁוְעָתָם? אֶלָּא שֶׁבִּתְפִלָּתוֹ מֵרִים קוֹלוֹ וְזוֹקֵף עֵינָיו לְמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כב) וְשׁוֹעַ אֶל הָהָר. וְהַתְּפִלָּה הַזּוֹ מְשַׁבֶּרֶת שְׁעָרִים וְדוֹפֶקֶת (ס\"א ודוחקת) אוֹתָם לְהַכְנִיס אֶת תְּפִלָּתוֹ. אֶל דִּמְעָתִי אַל תֶּחֱרַשׁ - זֹאת נִכְנֶסֶת לִפְנֵי הַמֶּלֶךְ וְאֵין שַׁעַר שֶׁעוֹמֵד לְפָנֶיהָ, וּלְעוֹלָם לֹא חָזְרוּ דְמָעוֹת רֵיקָם.</p>\n<p>עוֹד, הִנֵּה כָּתוּב כָּאן שָׁלֹשׁ דְּרָגוֹת: תְּפִלָּה, שַׁוְעָה, דִּמְעָה. כְּנֶגֶד אֵלּוּ שָׁלֹשׁ אֲחֵרִים: כִּי גֵר אָנֹכִי עִמָּךְ, אַחַר כָּךְ תּוֹשָׁב, אַחַר כָּךְ כְּכָל אֲבוֹתָי, עִקַּר הָעוֹלָם.</p>\n<p>בֹּא רְאֵה, תְּפִלָּה שֶׁל אָדָם מֵעֹמֶד, מִשּׁוּם שֶׁשְּׁתֵּי תְפִלּוֹת הֵן - אַחַת מִיֹּשֶׁב וְאַחַת מֵעֹמֶד, וְהֵן אַחַת כְּנֶגֶד שְׁתֵּי דְרָגוֹת - תְּפִלָּה שֶׁל יָד וּתְפִלָּה שֶׁל רֹאשׁ. כְּלַפֵּי יוֹם וָלַיְלָה, וְהַכֹּל אֶחָד. אַף כָּאן תְּפִלָּה מִיֹּשֶׁב כְּלַפֵּי תְפִלָּה שֶׁל יָד, לְתַקֵּן אוֹתָהּ כְּמוֹ (כמי) שֶׁמְּתַקֵּן אֶת הַכַּלָּה וּמְקַשֵּׁט אוֹתָהּ לְהַכְנִיסָהּ לַחֻפָּה, כָּךְ גַּם מְקַשְּׁטִים אוֹתָהּ בְּסוֹד הַמֶּרְכָּבָה וּמַחֲנוֹתֶיהָ, יוֹצֵר מְשָׁרְתִים וַאֲשֶׁר מְשָׁרְתָיו וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ וְכוּ'.</p>\n<p>וְעַל זֶה תְּפִלָּה מִיֹּשֶׁב. כֵּיוָן שֶׁנִּכְנֶסֶת לַמֶּלֶךְ הָעֶלְיוֹן וְהוּא בָּא לְקַבֵּל אוֹתָהּ, אָז אָנוּ עוֹמְדִים לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן, שֶׁהֲרֵי אָז (הדרגה) הַזָּכָר מִתְחַבֵּר עִם הַנְּקֵבָה, וּמִשּׁוּם כָּךְ לֹא יַפְסִיק בֵּין גְּאֻלָּה לִתְפִלָּה (וגאלה ותפלה הן שתי דרגות, הסוד של צדיק וצדק, יוסף ורחל).</p>\n<p>וּמִשּׁוּם שֶׁאָדָם עוֹמֵד לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן, נוֹטֵל אַרְבַּע אַמּוֹת לִתְפִלָּתוֹ, וֶהֱקִימוּהַ שֶׁבְּשִׁעוּר (ד\"א בשעור) הַסֶּרֶט חֶבֶל שֶׁל יוֹצֵר כֹּל. וְכָל מַה שֶּׁבָּא בְּצַד הַזָּכָר, צָרִיךְ לְאָדָם לַעֲמֹד בְּקִיּוּמוֹ וּמִזְדַּקֵּף (ס\"א ויזדקף). כְּמוֹ כֵן כְּשֶׁהוּא כּוֹרֵעַ, כּוֹרֵעַ בְּבָרוּךְ. וּכְשֶׁהוּא זוֹקֵף, זוֹקֵף בַּשֵּׁם, כְּדֵי לְהַרְאוֹת אֶת שֶׁבַח הַזָּכָר עַל הַנְּקֵבָה.</p>\n<p>וּבֹא וּרְאֵה, שֶׁהֲרֵי אָמַרְנוּ אַל יִתְפַּלֵּל אָדָם אֲחוֹרֵי רַבּוֹ, וְנִתְבָּאֵר, כַּכָּתוּב (דברים י) אֶת ה' אֱלֹהֶיךְ תִּירָא. אֶת - לִכְלֹל שֶׁצָּרִיךְ לִירָא מֵרַבּוֹ כְּמוֹרָא הַשְּׁכִינָה, וְיִרְאַת תַּלְמִיד הוּא רַבּוֹ. מִשּׁוּם כָּךְ בִּשְׁעַת הַתְּפִלָּה לֹא יָשִׂים אוֹתוֹ הַמּוֹרָא לְפָנָיו (ד\"א לתפלה), אֶלָּא אֶת מוֹרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ וְלֹא מוֹרָא אַחֵר.</p>\n<p>וּבֹא וּרְאֵה, אֶת תְּפִלַּת מִנְחָה תִּקֵּן יִצְחָק, וַדַּאי כְּמוֹ שֶׁתִּקֵּן אַבְרָהָם תְּפִלַּת הַבֹּקֶר כְּנֶגֶד אוֹתָהּ הַדַּרְגָּה שֶׁנִּדְבַּק בָּהּ. וְכֵן (כך) יִצְחָק תִּקֵּן תְּפִלַּת מִנְחָה כְּנֶגֶד אוֹתָהּ דַּרְגָּה שֶׁנִּדְבַּק בָּהּ. וְעַל כֵּן תְּפִלַּת מִנְחָה מִכַּאֲשֶׁר נוֹטָה הַשֶּׁמֶשׁ לָרֶדֶת בְּדַרְגָּתוֹ לְצַד מַעֲרָב.</p>\n<p>שֶׁהֲרֵי בְּטֶרֶם נָטָה הַשֶּׁמֶשׁ לְצַד מַעֲרָב, נִקְרָא יוֹם מִן הַבֹּקֶר עַד הַזְּמַן הַהוּא, שֶׁכָּתוּב (תהלים כב) חֶסֶד אֵל כָּל הַיּוֹם. וְאִם תֹּאמַר עַד חֲשֵׁכָה - בֹּא רְאֵה, שֶׁכָּתוּב (ירמיה ו) אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. כִּי פָנָה הַיּוֹם - כְּנֶגֶד תְּפִלַּת הַבֹּקֶר, שֶׁכָּתוּב חֶסֶד אֵל כָּל הַיּוֹם, שֶׁהֲרֵי אָז הַשֶּׁמֶשׁ הִיא לְצַד מִזְרָח. כֵּיוָן שֶׁנָּטָה הַשֶּׁמֶשׁ וְיָרַד לְצַד מַעֲרָב, הֲרֵי אָז הוּא זְמַן תְּפִלַּת הַמִּנְחָה, וּכְבָר פָּנָה הַיּוֹם וּבָאוּ צִלְלֵי עֶרֶב וְהִתְעוֹרֵר הַדִּין הַקָּשֶׁה בָּעוֹלָם.</p>\n<p>וּפָנָה הַיּוֹם שֶׁהִיא הַדַּרְגָּה שֶׁל חֶסֶד, וְנָטוּ צִלְלֵי עֶרֶב שֶׁהֵם הַדַּרְגָּה שֶׁל הַדִּין הַקָּשֶׁה, וְאָז נֶחֱרַב בֵּית הַמִּקְדָּשׁ וְנִשְׂרַף הַהֵיכָל. וְעַל כֵּן שָׁנִינוּ שֶׁיִּהְיֶה אָדָם זָהִיר בִּתְפִלַּת הַמִּנְחָה, שֶׁהוּא הַזְּמַן שֶׁשָּׁרוּי הַדִּין הַקָּשֶׁה בָּעוֹלָם.</p>\n<p>יַעֲקֹב תִּקֵּן תְּפִלַּת עַרְבִית, שֶׁהֲרֵי הוּא תִּקֵּן אוֹתָהּ וְזָן אוֹתָהּ בְּכָל מַה שֶּׁצָּרִיךְ, וַדַּאי שֶׁוָּא\"ו תִּקֵּן אֶת הֵ\"א, וְהֵ\"א נִזּוֹנֵית מִוָּא\"ו, שֶׁאֵין לָהּ אוֹר מִשֶּׁל עַצְמָהּ כְּלָל.</p>\n<p>וּמִשּׁוּם כָּךְ תְּפִלַּת עַרְבִית רְשׁוּת, שֶׁהֲרֵי נִכְלֶלֶת בִּתְפִלַּת הַיּוֹם כְּדֵי שֶׁתִּהְיֶה מְאִירָה, וְכָעֵת לֹא זֶה הַזְּמַן. וּבֵאַרְנוּ אוֹתָהּ, שֶׁהֲרֵי לֹא הִתְגַּלָּה אוֹר הַיּוֹם שֶׁיָּאִיר לָהּ, וְהִיא שׁוֹלֶטֶת בַּחֲשֵׁכָה עַד זְמַן חֲצוֹת הַלַּיְלָה, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן הָעֵדֶן, וְאָז הַזְּמַן שֶׁהָאָדָם יִשְׁתַּעֲשַׁע (וללמד) בַּתּוֹרָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, דָּוִד בָּא וְאָמַר שְׁלֹשֶׁת זְמַנֵּי הַתְּפִלּוֹת הַלָּלוּ, שֶׁכָּתוּב (תהלים נה) עֶרֶב וָבקֶר וְצָהֳרַיִם, הִנֵּה שְׁלֹשָׁה. וְהוּא לֹא הִתְפַּלֵּל אֶלָּא שְׁנַיִם מֵהֶם, שֶׁכָּתוּב אָשִׂיחָה וְאֶהֱמֶה, וְלֹא יוֹתֵר. זֶה לִתְפִלַּת הַבֹּקֶר - וְזֶה לִתְפִלַּת הַמִּנְחָה. מִשּׁוּם כָּךְ דִּיֵּק אָשִׂיחָה וְאֶהֱמֶה. בַּבֹּקֶר, שֶׁהִיא שְׁעַת הַחֶסֶד, מַסְפִּיק לוֹ בְּחֶסֶד בְּאָשִׂיחָה. וּבְמִנְחָה, שֶׁהִיא שְׁעַת הַדִּין הַקָּשֶׁה, צָרִיךְ הֶמְיָה, וּמִשּׁוּם כָּךְ וְאֶהֱמֶה. אַחַר כָּךְ כְּשֶׁנֶּחְלָק הַלַּיְלָה, הָיָה קָם לְשִׁירוֹת וְתִשְׁבָּחוֹת כָּרָאוּי, שֶׁכָּתוּב (תהלים סב) וּבַלַּיְלָה שִׁירֹה עִמִּי, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>קָם רַבִּי שִׁמְעוֹן וְהָלְכוּ. הָלַךְ אוֹתוֹ הָאִישׁ עִמּוֹ עַד טְבֶרְיָה. בְּעוֹדָם הוֹלְכִים, אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה, תְּפִלּוֹת כְּנֶגֶד תְּמִידִין תִּקְּנוּם הַחֲכָמִים שֶׁל אַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה, מִשּׁוּם שֶׁנִּמְצָאוֹת שְׁתַּיִם, שֶׁכָּתוּב (במדבר כח) אֶת הַכֶּבֶשׂ אֶחָד תַּעֲשֶׂה בַּבֹּקֶר וְאֶת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם, וְהֵם נִקְרָבִים בִּשְׁנֵי הַזְּמַנִּים הַלָּלוּ שֶׁל הַיּוֹם, שֶׁהֵם זְמַנֵּי הַתְּפִלָּה.</p>\n<p>אָמַר אוֹתוֹ הָאִישׁ, הֲרֵי בַּתְּחִלָּה הָאָבוֹת תִּקְּנוּ אֶת הַתְּפִלּוֹת הַלָּלוּ, וּמַה שֶּׁתִּקְּנוּ אַבְרָהָם וְיִצְחָק הוּא הָעִקָּר. וּמַה שֶּׁתִּקֵּן יַעֲקֹב שֶׁהוּא הַמְשֻׁבָּח שֶׁל הָאָבוֹת, לָמָּה הִיא רְשׁוּת וְלֹא עִקָּר כְּמוֹ אֵלּוּ?</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי נִתְבָּאֵר, אֲבָל בֹּא רְאֵה, שְׁנֵי הַזְּמַנִּים הַלָּלוּ שֶׁל שְׁתֵּי הַתְּפִלּוֹת אֵינָם אֶלָּא לְחַבֵּר אֶת יַעֲקֹב לְגוֹרָלוֹ. כֵּיוָן שֶׁהִתְחַבְּרוּ זֶה עִם זֶה, אֵינֶנוּ צְרִיכִים יוֹתֵר. שֶׁכֵּיוָן שֶׁנִּתְּנָה הָאִשָּׁה בֵּין שְׁתֵּי הַזְּרוֹעוֹת וּמִתְחַבֶּרֶת בַּגּוּף, לֹא צָרִיךְ יוֹתֵר, וְעַל כֵּן אָנוּ צְרִיכִים לְעוֹרֵר שְׁתֵּי הַזְּרוֹעוֹת בִּגְלַל שֶׁנִּתְּנָה בֵינֵיהֶם. כֵּיוָן שֶׁהִיא בֵּינֵיהֶם, הַגּוּף וְהָאִשָּׁה, אָז דִּבְרֵיהֶם בְּלַחַשׁ שֶׁלֹּא לְהַזְכִּיר.</p>\n<p>וּמִשּׁוּם כָּךְ, יַעֲקֹב מְשַׁמֵּשׁ בַּמָּרוֹם שָׁנִינוּ. מַה זֶּה בַּמָּרוֹם? כְּמוֹ שֶׁנֶּאֱמַר (תהלים צב) וְאַתָּה מָרוֹם לְעוֹלָם ה'. וְהַכֹּל הוּא סוֹד לְיוֹדְעֵי הַדִּין. בָּאוּ רַבִּי אַבָּא וְהַיְּהוּדִי הַהוּא וְנָשְׁקוּ אֶת יָדוֹ. אָמַר רַבִּי אַבָּא, עַד הַיּוֹם הַזֶּה לֹא לָמַדְתִּי בַּדָּבָר הַזֶּה, רַק עַכְשָׁו. אַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לִשְׁמֹעַ אוֹתוֹ.</p>"],[9522011275,"<p>וַיְבִאֶהָ יִצְחָק הָאֹהֱלָה שָׂרָה אִמּוֹ. אָמַר רַבִּי יוֹסֵי, הַפָּסוּק הַזֶּה קָשֶׁה. הָאֹהֱלָה? הָיָה צָרִיךְ לִהְיוֹת לְאֹהֶל שָׂרָה אִמּוֹ! מַה זֶּה הָאֹהֱלָה? שֶׁחָזְרָה לְשָׁם הַשְּׁכִינָה. מִשּׁוּם שֶׁכָּל זְמַן שֶׁשָּׂרָה הָיְתָה קַיֶּמֶת בָּעוֹלָם, לֹא זָזָה מִמֶּנָּה הַשְּׁכִינָה, וְנֵר הָיָה דוֹלֵק מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת וְהָיָה מֵאִיר אֶת כָּל אוֹתָם יְמוֹת הַשָּׁבוּעַ. אַחַר שֶׁמֵּתָה, כָּבָה אוֹתוֹ הַנֵּר. כֵּיוָן שֶׁבָּאָה רִבְקָה, חָזְרָה הַשְּׁכִינָה וְהִדְלִיקָה אֶת הַנֵּר. שָׂרָה אִמּוֹ - שֶׁדָּמְתָה לְשָׂרָה בְּכָל מַעֲשֶׂיהָ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, כְּמוֹ שֶׁדְּמוּתוֹ שֶׁל יִצְחָק הָיְתָה כִּדְמוּתוֹ שֶׁל אַבְרָהָם, וְכָל מִי שֶׁרָאָה אֶת יִצְחָק אָמַר זֶה וַדַּאי אַבְרָהָם שֶׁהוֹלִיד אֶת יִצְחָק - כָּךְ גַּם דְּמוּתָהּ שֶׁל רִבְקָה מַמָּשׁ הָיְתָה כִּדְמוּתָהּ שֶׁל שָׂרָה, וּמִשּׁוּם כָּךְ שָׂרָה אִמּוֹ וַדַּאי.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, בַּכֹּל כָּךְ זֶה, אֲבָל בּא רְאֵה, זֶהוּ סוֹד. שֶׁאַף עַל גַּב שֶׁשָּׂרָה מֵתָה, דְּמוּתָהּ לֹא זָזָה מִן הַבַּיִת, וְלֹא נִרְאֲתָה שָׁם מִיּוֹם שֶׁמֵּתָה עַד שֶׁבָּאָה רִבְקָה. כֵּיוָן שֶׁנִּכְנְסָה רִבְקָה, נִרְאֲתָה דְמוּתָהּ שֶׁל שָׂרָה, שֶׁכָּתוּב וַיְבִאֶהָ יִצְחָק הָאֹהֱלָה וְגוֹ'. מִיָּד שָׂרָה אִמּוֹ נִרְאֲתָה שָׁם. וְלֹא הָיָה רוֹאֶה, רַק יִצְחָק לְבַדּוֹ כְּשֶׁנִּכְנַס לְשָׁם, וְעַל כֵּן וַיִּנָּחֵם יִצְחָק אַחֲרֵי אִמּוֹ. (ס\"א מה זה אחרי אמו? אחרי) שֶׁאִמּוֹ נִרְאֲתָה וְהִזְדַּמְּנָה בַּבַּיִת, וְעַל כֵּן לֹא כָתוּב אַחֲרֵי מִיתַת אִמּוֹ, אֶלָּא אַחֲרֵי אִמּוֹ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, מַה שּׁוֹנֶה שֶׁכָּתוּב בְּיִצְחָק, וַיִּקַּח אֶת רִבְקָה וַתְּהִי לוֹ לְאִשָּׁה וַיֶּאֱהָבֶהָ? כֵּיוָן שֶׁאָמַר וַתְּהִי לוֹ לְאִשָּׁה, לֹא יָדַעְנוּ שֶׁהוּא אָהַב אוֹתָהּ? שֶׁהֲרֵי כָּל בְּנֵי הָעוֹלָם אוֹהֲבִים אֶת נְשׁוֹתֵיהֶם. מַה שּׁוֹנֶה בְּיִצְחָק שֶׁכָּתוּב בּוֹ וַיֶּאֱהָבֶהָ?</p>\n<p>אֶלָּא וַדַּאי הִתְעוֹרְרוּת שֶׁל הָאַהֲבָה שֶׁל הַזָּכָר לָאִשָּׁה אֵינָהּ אֶלָּא בִּשְׂמֹאל, שֶׁכָּתוּב (שיר א) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וְחֹשֶׁךְ וְלַיְלָה הֵם יַחַד, וְהַשְּׂמֹאל מְעוֹרֵר תָּמִיד אַהֲבָה לַנְּקֵבָה וְאוֹחֵז בָּהּ. וְעַל כֵּן, אַף עַל גַּב שֶׁאַבְרָהָם (ס\"א היה) אוֹהֵב אֶת שָׂרָה, לֹא כָתוּב בּוֹ וַיֶּאֱהָבֶהָ, אֶלָּא בְּיִצְחָק. וְאִם תֹּאמַר וַיֶּאֱהַב יַעֲקֹב אֶת רָחֵל - הַצַּד שֶׁל יִצְחָק שֶׁהָיָה בּוֹ עָשָׂה לוֹ.</p>\n<p>בֹּא רְאֵה, כְּשֶׁאַבְרָהָם רָאָה אֶת שָׂרָה (ס\"א את רבקה), הָיָה מְחַבֵּק אוֹתָהּ וְלֹא יוֹתֵר. אֲבָל יִצְחָק שֶׁהוּא בַּעְלָהּ, אָחַז בָּהּ וְשָׂם אֶת זְרוֹעוֹ תַּחַת רֹאשָׁהּ, שֶׁכָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. אַחַר כָּךְ בָּא יַעֲקֹב וְשִׁמֵּשׁ מִטָּתוֹ, וְהוֹלִיד שְׁנֵים עָשָׂר שְׁבָטִים, כֻּלָּם כָּרָאוּי.</p>\n<p>וּבֹא וּרְאֵה, כָּל הָאָבוֹת הָלְכוּ בְּסוֹד אֶחָד, וְכֻלָּם שִׁמְּשׁוּ בְּאַרְבַּע נָשִׁים כָּל אֶחָד מֵהֶם. אַבְרָהָם בְּאַרְבַּע - שָׂרָה וְהָגָר וּשְׁתֵּי פִּילַגְשִׁים, שֶׁכָּתוּב וְלִבְנֵי הַפִּילַגְשִׁים אֲשֶׁר לְאַבְרָהָם. פִּילַגִשִׁים - שְׁתַּיִם. הִנֵּה אַרְבַּע.</p>\n<p>יִצְחָקֹ בְּסוֹד שֶׁל אַרְבַּע שֶׁל הַצַּד שֶׁל רִבְקָה, שֶׁכָּתוּב וַיִּקַּח אֶת רִבְקָה - אֶחָד. וַתְּהִי לוֹ לְאִשָּׁה - שְׁתַּיִם. וַיֶּאֱהָבֶהָ - שָׁלֹשׁ. וַיִּנָּחֵם יִצְחָק אַחֲרֵי אִמּוֹ - הִנֵּה אַרְבַּע. כְּנֶגֶד זֶה הָיוּ לְיַעֲקֹב אַרְבַּע נָשִׁים. וְהַכֹּל בְּסוֹד אֶחָד.</p>\n<p>רַבִּי חִיָּיא אָמַר, אַבְרָהָם וְיִצְחָק שִׁמְּשׁוּ כָּל אֶחָד עִם אִשָּׁה אַחַת בְּסוֹד שֶׁל קֹדֶשׁ. אַבְרָהָם עִם שָׂרָה, יִצְחָק עִם רִבְקָה. דִּכְנֶגֶד שְׁנֵיהֶם הָיוּ אַרְבַּע נָשִׁים לְיַעֲקֹב בִּשְׁנֵי חֲלָקִים. רַבִּי שִׁמְעוֹן אָמַר, עָלוּ הַדְּבָרִים לִמְקוֹמָם, שֶׁהֲרֵי הַכֹּל נַעֲשָׂה בְּסוֹד קָדוֹשׁ, וְהַכֹּל בְּסוֹד אֶחָד.</p>"],[9522011276,"<p>וַיֹּסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה. קְטוּרָה זוֹ הִיא הָגָר. שֶׁהֲרֵי שָׁנִינוּ, אַחַר שֶׁנִּפְרְדָה הָגָר מֵאַבְרָהָם וְטָעֲתָה אַחַר גִּלּוּלֵי אָבִיהָ, אַחַר כָּךְ נִקְשְׁרָה לְמַעֲשִׂים כְּשֵׁרִים, וּמִשּׁוּם כָּךְ הִשְׁתַּנָּה שְׁמָהּ וְנִקְרְאָה קְטוּרָה בְּמַעֲשִׂים כְּשֵׁרִים, וְשָׁלַח אַבְרָהָם וְלָקַח אוֹתָהּ לְאִשָּׁה. מִכָּאן שֶׁשִּׁנּוּי שֵׁם מְכַפֵּר עַל חֲטָאִים, וְעַל כֵּן הִשְׁתַּנָּה שְׁמָהּ.</p>\n<p>וַיֹּסֶף אַבְרָהָם. מַה זֶּה וַיֹּסֶף? אִם תֹּאמַר שֶׁהוּא הוֹסִיף עַל שָׂרָה - לֹא כָּךְ! אֶלָּא בִּימֵי שָׂרָה הִזְדַּוֵּג עִמָּהּ פַּעַם אַחַת, וְאַחַר כָּךְ גֵּרַשׁ אוֹתָהּ עַל עִסְקֵי יִשְׁמָעֵאל, וְאַחַר כָּךְ וַיֹּסֶף, כְּמוֹ מִקֹּדֶם פַּעַם אַחֶרֶת עַל מַה שֶּׁנָּשָׂא אוֹתָהּ בָּרִאשׁוֹנָה. וּלְפִי שֶׁשִּׁנְּתָה מַעֲשֶׂיהָ, כָּךְ גַּם שִׁנָּה שְׁמָהּ.</p>\n<p>בֹּא רְאֵה, שֶׁאָמַר רַבִּי אֶלְעָזָר, וַיְבִאֶהָ יִצְחָק הָאֹהֱלָה שָׂרָה אִמּוֹ - שֶׁהִתְגַּלְּתָה דְמוּת שָׂרָה, וְיִצְחָק הִתְנַחֵם אַחֲרֵי שֶׁהִתְגַּלְּתָה אִמּוֹ וְאֶת דְּמוּתָהּ הָיָה רוֹאֶה כָּל יוֹם. וְאַבְרָהָם, אַף עַל גַּב שֶׁנָּשָׂא, לֹא נִכְנַס לְאוֹתוֹ הַבַּיִת, וְלֹא הִכְנִיס אֶת אוֹתָהּ הָאִשָּׁה לְשָׁם כְּדֵי שֶׁשִּׁפְחָה לֹא תִירַשׁ גְּבִרְתָּהּ. וּבְאֹהֶל שָׂרָה לֹא נִרְאֲתָה אִשָּׁה אַחֶרֶת, אֶלָּא רִבְקָה.</p>\n<p>וְאַף עַל גַּב שֶׁאַבְרָהָם הָיָה יוֹדֵעַ שֶׁדְּמוּתָהּ שֶׁל שָׂרָה נִגְלְתָה שָׁם, הִשְׁאִיר לְיִצְחָק אוֹתוֹ הָאֹהֶל, לִרְאוֹת אֶת הַדְּמוּת שֶׁל אִמּוֹ בְּכָל יוֹם. יִצְחָק וְלֹא אַבְרָהָם. זֶהוּ שֶׁכָּתוּב וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק. אֶת כָּל אֲשֶׁר לוֹ דַּוְקָא, זוֹ אוֹתָהּ הַדְּמוּת שֶׁל שָׂרָה בְּאוֹתוֹ הַמִּשְׁכָּן.</p>\n<p>דָּבָר אַחֵר וַיִתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק, סוֹד הָאֱמוּנָה הָעֶלְיוֹנָה שֶׁיִּדְבַּק יִצְחָק בְּדַרְגַּת חֶלְקוֹ כָּרָאוּי. בּא רְאֵה, כָּאן נִכְלְלוּ (מים עם אש) אֵשׁ עִם מַיִם. וַדַּאי אֵשׁ נוֹשֵׂא מַיִם. מַשְׁמָע וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק, זֶה הַמַּיִם שֶׁנִּכְלָלִים בָּאֵשׁ. וּבָרִאשׁוֹנָה נִכְלְלוּ יַחַד אֵשׁ וּמַיִם. מָתַי? בְּשָׁעָה שֶׁעָקַד אֶת יִצְחָק לַעֲשׂוֹת בּוֹ דִּין, אָז נִכְלְלָה הָאֵשׁ בַּמַּיִם. וְכָאן נִכְלְלוּ מַיִם בְּאֵשׁ, שֶׁהַכֹּל יִהְיֶה בְּסוֹד הָאֱמוּנָה הָעֶלְיוֹנָה.</p>"],[9522011277,"<p>וְלִבְנֵי הַפִּילַגְשִׁים אֲשֶׁר לְאַבְרָהָם נָתַן אַבְרָהָם מַתָּנוֹת. מַה זֶּה מַתָּנוֹת? אֵלּוּ הַצְּדָדִים הַדְּרָגוֹת הַתַּחְתּוֹנוֹת שֶׁהֵם שֵׁמוֹת שֶׁל צִדְדֵי רוּחַ הַטֻּמְאָה כְּדֵי לְהַשְׁלִים אֶת הַדְּרָגוֹת, וְהִתְעַלָּה יִצְחָק עַל הַכֹּל בָּאֱמוּנָה הָעֶלְיוֹנָה כָּרָאוּי.</p>\n<p>בְּנֵי הַפִּילַגְשִׁים - אֵלּוּ הָיוּ בְּנֵי קְטוּרָה. פִּילֶגֶשׁ בָּרִאשׁוֹנָה, וּפִילֶגֶשׁ כָּעֵת. רַבִּי חִיָּיא אָמַר, פִּילַגְשִׁים מַמָּשׁ. וַיְשַׁלְּחֵם מֵעַל יִצְחָק בְּנוֹ - שֶׁלֹּא לִשְׁלֹט אֵצֶל יִצְחָק. בְּעוֹדֶנּוּ חַי - בְּעוֹד שֶׁאַבְרָהָם הָיָה חַי וְקַיָּם בָּעוֹלָם, שֶׁלֹּא יִתְגָּרוּ בוֹ אַחַר כָּךְ, וּכְדֵי שֶׁיִּצְחָק יְתֻקַּן בְּצַד הַדִּין הַקָּשֶׁה הָעֶלְיוֹן שֶׁיִּתְגַּבֵּר עַל כֻּלָּם וְכֻלָּם יִכָּנְעוּ לְפָנָיו. קֵדְמָה אֶל אֶרֶץ קֶדֶם - מִשּׁוּם שֶׁשָּׁם הֵם צִדְדֵי הַכְּשָׁפִים הַטְּמֵאִים.</p>\n<p>בֹּא רְאֵה, כָּתוּב (מלכים א ה) וַתֵּרֶב חָכְמַת שְׁלֹמֹה מֵחָכְמַת כָּל בְּנֵי קֶדֶם. אֵלּוּ הֵם שֶׁהָיוּ מִבְּנֵי (הם) בְּנֵי פִּילַגְשִׁים שֶׁל אַבְרָהָם. וַהֲרֵי בֵּאַרְנוּ שֶׁהֲרֵי בְּאוֹתָם הַרֲרֵי קֶדֶם הֵם מְלַמְּדִים כְּשָׁפִים לִבְנֵי אָדָם, וּמֵאוֹתָהּ אֶרֶץ קֶדֶם יָצְאוּ לָבָן וּבְעוֹר וּבִלְעָם, וְכֻלָּם מְכַשְּׁפִים, וַהֲרֵי בֵּאֲרוּהוּ.</p>"],[9522011278,"<p>רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (ישעיה מב) מִי נָתַן לִמְשִׁסָּה יַעֲקֹב וְיִשְׂרָאֵל לְבזְזִים הֲלֹא ה' וְגוֹ'. בּא רְאֵה, מִזְּמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, הַבְּרָכוֹת לֹא שׁוֹרוֹת בָּעוֹלָם וְנִמְנָעוֹת, כִּבְיָכוֹל נִמְנָעוֹת מִמַּעְלָה וּמַטָּה, וְכָל אוֹתָן שְׁאָר הַדְּרָגוֹת הַתַּחְתּוֹנוֹת מִתְגַּבְּרוֹת וְהוֹלְכוֹת וְשׁוֹלְטוֹת עַל יִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם גָּרְמוּ בַּחֲטָאֵיהֶם.</p>\n<p>הַפָּסוּק הַזֶּה אֵין מִתְיַשְּׁבִים דְּבָרָיו, שֶׁכָּתוּב מִי נָתַן לִמְשִׁסָּה יַעֲקֹב. כֵּיוָן שֶׁאָמַר מִי נָתַן לִמְשִׁסָּה יַעֲקֹב וְיִשְׂרָאֵל, מַה זֶּה חָטָאנוּ לוֹ? הָיָה צָרִיךְ לִהְיוֹת חָטְאוּ לוֹ! וְאִם אָמַר חָטָאנוּ לוֹ, מַהוּ וְלֹא אָבוּ? וְלֹא אָבִינוּ צָרִיךְ לִהְיוֹת!</p>\n<p>אֶלָּא בְּשָׁעָה שֶׁנֶּחֱרַב הַמִּקְדָּשׁ וְנִשְׂרַף הַהֵיכָל וְהָעָם הָגְלָה, רָצְתָה הַשְּׁכִינָה לְהֵעָקֵר מִמְּקוֹמָהּ וְלָלֶכֶת עִמָּהֶם בַּגָּלוּת. אָמְרָה: אֵלֵךְ בָּרִאשׁוֹנָה לִרְאוֹת אֶת בֵּיתִי וְהֵיכָלִי, וְאֶפְקֹד אֶת מְקוֹמוֹת הַכֹּהֲנִים וְהַלְוִיִּם שֶׁהָיוּ עוֹבְדִים בְּבֵיתִי.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, בְּאוֹתָהּ שָׁעָה הִסְתַּכְּלָה כְּנֶסֶת יִשְׂרָאֵל לְמַעְלָה וְרָאֲתָה אֶת בַּעְלָהּ מִסְתַּלֵּק מִמֶּנָּה לְמַעְלָה לְמַעְלָה. יָרְדָה לְמַטָּה, נִכְנְסָה לַבַּיִת וְהִסְתַּכְּלָה בְּכָל אוֹתָם הַמְּקוֹמוֹת, וְנִשְׁמַע קוֹל לְמַעְלָה לְמַעְלָה, וְנִשְׁמַע קוֹל לְמַטָּה. זֶהוּ שֶׁכָּתוּב (ירמיה לא) קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַמְרוּרִים רָחֵל מְבַכָּה עַל בָּנֶיהָ וְגוֹ', וּבֵאֲרוּהָ.</p>\n<p>כֵּיוָן שֶׁנִּכְנְסָה לַגָּלוּת, הִסְתַּכְּלָה עַל הָעָם, וְרָאֲתָה שֶׁדּוֹחֲקִים אוֹתָם וְרוֹמְסִים אוֹתָם בַּגָּלוּת בֵּין רַגְלֵי שְׁאָר הָעַמִּים. אָז אָמְרָה: (ישעיה מב) מִי נָתַן לִמְשִׁסָּה יַעֲקֹב וְגוֹ'. וְהֵם אוֹמְרִים: הֲלֹא ה' זוּ חָטָאנוּ לוֹ. וְהִיא אוֹמֶרֶת: וְלֹא אָבוּ בִדְרָכָיו הָלוֹךְ וְלֹא שָׁמְעוּ בְּתוֹרָתוֹ.</p>\n<p>וּבְשָׁעָה שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִפְקֹד אֶת עַמּוֹ, כְּנֶסֶת יִשְׂרָאֵל תָּשׁוּב מִן הַגָּלוּת בָּרִאשׁוֹנָה. (אומר לה הקדוש ברוך הוא): תֵּלְכִי לַבַּיִת כְּדֵי שֶׁבֵּית הַמִּקְדָּשׁ יִבָּנֶה בַּהַתְחָלָה. וְיֹאמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: קוּמִי מִן הֶעָפָר. הִיא שָׁבָה וְאוֹמֶרֶת: לְאֵיזֶה מָקוֹם אֵלֵךְ? בֵּיתִי חָרֵב, וְהֵיכָלִי נִשְׂרַף בָּאֵשׁ. עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִבְנֶה אֶת בֵּית הַמִּקְדָּשׁ בָּרִאשׁוֹנָה וְיַתְקִין אֶת הַהֵיכָל וְיִבְנֶה אֶת קִרְיַת יְרוּשָׁלַיִם, וְאַחַר כָּךְ יָקִים אוֹתָהּ מִן הֶעָפָר. זֶהוּ שֶׁכָּתוּב (תהלים קמז) בּוֹנֵה יְרוּשָׁלַיִם ה' וְגוֹ'. בּוֹנֵה יְרוּשָׁלַיִם בָּרִאשׁוֹנָה, וְאַחַר כָּךְ נִדְחֵי יִשְׂרָאֵל יְכַנֵּס. וְיֹאמַר לָהּ: (ישעיה נב) הִתְנַעֲרִי מֵעָפָר קוּמִי שְׁבִי יְרוּשָׁלם וְגוֹ'. וִיכַנֵּס אֶת גָּלֻיּוֹת יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב בּוֹנֵה יְרוּשָׁלַיִם ה' - בָּרִאשׁוֹנָה, וְאַחַר כָּךְ - נִדְחֵי יִשְׂרָאֵל יְכַנֵּס. וְאָז הָרוֹפֵא לִשְׁבוּרֵי לֵב וּמְחַבֵּשׁ לְעַצְּבוֹתָם, זוֹ תְחִיַּת הַמֵּתִים, וְכָתוּב (יחזקאל לו) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם וְעָשִׂיתִי אֵת אֲשֶׁר בְּחֻקַּי תֵּלֵכוּ וְגוֹ'. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522011279,"<p>וְאֵלֶּה תּוֹלְדֹת יִצְחָק וְגוֹ'. פָּתַח רַבִּי חִיָּיא וְאָמַר, (תהלים קו) מִי יְמַלֵּל גְּבוּרוֹת ה' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ. בּא רְאֵה, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא וְעָלָה בְרָצוֹן לְפָנָיו לִבְרֹא אֶת הָעוֹלָם, הָיָה מִסְתַּכֵּל בַּתּוֹרָה וּבוֹרֵא אוֹתוֹ, וּבְכָל מַעֲשֶׂה וּמַעֲשֶׂה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, הָיָה מִסְתַּכֵּל בַּתּוֹרָה וּבוֹרֵא אוֹתוֹ. זֶהוּ שֶׁכָּתוּב (משלי ח) וָאֶהְיֶה אֶצְלוֹ אָמוֹן וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. אַל תִּקְרֵי אָמוֹן אֶלָּא אֻמָּן.</p>\n<p>כְּשֶׁרָצָה לִבְרֹא אָדָם, אָמְרָה הַתּוֹרָה לְפָנָיו: אִם הָאָדָם יִבָּרֵא וְאַחַר כָּךְ יֶחֱטָא וְאַתָּה תָּדוּן אוֹתוֹ, לָמָּה יִהְיוּ מַעֲשֵׂי יָדֶיךְ לְחִנָּם, שֶׁהֲרֵי לֹא יוּכַל לִסְבֹּל אֶת דִּינְךְ? אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: הִנֵּה תִּקַּנְתִּי תְשׁוּבָה טֶרֶם שֶׁבָּרָאתִי אֶת הָעוֹלָם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לָעוֹלָם בְּשָׁעָה שֶׁעָשָׂה אוֹתוֹ וּבָרָא אֶת הָאָדָם, אָמַר לוֹ: עוֹלָם, עוֹלָם, אַתָּה וְחֻקּוֹתֶיךְ לֹא יִתְקַיְּמוּ אֶלָּא עַל הַתּוֹרָה. וּמִשּׁוּם כָּךְ בָּרָאתִי בְךְ אֶת הָאָדָם, כְּדֵי שֶׁיִּתְעַסֵּק בָּהּ, וְאִם לֹא - הֲרֵינִי מַחֲזִירְךְ לְתֹהוּ וָבהוּ, וְהַכֹּל בִּשְׁבִיל הָאָדָם קַיָּם. זֶהוּ שֶׁכָּתוּב (ישעיה מה) אָנֹכִי עָשִׂיתִי אֶרֶץ וְאָדָם עָלֶיהָ בָּרָאתִי. וְהַתּוֹרָה עוֹמֶדֶת וּמַכְרִיזָה לִפְנֵי בְּנֵי אָדָם כְּדֵי שֶׁיִּתְעַסְּקוּ וְיִשְׁתַּדְּלוּ בָהּ, וְאֵין מִי שֶׁיַּרְכִּין אָזְנוֹ.</p>\n<p>בֹּא רְאֵה, כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, מְקַיֵּם הָעוֹלָם וּמְקַיֵּם כָּל מַעֲשֶׂה וּמַעֲשֶׂה עַל תִּקּוּנוֹ כָּרָאוּי, וְאֵין לְךְ כָּל אֵיבָר וְאֵיבָר בָּאָדָם שֶׁאֵין כְּנֶגְדּוֹ בְּרִיָּה בָּעוֹלָם. שֶׁהֲרֵי כְּמוֹ שֶׁאָדָם נֶחֱלָק לְאֵיבָרִים, וְכֻלָּם עוֹמְדִים דְּרָגוֹת עַל דְּרָגוֹת מְתֻקָּנִים אֵלּוּ עַל אֵלּוּ וְכֻלָּם גּוּף אֶחָד - כָּךְ גַּם הָעוֹלָם, כָּל אוֹתָם בְּרִיּוֹת כֻּלָּם אֵיבָרִים אֵיבָרִים וְעוֹמְדִים אֵלּוּ עַל אֵלּוּ, וְכַאֲשֶׁר כֻּלָּם מְתֻקָּנִים - הִנֵּה גוּף (אחד) מַמָּשׁ. וְהַכֹּל כְּמוֹ שֶׁהַתּוֹרָה. שֶׁהֲרֵי כָּל הַתּוֹרָה אֵיבָרִים וּפְרָקִים וְעוֹמְדִים אֵלּוּ עַל אֵלּוּ, וּכְשֶׁכֻּלָּם נִתְקָנִים - נַעֲשִׂים גּוּף אֶחָד. כֵּיוָן שֶׁדָּוִד הִסְתַּכֵּל בַּמַּעֲשֶׂה הַזֶּה, פָּתַח וְאָמַר, (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְאָה הָאָרֶץ קִנְיָנֶךְ.</p>\n<p>בַּתּוֹרָה כָּל הַסּוֹדוֹת עֶלְיוֹנִים חֲתוּמִים שֶׁלֹּא יְכוֹלִים לְהַשִּׂיג. בַּתּוֹרָה כָּל אוֹתָם דְּבָרִים עֶלְיוֹנִים שֶׁהִתְגַּלּוּ וְלֹא הִתְגַּלּוּ. בַּתּוֹרָה הֵם כָּל הַדְּבָרִים שֶׁלְּמַעְלָה וּלְמַטָּה. כָּל הַדְּבָרִים שֶׁל הָעוֹלָם הַזֶּה וְכָל הַדְּבָרִים שֶׁל הָעוֹלָם הַבָּא הֵם בַּתּוֹרָה, וְאֵין מִי שֶׁמַּשְׁגִּיחַ וּמַכִּיר אוֹתָם. וּמִשּׁוּם כָּךְ כָּתוּב (תהלים קו) מִי יְמַלֵּל גְּבוּרוֹת ה' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ.</p>\n<p>בֹּא רְאֵה, בָּא שְׁלֹמֹה וּבִקֵּשׁ לַעֲמֹד עַל דִּבְרֵי הַתּוֹרָה וְעַל דִּקְדּוּקֵי הַתּוֹרָה וְלֹא יָכֹל. אָמַר, אָמַרְתִּי אֶחְכָּמָה וְהִיא רְחוֹקָה מִמֶּנִּי. דָּוִד אָמַר, (תהלים קיט) גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךְ. בֹּא רְאֵה, כָּתוּב בִּשְׁלֹמֹה (מלכים א ה) וַיְדַבֵּר שְׁלֹשֶׁת אֲלָפִים מָשָׁל וַיְהִי שִׁירוֹ חֲמִשָּׁה וָאָלֶף. וַהֲרֵי בֵּאֲרוּהוּ שֶׁחֲמִשָּׁה וְאֶלֶף טְעָמִים הָיוּ בְּכָל מָשָׁל וּמָשָׁל שֶׁהָיָה אוֹמֵר. וּמַה שְּׁלֹמֹה, שֶׁהוּא בָּשָׂר וָדָם, כָּךְ הָיוּ בִּדְבָרָיו - דִּבְרֵי הַתּוֹרָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אַחַת כַּמָּה וְכַמָּה שֶׁבְּכָל דָּבָר וְדָבָר יֵשׁ בּוֹ כַּמָּה מְשָׁלִים, כַּמָּה שִׁירִים, כַּמָּה תִשְׁבָּחוֹת, כַּמָּה סוֹדוֹת עֶלְיוֹנִים, כַּמָּה חָכְמוֹת, וְעַל כֵּן כָּתוּב מִי יְמַלֵּל גְּבוּרוֹת ה'.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב לְמַעְלָה, וְאֵלֶּה תֹּלְדת יִשְׁמָעֵאל. שֶׁהֵם שְׁנֵים עָשָׂר נְשִׂיאִים. אַחַר כָּךְ אָמַר וְאֵלֶּה תּוֹלְדת יִצְחָק. הֲתַעֲלֶה עַל דַּעְתְּךְ שֶׁכָּתוּב בּוֹ בְּיִשְׁמָעֵאל שֶׁהוֹלִיד שְׁנֵים עָשָׂר נְשִׂיאִים וְיִצְחָק הוֹלִיד שְׁנֵי בָנִים, שֶׁזֶּה הִתְעַלָּה וְזֶה לֹא הִתְעַלָּה? עַל כֵּן כָּתוּב מִי יְמַלֵּל גְּבוּרוֹת ה'. זֶה יִצְחָק. וְיִצְחָק הוֹצִיא אֶת יַעֲקֹב, שֶׁהוּא הָיָה לְבַדּוֹ יוֹתֵר מִכֻּלָּם, שֶׁהוֹלִיד שְׁנֵים עָשָׂר שְׁבָטִים, הַקִּיּוּם שֶׁל מַעְלָה וּמַטָּה. אֲבָל יִצְחָק לְמַעְלָה בִּקְדֻשָּׁה עֶלְיוֹנָה, (וישמעאל) וְעֵשָׂו לְמַטָּה, וְעַל כֵּן כָּתוּב מִי יְמַלֵּל גְּבוּרוֹת ה' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ. זֶה יַעֲקֹב. כְּשֶׁנִּדְבַּק הַשֶּׁמֶשׁ בַּלְּבָנָה, כַּמָּה כּוֹכָבִים מְאִירִים מֵהֶם.</p>\n<p>וְאֵלֶּה תּוֹלְדת יִצְחָק בֶּן אַבְרָהָם. אָמַר רַבִּי יוֹסֵי, מַה שּׁוֹנֶה שֶׁעַד כָּאן לֹא כָתוּב בֶּן אַבְרָהָם וְכָעֵת אָמַר? אֶלָּא אַף עַל גַּב שֶׁכָּתוּב וַיְבָרֶךְ אֱלֹהִים אֶת יִצְחָק בְּנוֹ, כָּעֵת שֶׁמֵּת אַבְרָהָם, דְּמוּתוֹ הָיְתָה בּוֹ, וְנִשְׁאֲרָה בְּיִצְחָק. שֶׁכָּל מִי שֶׁרָאָה אֶת יִצְחָק, הָיָה אוֹמֵר זֶה וַדַּאי אַבְרָהָם, וְהָיָה מֵעִיד וְאוֹמֵר, אַבְרָהָם הוֹלִיד אֶת יִצְחָק.</p>\n<p>רַבִּי יִצְחָק קָם לַיְלָה אֶחָד לַעֲסֹק בַּתּוֹרָה, וְרַבִּי יְהוּדָה קָם בְּקֵיסַרְיָה בַּשָּׁעָה הַהִיא. אָמַר רַבִּי יְהוּדָה, אָקוּם וְאֵלֵךְ לְרַבִּי יִצְחָק, וְאֶעֱסֹק בַּתּוֹרָה וְנִתְחַבֵּר יַחַד. הָלַךְ עִמּוֹ חִזְקִיָּה בְּנוֹ, שֶׁהָיָה יֶלֶד. כְּשֶׁקָּרַב לַשַּׁעַר, שָׁמַע אֶת רַבִּי יִצְחָק שֶׁהָיָה אוֹמֵר, וַיְהִי אַחֲרֵי מוֹת אַבְרָהָם וַיְבָרֶךְ אֱלֹהִים אֶת יִצְחָק בְּנוֹ וַיֵּשֶׁב יִצְחָק עִם בְּאֵר לַחַי רֹאִי. הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ, וְאֵין סוֹפוֹ רֹאשׁוֹ. מַה שּׁוֹנֶה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֻצְרַךְ לְבָרֵךְ אֶת יִצְחָק מִשּׁוּם שֶׁאַבְרָהָם לֹא בֵרַךְ אוֹתוֹ? מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא יִתְבָּרֵךְ עֵשָׂו, וְעַל כֵּן עָלוּ אוֹתָן בְּרָכוֹת לַקָּבָּ\"ה, וּבֵאֲרוּהוּ. וַיֵּשֶׁב יִצְחָק עִם בְּאֵר לַחַי רֹאִי, מַה זֶּה לַחַי רֹאִי? אֶלָּא שֶׁהִתְחַבֵּר עִם הַשְּׁכִינָה, הַבְּאֵר שֶׁל מַלְאַךְ הַבְּרִית נִרְאָה עָלֶיהָ כְּתַרְגּוּמוֹ, וּמִשּׁוּם כָּךְ בֵּרְכוֹ.</p>\n<p>בֵּינְתַיִם דָּפַק רַבִּי יְהוּדָה בַּשַּׁעַר וְנִכְנַס, וְהִתְחַבְּרוּ. אָמַר רַבִּי יִצְחָק, כָּעֵת זִוּוּג הַשְּׁכִינָה עִמָּנוּ. אָמַר רַבִּי יְהוּדָה, הַבְּאֵר לַחַי רֹאִי הַזּוֹ שֶׁאָמַרְתָּ - יָפֶה, אֲבָל בַּדָּבָר נִשְׁמָע. פָּתַח וְאָמַר, (שיר ד) מַעְיַן גַּנִּים בְּאֵר מַיִם חַיִּים וְנֹזְלִים מִן לְבָנוֹן. הַפָּסוּק הַזֶּה נִתְבָּאֵר, אֲבָל הִנֵּה פֵּרְשׁוּהוּ, מַעְיַן גַּנִּים - זֶה אַבְרָהָם. בְּאֵר מַיִם חַיִּים - זֶה יִצְחָק. וְנֹזְלִים מִן לְבָנוֹן - זֶה יַעֲקֹב. בְּאֵר מַיִם חַיִּים זֶה יִצְחָק, הַיְינוּ שֶׁכָּתוּב וַיֵּשֶׁב יִצְחָק עִם בְּאֵר לַחַי רֹאִי. וּמָה הַבְּאֵר? זוֹ הַשְּׁכִינָה. לַחַי - זֶה חַי הָעוֹלָמִים, צַדִּיק חַי הָעוֹלָמִים, וְאֵין לְהַפְרִיד אוֹתָם. חַי הוּא בִּשְׁנֵי עוֹלָמוֹת. חַי לְמַעְלָה, שֶׁהוּא הָעוֹלָם הָעֶלְיוֹן. חַי כְּלַפֵּי הָעוֹלָם הַתַּחְתּוֹן. וְהָעוֹלָם הַתַּחְתּוֹן בִּשְׁבִילוֹ קַיָּם וּמֵאִיר.</p>\n<p>בֹּא רְאֵה, הַלְּבָנָה לֹא מְאִירָה אֶלָּא כְּשֶׁרוֹאָה אֶת הַשֶּׁמֶשׁ, וְכֵיוָן שֶׁרוֹאָה אוֹתוֹ - מְאִירָה. וְעַל כֵּן בְּאֵר לַחַי רֹאִי הַזּוֹ וַדַּאי, וְאָז מְאִירָה וְעוֹמֶדֶת בְּמַיִם חַיִּים. לַחַי רֹאִי, כְּדֵי לְהִתְמַלֵּא וְלִהְיוֹת מְאִירָה מֵהַחַי הַזֶּה.</p>\n<p>בֹּא רְאֵה, כָּתוּב (שמואל ב כז) וּבְנָיָהוּ בֶּן יְהוֹיָדָע בֶּן אִישׁ חַי, שֶׁהָיָה צַדִּיק וְהֵאִיר לְדוֹרוֹ, כְּמוֹ הַחַי שֶׁלְּמַעְלָה מֵאִיר לָעוֹלָם, וּבְכָל זְמַן הַבְּאֵר הַזּוֹ לַחַי מִסְתַּכֶּלֶת וְרוֹאָה כְּדֵי לְהָאִיר, כְּמוֹ שֶׁאָמַרְנוּ. וַיֵּשֶׁב יִצְחָק עִם בְּאֵר לַחַי רֹאִי, הַיְנוּ שֶׁכָּתוּב בְּקַחְתּוֹ אֶת רִבְקָה, וְיַּשָׁב עִמָּהּ וְהִתְאַחֵד עִמָּהּ, חֹשֶׁךְ בַּלַּיְלָה, שֶׁכָּתוּב (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וּבא וּרְאֵה, יִצְחָק הָיָה בְּקִרְיַת אַרְבַּע אַחֲרֵי שֶׁמֵּת אַבְרָהָם. מַה זֶּה וַיֵּשֶׁב יִצְחָק עִם בְּאֵר לַחַי רֹאִי? שֶׁהִזְדַּוֵּג עִמָּהּ, וְאָחַז בְּאוֹתָהּ הַבְּאֵר לְעוֹרֵר הָאַהֲבָה, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>פָּתַח רַבִּי יִצְחָק וְאָמַר, (קהלת א) וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ וְאֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ הוּא שָׁם. וְזָרַח הַשֶּׁמֶשׁ - זֶה הַשֶּׁמֶשׁ שֶׁמֵּאִיר לַלְּבָנָה. שֶׁכַּאֲשֶׁר נִרְאֶה עִמָּהּ, אָז מְאִירָה, וּמֵאִיר וְזוֹרֵחַ מִמָּקוֹם עֶלְיוֹן שֶׁעוֹמֵד עָלָיו, מִשָּׁם זוֹרֵחַ תָּמִיד. וּבָא הַשָּׁמֶשׁ - לְהִזְדַּוֵּג עִם הַלְּבָנָה. הוֹלֵךְ אֶל דָּרוֹם - שֶׁהוּא הַיָּמִין, וְשָׂם בּוֹ אֶת כֹּחוֹ. וּמִשּׁוּם שֶׁכֹּחוֹ בּוֹ, כָּל כֹּחַ הַגּוּף הוּא בְּיָמִין וּבוֹ הוּא תָלוּי. אַחַר כָּךְ סוֹבֵב אֶל צָפוֹן. מֵאִיר לְצַד זֶה וּמֵאִיר לְצַד זֶה. סוֹבֵב סֹבֵב הוֹלֵךְ הָרוּחַ. בָּרִאשׁוֹנָה כָּתוּב שֶׁמֶשׁ, וְכָעֵת רוּחַ? אֶלָּא הַכֹּל אֶחָד וְסוֹד אֶחָד, וְכָל זֶה מִשּׁוּם שֶׁהַלְּבָנָה מוּאֶרֶת מִמֶּנּוּ וְיִתְחַבְּרוּ שְׁנֵיהֶם.</p>\n<p>בֹּא רְאֵה, כְּשֶׁאַבְרָהָם בָּא לָעוֹלָם, חִבֵּק אֶת הַלְּבָנָה וְקֵרַב אוֹתָהּ. כֵּיוָן שֶׁבָּא יִצְחָק, אָחַז בָּהּ וְהֶחֱזִיק בָּהּ כָּרָאוּי וּמָשַׁךְ אוֹתָהּ בְּאַהֲבָה, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. כֵּיוָן שֶׁבָּא יַעֲקֹב, אָז הִתְחַבֵּר הַשֶּׁמֶשׁ עִם הַלְּבָנָה וְהֵאִירָה, וְנִמְצָא יַעֲקֹב שָׁלֵם בְּכָל הַצְּדָדִים, וְהַלְּבָנָה הֵאִירָה וְנִתְקְנָה בִּשְׁנֵים עָשָׂר שְׁבָטִים.</p>\n<p>פָּתַח רַבִּי יְהוּדָה וְאָמַר, (תהלים קלד) הִנֵּה בָּרְכוּ אֶת ה' כָּל עַבְדֵי ה' וְגוֹ'. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ. אֲבָל בֹּא רְאֵה, הִנֵּה בָּרְכוּ אֶת ה', וּמִי הֵם שֶׁרְאוּיִים לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא? כָּל עַבְדֵי ה', מִשּׁוּם שֶׁכָּל אָדָם בָּעוֹלָם מִיִּשְׂרָאֵל, אַף עַל גַּב שֶׁכֻּלָּם רְאוּיִים לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, הַבְּרָכָה שֶׁבִּשְׁבִילָם יִתְבָּרְכוּ הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים מַה הִיא? אוֹתָהּ שֶׁמְּבָרְכִים אוֹתוֹ עַבְדֵי ה', וְלֹא כֻלָּם. וּמִי הֵם שֶׁבִּרְכָתָם בְּרָכָה? הָעֹמְדִים בְּבֵית ה' בַּלֵּילוֹת. אֵלֶּה הֵם שֶׁעוֹמְדִים בַּחֲצוֹת הַלַּיְלָה וּמִתְעוֹרְרִים לִקְרֹא בַּתּוֹרָה, אֵלּוּ עוֹמְדִים בְּבֵית ה' בַּלֵּילוֹת, שֶׁהֲרֵי אָז בָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן. וְאָנוּ עוֹמְדִים כָּאן לְהִתְעוֹרֵר בְּדִבְרֵי תוֹרָה, נֹאמַר בְּדִבְרֵי יִצְחָק, שֶׁאָנוּ בּוֹ.</p>"],[9522011280,"<p>פָּתַח רַבִּי יִצְחָק וְאָמַר, וַיְהִי יִצְחָק בֶּן אַרְבָּעִים שָׁנָה בְּקַחְתּוֹ אֶת רִבְקָה וְגוֹ'. בֶּן אַרְבָּעִים שָׁנָה, לָמָּה בָּא לִמְנוֹת כָּאן שֶׁהָיָה בֶּן אַרְבָּעִים שָׁנָה כְּשֶׁנָּשָׂא אֶת רִבְקָה? אֶלָּא וַדַּאי הֲרֵי נִכְלָל יִצְחָק בְּצָפוֹן וְדָרוֹם, בְּאֵשׁ וּמַיִם, וְאָז הָיָה יִצְחָק בֶּן אַרְבָּעִים שָׁנָה בְּקַחְתּוֹ אֶת רִבְקָה. כְּמַרְאֵה הַקֶּשֶׁת, יָרֹק לָבָן אָדם. בַּת שָׁלֹשׁ שָׁנִים אָחַז בָּהּ כְּשֶׁאָחַז בָּהּ בְּרִבְקָה, וּכְשֶׁהוֹלִיד, הוֹלִיד בֶּן שִׁשִּׁים, לְהוֹלִיד כָּרָאוּי, כְּדֵי שֶׁיֵּצֵא יַעֲקֹב שָׁלֵם מִבֶּן שִׁשִּׁים שָׁנָה כָּרָאוּי. וְאֶת כֻּלָּם אָחַז יַעֲקֹב אַחַר כָּךְ וְנַעֲשָׂה אִישׁ שָׁלֵם.</p>\n<p>בַּת בְּתוּאֵל הָאֲרַמִּי מִפַּדַּן אֲרָם אֲחוֹת לָבָן הָאֲרַמִּי, מָה אִכְפַּת לָנוּ כָּל זֶה, שֶׁהֲרֵי כְּבָר נֶאֱמַר וּבְתוּאֵל יָלַד אֶת רִבְקָה וְגוֹ', וְכָעֵת אָמַר בַּת בְּתוּאֵל הָאֲרַמִּי, וְאַחַר כָּךְ מִפַּדַּן אֲרָם, וְאַחַר כָּךְ אֲחוֹת לָבָן הָאֲרַמִּי? אֶלָּא פֵּרְשׁוּהָ, שֶׁהָיְתָה בֵּין רְשָׁעִים, וְהִיא לֹא עָשְׂתָה כְּמַעֲשֵׂיהֶם. שֶׁהָיְתָה בַּת בְּתוּאֵל, וּמִפַּדַּן אֲרָם, וַאֲחוֹת לָבָן, וְכֻלָּם הָיוּ רְשָׁעִים לְהָרַע, וְהִיא הֶעֶלְתָה מַעֲשִׂים כְּשֵׁרִים וְלֹא עָשְׂתָה כְמַעֲשֵׂיהֶם.</p>\n<p>עַכְשָׁו יֵשׁ לְהִסְתַּכֵּל, אִם רִבְקָה הָיְתָה בַּת עֶשְׂרִים שָׁנָה אוֹ יוֹתֵר, אוֹ בַּת שְׁלֹשׁ עֶשְׂרֵה, אָז הוּא הַשֶּׁבַח שֶׁלָּהּ שֶׁלֹּא עָשְׂתָה כְּמַעֲשֵׂיהֶם, אֲבָל עַד עַתָּה הָיְתָה בַּת שָׁלֹשׁ שָׁנִים, אָז מָה הַשֶּׁבַח שֶׁלָּהּ? אָמַר רַבִּי יְהוּדָה, בַּת שָׁלֹשׁ שָׁנִים הָיְתָה, וְעָשְׂתָה לָעֶבֶד אֶת כָּל אוֹתוֹ הַמַּעֲשֶׂה.</p>\n<p>אָמַר רַבִּי יִצְחָק, אַף עַל גַּב שֶׁכָּל זֶה עָשְׂתָה, לֹא יָדַעְנוּ הַאִם מַעֲשֶׂיהָ כְּשֵׁרִים אוֹ לֹא. אֶלָּא בֹּא רְאֵה, כָּתוּב כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים כֵּן רַעְיָתִי בֵּין הַבָּנוֹת. כְּשׁוֹשַׁנָּה - זוֹ כְּנֶסֶת יִשְׂרָאֵל. שֶׁהִיא בֵּין אוּכְלוּסֶיהָ כְּמוֹ שׁוֹשַׁנָּה בֵּין קוֹצִים, וְסוֹד הַדָּבָר - יִצְחָק בָא מֵהַצַּד שֶׁל אַבְרָהָם שֶׁהוּא חֶסֶד עֶלְיוֹן, וְעוֹשֶׂה חֶסֶד עִם כָּל הַבְּרִיּוֹת, וְאַף עַל גַּב שֶׁהוּא הַדִּין הַקָּשֶׁה. וְרִבְקָה בָּאָה מִצַּד שֶׁל הַדִּין הַקָּשֶׁה, וְהִתְעַלְּתָה מִבֵּינֵיהֶם, וְהִתְחַבְּרָה עִם יִצְחָק. שֶׁהֲרֵי רִבְקָה בָּאָה מִצַּד הַדִּין הַקָּשֶׁה, וְאַף עַל גַּב שֶׁהָיְתָה מִצַּד הַדִּין הָרָפֶה וְחוּט שֶׁל חֶסֶד תָּלוּי בָּהּ, וְיִצְחָק דִּין קָשֶׁה וְהִיא רָפֶה - הָיוּ כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים. וְאִם לֹא שֶׁהִיא רָפֶה, לֹא יָכוֹל הָעוֹלָם לִסְבֹּל אֶת הַדִּין הַקָּשֶׁה שֶׁל יִצְחָק. כְּמוֹ כֵן הַקָּדוֹשׁ בָּרוּךְ הוּא מְזַוֵּג זִוּוּגִים בָּעוֹלָם, אֶחָד תַּקִּיף וְאֶחָד רָפֶה, כְּדֵי שֶׁהַכֹּל יִתְתַּקֵּן וְיִתְבַּסֵּם הָעוֹלָם.</p>"],[9522011281,"<p>פָּתַח רַבִּי יְהוּדָה אַחֲרָיו וְאָמַר, וַיֶּעְתַּר יִצְחָק לַה' לְנֹכַח אִשְׁתּוֹ, מַהוּ וַיֶּעְתַּר? שֶׁהִקְרִיב לוֹ קָרְבָּן וְהִתְפַּלֵּל עָלֶיהָ. וְאֵיזֶה קָרְבָּן הִקְרִיב? הִקְרִיב עוֹלָה, שֶׁכָּתוּב וַיֵּעָתֶר לוֹ ה'. כָּתוּב כָּאן וַיֵּעָתֶר לוֹ ה', וְכָתוּב שָׁם (שמואל ב כא) וַיֵּעָתֵר אֱלֹהִים לָאָרֶץ וְגוֹ'. מַה לְּהַלָּן קָרְבָּן - אַף כָּאן קָרְבָּן. כָּתוּב וַיֶּעְתַּר יִצְחָק, וְכָתוּב וַיֵּעָתֶר לוֹ. שֶׁיָּצְאָה אֵשׁ מִלְמַעְלָה כְּנֶגֶד הָאֵשׁ שֶׁלְּמַטָּה.</p>\n<p>דָּבָר אַחֵר וַיֶּעְתַּר יִצְחָק - שֶׁהִתְפַּלֵּל תְּפִלָּתוֹ וְחָתַר חֲתִירָה לְמַעְלָה אֶל הַמַּזָּל שֶׁעַל הַבָּנִים, שֶׁהֲרֵי בְּאוֹתוֹ מָקוֹם תְּלוּיִים הַבָּנִים, שֶׁכָּתוּב וַתִּתְפַּלֵּל עַל ה', וְאָז וַיֵּעָתֶר לוֹ ה'. אַל תִּקְרֵי וַיֵּעָתֶר לוֹ אֶלָּא וַיַּחְתֹּר לוֹ. חֲתִירָה חָתַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְקִבֵּל אוֹתוֹ, וְאָז - וַתַּהַר רִבְקָה אִשְׁתּוֹ.</p>\n<p>בֹּא רְאֵה, עֶשְׂרִים שָׁנָה הִשְׁתַּהָה יִצְחָק עִם אִשְׁתּוֹ וְלֹא הוֹלִידָה, עַד שֶׁהִתְפַּלֵּל תְּפִלָּתוֹ. מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בִּתְפִלּוֹת הַצַּדִּיקִים בְּשָׁעָה שֶׁמְּבַקְשִׁים לְפָנָיו אֶת תְּפִלָּתָם עַל מַה שֶּׁהִצְטָרְכוּ. מָה הַטַּעַם? כְּדֵי שֶׁיִּתְרַבֶּה וְיִתּוֹסֵף מִשְׁחַת קֹדֶשׁ לְכָל מִי שֶׁצָּרִיךְ בִּתְפִלּוֹת הַצַּדִּיקִים.</p>\n<p>בֹּא רְאֵה, אַבְרָהָם לֹא הִתְפַּלֵּל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּתֵּן לוֹ בָּנִים, אַף עַל גַּב שֶׁשָּׂרָה הָיְתָה עֲקָרָה. וְאִם תֹּאמַר, הֲרֵי כָּתוּב הֵן לִי לֹא נָתַתָּה זָרַע - הַהוּא לֹא מִשּׁוּם תְּפִלָּה הָיָה (ההוא לא צריך בנים), אֶלָּא כְּמִי שֶׁמְּסַפֵּר לִפְנֵי רִבּוֹנוֹ. אֲבָל יִצְחָק הִתְפַּלֵּל עַל אִשְׁתּוֹ מִשּׁוּם שֶׁהוּא הָיָה יוֹדֵעַ שֶׁהוּא לֹא עָקָר, אֶלָּא אִשְׁתּוֹ. שֶׁיִּצְחָק הָיָה יוֹדֵעַ בְּסוֹד הַחָכְמָה שֶׁיַּעֲקֹב עָתִיד לְהוֹצִיא מִמֶּנּוּ בִּתְרֵיסַר שְׁבָטִים, אֲבָל לֹא יָדַע אִם בָּאִשָּׁה הַזּוֹ אוֹ בְּאַחֶרֶת, וְעַל כֵּן לְנֹכַח אִשְׁתּוֹ וְלֹא לְנֹכַח רִבְקָה.</p>\n<p>אָמַר אוֹתוֹ הַיֶּלֶד, בְּנוֹ שֶׁל רַבִּי יְהוּדָה, אִם כָּךְ, לָמָּה לֹא אָהַב יִצְחָק אֶת יַעֲקֹב כָּל כָּךְ כְּמוֹ עֵשָׂו הוֹאִיל וְהָיָה יוֹדֵעַ שֶׁהוּא עָתִיד לְקַיֵּם מִמֶּנּוּ שְׁנֵים עָשָׂר שְׁבָטִים? אָמַר לוֹ, יָפֶה אָמַרְתָּ, אֶלָּא כָּל מִין אוֹהֵב אֶת מִינוֹ וְנִמְשָׁךְ וְהוֹלֵךְ מִין אַחַר מִינוֹ.</p>\n<p>בֹּא רְאֵה, עֵשָׂו יָצָא אָדם, כַּכָּתוּב וַיֵּצֵא הָרִאשׁוֹן אַדְמוֹנִי כֻּלּוֹ וְגוֹ', וְהוּא הַמִּין שֶׁל יִצְחָק, שֶׁהוּא הַדִּין הַקָּשֶׁה שֶׁלְּמַעְלָה, וְיָצָא מִמֶּנּוּ עֵשָׂו, הַדִּין הַקָּשֶׁה לְמַטָּה, שֶׁדּוֹמֶה לְמִינוֹ, וְכָל מִין הוֹלֵךְ לְמִינוֹ, וְעַל כֵּן אָהַב אֶת עֵשָׂו יוֹתֵר מִיַּעֲקֹב, כַּכָּתוּב וַיֶּאֱהַב יִצְחָק אֶת עֵשָׂו כִּי צַיִד בְּפִיו. כָּתוּב כָּאן כִּי צַיִד בְּפִיו, וְכָתוּב שָׁם (בראשית י) עַל כֵּן יֵאָמַר כְּנִמְרֹד גִּבּוֹר צַיִד לִפְנֵי ה'.</p>"],[9522011282,"<p>אָמַר רַבִּי יִצְחָק, כָּתוּב וַיִּתְרֹצֲצוּ הַבָּנִים בְּקִרְבָּהּ וַתֹּאמֶר אִם כֵּן לָמָּה זֶּה אָנֹכִי וַתֵּלֶךְ לִדְר!שׁ אֶת ה'. לְאֵיזֶה מָקוֹם הָלְכָה? לְבֵית הַמִּדְרָשׁ שֶׁל שֵׁם וְעֵבֶר. וַיִּתְרֹצֲצוּ הַבָּנִים בְּקִרְבָּהּ - שֶׁשָּׁם הָיָה אוֹתוֹ עֵשָׂו הָרָשָׁע נִלְחָם בִּקְרָב עִם יַעֲקֹב. וַיִּתְרֹצֲצוּ - נִשְׁבְּרוּ כְּמוֹ שֶׁאָמַרְנוּ, רִצֵּץ אֶת מֹחוֹ. נִשְׁבְּרוּ זֶה עִם זֶה וְנֶחְלְקוּ. בּא רְאֵה, הַצַּד הַזֶּה שֶׁרוֹכֵב נָחָשׁ, וְצַד זֶה שֶׁרוֹכֵב עַל הַכִּסֵּא הַשָּׁלֵם הַקָּדוֹשׁ בְּצַד הַשֶּׁמֶשׁ, לְשַׁמֵּשׁ עִם הַלְּבָנָה.</p>\n<p>וּבֹא וּרְאֵה, מִשּׁוּם שֶׁנִּמְשַׁךְ עֵשָׂו אַחֲרֵי אוֹתוֹ נָחָשׁ, הָלַךְ אִתּוֹ יַעֲקֹב בְּעַקְמִימוּת. כְּמוֹ הַנָּחָשׁ שֶׁהוּא חָכָם וְהוּא הוֹלֵךְ בְּעַקְמִימוּת, כְּמוֹ שֶׁנֶּאֱמַר וְהַנָּחָשׁ הָיָה עָרוּם וְגוֹ', חָכָם. וְהַמַּעֲשִׂים שֶׁל יַעֲקֹב כְּלַפָּיו הָיוּ לוֹ כְּמוֹ נָחָשׁ, וְכָךְ צָרִיךְ לוֹ כְּדֵי לִמְשֹׁךְ אֶת עֵשָׂו אַחַר אוֹתוֹ הַנָּחָשׁ, וְיִפָּרֵד מִמֶּנּוּ, וְלֹא יִהְיֶה לוֹ חֵלֶק עִמּוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וְשָׁנִינוּ, בָּא לְהָרְגְךְ - הַקְדֵּם אַתָּה וַהֲרֹג אוֹתוֹ. כָּתוּב (הושע יב) בַּבֶּטֶן עָקַב אֶת אָחִיו, שֶׁהִשְׁרָה אוֹתוֹ לְמַטָּה בְּאוֹתוֹ הֶעָקֵב, זֶהוּ שֶׁכָּתוּב וְיָדוֹ אֹחֶזֶת בַּעֲקֵב עֵשָׂו, שֶׁשָּׂם אֶת יָדוֹ עַל אוֹתוֹ עָקֵב לְהַכְנִיעוֹ.</p>\n<p>דָּבָר אַחֵר וְיָדוֹ אֹחֶזֶת - שֶׁלֹּא יָכֹל לָצֵאת מִמֶּנּוּ מִכֹּל וָכֹל, אֶלָּא וְיָדוֹ אֹחֶזֶת בַּעֲקֵב עֵשָׂו - זוֹ הַלְּבָנָה שֶׁהִתְכַּסָּה אוֹרָהּ מִשּׁוּם הֶעָקֵב שֶׁל עֵשָׂו, וְעַל כֵּן הִצְטָרֵךְ לוֹ לָלֶכֶת עִמּוֹ בְּחָכְמָה כְּדֵי לִדְחוֹתוֹ לְמַטָּה וְיִדְבַּק בִּמְקוֹמוֹ.</p>\n<p>וַיִּקְרָא שְׁמוֹ יַעֲקֹב, הַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לוֹ יַעֲקֹב וַדַּאי. בֹּא רְאֵה, כָּתוּב הֲכִי קָרָא שְׁמוֹ יַעֲקֹב. לֹא כָתוּב נִקְרָא שְׁמוֹ, אֶלָּא קָרָא שְׁמוֹ. וַיַּעְקְבֵנִי, וַדַּאי רָאָה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי אוֹתוֹ הַנָּחָשׁ הַקַּדְמוֹנִי הוּא חָכָם לְהָרַע. כֵּיוָן שֶׁבָּא יַעֲקֹב, אָמַר, הֲרֵי וַדַּאי חָכָם כְּנֶגְדּוֹ, וּמִשּׁוּם כָּךְ קָרָא לוֹ יַעֲקֹב.</p>\n<p>הֲרֵי הֵקַמְנוּ בְּכָל מָקוֹם, וַיִּקְרָא סְתָם זוֹ הִיא הַדַּרְגָּה הָאַחֲרוֹנָה, כַּכָּתוּב וַיִּקְרָא אֶל מֹשֶׁה וְגוֹ'. וְכָאן וַיִּקְרָא שְׁמוֹ יַעֲקֹב, בְּכָל מָקוֹם שְׁמוֹ לֹא נִקְרָא (אלא) עַל יְדֵי בֶּן אָדָם. בְּמָקוֹם אַחֵר מַה כָּתוּב? (בראשית לג) וַיִּקְרָא לוֹ אֵל אֱלֹהֵי יִשְׂרָאֵל. הַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לְיַעֲקֹב אֵל. אָמַר לוֹ, אֲנִי אֱלוֹהַּ בָּעֶלְיוֹנִים, וְאַתָּה אֱלוֹהַּ בַּתַּחְתּוֹנִים.</p>\n<p>וּבֹא וּרְאֵה, יַעֲקֹב הָיָה יוֹדֵעַ שֶׁעֵשָׂו הָיָה לוֹ לְהִדָּבֵק בְּאוֹתוֹ נָחָשׁ עֲקַלָּתוֹן, וְעַל כֵּן בְּכָל מַעֲשָׂיו נִמְשָׁךְ עָלָיו כְּנָחָשׁ עֲקַלָּתוֹן אַחֵר, בְּחָכְמָה, בְּעַקְמוּמִיּוּת, וְכָךְ צָרִיךְ. וְזֶה בָּא כְּמוֹ זֶה מַה שֶּׁאָמַר רַבִּי שִׁמְעוֹן, מַה שֶּׁכָּתוּב (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הַתַּנִּינִם הַגְּדֹלִים - זֶה יַעֲקֹב וְעֵשָׂו. וְאֵת כָּל נֶפֶשׁ הַחַיָּה הָרֹמֶשֶׂת - אֵלּוּ שְׁאָר הַדְּרָגוֹת שֶׁבֵּינֵיהֶם. וַדַּאי שֶׁיַּעֲקֹב נַעֲשָׂה חָכָם כְּנֶגֶד אוֹתוֹ הַנָּחָשׁ הָאַחֵר, וְכָךְ צָרִיךְ.</p>\n<p>וּמִשּׁוּם כָּךְ בְּכָל חֹדֶשׁ וְחֹדֶשׁ שָׂעִיר אֶחָד, כְּדֵי לְהַמְשִׁיכוֹ לִמְקוֹמוֹ וְיִפָּרֵד מִן הַלְּבָנָה, וְכֵן בִּימֵי הַכִּפּוּרִים לְהַקְרִיב אוֹתוֹ הַשָּׂעִיר, וְזֶה בְּחָכְמָה לִשְׁלֹט עָלָיו וְלֹא יוּכַל לְהָרַע, שֶׁכָּתוּב (ויקרא טז) וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲונֹתָם אֶל אֶרֶץ גְּזֵרָה, וּבֵאֲרוּהוּ שֶׁזֶּה עֵשָׂו, שֶׁהוּא שָׂעִיר, וְהַכֹּל בְּחָכְמָה וּבְרַמָּאוּת כְּלַפָּיו. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (תהלים יח) וְעִם עִקֵּשׁ תִּתְפַּתָּל, מִשּׁוּם שֶׁהוּא נָחָשׁ רַע, עֲקֹם רוּחַ, חָכָם לְהָרַע, מַסְטִין לְמַעְלָה וּמַסְטִין לְמַטָּה.</p>\n<p>וּמִשּׁוּם כָּךְ יִשְׂרָאֵל מַקְדִּימִים וּמִתְחַכְּמִים לוֹ בְּחָכְמָה, בְּעַקְמִימוּת, כְּדֵי שֶׁלֹּא יוּכַל לְהָרַע וְלִשְׁלֹט. וְעַל כֵּן יַעֲקֹב, שֶׁהוּא בְּסוֹד הָאֱמוּנָה, כָּל מַעֲשָׂיו כְּלַפֵּי עֵשָׂו מִשּׁוּם שֶׁלֹּא נָתַן מָקוֹם לַנָּחָשׁ הַהוּא לְטַמֵּא אֶת הַמִּקְדָּשׁ, וְלֹא יִקְרַב אֵלָיו וְלֹא יִשְׁלֹט בָּעוֹלָם. וְעַל כֵּן לֹא הִצְטָרֵךְ לְאַבְרָהָם לְהִתְנַהֵג בְּעַקְמִימוּת, וְלֹא לְיִצְחָק, מִשּׁוּם שֶׁעֵשָׂו, שֶׁהוּא הַצַּד שֶׁל הַנָּחָשׁ הַהוּא, טֶרֶם בָּא לָעוֹלָם. אֲבָל יַעֲקֹב, שֶׁהוּא בַּעַל הַבַּיִת, צָרִיךְ לוֹ לַעֲמֹד כְּנֶגֶד אוֹתוֹ הַנָּחָשׁ שֶׁלֹּא תִהְיֶה לוֹ כְּלָל שְׁלִיטָה לְטַמֵּא אֶת בֵּית הַמִּקְדָּשׁ שֶׁל יַעֲקֹב, וְעַל כֵּן צָרִיךְ לְיַעֲקֹב יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם, וּמִשּׁוּם כָּךְ יִשְׂרָאֵל קְדוֹשִׁים נִבְחֲרוּ לְחֵלֶק גּוֹרָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>"],[9522011283,"<p>וְאֵלֶּה תּוֹלְדת יִצְחָק בֶּן אַבְרָהָם אַבְרָהָם הוֹלִיד אֶת יִצְחָק. רַבִּי יִצְחָק פָּתַח, הַדּוּדָאִים נָתְנוּ רֵיחַ וְגוֹ'. שָׁנוּ רַבּוֹתֵינוּ, לֶעָתִיד לָבֹא הַקָּדוֹשׁ בָּרוּךְ הוּא מְחַיֶּה אֶת הַמֵּתִים וִינַעֵר אוֹתָם מֵעֲפָרָם שֶׁלֹּא יִהְיוּ בִּנְיַן עָפָר כְּמוֹת שֶׁהָיוּ בַּתְּחִלָּה שֶׁנִּבְרְאוּ מֵעָפָר מַמָּשׁ, דָּבָר שֶׁאֵינוֹ מִתְקַיֵּם. זֶהוּ שֶׁכָּתוּב (בראשית ב) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה.</p>\n<p>וּבְאוֹתָהּ שָׁעָה יִתְנַעֲרוּ מֵעָפָר מֵאוֹתוֹ הַבִּנְיָן, וְיַעַמְדוּ בְּבִנְיָן מְקֻיָּם לִהְיוֹת לָהֶם קִיּוּם. זֶהוּ שֶׁכָּתוּב (ישעיה נב) הִתְנַעֲרִי מֵעָפָר קוּמִי שְׁבִי יְרוּשָׁלַיִם. יִתְקַיְּמוּ בְּקִיּוּם, וְיַעֲלוּ מִתַּחַת לָאָרֶץ, וִיקַבְּלוּ נִשְׁמָתָם בְּאֶרֶץ יִשְׂרָאֵל. בְּאוֹתָהּ שָׁעָה יָצִיף הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל מִינֵי רֵיחוֹת שֶׁבְּגַן עֵדֶן עֲלֵיהֶם. זֶהוּ שֶׁכָּתוּב הַדּוּדָאִים נָתְנוּ רֵיחַ.</p>\n<p>אָמַר רַבִּי יִצְחָק, אַל תִּקְרָא הַדּוּדאִים אֶלָּא הַדּוֹדִים. זֶהוּ הַגּוּף וְהַנְּשָׁמָה שֶׁהֵם דּוֹדִים וְרֵעִים זֶה עִם זֶה. רַב נַחְמָן אָמַר דּוּדָאִים מַמָּשׁ. מָה הַדּוּדָאִים מוֹלִידִים אַהֲבָה בָּעוֹלָם, אַף הֵם מוֹלִידִים אַהֲבָה בָּעוֹלָם. וּמַה זֶּה נָתְנוּ רֵיחַ? כִּשְׁרוֹן מַעֲשֵׂיהֶם, לָדַעַת וּלְהַכִּיר אֶת בּוֹרְאָם.</p>\n<p>וְעַל פְּתָחֵינוּ - אֵלּוּ פִּתְחֵי שָׁמַיִם שֶׁהֵם פְּתוּחִים לְהוֹרִיד נְשָׁמוֹת לַפְּגָרִים. כָּל מְגָדִים - אֵלּוּ הַנְּשָׁמוֹת. חֲדָשִׁים גַּם יְשָׁנִים - אוֹתָם שֶׁיָּצְאוּ נִשְׁמָתָם מֵהַיּוֹם כַּמָּה שָׁנִים וְאוֹתָם שֶׁיָּצְאוּ נִשְׁמָתָם מִיָּמִים מוּעָטִים וְזָכוּ בְּכִשְׁרוֹן מַעֲשֵׂיהֶם לְהִכָּנֵס בָּעוֹלָם הַבָּא, כֻּלָּם עֲתִידִים לֵירֵד בְּבַת אַחַת לְהִכָּנֵס בַּגּוּפוֹת הַמּוּכָנִים לָהֶם.</p>\n<p>אָמַר רַבִּי אָחָא בַּר יַעֲקֹב, בַּת קוֹל יוֹצֵאת וְאוֹמֶרֶת: חֲדָשִׁים גַּם יְשָׁנִים דּוֹדִים צָפַנְתִּי לָךְ. צָפַנְתִּי אוֹתָם בְּאוֹתָם הָעוֹלָמוֹת. לָךְ - בִּשְׁבִילְךְ, בִּשְׁבִיל שֶׁאַתָּה גוּף קָדוֹשׁ וְנָקִי. דָּבָר אַחֵר הַדּוּדָאִים (נתנו ריח) - אֵלּוּ מַלְאֲכֵי שָׁלוֹם. נָתְנוּ רֵיחַ - אֵלּוּ הַנְּשָׁמוֹת שֶׁהֵם רֵיחַ הָעוֹלָם. נָתְנוּ - הִשְׁאִירוּ, כְּמוֹ שֶׁנֶּאֱמַר (במדבר כא) וְלֹא נָתַן סִיחוֹן אֶת יִשְׂרָאֵל.</p>\n<p>שֶׁלָּמַדְנוּ, אָמַר רַבִּי יְהוּדָה, שָׁלֹשׁ כִּתּוֹת שֶׁל מַלְאֲכֵי הַשָּׁרֵת הוֹלְכִים בְּכָל חֹדֶשׁ וּבְכָל שַׁבָּת לְלַוּוֹת לַנְּשָׁמָה עַד מְקוֹם מַעֲלָתָהּ. וּבְמִי נָקִים אֶת עַל פְּתָחֵינוּ כָּל מְגָדִים? אָמַר רַבִּי יְהוּדָה, אֵלּוּ הֵן הַגּוּפוֹת שֶׁהֵם עוֹמְדִים בְּפִתְחֵי קְבָרוֹת לְקַבֵּל נִשְׁמָתָן, וְדוּמָה נוֹתֵן פֶּתֶק שֶׁל חֶשְׁבּוֹן, וְהוּא מַכְרִיז וְאוֹמֵר: רִבּוֹנוֹ שֶׁל עוֹלָם, חֲדָשִׁים גַּם יְשָׁנִים, אוֹתָם שֶׁנִּקְבְּרוּ מִכַּמָּה יָמִים וְאוֹתָם שֶׁנִּקְבְּרוּ מִזְּמַן מוּעָט - כֻּלָּם צָפַנְתִּי לָךְ, לְהוֹצִיא אוֹתָם בְּחֶשְׁבּוֹן.</p>\n<p>אָמַר רַב יְהוּדָה אָמַר רַב, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׂמֹחַ בְּאוֹתוֹ זְמַן עִם הַצַּדִּיקִים לְהַשְׁרוֹת שְׁכִינָתוֹ עִמָּהֶם, וְהַכֹּל יִשְׂמְחוּ בְּאוֹתָהּ שִׂמְחָה, זֶהוּ שֶׁכָּתוּב (שם קד) יִשְׂמַח ה' בְּמַעֲשָׂיו. אָמַר רַבִּי יְהוּדָה, עֲתִידִים הַצַּדִּיקִים בְּאוֹתוֹ זְמַן לִבְרֹא עוֹלָמוֹת וּלְהַחֲיוֹת מֵתִים. אָמַר לוֹ רַבִּי יוֹסֵי, וַהֲרֵי שָׁנִינוּ (קהלת א) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ? אָמַר לוֹ רַבִּי יְהוּדָה, בֹּא שְׁמַע, בְּעוֹד שֶׁהָרְשָׁעִים בָּעוֹלָם וְיִרְבּוּ, כָּל הָעוֹלָם אֵינוֹ בְּקִיּוּם, וּכְשֶׁהַצַּדִּיקִים בָּעוֹלָם, אֲזַי הָעוֹלָם מִתְקַיֵּם. וַעֲתִידִים לְהַחֲיוֹת מֵתִים כְּמוֹ שֶׁאָמַרְנוּ, (זכריה ח) עֹד יֵשְׁבוּ זְקֵנִים וּזְקֵנוֹת בִּרְחֹבוֹת יְרוּשָׁלָיִם וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ מֵרֹב יָמִים, כְּמוֹ שֶׁכָּתוּב לְמַעְלָה.</p>\n<p>בְּאוֹתוֹ זְמַן יַשִּׂיגוּ הַצַּדִּיקִים דַּעַת שְׁלֵמָה. שֶׁאָמַר רַבִּי יוֹסֵי, בַּיּוֹם שֶׁיִּשְׂמַח הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשָׂיו, עֲתִידִים הַצַּדִּיקִים לְהַכִּיר אוֹתוֹ בְּלִבָּם, וְאָז תִּרְבֶּה הַהַשְׂכָּלָה בְּלִבָּם כְּאִלּוּ רָאוּ אוֹתוֹ בָּעַיִן. זֶהוּ שֶׁכָּתוּב (ישעיה כח) וְאָמַר בַּיּוֹם הַהוּא הִנֵּה אֱלֹהֵינוּ זֶה וְגוֹ'. וְשִׂמְחַת הַנְּשָׁמָה בַּגּוּף יָתֵר מִכֻּלָּם, עַל שֶׁיִּהְיוּ שְׁנֵיהֶם קַיָּמִים וְיֵדְעוּ וְיַשִּׂיגוּ אֶת בּוֹרְאָם וְיֵהָנוּ מִזִּיו הַשְּׁכִינָה, וְזֶהוּ הַטּוֹב הַגָּנוּז לַצַּדִּיקִים לֶעָתִיד לָבֹא. זֶהוּ שֶׁכָּתוּב וְאֵלֶּה תּוֹלְדת יִצְחָק בֶּן אַבְרָהָם. אֵלּוּ הֵם תּוֹלְדוֹת הַשִּׂמְחָה וְהַשְּׂחוֹק שֶׁיְּהֵא בָּעוֹלָם בְּאוֹתוֹ זְמַן. בֶּן אַבְרָהָם - הִיא הַנְּשָׁמָה הַזּוֹכָה לְכָךְ וְלִהְיוֹת שְׁלֵמָה בְּמַעֲלָתָהּ. אַבְרָהָם הוֹלִיד אֶת יִצְחָק - הַנְּשָׁמָה מוֹלִידָה הַשִּׂמְחָה וְהַשְּׂחוֹק הַזֶּה בָּעוֹלָם.</p>\n<p>אָמַר רַבִּי יְהוּדָה לְרַבִּי חִיָּיא, זֶה שֶׁשָּׁנִינוּ שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת סְעוּדָה לַצַּדִּיקִים לֶעָתִיד לָבא מַה הִיא? אָמַר לוֹ, טֶרֶם הָלַכְתִּי לִפְנֵי אוֹתָם הַמַּלְאָכִים הַקְּדוֹשִׁים, בַּעֲלֵי הַמִּשְׁנָה, כָּךְ נִשְׁמַע לִי. כֵּיוָן שֶׁשָּׁמַעְתִּי אֶת זֶה שֶׁאָמַר רַבִּי אֶלְעָזָר, הִתְיַשֵּׁב בְּלִבִּי. שֶׁאָמַר רַבִּי אֶלְעָזָר, סְעוּדַת הַצַּדִּיקִים לֶעָתִיד לָבֹא כְּמוֹ זֶה שֶׁכָּתוּב (שמות כד) וַיֶּחֱזוּ אֶת הָאֱלֹהִים וַיֹּאכְלוּ וַיִּשְׁתּוּ. וְזֶה הוּא שֶׁשָּׁנִינוּ נִזּוֹנִים. וְאָמַר רַבִּי אֶלְעָזָר, בְּמָקוֹם אֶחָד שָׁנִינוּ נֶהֱנִים, וּבְמָקוֹם אַחֵר שָׁנִינוּ נִזּוֹנִים. מַה בֵּין זֶה לָזֶה? אֶלָּא כָּךְ אָמַר אָבִי, הַצַּדִּיקִים שֶׁלֹּא זָכוּ כָּל כָּךְ, נֶהֱנִים מֵאוֹתוֹ זִיו, שֶׁלֹּא יַשִּׂיגוּ כָּל כָּךְ. אֲבָל הַצַּדִּיקִים שֶׁזָּכוּ, נִזּוֹנִים עַד שֶׁיַּשִּׂיגוּ הַשָּׂגָה שְׁלֵמָה. וְאֵין אֲכִילָה וּשְׁתִיָּה אֶלָּא זוֹ, וְזוֹ הִיא הַסְּעוּדָה וְהָאֲכִילָה. וּמִנַּיִן לָנוּ זֶה? מִמֹּשֶׁה, שֶׁכָּתוּב (שמות לד) וַיְהִי שָׁם עִם ה' אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה לֶחֶם לֹא אָכַל וּמַיִם לֹא שָׁתָה. מָה הַטַּעַם לֶחֶם לֹא אָכַל וּמַיִם לֹא שָׁתָה? מִפְּנֵי שֶׁהָיָה נִזּוֹן מִסְּעוּדָה אַחֶרֶת, מֵאוֹתוֹ זִיו שֶׁל מַעְלָה. וּכְמוֹ כֵן סְעוּדָתָם שֶׁל צַדִּיקִים לֶעָתִיד לָבא.</p>\n<p>אָמַר רַבִּי יְהוּדָה, סְעוּדַת הַצַּדִּיקִים לֶעָתִיד לָבא לִשְׂמֹחַ בְּשִׂמְחָתוֹ, זֶהוּ שֶׁכָּתוּב (תהלים לד) יִשְׁמְעוּ עֲנָוִים וְיִשְׂמָחוּ. רַב הוּנָא אָמַר, מִכָּאן (שם ה) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ. אָמַר רַבִּי יִצְחָק, זֶה וָזֶה יֶשְׁנָם לֶעָתִיד לָבא. וְלָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, יַיִן הַמְשֻׁמָּר בַּעֲנָבָיו מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית - אֵלּוּ דְּבָרִים עַתִּיקִים שֶׁלֹּא נִגְלוּ לְאָדָם מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וַעֲתִידִים לְהִתְגַּלּוֹת לַצַּדִּיקִים לֶעָתִיד לָבֹא, וְזוֹ הִיא הַשְּׁתִיָּה וְהָאֲכִילָה, וַדַּאי זוֹ הִיא.</p>\n<p>אָמַר רַבִּי יְהוּדָה בְּרַבִּי שָׁלוֹם, אִם כֵּן מַהוּ לִוְיָתָן וּמַה הַשּׁוֹר, שֶׁכָּתוּב (איוב מ) כִּי בוּל הָרִים יִשְׂאוּ לוֹ? אָמַר רַבִּי יוֹסֵי, וְהִנֵּה כָּתוּב (ישעיה כז) בָּעֵת הַהִיא יִפְקֹד ה' בְּחַרְבּוֹ הַקָּשָׁה וְהַגְּדוֹלָה וְהַחֲזָקָה עַל לִוְיָתָן נָחָשׁ בָּרִחַ וְעַל לִוְיָתָן נָחָשׁ עֲקַלָּתוֹן וְהָרַג אֶת הַתַּנִּין אֲשֶׁר בַּיָּם. הִנֵּה כָּאן שְׁלֹשָׁה. אֶלָּא רֶמֶז הוּא שֶׁרָמַז עַל הַמַּלְכֻיּוֹת. אָמַר רַבִּי תַּנְחוּם, אֵין לוֹמַר עַל מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ, וַדַּאי כָּךְ זֶה.</p>\n<p>אָמַר רַבִּי יִצְחָק, אֲנִי הָיִיתִי לִפְנֵי רַבִּי יְהוֹשֻׁעַ וְשָׁאַלְתִּי עַל הַדָּבָר הַזֶּה. אָמַרְתִּי, הַסְּעוּדָה הַזּוֹ שֶׁל הַצַּדִּיקִים לֶעָתִיד לָבא הַאִם כָּךְ הוּא? לֹא הִתְיַשְּׁבָה בְּלִבִּי, שֶׁהִנֵּה אָמַר רַבִּי אֶלְעָזָר, סְעוּדַת הַצַּדִּיקִים לֶעָתִיד לָבֹא כְּמוֹ זֶה שֶׁכָּתוּב (שמות כד) וַיֶּחֱזוּ אֶת הָאֱלֹהִים וַיֹּאכְלוּ וַיִּשְׁתּוּ. אָמַר רַבִּי יְהוֹשֻׁעַ, יָפֶה אָמַר רַבִּי אֶלְעָזָר, וְכָךְ הוּא.</p>\n<p>עוֹד אָמַר רַבִּי יְהוֹשֻׁעַ, הָאֱמוּנָה הַזּוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ לְרֹב הָעוֹלָם שֶׁמְּזֻמָּנִים הֵם לַסְּעוּדָה הַזּוֹ שֶׁל לִוְיָתָן וְהַשּׁוֹר הַהוּא, וְלִשְׁתּוֹת יַיִן טוֹב שֶׁמְּשֻׁמָּר מִכְּשֶׁנִּבְרָא הָעוֹלָם, פָּסוּק מָצְאוּ וְדָרְשׁוּ, שֶׁכָּתוּב (ויקרא כו) ואכלתם לחמכם לשבע. שֶׁאָמַר רַבִּי זֵירָא, כָּל מִינֵי פִּתּוּי פִּתָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל לְהַחֲזִירָם לְמוּטָב, וְזֶה הוּא יוֹתֵר מִכֻּלָּם, שֶׁאָמַר לָהֶם וַאֲכַלְתֶּם לַחְמְכֶם לָשּבַע, וּבַקְּלָלוֹת - וַאֲכַלְתֶּם וְלֹא תִשְׂבָּעוּ, וְזֶה קָשֶׁה לָהֶם מִן הַכֹּל. מָה הַטַּעַם? שֶׁכָּתוּב (שמות טז) מִי יִתֵּן מוּתֵנוּ בְּיַד ה' בְּאֶרֶץ מִצְרַיִם וְגוֹ'. אָמַר רַבִּי זֵירָא, מְלַמֵּד שֶׁמִּשּׁוּם הָאֲכִילָה מָסְרוּ נַפְשָׁם לָמוּת בְּיָדָם. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא תַּאֲוָתָם, אָמַר לָהֶם: אִם תִּשְׁמְעוּ לְקוֹל הַמִּצְווֹת - וַאֲכַלְתֶּם לָשּבַע, כְּדֵי לְהָנִיחַ דַּעְתָּם. כְּמוֹ כֵן רָאוּ רַבּוֹתֵינוּ שֶׁהַגָּלוּת נִמְשֶׁכֶת, הִסְתַּמְּכוּ עַל פְּסוּקֵי הַתּוֹרָה, וְאָמְרוּ שֶׁעֲתִידִים לֶאֱכֹל וְלִשְׂמֹחַ בִּסְעוּדָה גְּדוֹלָה שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לָהֶם, וְעַל כֵּן רֹב הָעוֹלָם סָבְלוּ אֶת הַגָּלוּת מִשּׁוּם אוֹתָהּ הַסְּעוּדָה.</p>\n<p>אָמַר רַבִּי יוֹחָנָן, אֵין לָנוּ לִסְתֹּר אֶת אֱמוּנַת הַכֹּל, אֶלָּא לְקַיֵּם אוֹתָהּ. שֶׁהֲרֵי הַתּוֹרָה מְעִידָה עַל זֶה שֶׁהֲרֵי אָנוּ יוֹדְעִים אֶת אֱמוּנַת הַצַּדִּיקִים, וְהַכִּסּוּף שֶׁלָּהֶם מַה הוּא? שֶׁכָּתוּב (שיר א) נָגִילָה וְנִשְׂמְחָה בָּךְ, וְלֹא בַּאֲכִילָה. נַזְכִּירָה דדֶיךְ מִיַּיִן. וְאוֹתָהּ סְעוּדָה שֶׁמְּזֻמָּנִים אֵלֶיהָ, יִהְיֶה לָנוּ חֵלֶק לֵהָנוֹת מִמֶּנָּה, וְזוֹ הִיא הַשִּׂמְחָה וְהַשְּׂחוֹק. וְאֵלֶּה תּוֹלְדת יִצְחָק - שֶׁיִּצְחֲקוּ הַצַּדִּיקִים לֶעָתִיד לָבא. אַבְרָהָם הוֹלִיד אֶת יִצְחָק - זְכוּת הַנְּשָׁמָה מוֹלִיד הַשְּׂחוֹק הַזֶּה וְהַשִּׂמְחָה בָּעוֹלָם.</p>"],[9522011284,"<p>וַיְהִי יִצְחָק בֶּן אַרְבָּעִים שָׁנָה. רַבִּי בּוֹ בְּשֵׁם רַבִּי יוֹסֵי פָּתַח וְאָמַר, (שיר א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ וְגוֹ', בְּכַמָּה מַעֲלוֹת נִבְרָא הָעוֹלָם, שֶׁשָּׁנִינוּ, אָמַר רַבִּי אָחָא בַּר יַעֲקֹב, כָּל מַה שֶּׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָמוֹת שֶׁלּוֹ, חוּץ מִמֶּנּוּ, הָיוּ בְּשִׁתּוּף. וְהַאִם אָמַר כָּךְ רַבִּי אָחָא? חַס וְשָׁלוֹם! שֶׁהֲרֵי בַּדָּבָר הַזֶּה תִּרְבֶּה הַמַּחֲלֹקֶת בָּעוֹלָם. שֶׁאִם תֹּאמַר כֵּן, הַמַּלְאָכִים שֶׁהֵם נִבְרָאִים רוּחַ הַקֹּדֶשׁ מַמָּשׁ, יֹאמַר שֶׁיֵּשׁ בָּהֶם שִׁתּוּף, הֲרֵי כָּל הַפָּנִים שֶׁלָּהֶם וְשֶׁלָּנוּ שָׁוִים.</p>\n<p>אָמַר רַבִּי אַבָּא, בַּדָּבָר הַזֶּה תִּתְרַבֶּה הַמַּחֲלֹקֶת בָּעוֹלָם, שֶׁהֲרֵי שָׁנִינוּ בְּמִשְׁנָתֵנוּ, שֶׁכָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא - עָשָׂה כְּמוֹ הַגּוּף וְהַנְּשָׁמָה. וְאִם תֹּאמַר שֶׁהֲרֵי אֵין לַמַּלְאָכִים גּוּף - כָּךְ זֶה, אֲבָל אֵינָם יְכוֹלִים לַעֲשׂוֹת מַעֲשֶׂה עַד שֶׁתִּשְׁתַּתֵּף עִמָּהֶם הַנְּשָׁמָה הַקְּדוֹשָׁה הַהִיא, שֶׁהִיא סִיּוּעַ שֶׁלְּמַעְלָה. וּבַגְּוָנִים הַלָּלוּ, כָּל מַה שֶּׁעוֹשֶׂה, צָרִיךְ אֶת אוֹתוֹ סִיּוּעַ שֶׁלְּמַעְלָה מִמֶּנּוּ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, בַּשָּׁעָה הַהִיא שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת מֵתִים, וְהִנֵּה סוֹף כָּל (הצרות) עֳמָקִים (עתיקים) יִהְיֶה בָּאַרְבָּעִים, וּגְזַר הַדִּין - (דברים כה) אַרְבָּעִים יַכֶּנּוּ לֹא יֹסִיף. סוֹף הֲלִיכָתָם שֶׁל יִשְׂרָאֵל בַּמִּדְבָּר בִּשְׁנַת הָאַרְבָּעִים. אַרְבָּעִים שָׁנָה קֹדֶם תְּחִיַּת הַגּוּף מַמְתֶּנֶת לוֹ הַנְּשָׁמָה בְּאֶרֶץ יִשְׂרָאֵל. בִּשְׁנַת הָאַרְבָּעִים יָקוּמוּ הַגּוּפוֹת מִן הֶעָפָר. בָּאַרְבָּעִים נִכְלָא הַגֶּשֶׁם, זֶהוּ שֶׁכָּתוּב (בראשית ז) וַיְהִי הַגֶּשֶׁם עַל הָאָרֶץ אַרְבָּעִים יוֹם, וְכָתוּב (בראשית ח ו) וַיְהִי מִקֵּץ אַרְבָּעִים יוֹם וַיִּפְתַּח נֹחַ. זְמַן גְּאֻלָּתָם שֶׁל יִשְׂרָאֵל בִּשְׁנַת הָאַרְבָּעִים הוּא, וּבַחֲמִשִּׁים בָּא יִשּׁוּב הָעוֹלָם, שֶׁהִיא הַיּוֹבֵל. הַחְזָרַת הַנְּשָׁמָה לַגּוּף בִּשְׁנַת הָאַרְבָּעִים שֶׁהִמְתִּינָה לוֹ בְּאֶרֶץ יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב וַיְהִי יִצְחָק בֶּן אַרְבָּעִים שָׁנָה, שֶׁהִמְתִּין לַגּוּף. בְּקַחְתּוֹ אֶת רִבְקָה - בְּהַכְנָסָתָהּ בַּגּוּף הַמְזֻמָּן לוֹ. בְּאוֹתָהּ שָׁעָה בְּהַכְנָסָתָהּ בּוֹ, אֵין תַּאֲוָתָם וְכִסּוּפָם אֶלָּא לֵהָנוֹת מִזִּיו הַשְּׁכִינָה וְלִזּוֹן מִזִּיוָהּ. זֶהוּ שֶׁכָּתוּב (שיר א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. אָמַר רַבִּי אַבָּא, יִשָּׁקֵנִי - יְפַרְנְסֵנִי. שֶׁאֵין פַּרְנָסָתָם אֶלָּא לֵהָנוֹת וְלִזּוֹן מִזִּיוָהּ שֶׁל מַעְלָה. אָמַר רַבִּי יוֹסֵי, סוֹף הַפָּסוּק מוֹכִיחַ, שֶׁכָּתוּב כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן.</p>\n<p>בַּת בְּתוּאֵל - בַּת בִּתּוֹ שֶׁל אֵל. רַב הוּנָא אָמַר, לֹא כָּךְ הוּא. וַאֲנִי הָיִיתִי בִּכְרַכֵּי הַיָּם וְשָׁמַעְתִּי שֶׁהָיוּ קוֹרְאִים לְאוֹתוֹ הָעֶצֶם שֶׁעַל הַשִּׁדְרָה, אוֹתוֹ שֶׁנִּשְׁאָר בַּקֶּבֶר מִכָּל הַגּוּף - בְּתוּאֵל הָאֲרַמִּי. שָׁאַלְתִּי עָלָיו. אָמְרוּ שֶׁהוּא כְּרֹאשׁ (דומה) הַנָּחָשׁ, שֶׁהוּא רַמַּאי, וְאוֹתוֹ הָעֶצֶם הוּא רַמַּאי מִכָּל שְׁאָר הָעֲצָמוֹת.</p>\n<p>שֶׁלָּמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, לָמָּה נִשְׁאָר בְּקִיּוּם אוֹתוֹ הָעֶצֶם יוֹתֵר מִכָּל שְׁאָר הָעֲצָמוֹת? מִשּׁוּם שֶׁהוּא רַמַּאי, וְאֵינוֹ סוֹבֵל טַעַם שֶׁל הַמָּזוֹן שֶׁל בְּנֵי הָאָדָם כְּמוֹ שְׁאָר הָעֲצָמוֹת, וּמִשּׁוּם כָּךְ הוּא חָזָק מִכָּל הָעֲצָמוֹת, וְהוּא יִהְיֶה הָעִקָּר שֶׁהַגּוּף נִבְנֶה מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב בַּת בְּתוּאֵל הָאֲרַמִּי.</p>\n<p>וְלָמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, הוּא רַמַּאי וּמֵעוֹלָם רַמַּאי, וְשֶׁכֵּן יֵצֶר הָרָע שֶׁהוּא רַמַּאי. זֶהוּ שֶׁכָּתוּב בַּת בְּתוּאֵל הָאֲרַמִּי - עֶצֶם רַמַּאי. מִפַּדַּן אֲרָם - מִצֶּמֶד רַמָּאִים, כְּמוֹ שֶׁשָּׁנִינוּ פַּדְּנָא דְתוֹרָא, שֶׁהוּא צֶמֶד. אֲחוֹת לָבָן - אֲחוֹת יֵצֶר הָרָע הָאֲרַמִּי. כְּמוֹ שֶׁשָּׁנִינוּ, בַּתְּחִלָּה שֶׁהָיָה מְנֻוָּל בְּחַטָּאוֹת בְּזֶה הָעוֹלָם נִקְרָא לוֹט. לֶעָתִיד לָבא שֶׁלֹּא יְהֵא מְנֻוָּל כְּמוֹ בָּרִאשׁוֹנָה, כְּמִי שֶׁרוֹחֵץ וּמַטְבִּיל אֶת טֻמְאָתוֹ, קוֹרְאִים לוֹ לָבָן. עַל כָּל פָּנִים אֵין יֵצֶר הָרָע בָּטֵל מִן הָעוֹלָם. בֹּא שְׁמַע שֶׁכָּךְ אָנוּ בֵּאַרְנוּ בַּבָּרַיְתָא. שְׁתֵּי בְנוֹת לוֹט, שֶׁהֵן שְׁנֵי כֹּחוֹת הַגּוּף הַמְּעוֹרְרוֹת אֶת יֵצֶר הָרָע, עַכְשָׁו שֶׁאֵינוֹ כָּל כָּךְ מְנֵוּל וְנִטְבַּל מִלִּכְלוּכוֹ נִקְרָא לָבָן, וְאוֹתָן שְׁתֵּי בָנוֹת אֵינָן בְּטֵלוֹת מַמָּשׁ. זֶהוּ שֶׁכָּתוּב (בראשית כט) וּלְלָבָן שְׁתֵּי בָנוֹת.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּךְ הוּא. שָׁם כָּתוּב בְּכִירָה וּצְעִירָה, וְכָאן כָּתוּב גְּדוֹלָה וּקְטַנָּה. אָמַר רַבִּי יוֹסֵי, אֲבָל אֵינָן בְּכֹחַ לַעֲשׂוֹת רָע וּלְהִתְעוֹרֵר לַיֵּצֶר הָרָע כְּמִתְּחִלָּה, מַשְׁמָע שֶׁכָּתוּב שֵׁם הַגְּדֹלָה לֵאָה, שֶׁלֵּאָה מִכֹּחָהּ וּמֵרִשְׁעָתָהּ. וְשֵׁם הַקְּטַנָּה רָחֵל, שֶׁאֵין בָּהּ כֹּחַ הַמִּתְעוֹרֵר, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כג) וּכְרָחֵל לִפְנֵי גוֹזְזֶיהָ נֶאֱלָמָה.</p>\n<p>אָמַר רַב הוּנָא, זֶה יֵצֶר הָרָע, וּשְׁתֵּי בְנוֹתָיו מִתְחַלְּפוֹת מִכְּמוֹת שֶׁהָיוּ בָּרִאשׁוֹנָה. בַּתְּחִלָּה לוֹט, מְקֻלָּל מְנֻוָּל. עַכְשָׁו לָבָן, מְלֻבָּן, שֶׁאֵינוֹ מְקֻלָּל וּמְנֻוָּל בְּנִוּוּלוֹ כְּבָרִאשׁוֹנָה. בַּתְּחִלָּה שְׁתֵּי בְנוֹתָיו חֲזָקוֹת, כָּל אַחַת וְאַחַת בְּכֹחָהּ, וְעַכְשָׁו שֵׁם הַגְּדלָה לֵאָה - לֵאָה בְּלֹא כֹחַ, לֵאָה בְּלֹא חִזּוּק, לֵאָה מִמַּעֲשֶׂיהָ הָרִאשׁוֹנִים. וְשֵׁם הַקְּטַנָּה רָחֵל, כְּמוֹ שֶׁאָמַרְנוּ, וְלֹא כְּמוֹת שֶׁהָיוּ בָּרִאשׁוֹנָה.</p>\n<p>אָמַר רַב אָחָא בַּר יַעֲקֹב, בֹּא רְאֵה מַה כָּתוּב, וַיֶּעְתַּר יִצְחָק לַה' לְנֹכַח אִשְׁתּוֹ כִּי עֲקָרָה הִיא. אָמַר רַבִּי אָחָא, מִפְּנֵי מָה הִיא עֲקָרָה? מִפְּנֵי שֶׁיֵּצֶר הָרָע אֵינוֹ נִמְצָא בְּכֹחַ בָּעוֹלָם, וְעַל כָּךְ אֵין נִמְצָא פְּרִיָּה וּרְבִיָּה זוּלָתִי בַּתְּפִלָּה. וּמַה כָּתוּב? וַיֵּעָתֶר לוֹ ה' וַתַּהַר רִבְקָה אִשְׁתּוֹ. כֵּיוָן שֶׁמִּתְעוֹרֵר יֵצֶר הָרָע, נִמְצָא פְּרִיָּה וּרְבִיָּה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אִם כֵּן, מַה הֶפְרֵשׁ בֵּין הָעוֹלָם הַזֶּה לְאוֹתוֹ זְמַן? וְעוֹד, שֶׁהִנֵּה הַכָּתוּב אָמַר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה. אָמַר רַבִּי אָחָא, כָּךְ הוּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֵעִיר אוֹתוֹ לָעִנְיָן הַהוּא שֶׁצָּרִיךְ לְזַוֵּג, וְלֹא לְכָל שָׁעָה, שֶׁיִּהְיֶה תָמִיד עִם אָדָם כְּמוֹ כָּעֵת, שֶׁהוּא נִמְצָא תָמִיד וְחוֹטְאִים בּוֹ בְּנֵי אָדָם, אֶלָּא לְאוֹתוֹ זִוּוּג לְבַדּוֹ. וְהַהִתְעוֹרְרוּת הַהִיא תִּהְיֶה הִתְעוֹרְרוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (יחזקאל לו) וַהֲסִירֹתִי אֶת לֵב הָאֶבֶן מִבְּשַׂרְכֶם וְנָתַתִּי לָכֶם לֵב בָּשָׂר. מַה זֶּה לֵב בָּשָׂר? אָמַר רַבִּי יְהוּדָה, לֵב לְהוֹצִיא בָשָׂר, וְלֹא לְדָבָר אַחֵר.</p>\n<p>רַבִּי יִצְחָק בְּרַבִּי יוֹסֵי הָיָה בָּא מִקַּפּוֹטְקִיָּא לְלוֹד. פָּגַע בּוֹ רַבִּי יְהוּדָה. אָמַר לוֹ רַבִּי יִצְחָק, תֹּאמַר שֶׁחֲבֵרֵינוּ חַכְמֵי הַבָּרַיְתָא הִתְעוֹרְרוּ לָעִנְיָן הַזֶּה שֶׁיֵּצֶר הָרָע יִשְׁתַּכַּח מִן הָעוֹלָם, פְּרָט לְאוֹתָהּ שְׁעַת הַזִּוּוּג. אָמַר לוֹ, חַיֶּיךְ, כָּךְ צָרִיךְ יֵצֶר הָרָע לָעוֹלָם כְּגֶשֶׁם לָעוֹלָם. שֶׁאִלְמָלֵא יֵצֶר הָרָע, חֶדְוַת הַשְּׁמוּעָה לֹא תִהְיֶה, אֲבָל לֹא מְנֵוִּלֶת כְּבָרִאשׁוֹנָה לַחֲטֹא בוֹ. זֶהוּ שֶׁכָּתוּב (ישעיה יא) לֹא יָרֵעוּ וְלֹא יַשְׁחִיתוּ בְּכָל הַר קָדְשִׁי וְגוֹ'. אָמַר רַבִּי שִׁמְעוֹן, הוּא הַלֵּב שֶׁמְּדוֹרוֹ שֶׁל יֵצֶר הָרָע בּוֹ. רַבִּי אֱלִיעֶזֶר אוֹמֵר, לֵב טוֹב בִּנְיַן הַגּוּף וְהַנְּשָׁמָה, וּמִשּׁוּם כָּךְ כָּתוּב (דברים ו) וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ בְּכָל לְבָבְךְ, שֶׁהוּא עִקַּר הַכֹּל.</p>\n<p>כְּשֶׁבָּא רַב כַּהֲנָא, אָמַר, כָּךְ אוֹמְרִים מִשְּׁמָם שֶׁל בַּעֲלֵי הַבָּרַיְתָא: שְׁנֵי בִנְיָנִים שֶׁל הַגּוּף הֵם - הַכָּבֵד וְהַלֵּב. שֶׁאָמַר רַבִּי שִׁמְעוֹן אָמַר רַבִּי יְהוּדָה, הַכָּבֵד וְהַלֵּב מַנְהִיגִים אֶת הַגּוּף בְּכָל צִדְדֵי אֵיבָרָיו. הַמַּנְהִיג שֶׁל הָרֹאשׁ הוּא הַמֹּחַ, אֲבָל שֶׁל הַגּוּף הֵם שְׁנַיִם. וְהָרִאשׁוֹן הוּא הַכָּבֵד, וְהַשֵּׁנִי הַלֵּב. וְהַיְנוּ שֶׁכָּתוּב בַּפָּרָשָׁה וַיִּתְרֹצֲצוּ הַבָּנִים בְּקִרְבָּהּ, אֵלּוּ שְׁנֵי בִנְיְנֵי הַגּוּף.</p>"],[9522011285,"<p>מָה הַטַּעַם וַיִּתְרֹצֲצוּ? מִשּׁוּם שֶׁמֵּהַלֵּב (מתעורר) נִשְׁכָּח הַיֵּצֶר הָרָע. וַיִּתְרֹצֲצוּ? (שאלו) וַיִּשְׁלָיוּ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא, אָמַר רַב הוּנָא, וַיִּתְרֹצֲצוּ - וַיִּשָּׁבְרוּ, כְּלוֹמַר, נִשְׁבַּר כֹּחָם וְחֵילָם. אָמַר רַבִּי יְהוּדָה, הַגּוּף מַהוּ אוֹמֵר? אִם כֵּן לָמָּה זֶּה אָנֹכִי, וְלָמָּה נִבְרֵאתִי? מִיָּד - וַתֵּלֶךְ לִדְר!שׁ אֶת ה'.</p>\n<p>וַיֹּאמֶר ה' לָהּ שְׁנֵי גוֹיִם בְּבִטְנֵךְ וּשְׁנֵי לְאֻמִּים וְגוֹ'. אֵלּוּ הַשְּׁנֵי גֵאִים - הַכָּבֵד וְהַלֵּב. רַבִּי יוֹסֵי אָמַר, הַמֹּחַ וְהַלֵּב. רַבִּי יְהוּדָה אָמַר, הַמֹּחַ אֵין בִּכְלַל זֶה, מַשְׁמָע שֶׁכָּתוּב בְּבִטְנֵךְ, וְאֵין הַמֹּחַ בַּבֶּטֶן אֶלָּא בָּרֹאשׁ. וּשְׁנֵי לְאֻמִּים מִמֵּעַיִךְ וְגוֹ', וְרַב יַעֲבֹד צָעִיר. זֶהוּ הַכָּבֵד, שֶׁהוּא רַב וְגָדוֹל וְהוּא מְשַׁמֵּשׁ לִפְנֵי הַלֵּב. שֶׁאָמַר רַבִּי יְהוּדָה, הַכָּבֵד קוֹלֵט הַדָּם וּמְשַׁמֵּשׁ בּוֹ לִפְנֵי הַלֵּב.</p>\n<p>וַיֵּצֵא הָרִאשׁוֹן אַדְמוֹנִי. אָמַר רַב כַּהֲנָא, הַכָּבֵד הוּא הָרִאשׁוֹן, וְהוּא אַדְמוֹנִי. לָמָּה הוּא אַדְמוֹנִי? עַל שֶׁבּוֹלֵעַ אֶת הַדָּם תְּחִלָּה. רַבִּי אֱלִיעֶזֶר אוֹמֵר, לָמָּה נִקְרָא שְׁמוֹ רִאשׁוֹן? עַל שֶׁהוּא רִאשׁוֹן לִבְלֹעַ הַדָּם מִכָּל הַמַּאֲכָל, וְהוּא רִאשׁוֹן לַדָּם, אֲבָל לֹא לַיְצִירָה. וּבַמֶּה נְבָאֵר וְרַב יַעֲבֹד צָעִיר? עַל שֶׁהוּא רַב וְגָדוֹל בְּשִׁעוּרוֹ מִן הַלֵּב, וְהוּא עוֹבֵד לַלֵּב. אָמַר רַבִּי אַבָּא, לָמָּה בָּאָה הַפָּרָשָׁה הַזּוֹ? אֶלָּא לְהַרְאוֹת לִבְנֵי הָעוֹלָם, שֶׁאַף עַל גַּב שֶׁהַשְּׁלֵמוּת הַהִיא תִּהְיֶה בָּאָרֶץ - דַּרְכּוֹ וְטִבְעוֹ שֶׁל הָעוֹלָם לֹא יִשְׁתַּנֶּה. רַבִּי יֵיסָא אָמַר, בֹּא רְאֵה, הַכָּבֵד הוּא הַצָּד צַיִד, וְהוּא צַיִד בְּפִיו, וְהַלֵּב הוּא הַחוֹשֵׁב, וְהוּא יֹשֵׁב אֹהָלִים. זֶהוּ שֶׁכָּתוּב וַיָּזֶד יַעֲקֹב נָזִיד, חוֹשֵׁב מַחֲשָׁבוֹת, נוֹשֵׂא וְנוֹתֵן בַּתּוֹרָה.</p>\n<p>וַיָּזֶד יַעֲקֹב נָזִיד, רִבִּי בָא בְּשֵׁם רִבִּי אַחָא אָמַר, לְעוֹלָם טִבְעוֹ שֶׁל עוֹלָם אֵינוֹ מִשְׁתַּנֶּה, בּא רְאֵה, מַה כְּתִיב, וַיָּזֶד יַעֲקֹב נָזִיד, כְּמוֹ שֶׁנֶּאֱמַר (שמות יח) אֲשֶׁר זָדוּ עֲלֵיהֶם, וְתַרְגּוּמוֹ: שֶׁחָשְׁבוּ. כְּלוֹמַר, הַלֵּב חוֹשֵׁב וּמְהַרְהֵר בַּתּוֹרָה בִּידִיעַת בּוֹרְאוֹ. מַה כָּתוּב? וַיָּבא עֵשָׂו מִן הַשָּׂדֶה וְהוּא עָיֵף. הַכָּבֵד שֶׁדֶּרֶךְ טִבְעוֹ לָצֵאת וְלָצוּד צַיִד בְּפִיו לִבְלֹעַ וְאֵינוֹ מוֹצֵא, נִקְרָא עָיֵף, וְהוּא אוֹמֵר לַלֵּב: עַד שֶׁאַתָּה מְהַרְהֵר בִּדְבָרִים אֵלּוּ בְּדִבְרֵי תוֹרָה, הַרְהֵר בַּאֲכִילָה וּבִשְׁתִיָּה לְקַיֵּם גּוּפְךְ. זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר עֵשָׂו אֶל יַעֲקֹב הַלְעִיטֵנִי נָא מִן הָאָדם הָאָדם הַזֶּה, כִּי כֵן דַרְכִּי לִבְלֹעַ הַדָּם וּלְשַׁגֵּר לִשְׁאָר הָאֵבָרִים, כִּי עָיֵף אָנֹכִי, בְּלֹא אֲכִילָה וּשְׁתִיָּה. וְהַלֵּב אוֹמֵר: תֵּן לִי הָרִאשׁוֹן וְהַמֻּבְחָר מִכָּל מַה שֶּׁתִּבְלַע, תֵּן לִי בְּכוֹרָתְךְ. זֶה שֶׁכָּתוּב מִכְרָה כַיּוֹם אֶת בְּכֹרָתְךְ לִי, רֵאשִׁית הַתַּאֲוָה. עַד שֶׁהַלֵּב מְהַרְהֵר וְחוֹשֵׁב בַּמַּאֲכָל, בּוֹלֵעַ הַכָּבֵד. שֶׁאִלְמָלֵא אוֹתוֹ כִסּוּף וְהִרְהוּר שֶׁל הַלֵּב בַּמַּאֲכָל, לֹא יוּכְלוּ הַכָּבֵד וְהָאֵבָרִים לִבְלֹעַ. שֶׁאָמַר רַבִּי יוֹסֵי, כֵּן דֶּרֶךְ הָעֲבָדִים - שֶׁאֵינָם אוֹכְלִים עַד שֶׁהָאָדוֹן אוֹכֵל.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּתוּב לְאַחַר כֵּן, וְיַעֲקֹב נָתַן לְעֵשָׂו לֶחֶם וּנְזִיד עֲדָשִׁים. מַה זֶּה עֲדָשִׁים? עֲגַלְגַּלִּים כְּגֻלְגֹּלֶת, וְהַגַּלְגַּל סוֹבֵב בָּעוֹלָם, כְּלוֹמַר שֶׁלֹּא נִשְׁכָּח מִדַּרְכּוֹ. כָּךְ הוּא בֶּן אָדָם, בְּאוֹתוֹ זְמַן, אַף עַל גַּב שֶׁכָּל אוֹתוֹ חֶסֶד וְכָבוֹד וּשְׁלֵמוּת יִהְיוּ, דַּרְכּוֹ שֶׁל הָעוֹלָם לֶאֱכֹל וְלִשְׁתּוֹת לֹא יִשְׁתַּכַּח.</p>"],[9522011286,"<p>מִשְׁנָה, שָׁנִינוּ, אַרְבַּע רוּחוֹת הָעוֹלָם מְנַשְּׁבוֹת, וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְעוֹרֵר רוּחַ אֶחָד לְקַיֵּם הַגּוּף שֶׁיִּהְיֶה כָּלוּל מֵאַרְבַּע רוּחוֹת. זֶהוּ שֶׁכָּתוּב (יחזקאל לז) מֵאַרְבַּע רוּחוֹת בּאִי הָרוּחַ. בְּאַרְבַּע לֹא כָתוּב, אֶלָּא מֵאַרְבַּע רוּחוֹת הָעוֹלָם, שֶׁיְּהֵא כָּלוּל מֵאַ רְבַּעְתָּם. וְלָמַדְנוּ, אוֹתוֹ הָרוּחַ הוּא רוּחַ הַמּוֹלִיד, הוּא הָרוּחַ הָאוֹכֵל וְשׁוֹתֶה, וְאֵין בֵּין הָעוֹלָם הַזֶּה לִימוֹת הַמָּשִׁיחַ אֶלָּא שִׁעְבּוּד מַלְכֻיּוֹת בִּלְבַד, וְאֵין בֵּין עוֹלָם הַזֶּה לִתְחִיַּת הַמֵּתִים אֶלָּא נְקִיּוּת וְהַשָּׂגַת יְדִיעָה. רַב נַחְמָן אָמַר, וַאֲרִיכוּת יָמִים.</p>\n<p>אָמַר רַב יוֹסֵף, וְכִי יְמוֹת הַמָּשִׁיחַ וּתְחִיַּת הַמֵּתִים אֵינָם אֶחָד? אָמַר לוֹ, לֹא, שֶׁשָּׁנִינוּ, בֵּית הַמִּקְדָּשׁ קוֹדֵם לְקִבּוּץ גָּלֻיּוֹת, קִבּוּץ גָּלֻיּוֹת קוֹדֵם לִתְחִיַּת הַמֵּתִים, וּתְחִיַּת הַמֵּתִים הָאַחֲרוֹן שֶׁבְּכֻלָּם. מִנַּיִן לָנוּ? שֶׁכָּתוּב (תהלים קמו) בּוֹנֵה יְרוּשָׁלַיִם ה' נִדְחֵי יִשְׂרָאֵל יְכַנֵּס. הָרוֹפֵא לִשְׁבוּרֵי לֵב וּמְחַבֵּשׁ לְעַצְבוֹתָם. זוֹ הִיא תְחִיַּת הַמֵּתִים שֶׁהִיא הָרְפוּאָה לִשְׁבוּרֵי לֵב עַל מֵתֵיהֶם. בּוֹנֵה יְרוּשָׁלַיִם תְּחִלָּה, וְאַחֲרָיו נִדְחֵי יִשְׂרָאֵל יְכַנֵּס, וְהָרוֹפֵא לִשְׁבוּרֵי לֵב אַחֲרוֹן עַל הַכֹּל.</p>\n<p>שָׁנִינוּ, אַרְבָּעִים שָׁנָה קוֹדֵם הַקִּבּוּץ גָּלֻיּוֹת לִתְחִיַּת הַמֵּתִים, כְּמוֹ שֶׁאָמַרְנוּ וַיְהִי יִצְחָק בֶּן אַרְבָּעִים שָׁנָה. אַרְבָּעִים הַשָּׁנָה הַלָּלוּ מַה מַּעֲשֵׂיהֶם? אָמַר רַב כַּהֲנָא אָמַר רַבִּי בְּרוֹקָא, מִקִּבּוּץ גָּלֻיּוֹת עַד תְּחִיַּת הַמֵּתִים כַּמָּה צָרוֹת, כַּמָּה מִלְחָמוֹת יִתְעוֹרְרוּ עַל יִשְׂרָאֵל, וְאַשְׁרֵי הַנִּמְלָט מֵהֶם, שֶׁכָּתוּב (דניאל יב) בָּעֵת הַהִיא יִמָּלֵט עַמְּךְ כָּל הַנִּמְצָא כָּתוּב בַּסֵּפֶר. רַבִּי יְהוּדָה אָמַר מִכָּאן, יִתְבָּרְרוּ וְיִתְלַבְּנוּ וְיִצָּרְפוּ רַבִּים. רַבִּי יִצְחָק אָמַר מִכָּאן, (זכריה יג) וּצְרַפְתִּים כִּצְרֹף אֶת הַכֶּסֶף וּבְחַנְתִּים כִּבְחֹן אֶת הַזָּהָב. וּבְאוֹתָם הַיָּמִים יִהְיוּ יָמִים אֲשֶׁר יֹאמְרוּ אֵין לִי בָּהֶם חֵפֶץ. וּמִשָּׁעָה שֶׁיַּעַבְרוּ הַצָּרוֹת עַד תְּחִיַּת הַמֵּתִים אַרְבָּעִים שָׁנָה.</p>\n<p>רַב הוּנָא אָמַר, בּא רְאֵה, כִּי אַרְבָּעִים שָׁנָה הָלְכוּ בְּנֵי יִשְׂרָאֵל בַּמִּדְבָּר וְגוֹ' אֲשֶׁר לֹא שָׁמְעוּ בְּקוֹל ה' - כְּמוֹ כֵן (הגוף) כָּאן. אָמַר רַב יוֹסֵף, כָּל אֵלּוּ דָּבָר אֶחָד אָמְרוּ. וּלְסוֹף אַרְבָּעִים שָׁנָה, שֶׁהַצָּרוֹת יַעַבְרוּ וְהָרְשָׁעִים יִכְלוּ, יִחְיוּ הַמֵּתִים שׁוֹכְנֵי עָפָר. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (נחום א) לֹא תָקוּם פַּעֲמַיִם צָרָה, וְדַי לָהֶם בְּמַה שֶּׁעָבְרוּ. וּמִזְּמַן תְּחִיַּת הַמֵּתִים יִתְיַשֵּׁב הָעוֹלָם בְּיִשּׁוּבוֹ, זֶהוּ שֶׁכָּתוּב בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>רַבִּי אֶלְעָזָר בֶּן עֲרָךְ הָיָה יוֹשֵׁב, וְהָיָה מִצְטַעֵר בְּנַפְשׁוֹ מְאֹד. נִכְנַס לְפָנָיו רַבִּי יְהוֹשֻׁעַ. אָמַר לוֹ, מַרְאֵה הָאוֹר שֶׁל מְאוֹר הָעוֹלָם לָמָּה חֲשׁוּכִים? אָמַר לוֹ, מַרְאֶה וּפַחַד רַב נִכְנַס בִּי, שֶׁהֲרֵי אֲנִי רוֹאֶה מַה שֶּׁהִתְעוֹרְרוּ חֲבֵרֵינוּ בַּעֲלֵי הַבָּרַיְתָא, שֶׁשּׁוֹרָה עֲלֵיהֶם רוּחַ שֶׁל קְדוֹשִׁים, וְהַהוּא שֶׁהֵעִירוּ שֶׁבַּשִּׁשִּׁי יִהְיֶה גְאֻלָּה, יָפֶה. אֲבָל אֲנִי רוֹאֶה אֲרִיכוּת יֶתֶר עַל אוֹתָם שׁוֹכְנֵי עָפָר, שֶׁבָּאֶלֶף הַשִּׁשִּׁי לִזְמַן אַרְבַּע מֵאוֹת וּשְׁמוֹנֶה שָׁנִים מִמֶּנּוּ יִהְיוּ עוֹמְדִים כָּל שׁוֹכְנֵי עָפָר בְּקִיּוּמָם. וּמִשּׁוּם כָּךְ הֵעִירוּ חֲבֵרֵינוּ עַל הַפָּסוּק שֶׁקָּרָא לָהֶם בְּנֵי חֵת, חֵ\"ת - שֶׁיִּתְעוֹרְרוּ לְח\"ת שָׁנָה, וְהַיְנוּ שֶׁכָּתוּב (ויקרא כה) בִּשְׁנַת הַיּוֹבֵל הַ את תָּשֻׁבוּ אִישׁ אֶל אֲחֻזָּתוֹ. כְּשֶׁיִּשְׁתַּלֵּם הַ א\"ת, שֶׁהוּא חֲמֵשֶׁת אֲלָפִים וְאַרְבַּע מֵאוֹת וּשְׁמוֹנֶה, תָּשׁוּבוּ אִישׁ אֶל אֲחֻזָּתוֹ, אֶל נִשְׁמָתוֹ, שֶׁהִיא אֲחֻזָּתוֹ וְנַחֲלָתוֹ.</p>\n<p>(עוד) אָמַר רַבִּי יְהוֹשֻׁעַ, שֶׁזֶּה לֹא יִהְיֶה לְךְ קָשֶׁה, שֶׁהֲרֵי שָׁנִינוּ, שָׁלֹשׁ כִּתּוֹת הֵן: שֶׁל צַדִּיקִים גְּמוּרִים, וְשֶׁל רְשָׁעִים גְּמוּרִים, וְשֶׁל בֵּינוֹנִים. צַדִּיקִים גְּמוּרִים יָקוּמוּ בַּקִּימָה שֶׁל מֵתֵי אֶרֶץ יִשְׂרָאֵל, מֵהַיּוֹם כַּמָּה שָׁנִים, שֶׁהֵם קוֹדְמִים בַּתְּחִלָּה בִּשְׁנַת הָאַרְבָּעִים שֶׁל קִבּוּץ גָּלֻיּוֹת. וְהָאַחֲרוֹנִים כֻּלָּם לִזְמַן אַרְבַּע מֵאוֹת וּשְׁמוֹנֶה שָׁנָה לָאֶלֶף הַשִּׁשִּׁי, כְּמוֹ שֶׁאָמַרְנוּ. מִי יִזְכֶּה לָאֹרֶךְ הַזֶּה? מִי יִתְקַיֵּם בְּקִיּוּם דָּתוֹ בֵּין הַזְּמַן הַזֶּה, וְעַל כֵּן אֲנִי מִצְטַעֵר בְּנַפְשִׁי.</p>\n<p>אָמַר לוֹ, רַבִּי, הִנֵּה שָׁנִינוּ, יְהִי אוֹר - יְהִי רָ\"ז. חָזַר וְאָמַר, בִּתְשׁוּבָה יִתְקַדֵּם הַכֹּל. אָמַר רַבִּי יְהוֹשֻׁעַ, אִם לֹא שֶׁאָמַרְתָּ כָּךְ, חָסַמְנוּ אֶת הַפִּיּוֹת לְצַפּוֹת לַגְּאֻלָּה כָּל יוֹם, שֶׁכָּתוּב (יחזקאל לג) חֹסֶן יְשׁוּעוֹת. מַהוּ יְשׁוּעוֹת? אֵלּוּ הַמְצַפִּים יְשׁוּעוֹת בְּכָל יוֹם.</p>\n<p>מַהִי דַעְתּוֹ שֶׁל רַבִּי אֶלְעָזָר? הַיְנוּ מַה שֶּׁכָּתוּב וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ. מִמַּשְׁמָע שֶׁכָּתוּב מִיְּשֵׁנֵי, אֵלּוּ הֵם הַצַּדִּיקִים הַנִּקְדָּמִים בְּחַיֵּיהֶם קֹדֶם זֶה. וְכַמָּה שָׁנִים הֵם נִקְדָּמִים? רַבִּי יְהוּדָה אוֹמֵר, מָאתַיִם וְעֶשֶׂר שָׁנִים. רַבִּי יִצְחָק אוֹמֵר, רד\"י שָׁנָה, שֶׁכָּתוּב (במדבר כד) וְיֵרְ\"ד מִיַּעֲקֹב וְגוֹ'. יר\"ד שָׁנָה נִקְדָּמִים הַצַּדִּיקִים לִשְׁאָר כָּל אָדָם. רַב נַחְמָן אָמַר, לְפִי הַשִּׁעוּר שֶׁנִּבְלָה בֶּעָפָר. אָמַר לוֹ רַבִּי יוֹסֵי, אִם כֵּן, הַרְבֵּה תְחִיּוֹת הָיוּ, אֶלָּא כָּל הַתְּחִיּוֹת יִהְיוּ בְּאוֹתוֹ הַזְּמַן, וְזֶהוּ שֶׁנֶּאֱמַר בְּחָזוֹן, (דניאל י) וֶאֱמֶת הַדָּבָר וְצָבָא גָדוֹל.</p>\n<p>וַיְהִי רָעָב בָּאָרֶץ מִלְּבַד הָרָעָב הָרִאשׁוֹן אֲשֶׁר הָיָה בִּימֵי אַבְרָהָם. רַבִּי אַבָּהוּ פָּתַח וְאָמַר, (שיר א) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. שֶׁשָּׁנִינוּ, אַרְבַּע תְּקוּפוֹת וְאַרְבָּעָה זְמַנִּים מְשֻׁנִּים זוֹ מִזּוֹ יַעַבְרוּ הַצַּדִּיקִים לֶעָתִיד לָבֹא. הָאֶחָד - אוֹתוֹ זְמַן יִשְׂגֶּא הַחָכְמָה בָּעוֹלָם וְיַשִּׂיגוּ הַשָּׂגָה מַה שֶּׁלֹּא הִשִּׂיגוּ בְּזֶה הָעוֹלָם. שֶׁשָּׁנִינוּ, אָמַר רַבִּי פִּנְחָס, הַשָּׂגַת הַצַּדִּיקִים לֶעָתִיד לָבֹא יוֹתֵר מִמַּלְאֲכֵי הַשָּׁרֵת, שֶׁכָּתוּב (ישעיה יא) כַּמַּיִם לַיָּם מְכַסִּים, הַשֵּׁנִי תִּתְעַסְּקוּ. (חסר) (עד כאן מדרש הנעלם)</p>"],[9522011287,"<p>וַיִּגְדְּלוּ הַנְּעָרִים, הַצַּד שֶׁל אַבְרָהָם גָּרַם לָהֶם לְהִתְגַּדֵּל וּזְכוּתוֹ סִיְּעָה לָהֶם, הוּא הָיָה מְחַנֵּךְ אוֹתָם בְּמִצְווֹת, שֶׁכָּתוּב כִּי יְדַעְתִּיו לְמַעַן יְצַוֶּה אֶת בָּנָיו וְגוֹ', לְרַבּוֹת יַעֲקֹב וְעֵשָׂו. וַיִּגְדְּלוּ הַנְּעָרִים וַיְהִי עֵשָׂו אִישׁ יֹדֵעַ צַיִד וְגוֹ'. אָמַר רַבִּי אֶלְעָזָר, כָּל אֶחָד וְאֶחָד נִפְרַד לְדַרְכּוֹ, זֶה לְצַד הָאֱמוּנָה - וְזֶה לַצַּד שֶׁל עֲבוֹדָה זָרָה.</p>\n<p>וְכֵן הָיָה בַּמֵּעַיִם שֶׁל רִבְקָה, שֶׁשָּׁם כָּל אֶחָד הָלַךְ לְצִדּוֹ. שֶׁכַּאֲשֶׁר הִיא הִשְׁתַּדְּלָה בְּמַעֲשִׂים כְּשֵׁרִים, אוֹ שֶׁעָבְרָה סָמוּךְ לְמָקוֹם טוֹב לַעֲשׂוֹת אֶת מִצְווֹת הַתּוֹרָה, הָיָה יַעֲקֹב שָׂמֵחַ וְדוֹחֵק לָצֵאת. וּכְשֶׁהָיְתָה הוֹלֶכֶת סָמוּךְ לְמָקוֹם שֶׁל עֲבוֹדָה זָרָה, אוֹתוֹ הָרָשָׁע הִכָּה לָצֵאת, וּבֵאֲרוּהוּ. וּמִשּׁוּם כָּךְ, כְּשֶׁנִּבְרְאוּ וְיָצְאוּ לָעוֹלָם, כָּל אֶחָד נִפְרַד וְהָלַךְ וְנִמְשַׁךְ לִמְקוֹמוֹ שֶׁרָאוּי לוֹ. וְעַל כֵּן וַיִּגְדְּלוּ הַנְּעָרִים וַיְהִי עֵשָׂו אִישׁ יֹדֵעַ צַיִד וְגוֹ'.</p>\n<p>וַיְּאהַב יִצְחָק אֶת עֵשָׂו כִּי צַיִד בְּפִיו. הֲרֵי פֵּרְשׁוּהוּ, (כמו) שֶׁכָּתוּב אִישׁ יֹדֵעַ צַיִד אִישׁ שָׂדֶה. וְכָתוּב שָׁם (בראשית י) הוּא הָיָה גִבֹּר צַיִד. (מהו) אִישׁ שָׂדֶה, לְקַפֵּחַ אֶת בְּנֵי הָאָדָם וְלַהֲרֹג אוֹתָם. וְהוּא אָמַר שֶׁעָשָׂה תְפִלָּה, וְצָד אוֹתוֹ בְּפִיו. אִישׁ שָׂדֶה, מִשּׁוּם שֶׁחֵלֶק גּוֹרָלוֹ אֵינוֹ בְּיִשּׁוּב, אֶלָּא בְּמָקוֹם חָרֵב, בַּמִּדְבָּר, בַּשָּׂדֶה, וְעַל זֶה אִישׁ שָׂדֶה.</p>\n<p>וְאִם תֹּאמַר, אֵיךְ יִצְחָק לֹא יָדַע אֶת כָּל מַעֲשָׂיו הָרָעִים שֶׁל עֵשָׂו, וַהֲרֵי הַשְּׁכִינָה הָיְתָה עִמּוֹ? שֶׁאִם לֹא שָׁרְתָה עִמּוֹ שְׁכִינָה, אֵיךְ יָכֹל לְבָרֵךְ אֶת יַעֲקֹב בְּשָׁעָה שֶׁבֵּרַךְ אוֹתוֹ? אֶלָּא וַדַּאי שֶׁשְּׁכִינָה הָיְתָה דָרָה עִמּוֹ בַּבַּיִת וְדָרָה עִמּוֹ תָּמִיד, אֲבָל לוֹ הוֹדִיעָה לוֹ, כְּדֵי שֶׁיִּתְבָּרֵךְ יַעֲקֹב בְּלִי דַעְתּוֹ, אֶלָּא בְּדַעְתּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְכָךְ צָרִיךְ, שֶׁבַּשָּׁעָה הַהִיא שֶׁנִּכְנַס יַעֲקֹב לִפְנֵי אָבִיו, נִכְנְסָה עִמּוֹ שְׁכִינָה, וְאָז רָאָה יִצְחָק בְּדַעְתּוֹ שֶׁרָאוּי לִבְרָכָה וְיִתְבָּרֵךְ מִדַּעַת הַשְּׁכִינָה.</p>"],[9522011288,"<p>בֹּא רְאֵה, (פעם אחת היה יושב רבי שמעון ושאר החברים, נכנס לפניו רבי אלעזר בנו, אמרו לרבי שמעון, דבר גדול רצינו לבקש לפניך בענינם של יעקב ועשו, איך לא רצה יעקב לתת לעשו תבשיל עדשים עד שמכר לו את בכורתו? ועוד, שאמר עשו ליצחק אביו, ויעקבני זה פעמים,</p>\n<p>אמר להם, בשעה הזאת אתם חיבים לקבל מלקות, שהאמנתם לדברי עשו ושקרתם לדברי י קב, שהרי הכתוב מעיד עליו ויעקב איש תם, ועוד כתוב תתן אמת ליעקב, אלא כך הוא ענינו של יעקב עם עשו, משום שעשו היה שונא את הבכורה בראשונה, והיה רוצה מיעקב שיקח אותה ממנו אפלו בלי כסף, זהו שכתוב ויאכל וישת ויקם וילך ויבז עשו את הבכרה).</p>\n<p>וַיָּזֶד יַעֲקֹב נָזִיד וַיָּבא עֵשָׂו מִן הַשָּׂדֶה וְהוּא עָיֵף. אָמַר רַבִּי אֶלְעָזָר, וַיָּזֶד יַעֲקֹב - הִנֵּה פֵּרְשׁוּהָ שֶׁהֲרֵי בִּשְׁבִיל הָאֵבֶל שֶׁל אַבְרָהָם זֶה הָיָה, אֲבָל וַיָּזֶד יִצְחָק נָזִיד הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא וַיָּזֶד יַעֲקֹב נָזִיד, שֶׁהוּא הָיָה יוֹדֵעַ אֶת הַשֹּׁרֶשׁ שֶׁלּוֹ בְּאוֹתוֹ צַד שֶׁנִּדְבַּק בּוֹ, מִשּׁוּם כָּךְ עָשָׂה תַבְשִׁילִים אֲדֻמִּים, עֲדָשִׁים תַּבְשִׁיל אָדם, שֶׁהַתַּבְשִׁיל הַזֶּה מְשַׁבֵּר אֶת הַכֹּחַ וְהַחֹזֶק שֶׁל הַדָּם הָאָדם כְּדֵי לִשְׁבֹּר אֶת חָזְקוֹ וְכֹחוֹ, וּמִשּׁוּם כָּךְ עָשָׂה לוֹ בְּחָכְמָה כְּמוֹ אוֹתוֹ הַצֶּבַע הָאָדם.</p>\n<p>וְעַל הַתַּבְשִׁיל הַהוּא נִמְכַּר לוֹ לְעֶבֶד וּמָכַר בְּכוֹרָתוֹ לְיַעֲקֹב, וּבַשָּׁעָה הַהִיא יָדַע יַעֲקֹב, שֶׁבִּשְׁבִיל שָׂעִיר אֶחָד שֶׁיַּקְרִיבוּ יִשְׂרָאֵל לַדַּרְגָּה שֶׁלּוֹ, יִתְהַפֵּךְ לְעֶבֶד לְבָנָיו וְלֹא יְקַטְרֵג לָהֶם. וּבַכֹּל הָלַךְ יַעֲקֹב עִם עֵשָׂו בְּחָכְמָה, מִשּׁוּם אוֹתָהּ הַדַּרְגָּה שֶׁל עֵשָׂו הֶחָכָם, וְלֹא יָכֹל לִשְׁלֹט, וְנִכְנַע וְלֹא נִטְמָא (בו) בֵיתוֹ, וְהוּא יָגֵן עָלָיו.</p>\n<p>(ויאמר עשו אל יעקב הלעיטני נא מן האדם האדם הזה, למה כתוב פעמים האדם? אלא משום שכל מה שיש בו אדם, כמו שנאמר ויצא הראשון אדמוני, ותבשילו אדם, שכתוב מן האדם האדם הזה, וארצו אדמה, שכתוב ארצה שעיר שדה אדום, ואנשיו אדמים, שכתוב הוא עשו אבי אדום, ומי שעתיד להפרע ממנו אדם, שכתוב דודי צח ואדום, ולבושו אדם, שכתוב מדוע אדם ללבושך, וכתוב מי זה בא מאדום,)</p>\n<p>אָמַר רַבִּי יְהוּדָה, וְכֵן בְּלָבָן נִרְאֶה כָּךְ, מִשּׁוּם שֶׁהֲרֵי הוּא הָיָה מְכַשֵּׁף, כַּכָּתוּב (בראשית כ) נִחַשְׁתִּי וַיְבָרֲכֵנִי ה' בִּגְלָלֶךְ. וְאַף עַל גַּב שֶׁיַּעֲקֹב נִקְרָא אִישׁ שָׁלֵם, מִשּׁוּם כָּךְ הָיָה שָׁלֵם, עִם מִי שֶׁהִצְטָרֵךְ לוֹ לָלֶכֶת עִמּוֹ בְּרַחֲמִים הָיָה הוֹלֵךְ, וְעִם מִי שֶׁהִצְטָרֵךְ לוֹ לָלֶכֶת עִמּוֹ בְּדִין קָשֶׁה וּבְעַקְמִימוּת הָיָה הוֹלֵךְ, מִשּׁוּם שֶׁשְּׁנֵי חֲלָקִים הָיוּ בוֹ, וְעָלָיו כָּתוּב (תהלים יח) עִם חָסִיד תִּתְחַסָּד וְעִם עִקֵּשׁ תִּתְפַּתָּל. עִם חָסִיד בְּצַד הַחֶסֶ\"ד, וְעִם הָעִקֵּשׁ בַּצַּד שֶׁל הַדִּין הַקָּשֶׁה, הַכֹּל כָּרָאוּי.</p>"],[9522011289,"<p>וַיְהִי רָעָב בָּאָרֶץ מִלְּבַד הָרָעָב הָרִאשׁוֹן וְגוֹ'. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (שם יא) ה' צַדִּיק יִבְחָן וְרָשָׁע וְאֹהֵב (ר\"ת נחש) חָמָס שָׂנְאָה נַפְשׁוֹ. כַּמָּה מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא מְתֻקָּנִים, וְכָל מַה שֶּׁהוּא עוֹשֶׂה - הַכֹּל עַל הַדִּין וְהָאֱמֶת, כַּכָּתוּב (דברים לב) הַצּוּר תָּמִים פָּעֳלוֹ כִּי כָל דְּרָכָיו מִשְׁפָּט אֵל אֱמוּנָה וְאֵין עָוֶל צַדִּיק וְיָשָׁר הוּא.</p>\n<p>בֹּא רְאֵה, לֹא דָן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אָדָם הָרִאשׁוֹן עַד שֶׁצִּוָּה אוֹתוֹ לְתוֹעַלְתּוֹ שֶׁלֹּא יִסְטֶה לִבּוֹ וּרְצוֹנוֹ לְדֶרֶךְ אַחֶרֶת כְּדֵי שֶׁלֹּא יִטָּמֵא, וְהוּא לֹא נִשְׁמַר, וְעָבַר עַל מִצְווֹת אֲדוֹנוֹ, וְאַחַר כֵּן דָּן אוֹתוֹ בְּדִין.</p>\n<p>וְעִם כָּל זֶה לֹא דָן אוֹתוֹ כָּרָאוּי לוֹ, וְהֶאֱרִיךְ עִמּוֹ אֶת רֻגְזוֹ וְהִתְקַיֵּם יוֹם אֶחָד שֶׁהוּא אֶלֶף שָׁנִים, פְּרָט לְאוֹתָם שִׁבְעִים שָׁנִים שֶׁמָּסַר לְדָוִד הַמֶּלֶךְ, שֶׁלֹּא הָיָה לוֹ מֵעַצְמוֹ כְּלוּם.</p>\n<p>כְּמוֹ כֵן אֵינוֹ דָן אֶת הָאָדָם כְּמַעֲשָׂיו הָרָעִים שֶׁהוּא עוֹשֶׂה תָמִיד, שֶׁאִם כָּךְ לֹא יָכוֹל הָעוֹלָם לְהִתְקַיֵּם, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מַאֲרִיךְ רֻגְזוֹ עִם צַדִּיקִים, וְעִם רְשָׁעִים יוֹתֵר מֵהַצַּדִּיקִים. עִם הָרְשָׁעִים כְּדֵי שֶׁיָּשׁוּבוּ בִתְשׁוּבָה שְׁלֵמָה, שֶׁיִּתְקַיְּמוּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, כַּכָּתוּב (יחזקאל לג) חַי אָנִי נְאֻם ה' וְגוֹ' אִם אֶחְפֹּץ וְגוֹ' כִּי אִם בְּשׁוּב רָשָׁע מִדַּרְכּוֹ וְחָיָה. וְחָיָה בָּעוֹלָם הַזֶּה, וְחָיָה בָּעוֹלָם הַבָּא. וְעַל כֵּן מַאֲרִיךְ לָהֶם אֶת רֻגְזוֹ תָּמִיד. אוֹ כְּדֵי שֶׁיֵּצֵא מֵהֶם גֶּזַע טוֹב בָּעוֹלָם כְּמוֹ שֶׁהוֹצִיא אֶת אַבְרָהָם מִתֶּרַח, שֶׁהוּא גֶזַע טוֹב וְשֹׁרֶשׁ וְחֵלֶק טוֹב לָעוֹלָם.</p>\n<p>אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא מְדַקְדֵּק עִם הַצַּדִּיקִים תָּמִיד בְּכָל הַמַּעֲשִׂים שֶׁהֵם עוֹשִׂים, מִשּׁוּם שֶׁהוּא יוֹדֵעַ שֶׁלֹּא יִסְטוּ יָמִינָה וּשְׂמֹאלָה, וּמִשּׁוּם כָּךְ בּוֹחֵן אוֹתָם, לֹא בִּשְׁבִילוֹ, שֶׁהֲרֵי הוּא יוֹדֵעַ אֶת הַיֵּצֶר וְכֹחַ הָאֱמוּנָה שֶׁלָּהֶם, אֶלָּא כְּדֵי לְהָרִים רֹאשָׁם בִּשְׁבִילָם.</p>\n<p>כְּמוֹ זֶה עָשָׂה לוֹ לְאַבְרָהָם, שֶׁכָּתוּב (בראשית כב) וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. מַה זֶּה נִסָּה? הֲרָמַת נֵס, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סב) הָרִימוּ נֵס, שְׂאוּ נֵס, הֵרִים דִּגְלוֹ בְּכָל הָעוֹלָם. וְאַף עַל גַּב שֶׁזֶּה נִתְבָּאֵר, בִּשְׁבִיל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא הֵרִים אֶת דִּגְלוֹ שֶׁל אַבְרָהָם בְּעֵינֵי כֻלָּם. זֶהוּ שֶׁכָּתוּב נִסָּה אֶת אַבְרָהָם. אַף כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּדֵי לְהָרִים אֶת דֶּגֶל הַצַּדִּיקִים, הוּא בּוֹחֵן אוֹתָם לְהָרִים אֶת רֹאשָׁם בְּכָל הָעוֹלָם.</p>\n<p>צַדִּיק יִבְחָן, מָה הַטַּעַם? אָמַר רַבִּי שִׁמְעוֹן, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא, כְּשֶׁמִּתְרַצֶּה בַּצַּדִּיקִים, מַה כָּתוּב? (ישעיה נג) וַה' חָפֵץ דַּכְּאוֹ הֶחֱלִי, וּבֵאֲרוּהוּ. אֲבָל מִשּׁוּם שֶׁרְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מִתְרַצֶּה אֶלָּא בַּנְּשָׁמָה, אֲבָל בַּגּוּף לֹא. שֶׁהֲרֵי הַנְּשָׁמָה דּוֹמָה לַנְּשָׁמָה שֶׁל מַעְלָה, וְהַגּוּף אֵינוֹ רָאוּי לְהֵאָחֵז לְמַעְלָה, וְאַף עַל גַּב שֶׁדְּמוּת הַגּוּף הִיא בְּסוֹד עֶלְיוֹן.</p>\n<p>וּבֹא וּרְאֵה, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה מִנִּשְׁמַת הָאָדָם לֵהָנוֹת (להאיר) בָּהּ, הוּא מַכֶּה אֶת הַגּוּף כְּדֵי שֶׁתִּשְׁלֹט הַנְּשָׁמָה, שֶׁהֲרֵי בְּעוֹד הַנְּשָׁמָה עִם הַגּוּף, הַנְּשָׁמָה לֹא יְכוֹלָה לִשְׁלֹט. שֶׁכַּאֲשֶׁר יֵשׁ רַע (נשבר) לַגּוּף, הַנְּשָׁמָה שׁוֹלֶטֶת. צַדִּיק יִבְחָן, מַה זֶּה צַדִּיק יִבְחָן? כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כח) אֶבֶן בֹּחַן. כָּךְ גַּם צַדִּיק יִבְחָן, מְחַזֵּק אוֹתוֹ. כְּאֶבֶן בּחַן הַזּוֹ שֶׁהִיא פִּנַּת יִקְרַת, כָּךְ גַּם צַדִּיק יִבְחָן.</p>\n<p>וְרָשָׁע וְאֹהֵב חָמָס שָׂנְאָה נַפְשׁוֹ (תהלים יא). מַה זֶּה שָׂנְאָה נַפְשׁוֹ? הֲתַעֲלֶה עַל דַּעְתְּךְ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא שֶׁנַּפְשׁוֹ שׂוֹנֵאת אֶת הָרָשָׁע הַהוּא? אֶלָּא אוֹתָהּ דַּרְגָּה שֶׁכָּל הַנְּשָׁמוֹת תְּלוּיוֹת בָּהּ, שָׂנְאָה נַפְשׁוֹ שֶׁל הָרָשָׁע הַהוּא שֶׁלֹּא רוֹצֶה אוֹתָהּ כְּלָל, לֹא רוֹצֶה אוֹתָהּ לֹא בָּעוֹלָם הַזֶּה וְלֹא בָּעוֹלָם הַבָּא, וּמִשּׁוּם כָּךְ כָּתוּב וְרָשָׁע וְאֹהֵב חָמָס שָׂנְאָה נַפְשׁוֹ, וַדַּאי. דָּבָר אַחֵר שָׂנְאָה נַפְשׁוֹ, כְּמוֹ שֶׁנֶּאֱמַר (עמוס ו) נִשְׁבַּע אֲדנָי יֱהִֹוִה בְּנַפְשׁוֹ, וּמִשּׁוּם כָּךְ צַדִּיק יִבְחָן.</p>\n<p>בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם, צִוָּה אוֹתוֹ לְהֵיטִיב לוֹ. נָתַן לוֹ חָכְמָה, הִתְעַלָּה בְּדַרְגָּתוֹ לְמַעְלָה. כְּשֶׁיָּרַד לְמַטָּה, רָאָה תְּשׁוּקַת הַיֵּצֶר הָרָע וְנִדְבַּק בּוֹ, וְשָׁכַח כָּל מַה שֶּׁהִתְעַלָּה (שהסתכל) בַּכָּבוֹד הָעֶלְיוֹן שֶׁל רַבּוֹ.</p>\n<p>בָּא נֹחַ, בַּהַתְחָלָה כָּתוּב (בראשית ו) נֹחַ אִישׁ צַדִּיק תָּמִים הָיָה, וְאַחַר כָּךְ יָרַד לְמַטָּה, וְרָאָה יַיִן חָזָק שֶׁלֹּא צָלוּל, מִיּוֹם אֶחָד, וְשָׁתָה מִמֶּנּוּ וְהִשְׁתַּכֵּר וְהִתְגַּלָּה, כַּכָּתוּב וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה.</p>\n<p>בָּא אַבְרָהָם, הִתְעַלָּה בַּחָכְמָה, וְהִסְתַּכֵּל בִּכְבוֹד רִבּוֹנוֹ. אַחַר כָּךְ וַיְהִי רָעָב בָּאָרֶץ וַיֵּרֶד אַבְרָם מִצְרַיְמָה לָגוּר שָׁם כִּי כָבֵד הָרָעָב בָּאָרֶץ וְגוֹ'. מַה כָּתוּב אַחַר כָּךְ? וַיַּעַל אַבְרָם מִמִּצְרַיִם הוּא וְאִשְׁתּוֹ וְכָל אֲשֶׁר לוֹ וְלוֹט עִמּוֹ הַנֶּגְבָּה, וְהִתְעַלָּה לְדַרְגָּתוֹ הָרִאשׁוֹנָה שֶׁהָיְתָה בּוֹ בָּרִאשׁוֹנָה, וְנִכְנַס בְּשָׁלוֹם וְיָצָא בְשָׁלוֹם.</p>\n<p>בָּא יִצְחָק, מַה כָּתוּב? וַיְהִי רָעָב בָּאָרֶץ מִלְּבַד הָרָעָב הָרִאשׁוֹן וְגוֹ', וְהָלַךְ יִצְחָק וְהִתְעַלָּה מִשָּׁם אַחַר כָּךְ בְּשָׁלוֹם. וְאֶת כָּל הַצַּדִּיקִים בּוֹחֵן הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּדֵי לְהָרִים אֶת רֹאשָׁם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011290,"<p>וַיִּשְׁאֲלוּ אַנְשֵׁי הַמָּקוֹם לְאִשְׁתּוֹ וַיֹּאמֶר אֲחֹתִי הִיא, כְּמוֹ שֶׁאָמַר אַבְרָהָם, מִשּׁוּם שֶׁשְּׁכִינָה הָיְתָה עִמּוֹ וְעִם אִשְׁתּוֹ, וּבִשְׁבִיל הַשְּׁכִינָה הוּא אָמַר, שֶׁכָּתוּב (משלי ז) אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ, וְעַל כֵּן הִתְחַזֵּק וְאָמַר אֲחֹתִי הִיא. עוֹד, אַבְרָהָם וְיִצְחָק כָּךְ רָאוּי, שֶׁוַּדַּאי מִשּׁוּם הַפָּסוּק שֶׁכָּתוּב (שיר ה) אֲחֹתִי רַעְיָתִי יוֹנָתִי תַּמָּתִי, וּמִשּׁוּם כָּךְ וַדַּאי נִרְאֶה לָהֶם לוֹמַר אֲחֹתִי הִיא, וְעַל כֵּן מִתְחֲזְקִים הַצַּדִּיקִים בַּקָּבָּ\"ה.</p>\n<p>וַיְהִי כִּי אָרְכוּ לוֹ שָׁם הַיָּמִים וְגוֹ'. אֵת רִבְקָה אִשְׁתּוֹ - דַּוְקָא, (וזו השכינה, כמו ש בודה זרה כתוב בה ויקומו לצחק, כך גם מצחק את) זוֹ שְׁכִינָה שֶׁהָיְתָה עִם רִבְקָה. דָּבָר אַחֵר, וְכִי תַעֲלֶה עַל דַּעְתְּךְ שֶׁיִּצְחָק הָיָה מְשַׁמֵּשׁ מִטָּתוֹ בַּיּוֹם? שֶׁהֲרֵי שָׁנִינוּ, יִשְׂרָאֵל הֵם קְדוֹשִׁים וְלֹא מְשַׁמְּשִׁים מִטָּתָם בַּיּוֹם, וְיִצְחָק שֶׁהָיָה קָדוֹשׁ הָיָה מְשַׁמֵּשׁ מִטָּתוֹ בַּיּוֹם?</p>\n<p>אֶלָּא וַדַּאי שֶׁאֲבִימֶלֶךְ הָיָה חָכָם, וְהוּא הִסְתַּכֵּל בְּאִיצְטַגְנִינוּתוֹ שֶׁהוּא חַלּוֹן. כָּתוּב כָּאן בְּעַד הַחַלּוֹן, וְכָתוּב שָׁם (שופטים ה) בְּעַד הַחַלּוֹן נִשְׁקָפָה וַתְּיַבֵּב אֵם סִיסְרָא. מַה לְּהַלָּן בְּאִיצְטַגְנִינוּת, אַף כָּאן בְּאִיצְטַגְנִינוּת. וְרָאָה שֶׁלֹּא הָיָה כְּמוֹ שֶׁאוֹמֵר יִצְחָק, אֶלָּא וַדַּאי הוּא מְצַחֵק עִמָּהּ, וְהִיא אִשְׁתּוֹ. וְאָז וַיִּקְרָא אֲבִימֶלֶךְ לְיִצְחָק וַיֹּאמֶר וְגוֹ'. רַבִּי יוֹסֵי אָמַר, נָאֶה הָיָה לַאֲבִימֶלֶךְ לַעֲשׂוֹת לְיִצְחָק כְּמוֹ שֶׁעָשָׂה לְאַבְרָהָם, רַק שֶׁזֶּה הוֹכִיחַ אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרִאשׁוֹנָה.</p>\n<p>בֹּא רְאֵה, כָּתוּב כִּי אָמַרְתִּי רַק אֵין יִרְאַת אֱלֹהִים בַּמָּקוֹם הַזֶּה. אָמַר רַבִּי אַבָּא, מִשּׁוּם כָּךְ אָמַר אֲחֹתִי הִיא, כְּדֵי לְהִדָּבֵק בַּשְּׁכִינָה, שֶׁכָּתוּב אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ. מָה הַטַּעַם? מִשּׁוּם שֶׁבָּהֶם לֹא הָיְתָה אֱמוּנָה. שֶׁאִם נִמְצְאָה בָהֶם אֱמוּנָה, לֹא הָיָה צָרִיךְ, אֲבָל מִתּוֹךְ שֶׁלֹּא הָיְתָה בֵינֵיהֶם אֱמוּנָה אָמַר כָּךְ, וּמִשּׁוּם כָּךְ אָמַר, כִּי אָמַרְתִּי רַק אֵין יִרְאַת אֱלֹהִים בַּמָּקוֹם הַזֶּה. אֵין יִרְאַת אֱלֹהִים, זוֹ הָאֱמוּנָה.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, מִשּׁוּם שֶׁלֹּא שׁוֹרָה הַשְּׁכִינָה מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה, וְעַל זֶה אֵין יִרְאַת אֱלֹהִים בַּמָּקוֹם הַזֶּה, שֶׁזֶּה לֹא מְקוֹמוֹ וְלֹא שׁוֹרֶה כָּאן. וְיִצְחָק הֶחֱזִיק בּוֹ בֶּאֱמוּנָה, שֶׁרָאָה שֶׁהִנֵּה הַשְּׁכִינָה שׁוֹרָה בְּתוֹךְ אִשְׁתּוֹ.</p>"],[9522011291,"<p>וַיְצַו אֲבִימֶלֶךְ אֶת כָּל הָעָם לֵאמֹר הַנֹּגֵעַ בָּאִישׁ הַזֶּה וּבְאִשְׁתּוֹ מוֹת יוּמָת בֹּא רְאֵה כַּמָּה מַאֲרִיךְ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לָרְשָׁעִים מִשּׁוּם אוֹתוֹ הַחֶסֶד שֶׁעָשָׂה עִם הָאָבוֹת הַקְּדוֹשִׁים, שֶׁהֲרֵי מִשּׁוּם זֶה לֹא שָׁלְטוּ בְּיִשְׂרָאֵל עַד לְאַחַר דּוֹרוֹת אַחֲרוֹנִים. יָפֶה עָשָׂה אֲבִימֶלֶךְ שֶׁעָשָׂה חֶסֶד עִם יִצְחָק שֶׁאָמַר לוֹ (לאברהם) הִנֵּה אַרְצִי לְפָנֶיךְ בַּטּוֹב בְּעֵינֶיךְ שֵׁב.</p>\n<p>רַבִּי יְהוּדָה אָמַר, חֲבָל עַל הָרְשָׁעִים שֶׁחַסְדָּם אֵינוֹ שָׁלֵם. בֹּא רְאֵה, עֶפְרוֹן אָמַר בַּהַתְחָלָה, (בראשית כג) אֲדנִי שְׁמָעֵנִי הַשָּׂדֶה נָתַתִּי לָךְ וְהַמְּעָרָה אֲשֶׁר בּוֹ לְךְ נְתַתִּיהָ וְגוֹ'. וְאַחַר כָּךְ אָמַר, אֶרֶץ אַרְבַּע מֵאֹת שֶׁקֶל כֶּסֶף וְגוֹ'. וְכָתוּב וַיִּשְׁקֹל אַבְרָהָם לְעֶפְרֹן וְגוֹ', עֹבֵר לַסֹּחֵר. אַף כָּאן כָּתוּב בָּרִאשׁוֹנָה הִנֵּה אַרְצִי לְפָנֶיךְ וְגוֹ', וְאַחַר כָּךְ אָמַר לוֹ לֵךְ מֵעִמָּנוּ כִּי עָצַמְתָּ מִמֶּנּוּ מְאֹד. אָמַר לוֹ רַבִּי אֶלְעָזָר, זֶה הַחֶסֶד שֶׁעָשָׂה עִמּוֹ - שֶׁלֹּא לָקַח מִשֶּׁל אֲבִימֶלֶךְ כְּלוּם, וּשְׁלָחוֹ עִם כָּל מָמוֹנוֹ, וְאַחַר כָּךְ הָלַךְ אַחֲרָיו לִכְרוֹת עִמּוֹ בְּרִית.</p>\n<p>וְאָמַר רַבִּי אֶלְעָזָר, יָפֶה עָשָׂה יִצְחָק, שֶׁהֲרֵי מִשּׁוּם שֶׁיָּדַע אֶת סוֹד הַחָכְמָה הִשְׁתַּדֵּל וְחָפַר בְּאֵר מַיִם, כְּדֵי לְהִתְחַזֵּק בָּאֱמוּנָה כָּרָאוּי. כֵּן אַבְרָהָם הִשְׁתַּדֵּל וְחָפַר בְּאֵר מַיִם (וכן יצחק). יַעֲקֹב מָצָא אוֹתָהּ מְתֻקֶּנֶת וְיָשַׁב עָלֶיהָ, וְכֻלָּם הָלְכוּ אַחֲרָיו וְהִשְׁתַּדְּלוּ, כְּדֵי לְהִתְחַזֵּק בָּאֱמוּנָה הַשְּׁלֵמָה כָּרָאוּי.</p>\n<p>וְכָעֵת יִשְׂרָאֵל מִתְחַזְּקִים בּוֹ בַּסּוֹדוֹת שֶׁל מִצְווֹת הַתּוֹרָה, כְּמוֹ שֶׁכָּל יוֹם וָיוֹם מִתְחַזֵּק אָדָם בְּצִיצִית, שֶׁהִיא מִצְוָה, וְאָדָם מִתְעַטֵּף בָּהּ. כָּךְ גַּם בַּתְּפִלִּין שֶׁמֵּנִיחַ עַל רֹאשׁוֹ וּבִזְרוֹעוֹ, שֶׁהוּא סוֹד עֶלְיוֹן כָּרָאוּי, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בָּאָדָם שֶׁמִתְעַטֵּר בּוֹ בִּתְפִלִּין וּמִתְעַטֵּף בְּצִיצִית, וְהַכֹּל סוֹד הָאֱמוּנָה הָעֶלְיוֹנָה.</p>\n<p>וְעַל כֵּן, מִי שֶׁלֹּא מִתְעַטֵּף בָּזֶה וְלֹא מִתְעַטֵּר לְהִתְחַזֵּק בַּתְּפִלִּין בְּכָל יוֹם, דּוֹמֶה לוֹ שֶׁאֵין שׁוֹרָה עִמּוֹ הָאֱמוּנָה, וְסָר מִמֶּנּוּ פַּחַד רִבּוֹנוֹ, וּתְפִלָּתוֹ אֵינָהּ תְּפִלָּה כָּרָאוּי. וּמִשּׁוּם כָּךְ הָיוּ הָאָבוֹת מִתְחַזְּקִים בְּתוֹךְ הָאֱמוּנָה הָעֶלְיוֹנָה, מִשּׁוּם שֶׁבְּאֵר הָעֶלְיוֹנָה שֶׁל סוֹד הָאֱמוּנָה הַשְּׁלֵמָה שׁוֹרָה בּוֹ.</p>"],[9522011292,"<p>וַיַּעִִתֵּק מִשָּׁם וַיַּחְפֹּר בְּאֵר אַחֶרֶת וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (ישעיה נח) וְנָחֲךְ ה' תָּמִיד וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ וְעַצְמֹתֶיךְ יַחֲלִיץ וְגוֹ'. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ וְנִתְבָּאֵר. אֲבָל בַּפָּסוּק הַזֶּה בּוֹ הֶחֱזִיקוּ בַּעֲלֵי הָאֱמוּנָה שֶׁהִבְטִיחַ לָהֶם לָעוֹלָם הַבָּא. וְנָחֲךְ ה' תָּמִיד - בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וְנָחֲךְ ה', כֵּיוָן שֶׁאָמַר וְנָחֲךְ ה', לָמָּה תָּמִיד? אֶלָּא זֶה הַתָּמִיד שֶׁל בֵּין הָעַרְבַּיִם שֶׁהוּא הִתְחַזֵּק תַּחַת זְרוֹעוֹ שֶׁל יִצְחָק, וְזֶהוּ הַחֵלֶק לָעוֹלָם הַבָּא. מִנַּיִן לָנוּ? מִדָּוִד, שֶׁכָּתוּב (תהלים כג) יַנְחֵנִי בְמַעְגְּלֵי צֶדֶק לְמַעַן שְׁמוֹ.</p>\n<p>וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ - זוֹ הָאַסְפַּקְלַרְיָה הַמְּאִירָה שֶׁכָּל הַנְּשָׁמוֹת נֶהֱנוֹת לְהִסְתַּכֵּל וּלְהִתְעַנֵּג בְּתוֹכָהּ. וְעַצְמֹתֶיךְ יַחֲלִיץ - הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ. אִם נִשְׁמָתוֹ שֶׁל הַצַּדִּיק (עולה למעלה, נ\"א נהנית באור של מעלה), מַה זֶּה וְעַצְמֹתֶיךְ יַחֲלִיץ? אֶלָּא הִנֵּה פֵּרְשׁוּהָ, זוֹ תְחִיַּת הַמֵּתִים. שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת אֶת הַמֵּתִים וּלְתַקֵּן אֶת עַצְמוֹת הָאָדָם שֶׁיִּהְיוּ כְּבָרִאשׁוֹנָה בְּגוּף שָׁלֵם, וְהַנְּשׁמָה מוֹסִיפָה אוֹר בְּתוֹךְ הָאַסְפַּקְלַרְיָה הַמְּאִירָה שֶׁתָּאִיר עִם הַגּוּף לִבְרִית שָׁלֵם כָּרָאוּי.</p>\n<p>וּמִשּׁוּם כָּךְ כָּתוּב וְהָיִיתָ כְּגַן רָוֶה. מַה זֶּה כְּגַן רָוֶה? שֶׁלֹּא פוֹסְקִים מֵימָיו הָעֶלְיוֹנִים לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. וְהַגָּן (והגוף) הַזֶּה נִשְׁקָה מִמֶּנּוּ וּמִתְרַוֶּה מִמֶּנּוּ תָּמִיד. וּכְמוֹצָא מַיִם - זֶה הַנָּהָר הַהוּא שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן, וְלֹא פוֹסְקִים מֵימָיו לְעוֹלָמִים.</p>\n<p>בֹּא רְאֵה, בְּאֵר שֶׁל מַיִם נוֹבְעִים זֶהוּ סוֹד עֶלְיוֹן בְּתוֹךְ סוֹד הָאֱמוּנָה. בְּאֵר שֶׁיֵּשׁ בָּהּ מוֹצָא מַיִם, וְהִיא בְּאֵר שֶׁמִּתְמַלֵּאת מִמּוֹצָא הַמַּיִם הַהוּא, וְהֵם שְׁתֵּי דְרָגוֹת שֶׁהֵן אַחַת, זָכָר וּנְקֵבָה יַחַד כָּרָאוּי.</p>\n<p>וּבֹא וּרְאֵה, אוֹתוֹ מוֹצָא מַיִם וְאוֹתָהּ בְּאֵר הֵם אֶחָד, וְהַכֹּל נִקְרָא בְּאֵר, שֶׁהֲרֵי אוֹתוֹ הַמָּקוֹר שֶׁמַּכְנִיס וְלֹא פוֹסֵק לְעוֹלָמִים, וְהַבְּאֵר מִתְמַלֵּאת. וּמִי שֶׁמִּסְתַּכֵּל בַּבְּאֵר הַזּוֹ, מִסְתַּכֵּל בַּסּוֹד הָעֶלְיוֹן שֶׁל הָאֱמוּנָה. וְזֶהוּ סִימַן הָאָבוֹת - שֶׁמִּשְׁתַּדְּלִים לַחְפֹּר בְּאֵר מַיִם בְּתוֹךְ סוֹד עֶלְיוֹן, וְאֵין לְהַפְרִיד בֵּין הַמָּקוֹר וְהַבְּאֵר, וְהַכֹּל אֶחָד.</p>\n<p>וַיִּקְרָא שְׁמָהּ רְחֹבוֹת - רֶמֶז שֶׁעֲתִידִים בָּנָיו לַעֲבֹד וּלְתַקֵּן אֶת הַבְּאֵר הַזּוֹ כָּרָאוּי בְּסוֹד הַקָּרְבָּנוֹת וְהָעוֹלוֹת. כְּמוֹ כֵן, (בראשית ב) וַיַּנִּחֵהוּ בְגַן עֵדֶן לְעָבְדָהּ וּלְשָׁמְרָהּ. אֵלּוּ הַקָּרְבָּנוֹת וְהָעוֹלוֹת. וּמִשּׁוּם זֶה יִתְפַּשְּׁטוּ מַעְיְנוֹתָיו לְכָל הַצְּדָדִים, כְּמוֹ שֶׁנֶּאֱמַר (משלי ה) וְיָפוּצוּ מַעְיְנֹתֶיךְ חוּצָה בָּרְחוֹבֹת פַּלְגֵי מָיִם, וּמִשּׁוּם כָּךְ וַיִּקְרָא שְׁמָהּ רְחֹבוֹת.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (שם א) חָכְמוֹת בַּחוּץ תָּרֹנָּה בָּרְחֹבוֹת תִּתֵּן קוֹלָהּ. הַפָּסוּק הַזֶּה הוּא סוֹד עֶלְיוֹן. מַה זֶּה חָכְמוֹת? אֵלּוּ הַחָכְמָה הָעֶלְיוֹנָה וְהַחָכְמָה הַקְּטַנָּה שֶׁנִּכְלֶלֶת בָּעֶלְיוֹנָה וְשׁוֹרָה בָּהּ.</p>\n<p>בַּחוּץ תָּרֹנָּה - בּא רְאֵה, הַחָכְמָה הָעֶלְיוֹנָה הִיא סְתוּמָה שֶׁל כָּל הַסְּתוּמִים, וְלֹא נוֹדַעַת וְאֵינָהּ בְּגִלּוּי, כְּמוֹ שֶׁנֶּאֱמַר (איוב כח) לֹא יָדַע אֱנוֹשׁ עֶרְכָּהּ וְגוֹ'. כְּשֶׁמִּתְפַּשֶּׁטֶת לְהָאִיר, מְאִירָה בְּסוֹד הָעוֹלָם הַבָּא, וְהָעוֹלָם הַבָּא נִבְרָא מִמֶּנָּה, כְּפִי שֶׁשָּׁנִינוּ, הָעוֹלָם הַבָּא נִבְרָא בְּיוֹ\"ד, וְהַחָכְמָה הַזּוֹ נִכְסֵית שָׁם, וְהֵם אֶחָד בִּזְמַן שֶׁמִּתְיַצֵּב (שמתעטר נ\"א שנ שה) הַכֹּל בַּסּוֹד שֶׁל הָעוֹלָם הַבָּא, כְּפִי שֶׁאָמַרְנוּ. אָז הִיא הַשִּׂמְחָה לִהְיוֹת מְאִירָה, וְהַכֹּל בַּחֲשַׁאי, שֶׁלֹּא נִשְׁמָע בַּחוּץ לְעוֹלָמִים.</p>\n<p>עוֹד רוֹצֶה לְהִתְפַּשֵּׁט, וְיוֹצְאִים מִן הַמָּקוֹם הַזֶּה אֵשׁ וּמַיִם וְרוּחַ, כְּמוֹ שֶׁנִּתְבָּאֵר, וְנַעֲשִׂים קוֹל אֶחָד שֶׁיּוֹצֵא בַּחוּץ וְנִשְׁמָע, כְּמוֹ שֶׁנִּתְבָּאֵר. אָז מִשָּׁם וּלְהַלָּן זֶהוּ חוּץ. הֲרֵי בִּפְנִים הוּא בַּחֲשַׁאי, שֶׁלֹּא נִשְׁמָע לְעוֹלָמִים. עַכְשָׁו שֶׁנִּשְׁמָע הַסּוֹד נִקְרָא בַּחוּץ. מִכָּאן צָרִיךְ אָדָם לְהַתְקִין אֶת מַעֲשֵׂהוּ וּלְבַקֵּשׁ.</p>\n<p>בָּרְחֹבוֹת - מִי הָרְחוֹבוֹת? זֶה הָרָקִיעַ הַהוּא שֶׁבּוֹ מְאִירִים כָּל הַכּוֹכָבִים, וְהוּא הַמַּעְיָן שֶׁאֵין מֵימָיו פּוֹסְקִים, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְהוּא רְחוֹבוֹת, וְשָׁם תִּתֵּן קוֹלָהּ, עֶלְיוֹנָה וְתַחְתּוֹנָה, וְהַכֹּל אֶחָד.</p>\n<p>וּמִשּׁוּם זֶה אָמַר שְׁלֹמֹה, (משלי כד) הָכֵן בַּחוּץ מְלַאכְתֶּךְ וְעַתְּדָהּ בַּשָּׂדֶה לָךְ וְגוֹ'. הָכֵן בַּחוּץ, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב בַּחוּץ תָּרֹנָּה, שֶׁהֲרֵי מִכָּאן עוֹמֵד הַמַּעֲשֶׂה לְהִתְתַּקֵּן וְדָבָר לִשְׁאֵלָה, שֶׁכָּתוּב (דברים ד) כִּי שְׁאַל נָא לְיָמִים רִאשֹׁנִים וְגוֹ', וּלְמִקְצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמָיִם.</p>\n<p>וְעַתְּדָהּ בַּשָּׂדֶה לָךְ - זוֹ הַשָּׂדֶה אֲשֶׁר בֵּרֲכוֹ ה'. וְאַחַר שֶׁיֵּדַע הָאָדָם אֶת סוֹד הַחָכְמָה וְיַתְקִין אֶת עַצְמוֹ בָּהּ, מַה כָּתוּב אַחַר כָּךְ? וּבָנִיתָ בֵיתֶךְ. זוֹ הַנְּשָׁמָה שֶׁל אָדָם בְּגוּפוֹ, שֶׁיִּתְתַּקֵּן וְיֵעָשֶׂה אִישׁ שָׁלֵם. וְעַל כֵּן, כְּשֶׁחָפַר יִצְחָק וְעָשָׂה בְאֵר בְּשָׁלוֹם, לְאוֹתוֹ הַשָּׁלוֹם (שיהיה שלם) קָרָא רְחוֹבוֹת, וְהַכֹּל כָּרָאוּי. אַשְׁרֵי הַצַּדִּיקִים שֶׁמַּעֲשֵׂיהֶם לַקָּבָּ\"ה לְקַיֵּם אֶת הָעוֹלָם, שֶׁכָּתוּב כִּי יְשָׁרִים יִשְׁכְּנוּ אָרֶץ, יַשְׁכִּינוּ אָרֶץ, וַהֲרֵי פֵּרְשׁוּהָ.</p>"],[9522011293,"<p>וַיְהִי כִּי זָקֵן יִצְחָק. אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (בראשית א) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם וְלַחֹשֶׁךְ קָרָא לָיְלָה. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ וְנִתְבָּאֵר. אֲבָל בּא רְאֵה, כָּל מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא, כֻּלָּם הֵם דִּבְרֵי אֱמֶת, וְהַכֹּל בְּסוֹד עֶלְיוֹן. וְכָל דִּבְרֵי הַתּוֹרָה כֻּלָּם דִּבְרֵי אֱמוּנָה וְסוֹדוֹת עֶלְיוֹנִים כָּרָאוּי.</p>\n<p>וּבֹא וּרְאֵה, לֹא זָכָה יִצְחָק כְּמוֹ אַבְרָהָם, שֶׁלֹּא סָמוּ עֵינָיו וְלֹא כָהוּ. אֲבָל כָּאן הוּא סוֹד עֶלְיוֹן, סוֹד הָאֱמוּנָה, כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁכָּתוּב וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם. זֶה אַבְרָהָם, שֶׁהוּא אוֹר הַיּוֹם, וְאוֹרוֹ הוֹלֵךְ וּמֵאִיר וּמִתְחַזֵּק בְּתִקּוּן הַיּוֹם.</p>\n<p>וּמִשּׁוּם כָּךְ מַה כָּתוּב? וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים, בְּאוֹתָם הָאוֹרוֹת שֶׁמְּאִירִים. וְהוּא זָקֵן, (ומאיר, אז הולך ומאיר) כְּמוֹ שֶׁנֶּאֱמַר (משלי ד) הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם, וּמִשּׁוּם כָּךְ וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם. וְלַחֹשֶׁךְ קָרָא לָיְלָה - זֶה יִצְחָק, שֶׁהוּא חֹשֶׁךְ, וְהוּא הוֹלֵךְ לְקַבֵּל לְתוֹכוֹ אֶת הַלַּיְלָה. וּמִשּׁוּם כָּךְ, כְּשֶׁהוּא זָקֵן מַה כָּתוּב? וַיְהִי כִּי זָקֵן יִצְחָק וַתִּכְהֶיןָ עֵינָיו מֵרְאֹת. כָּךְ זֶה וַדַּאי, שֶׁרָצָה לְהֵחָשֵׁךְ וּלְהִדָּבֵק (בחשך) בְּדַרְגָּתוֹ כָּרָאוּי.</p>\n<p>בָּא רַבִּי אֶלְעָזָר בְּנוֹ וְנָשַׁק יָדָיו. אָמַר לוֹ, יָפֶה. אַבְרָהָם מֵאִיר מִצַּד שֶׁל דַּרְגָּתוֹ, יִצְחָק נֶחְשַׁךְ מֵהַצַּד שֶׁל דַּרְגָּתוֹ, וְיַעֲקֹב לָמָּה, שֶׁכָּתוּב וְעֵינֵי יִשְׂרָאֵל כָּבְדוּ מִ קֶן? אָמַר לוֹ, כָּךְ זֶה וַדַּאי, כָּתוּב כָּבְדוּ וְלֹא כָהוּ. כָּתוּב מִזֹּקֶן וְלֹא מִזִּקְנוֹ. אֶלָּא מִזֹּקֶן - מִ קֶן שֶׁל יִצְחָק, מֵאוֹתוֹ צַד כָּבְדוּ. לֹא יוּכַל לִרְאוֹת לְהִסְתַּכֵּל כָּרָאוּי, אֲבָל לֹא כָהוּ. אֲבָל יִצְחָק כָּהוּ וַדַּאי מִכֹּל וָכֹל, וְנַעֲשָׂה חֹשֶׁךְ, שֶׁהֲרֵי אָז נֶאֱחַז בּוֹ הַלַּיְלָה, וְהִתְקַיֵּם וְלַחֹשֶׁךְ קָרָא לָיְלָה.</p>"],[9522011294,"<p>וַיִּקְרָא אֶת עֵשָׂו בְּנוֹ הַגָּדֹל. שֶׁנִּכְלָל מִצִּדּוֹ שֶׁל הַדִּין הַקָּשֶׁה. וַיֹּאמֶר הִנֵּה נָא זָקַנְתִּי לֹא יָדַעְתִּי יוֹם מוֹתִי. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים פד) אַשְׁרֵי אָדָם עוֹז לוֹ בָךְ וְגוֹ'. אַשְׁרֵי הָאִישׁ שֶׁמִּתְחַזֵּק בַּקָּבָּ\"ה וְשָׂם בּוֹ אֶת תָּקְפּוֹ.</p>\n<p>יָכוֹל כַּחֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה שֶׁהִתְחַזְּקוּ וְאָמְרוּ, (דניאל ג) הֵן אִתָּנוּ אֱלֹהֵינוּ שֶׁאָנוּ עוֹבְדִים יָכוֹל לְהַצִּילֵנוּ מִתּוֹךְ כִּבְשַׁן הָאֵשׁ הַיּוֹקֶדֶת, וּמִיָּדְךְ הַמֶּלֶךְ יַצִּיל. בֹּא רְאֵה, שֶׁאִם לֹא יַצִּיל וְלֹא יַעֲמֹד עֲלֵיהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, נִמְצָא שֶׁשְּׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא יִתְקַדֵּשׁ בְּעֵינֵי הַכֹּל, כְּמוֹ שֶׁאָמְרוּ. אֶלָּא כֵּיוָן שֶׁיָּדְעוּ שֶׁלֹּא אָמְרוּ כָּרָאוּי, חָזְרוּ וְאָמְרוּ, וְהֵן לֹא יָדוּעַ לִהְיוֹת לְךְ הַמֶּלֶךְ וְגוֹ'. בֵּין יַצִּיל בֵּין לֹא יַצִּיל, יָדוּעַ לִהְיוֹת לְךְ הַמֶּלֶךְ וְגוֹ'. וְשָׁנִינוּ שֶׁיְּחֶזְקֵאל הוֹדִיעַ לָהֶם דָּבָר, וְשָׁמְעוּ וְקִבְּלוּ מִמֶּנּוּ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא עָמַד עֲלֵיהֶם, כְּדֵי שֶׁיְּקַבְּלוּ שָׂכָר, וְאָז חָזְרוּ וְאָמְרוּ, וְהֵן לֹא יָדוּעַ לִהְיוֹת לְךְ הַמֶּלֶךְ וְגוֹ'.</p>\n<p>אֶלָּא לֹא יִתְחַזֵּק אָדָם שֶׁיֹּאמַר, הַקָּדוֹשׁ בָּרוּךְ הוּא יַצִּילֵנִי, אוֹ יַעֲשֶׂה לִי כָּךְ וְכָךְ. אֲבָל יָשִׂים אֶת כֹּחוֹ בַּקָּבָּ\"ה שֶׁיְּסַיַּע לוֹ, כְּשֶׁהוּא מִשְׁתַּדֵּל בְּאוֹתָם הַמִּצְווֹת שֶׁל הַתּוֹרָה וְלָלֶכֶת בְּדֶרֶךְ אֱמֶת. שֶׁכֵּיוָן שֶׁאָדָם בָּא לְהִטָּהֵר, וַדַּאי מְסַיְּעִים לוֹ. וּבָזֶה יִתְחַזֵּק בַּקָּבָּ\"ה שֶׁהוּא יְסַיַּע לוֹ, וְיִתְחַזֵּק בּוֹ, שֶׁלֹּא יָשִׂים אֶת כֹּחוֹ בִּטְחוֹנוֹ בְּאַחֵר. וּמִשּׁוּם כָּךְ, עוֹז לוֹ בָךְ מְסִלּוֹת בִּלְבָבָם. שֶׁיַּעֲשֶׂה לִבּוֹ כָּרָאוּי בְּלִי הִרְהוּר אַחֵר, אֶלָּא כַּמְּסִלָּה הַזּוֹ שֶׁהִיא מִתְיַשֶּׁבֶת לַעֲבֹר בְּכָל מָקוֹם שֶׁצָּרִיךְ, כָּךְ גַּם.</p>\n<p>דָּבָר אַחֵר אַשְׁרֵי אָדָם עוֹז לוֹ בָךְ - עֹז כְּמוֹ שֶׁנֶּאֱמַר (תהלים כט) ה' עֹז לְעַמּוֹ יִתֵּן. מִשּׁוּם שֶׁצָּרִיךְ לָאָדָם לְהִתְעַסֵּק בַּתּוֹרָה לִשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁכָּל מִי שֶׁמִּתְעַסֵּק בַּתּוֹרָה וְאֵינוֹ מִשְׁתַּדֵּל לִשְׁמָהּ, טוֹב לוֹ שֶׁלֹּא נִבְרָא. מְסִלּוֹת בִּלְבָבָם, מַה זֶּה מְסִלּוֹת בִּלְבָבָם? כְּמוֹ שֶׁנֶּאֱמַר (שם סח) סֹלּוּ לָרֹכֵב בָּעֲרָבוֹת בְּיָהּ שְׁמוֹ. זוֹ הַתּוֹרָה הַהִיא שֶׁהוּא הִשְׁתַּדֵּל בָּהּ לְהָרִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְלַעֲשׂוֹתוֹ חֲטִיבָה בָּעוֹלָם.</p>\n<p>בֹּא רְאֵה, כָּל מַעֲשָׂיו שֶׁל יַעֲקֹב הָיוּ לִשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה עִמּוֹ תָּמִיד, שֶׁלֹּא זָזָה מִמֶּנּוּ הַשְּׁכִינָה. שֶׁהֲרֵי בְּשָׁעָה שֶׁקָּרָא לוֹ יִצְחָק אֶת עֵשָׂו בְּנוֹ, יַעֲקֹב לֹא הָיָה שָׁם, וְהַשְּׁכִינָה הוֹדִיעָה לְרִבְקָה, וְרִבְקָה הוֹדִיעָה לְיַעֲקֹב.</p>\n<p>רַבִּי יוֹסֵי אָמַר, בֹּא רְאֵה, אִם חַס וְחָלִילָה בְּאוֹתוֹ זְמַן הָיָה מִתְבָּרֵךְ עֵשָׂו, לֹא הָיָה שׁוֹלֵט יַעֲקֹב לְעוֹלָמִים. אֶלָּא מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא זֶה הָיָה, וְהַכֹּל בָּא בִּמְקוֹמוֹ כָּרָאוּי. בֹּא רְאֵה, כָּתוּב וְרִבְקָה אֹהֶבֶת אֶת יַעֲקֹב, וְזֶה נִתְבָּאֵר. וּמִשּׁוּם כָּךְ שָׁלְחָה בִּשְׁבִיל יַעֲקֹב, הִנֵּה שָׁמַעְתִּי אֶת אָבִיךְ מְדַבֵּר אֶל עֵשָׂו אָחִיךְ לֵאמֹר.</p>\n<p>וְעַתָּה בְנִי שְׁמַע בְּקֹלִי וְגוֹ'. בַּזְּמַן הַהוּא עֶרֶב פֶּסַח הָיָה, וְצָרִיךְ הַיֵּצֶר הָרָע לְהִתְבַּעֵר וְלִשְׁלֹט הַלְּבָנָה, סוֹד הָאֱמוּנָה, וְלָכֵן עָשְׂתָה שְׁנֵי תַבְשִׁילִים.</p>\n<p>רַבִּי יְהוּדָה אָמַר, כָּאן רֶמֶז שֶׁעֲתִידִים בְּנֵי יַעֲקֹב לְהַקְרִיב שְׁנֵי שְׂעִירִים, אֶחָד לַה' וְאֶחָד לַעֲזָאזֵל בְּיוֹם הַכִּפּוּרִים. מִשּׁוּם כָּךְ הִקְרִיבָה שְׁנֵי גְּדָיֵי עִזִּים - אֶחָד בִּשְׁבִיל הַדַּרְגָּה שֶׁלְּמַעְלָה, וְאֶחָד כְּדֵי לְהַכְנִיעַ אֶת דַּרְגָּתוֹ שֶׁל עֵשָׂו שֶׁלֹּא יִשְׁלֹט עַל יַעֲקֹב, וְעַל כֵּן שְׁנֵי גְּדָיֵי עִזִּים, וּמִשְּׁנֵיהֶם טָעַם יִצְחָק וְאָכַל.</p>\n<p>וַיָּבֵא לוֹ יַיִן וַיֵּשְׁתְּ. וַיָּבֵא לוֹ יַיִן, רֶמֶז רָמַז - מִמָּקוֹם רָחוֹק קֵרַב אוֹתוֹ מֵאוֹתוֹ מָקוֹם (של עשו). רַבִּי אֶלְעָזָר אָמַר, רֶמֶז מֵהַיַּיִן הַהוּא שֶׁכָּל הַשִּׂמְחָה נִמְצֵאת בּוֹ כְּדֵי לְשַׂמֵּחַ אֶת יִצְחָק, שֶׁצָּרִיךְ שִׂמְחָה, כְּשֶׁרוֹצִים שִׂמְחָה לְשַׂמֵּחַ אֶת צַד (הלוים) שֶׁלּוֹ, וְעַל כֵּן וַיָּבֵא לוֹ יַיִן וַיֵּשְׁתְּ.</p>"],[9522011295,"<p>וַתִּקַּח רִבְקָה אֶת בִּגְדֵי עֵשָׂו וְגוֹ'. אֵלּוּ הַלְּבוּשִׁים שֶׁהִרְוִיחַ עֵשָׂו מִנִּמְרוֹד, וְאֵלֶּה לְבוּשֵׁי כָבוֹד, שֶׁהָיוּ מֵאָדָם הָרִאשׁוֹן, וּבָאוּ לִידֵי נִמְרוֹד, וּבָהֶם הָיָה צָד צִידָה נִמְרוֹד, שֶׁכָּתוּב (בראשית י) הוּא הָיָה גִבֹּר צַיִד לִפְנֵי ה' וְגוֹ'. וְעֵשָׂו יָצָא לַשָּׂדֶה וְנִלְחַם בִּקְרָב עִם נִמְרוֹד וְהָרַג אוֹתוֹ, וְלָקַח מִמֶּנּוּ אֶת הַלְּבוּשִׁים הַלָּלוּ. זֶהוּ שֶׁכָּתוּב וַיָּבֹא עֵשָׂו מִן הַשָּׂדֶה וְהוּא עָיֵף. וּבֵאֲרוּהָ, כָּתוּב כָּאן וְהוּא עָיֵף, וְכָתוּב שָׁם (ירמיה ד) כִּי עָיְפָה נַפְשִׁי לְהֹ רְגִים.</p>\n<p>וְעֵשָׂו הָיָה מַעֲלֶה אֶת אוֹתָם הַלְּבוּשִׁים לְרִבְקָה, וּבָהֶם הָיָה יוֹצֵא וְצָד צַיִד, וְאוֹתוֹ הַיּוֹם לֹא לָקַח אוֹתָם, וְיָצָא לַשָּׂדֶה וְהִתְעַכֵּב שָׁם. וּכְשֶׁעֵשָׂו הָיָה לוֹבֵשׁ אוֹתָם, לֹא הָיוּ מַעֲלִים רֵיחוֹת כְּלָל. כֵּיוָן שֶׁיַּעֲקֹב לָבַשׁ אוֹתָם, אָז שָׁבָה הָאֲבֵדָה לִמְקוֹמָהּ וְהֶעֱלוּ רֵיחוֹת, מִשּׁוּם שֶׁיָּפְיוֹ שֶׁל יַעֲקֹב הָיָה יָפְיוֹ שֶׁל אָדָם, וּמִשּׁוּם כָּךְ חָזְרוּ בַּשָּׁעָה הַהִיא לִמְקוֹמָם וְהֶעֱלוּ רֵיחוֹת.</p>\n<p>אָמַר רַבִּי יוֹסֵי, יָפְיוֹ שֶׁל יַעֲקֹב (היה) שֶׁהוּא יָפְיוֹ שֶׁל אָדָם אֵיךְ אֶפְשָׁר? וַהֲרֵי שָׁנִינוּ, תַּפּוּחַ עֲקֵבוֹ שֶׁל אָדָם הָרִאשׁוֹן מַכְהֶה גַּלְגַּל חַמָּה, וְאִם תֹּאמַר שֶׁכָּךְ הָיָה יַעֲקֹב? אָמַר לוֹ רַבִּי אֶלְעָזָר, וַדַּאי שֶׁכָּךְ הָיָה. בָּרִאשׁוֹנָה טֶרֶם חָטָא אָדָם הָרִאשׁוֹן, לֹא הָיוּ יְכוֹלִים כָּל הַבְּרִיּוֹת לְהִסְתַּכֵּל בְּיָפְיוֹ. כֵּיוָן שֶׁחָטָא, הִשְׁתַּנָּה יָפְיוֹ וְרוּמוֹ הֻנְמַךְ, וְנַעֲשָׂה בֶּן מֵאָה אַמּוֹת. וּבֹא וּרְאֵה, יָפְיוֹ שֶׁל אָדָם הָרִאשׁוֹן הוּא סוֹד, שֶׁהָאֱמוּנָה הָעֶלְיוֹנָה תְּלוּיָה בַּיֹּפִי הַהוּא, וּמִשּׁוּם כָּךְ (תהלים צ) וִיהִי נֹעַם ה' אֱלֹהֵינוּ עָלֵינוּ, וְכָתוּב (שם כז) לַחֲזוֹת בְּנֹעַם ה'. וְזֶהוּ וַדַּאי יָפְיוֹ שֶׁל יַעֲקֹב, וְהַכֹּל הוּא סוֹד עֶלְיוֹן.</p>\n<p>וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרַכֵהוּ. בֹּא רְאֵה, וַיָּרַח אֶת רֵיחַ הַבְּגָדִים לֹא כָתוּב, אֶלָּא רֵיחַ בְּגָדָיו, כְּמוֹ שֶׁנֶּאֱמַר (שם קד) עֹטֶה אוֹר כַּשַּׂלְמָה נוֹטֶה שָׁמַיִם כַּיְרִיעָה. דָּבָר אַחֵר (זה הוא) וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרֲכֵהוּ - שֶׁכֵּיוָן שֶׁהִלְבִּישׁ אוֹתָם יַעֲקֹב, הֶעֱלוּ רֵיחוֹת בְּאוֹתָהּ הַשָּׁעָה. וְעַד שֶׁלֹּא הֵרִיחַ (שהריח) אֶת רֵיחַ לְבוּשׁוֹ לֹא בֵרַךְ אוֹתוֹ, שֶׁהֲרֵי אָז (לא) יָדַע שֶׁהוּא רָאוּי לְהִתְבָּרֵךְ. שֶׁאִם לֹא רָאוּי לְהִתְבָּרֵךְ, לֹא הָיוּ עוֹלִים כָּל הָרֵיחוֹת הַקְּדוֹשִׁים הַלָּלוּ עִמּוֹ. זֶהוּ שֶׁכָּתוּב וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרֲכֵהוּ.</p>\n<p>וַיֹּאמֶר רְאֵה רֵיחַ בְּנִי כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה'. וַיֹּאמֶר - דָּבָר נִסְתָּר הוּא. יֵשׁ אוֹמְרִים שֶׁהָיְתָה הַשְּׁכִינָה, וְיֵשׁ אוֹמְרִים שֶׁיִּצְחָק הָיָה. כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה' - מִי הַשָּׂדֶה? זֶה שְׂדֵה הַתַּפּוּחִים, הַשָּׂדֶה שֶׁהָאָבוֹת הָעֶלְיוֹנִים (חומדים) סוֹמְכִים אוֹתוֹ וּמְתַקְּנִים אוֹתוֹ.</p>"],[9522011296,"<p>וְיִתֶּן לְךְ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ וְרֹב דָּגָן וְתִירוֹשׁ. אָמַר רַבִּי אַבָּא, הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, אֲבָל (פתח רבי אבא ואמר) בֹּא רְאֵה, שִׁיר הַמַּעֲלוֹת אֶל ה' בַּצָּרָתָה לִּי קָרָאתִי וַיַּעֲנֵנִי. כַּמָּה שִׁירוֹת וְתִשְׁבָּחוֹת אָמַר דָּוִד הַמֶּלֶךְ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַכֹּל כְּדֵי לְהַתְקִין אֶת דַּרְגָּתוֹ וְלַעֲשׂוֹת לוֹ שֵׁם, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב ח) וַיַּעַשׂ דָּוִד שֵׁם. וְהַשִּׁירָה הַזּוֹ אָמַר (לו) כְּשֶׁרָאָה הַמַּעֲשֶׂה הַזֶּה לְיַעֲקֹב (של יעקב).</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, יַעֲקֹב אָמַר הַשִּׁירָה הַזּוֹ (שהרי) בְּשָׁעָה שֶׁאָמַר לוֹ אָבִיו גְּשָׁה נָא וַאֲמֻשְׁךְ בְּנִי הַאַתָּה זֶה בְּנִי עֵשָׂו אִם לֹא. אָז (משום) שֶׁהָיָה (היה) יַעֲקֹב בְּצָרָה גְדוֹלָה, שֶׁפָּחַד שֶׁאָבִיו יַכִּיר אוֹתוֹ וְיִוָּדַע לְפָנָיו. מַה כָּתוּב? וְלֹא הִכִּירוֹ כִּי הָיו יָדָיו כִּידֵי עֵשָׂו אָחִיו שְׂעִרֹת וַיְבָרֲכֵהוּ. אָז אָמַר, אֶל ה' בַּצָּרָתָה לִּי קָרָאתִי וַיַּעֲנֵנִי.</p>\n<p>ה' הַצִּילָה נַפְשִׁי מִשְּׂפַת שֶׁקֶר מִלָּשׁוֹן רְמִיָּה. זוֹהִי הַדַּרְגָּה שֶׁעֵשָׂו שָׁרוּי בָּהּ, שֶׁהִיא שְׂפַת הַשֶּׁקֶר (מה הוא). שְׂפַת שֶׁקֶר, בְּשָׁעָה שֶׁהֵבִיא אוֹתוֹ הַנָּחָשׁ קְלָלוֹת עַל הָעוֹלָם, וּבְהִתְחַכְּמוּת וּבְעַקְמִימוּת הֵבִיא קְלָלוֹת, שֶׁהִתְקַלֵּל הָעוֹלָם.</p>"],[9522011297,"<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁאָמַר יִצְחָק לְעֵשָׂו, וְצֵא הַשָּׂדֶה וְצוּדָה לִּי צָיִדה, בְּהֵ\"א, וּבֵאֲרוּהָ, וְיָצָא עֵשָׂו כְּדֵי שֶׁיִּתְבָּרֵךְ מִיִּצְחָק, שֶׁאָמַר לוֹ וַאֲבָרֶכְכָה לִפְנֵי ה'. שֶׁאִלּוּ אָמַר וַאֲבָרֶכְכָה וְלֹא יוֹתֵר - יָפֶה. כֵּיוָן שֶׁאָמַר לִפְנֵי ה', בְּאוֹתָהּ הַשָּׁעָה הִזְדַּעֲזַע כִּסֵּא כְבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמְרָה, וּמַה שֶּׁיֵּצֵא נָחָשׁ מֵאוֹתָן הַקְּלָלוֹת וְיִשָּׁאֵר יַעֲקֹב.</p>\n<p>בַּשָּׁעָה הַהִיא הִזְדַּמֵּן מִיכָאֵל, וּבָא לִפְנֵי יַעֲקֹב וְהַשְּׁכִינָה עִמּוֹ. וְיָדַע יִצְחָק, וְרָאָה אֶת גַּן עֵדֶן עִם יַעֲקֹב וּבֵרְכוֹ לְפָנָיו. וּכְשֶׁנִּכְנַס עֵשָׂו, נִכְנַס עִמּוֹ גֵּיהִנֹּם, וְעַל כֵּן וַיֶּחֱרַד יִצְחָק חֲרָדָה גְּדלָה עַד מְאֹד, שֶׁחָשַׁב שֶׁעֵשָׂו לֹא הָיָה בַּצַּד הַהוּא. פָּתַח וְאָמַר, וָאֲבָרֲכֵהוּ גַּם בָּרוּךְ יִהְיֶה.</p>\n<p>מִשּׁוּם כָּךְ הִזְדַּמֵּן יַעֲקֹב בְּחָכְמָה וּבְעַקְמוּמִיּוּת שֶׁהֵבִיא בְּרָכוֹת עַל יַעֲקֹב, שֶׁהוּא כְּמוֹ אָדָם הָרִאשׁוֹן, וְנִנְטְלוּ מֵאוֹתוֹ הַנָּחָשׁ, שֶׁהוּא שְׂפַת שֶׁקֶר. שֶׁכַּמָּה שֶׁקֶר אָמַר, וְכַמָּה דִּבְרֵי שֶׁקֶר עָשָׂה כְּדֵי לְהַטְעוֹת וּלְהָבִיא קְלָלוֹת עַל הָעוֹלָם. מִשּׁוּם כָּךְ בָּא יַעֲקֹב בְּחָכְמָה וְהִטְעָה אֶת אָבִיו, כְּדֵי לְהָבִיא בְּרָכוֹת עַל הָעוֹלָם וְלִטֹּל מִמֶּנּוּ מַה שֶּׁמָּנַע מִן הָעוֹלָם. וּמִדָּה כְּנֶגֶד מִדָּה הָיְתָה, וְעַל כֵּן כָּתוּב (תהלים קט) וַיֶּאֱהַב קְלָלָה וַתְּבוֹאֵהוּ וְלֹא חָפֵץ בִּבְרָכָה וַתִּרְחַק מִמֶּנּוּ. עָלָיו כָּתוּב (בראשית ג) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וּמִכֹּל חַיַּת הַשָּׂדֶה. וְנִשְׁאָר בּוֹ לְדוֹרֵי דוֹרוֹת, וּבָא יַעֲקֹב וְנָטַל מִמֶּנּוּ הַבְּרָכוֹת.</p>\n<p>וּמִיָּמָיו שֶׁל אָדָם הָרִאשׁוֹן נוֹעַד יַעֲקֹב לִטֹּל מֵהַנָּחָשׁ הַהוּא אֶת כָּל הַבְּרָכוֹת הַלָּלוּ, וְהוּא נִשְׁאָר עִם קְלָלוֹת וְלֹא יָצָא מֵהֶם. וְדָוִד אָמַר בְּרוּחַ הַקֹּדֶשׁ, (תהלים קכ) מַה יִּתֵּן לָךְ וּמַה יֹּסִיף לָךְ לָשׁוֹן רְמִיָּה חִצֵּי גִבּוֹר שְׁנוּנִים. מָה אִכְפַּת לְאוֹתוֹ הַנָּחָשׁ הָרַע שֶׁהֵבִיא קְלָלוֹת עַל הָעוֹלָם, כְּמוֹ שֶׁאָמְרוּ, נָחָשׁ נוֹשֵׁךְ וּמֵמִית, וְאֵין לוֹ מִמֶּנּוּ הֲנָאָה.</p>\n<p>לָשׁוֹן רְמִיָּה - שֶׁרִמָּה אֶת אָדָם וְאִשְׁתּוֹ וְהֵבִיא רַע עָלָיו וְעַל הָעוֹלָם. אַחַר כָּךְ בָּא יַעֲקֹב וְנָטַל מִשֶּׁלּוֹ אֶת כָּל אוֹתָם הַבְּרָכוֹת. חִצֵּי גִבּוֹר שְׁנוּנִים - זֶה עֵשָׂו שֶׁשָּׁמַר שִׂנְאָה (שהפחיד) לְיַעֲקֹב עַל אוֹתָן הַבְּרָכוֹת, כְּמוֹ שֶׁנֶּאֱמַר וַיִּשְׂטֹם עֵשָׂו אֶת יַעֲקֹב עַל הַבְּרָכָה וְגוֹ'. (בא ראה).</p>\n<p>וְיִתֶּן לְךְ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ - הִנֵּה מִלְמַעְלָה וּמִמַּטָּה בְּחִבּוּר אֶחָד. וְרֹב דָּגָן וְתִירשׁ - הִנֵּה פֵּרְשׁוּהָ, אֲבָל כַּכָּתוּב וְלֹא רָאִיתִי צַדִּיק נֶעֱזָב וְזַרְעוֹ מְבַקֶּשׁ לָחֶם. בּא רְאֵה, נַעַר הָיִיתִי וְגוֹ', וּבֵאֲרוּהָ - הַפָּסוּק הַזֶּה אָמַר אוֹתוֹ שָׂרוֹ שֶׁל עוֹלָם וְכוּ'. וּמִשּׁוּם כָּךְ אָמַר וְרֹב דָּגָן וְתִירשׁ.</p>\n<p>יַעֵבְדוּךָ עַמִּים וְיִשְׁתַּחֲוֻ לְךְ לְאֻמִּים - בִּזְמַן שֶׁשָּׁלַט שְׁלֹמֹה הַמֶּלֶךְ בִּירוּשָׁלַיִם, שֶׁכָּתוּב וְכָל מַלְכֵי הָאָרֶץ וְגוֹ' מְבִיאִים אִישׁ מִנְחָתוֹ וְגוֹ'. וְיִשְׁתַּחֲוֻ לְךְ לְאֻמִּים - בִּזְמַן שֶׁיָּבא מֶלֶךְ הַמָּשִׁיחַ, שֶׁכָּתוּב וְיִשְׁתַּחֲווּ לוֹ כָל מְלָכִים. רַבִּי יְהוּדָה אָמַר, הַכֹּל בִּזְמַן שֶׁיָּבֹא הַמֶּלֶךְ הַמָּשִׁיחַ, כַּכָּתוּב (תהלים עב) וְיִשְׁתַּחֲווּ לוֹ כָל מְלָכִים כָּל גּוֹיִם יַעַבְדוּהוּ.</p>\n<p>הֱוֵה גְבִיר לְאַחֶיךְ. הֱוֵה, וְלֹא אָמַר הֱיֵה אוֹ תִהְיֶה. אֶלָּא זֶה סוֹד עֶלְיוֹן שֶׁל הָאֱמוּנָה, שֶׁהָאוֹתִיּוֹת הַלָּלוּ הֵן סוֹדוֹת הָאֱמוּנָה. ה' לְמַעְלָה, וָא\"ו בָּאֶמְצַע, ה' אַחַר כָּךְ. וּמִשּׁוּם כָּךְ אָמַר הֱוֵה גְבִיר לְאַחֶיךְ, לִשְׁלֹט עֲלֵיהֶם וְלִרְדּוֹת אוֹתָם בִּזְמַן שֶׁבָּא דָוִד הַמֶּלֶךְ. רַבִּי יוֹסֵי אָמַר, הַכֹּל הוּא בִּזְמַן שֶׁיָּבא מֶלֶךְ הַמָּשִׁיחַ, שֶׁהֲרֵי מִשּׁוּם שֶׁעָבְרוּ יִשְׂרָאֵל עַל דִּבְרֵי הַתּוֹרָה, אָז וּפָרַקְתָּ עֻלּוֹ מֵעַל צַוָּארֶךְ.</p>\n<p>וְיִתֶּן לְךְ הָאֱלֹהִים. רַבִּי יוֹסֵי אָמַר, כָּל הַבְּרָכוֹת הַלָּלוּ מִצַּד שֶׁל חֶלְקוֹ שֶׁל יַעֲקֹב הָיוּ וּמִשֶּׁלּוֹ הוּא נָטַל. וְהַבְּרָכוֹת הָאֵלּוּ הָיָה רוֹצֶה יִצְחָק לְבָרֵךְ עֶת עֵשָׂו, וּמִשּׁוּם כָּךְ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, וְגָרַם לְיַעֲקֹב לִטֹּל מִשֶּׁלּוֹ.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁאוֹתוֹ הַנָּחָשׁ הֵבִיא קְלָלוֹת עַל הָעוֹלָם וְהָאֲדָמָה הִתְקַלְּלָה - מַה כָּתוּב? (בראשית ג) וּלְאָדָם אָמַר כִּי שָׁמַעְתָּ לְקוֹל אִשְׁתֶּךְ וְגוֹ', אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךְ וְגוֹ'. שֶׁלֹּא תִהְיֶה עוֹשָׂה פֵּרוֹת וְגִדּוּלִים כָּרָאוּי. כְּנֶגֶד זֶה וּמִשְׁמַנֵּי הָאָרֶץ. בְּעִצָּבוֹן תֹּאכֲלֶנָּה - כְּנֶגֶד זֶה מִטַּל הַשָּׁמַיִם. וְקוֹץ וְדַרְדַּר תַּצְמִיחַ לָךְ - כְּנֶגֶד זֶה וְרֹב דָּגָן וְתִיר!שׁ. בְּזֵעַת אַפֶּיךְ תֹּאכַל לֶחֶם - כְּנֶגֶד זֶה יַעַבְדוּךְ עַמִּים וְיִשְׁתַּחֲוֻ לְךְ לְאֻמִּים, שֶׁהֵם יַעַבְדוּ אֶת הָאָרֶץ וְיַעַבְדוּ בַּשָּׂדֶה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סא) וּבְנֵי נֵכָר אִכָּרֵיכֶם וְכֹרְמֵיכֶם. וְהַכֹּל נָטַל יַעֲקֹב זֶה כְּנֶגֶד זֶה, וּמִשֶּׁלּוֹ נָטַל. וְהַקָּדוֹשׁ בָּרוּךְ הוּא גָּרַם לְיַעֲקֹב שֶׁיִּטֹּל אֶת הַבְּרָכוֹת הַלָּלוּ לְהִדָּבֵק בִּמְקוֹמוֹ וְחֶלְקוֹ, וְעֵשָׂו שֶׁיִּדְבַּק בִּמְקוֹמוֹ וְחֶלְקוֹ.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, וְהִנֵּה רָאִינוּ שֶׁמִּשְׁמַנֵּי הָאָרֶץ וּמִטַּל הַשָּׁמַיִם, אוֹתָן בְּרָכוֹת נָטַל עֵשָׂו אַחַר כָּךְ, כְּמוֹ שֶׁנֶּאֱמַר הִנֵּה מִשְׁמַנֵּי הָאָרֶץ יִהְיֶה מוֹשָׁבֶךְ וּמִטַּל הַשָּׁמַיִם מֵעָל.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, לֹא זֶה כָּזֶה וְלֹא זֶה כָּזֶה, כַּמָּה נִפְרָדוֹת הַדְּרָגוֹת. בְּיַעֲקֹב כָּתוּב וְיִתֶּן לְךְ הָאֱלֹהִים - וּבָזֶה כָּתוּבּ יִהְיֶה. בְּיַעֲקֹב כָּתוּב מִטַּל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ - בְּעֵשָׂו כָּתוּבּ מִשְׁמַנֵּי הָאָרֶץ וְטַל הַשָּׁמַיִם, שֶׁהִנֵּה זֶה אֵינוֹ כָּזֶה.</p>\n<p>וְהַדְּרָגוֹת נִפְרָדוֹת כַּמָּה וְכַמָּה, מִשּׁוּם שֶׁבָּזֶה שֶׁל יַעֲקֹב כָּתוּב בּוֹ, וְיִתֶּן לְךְ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם - זֶה הַטַּל הָעֶלְיוֹן שֶׁשּׁוֹפֵעַ מֵעַתִּיק הַיָּמִים, שֶׁנִּקְרָא טַל הַשָּׁמַיִם, הַשָּׁמַיִם שֶׁל מַעְלָה, הַטַּל שֶׁשּׁוֹפֵעַ בְּדַרְגַּת הַשָּׁמַיִם, וּמִשָּׁם לִשְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים. וּמִשְׁמַנֵּי הָאָרֶץ - (זו הארץ שלמעלה, ארץ החיים, בעשו כתוב ומשמני הארץ, ביעקב משמני) הָאָרֶץ זוֹ אֶרֶץ הַחַיִּים שֶׁלְּמַעְלָה, וְיוֹרֵשׁ אוֹתָהּ בָּאָרֶץ שֶׁלְּמַעְלָה וּבַשָּׁמַיִם שֶׁל מַעְלָה, וּבְעֵשָׂו בָּאָרֶץ שֶׁל כָּאן לְמַטָּה, וּבַשָּׁמַיִם שֶׁל כָּאן לְמַטָּה.</p>\n<p>יַעֲקֹב לְמַעְלָה לְמַעְלָה, וְעֵשָׂו לְמַטָּה לְמַטָּה. עוֹד, יַעֲקֹב לְמַעְלָה וּלְמַטָּה, וְעֵשָׂו לְמַטָּה. וְאַף עַל גַּב שֶׁכָּתוּב וְהָיָה כַּאֲשֶׁר תָּרִיד וּפָרַקְתָּ עֻלּוֹ מֵעַל צַוָּארֶךְ - מִזֶּה שֶׁל כָּאן לְמַטָּה, אֲבָל לְמַעְלָה לֹא כְלוּם, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ. בּא רְאֵה, בְּשָׁעָה שֶׁהִתְחִילוּ לִטֹּל אֶת בִּרְכוֹתֵיהֶם יַעֲקֹב וְעֵשָׂו, יַעֲקֹב נָטַל חֶלְקוֹ שֶׁלְּמַעְלָה, וְעֵשָׂו נָטַל חֶלְקוֹ שֶׁלְּמַטָּה.</p>\n<p>רַבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא אָמַר לְרַבִּי אֶלְעָזָר, כְּלוּם שָׁמַעְתָּ מֵאָבִיךְ לָמָּה לֹא הִתְקַיְּמוּ הַבְּרָכוֹת שֶׁבֵּרַךְ יִצְחָק אֶת יַעֲקֹב, וְאוֹתָן הַבְּרָכוֹת שֶׁבֵּרַךְ יִצְחָק אֶת עֵשָׂו כֻּלָּם הִתְקַיְּמוּ?</p>\n<p>אָמַר לוֹ, כָּל אוֹתָם הַבְּרָכוֹת מִתְקַיְּמוֹת, וּבְרָכוֹת אֲחֵרוֹת שֶׁבֵּרַךְ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יַעֲקֹב. אֲבָל מִיָּד יַעֲקֹב נָטַל לְמַעְלָה, וְעֵשָׂו נָטַל לְמַטָּה. אַחַר כָּךְ כְּשֶׁיָּקוּם מֶלֶךְ הַמָּשִׁיחַ, יִטֹּל יַעֲקֹב לְמַעְלָה וּלְמַטָּה, וְיֹאבַד עֵשָׂו מִן הַכֹּל, וְלֹא יִהְיֶה לוֹ חֵלֶק וְנַחֲלָה וְזִכָּרוֹן בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (עובדיה א) וְהָיָה בֵית יַעֲקֹב אֵשׁ וּבֵית יוֹסֵף לֶהָבָה וּבֵית עֵשָׂו לְקַשׁ וְגוֹ'. כְּדֵי שֶׁיֹּאבַד עֵשָׂו מִן הַכֹּל, וְיַעֲקֹב יִירַשׁ שְׁנֵי עוֹלָמוֹת - הָעוֹלָם הַזֶּה וְהָעוֹלָם הַבָּא.</p>\n<p>וּבַזְּמַן הַזֶּה כָּתוּב, (שם) וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפֹּט אֶת הַר עֵשָׂו וְהָיְתָה לַה' הַמְּלוּכָה. אוֹתָהּ מַלְכוּת עֵשָׂו שֶׁנָּטַל בָּעוֹלָם הַזֶּה, נָתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא (תהיה לקדושברוךהוא) לְבַדּוֹ. וְכִי עַכְשָׁו אֵינָהּ מַלְכוּת מֵהַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא אַף עַל גַּב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט לְמַעְלָה וּלְמַטָּה, הִנֵּה נָתַן לִשְׁאָר הָעַמִּים לְכָל אֶחָד וְאֶחָד חֵלֶק וְנַחֲלָה בָּעוֹלָם הַזֶּה לְהִשְׁתַּמֵּשׁ בּוֹ, וּבַזְּמַן הַהוּא יִטֹּל מִכֻּלָּם אֶת הַמַּלְכוּת וְכֻלָּהּ תִּהְיֶה שֶׁלּוֹ, שֶׁכָּתוּב וְהָיְתָה לַה' הַמְּלוּכָה, לוֹ לְבַדּוֹ, שֶׁכָּתוּב (זכריה יד) וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>וַיְהִי אַךְ יָצֹא יָצָא יַעֲקֹב וְגוֹ'. רַבִּי שִׁמְעוֹן אָמַר, אַךְ יָצֹא יָצָא - שְׁתֵּי הַיְצִיאוֹת הַלָּלוּ לָמָּה? אֶלָּא אַחַת שֶׁל הַשְּׁכִינָה, וְאַחַת שֶׁל יַעֲקֹב. שֶׁהִנֵּה כְּשֶׁנִּכְנַס יַעֲקֹב, הַשְּׁכִינָה נִכְנְסָה עִמּוֹ וְהִתְבָּרֵךְ לִפְנֵי הַשְּׁכִינָה. שֶׁיִּצְחָק הָיָה אוֹמֵר אֶת הַבְּרָכוֹת, וְהַשְּׁכִינָה מוֹדָה לָהֶם עֲלֵיהֶם. וּכְשֶׁיָּצָא יַעֲקֹב, הַשְּׁכִינָה יָצְאָה עִמּוֹ. זֶהוּ שֶׁכָּתוּב אַךְ יָצֹא יָצָא יַעֲקֹב. שְׁתֵּי יְצִיאוֹת יַחַד.</p>\n<p>וְעֵשָׂו אָחִיו בָּא מִצֵּידוֹ. לֹא כָתוּב מִן הַצַּיִד, אֶלָּא מִצֵּידוֹ, שֶׁהוּא הַצֵּידָה שֶׁלּוֹ, שֶׁלֹּא הָיְתָה בּוֹ בְּרָכָה, וְרוּחַ הַקֹּדֶשׁ צוֹוַחַת וְאוֹמֶרֶת, (משלי כג) אַל תִּלְחַם אֶת לֶחֶם רַע עַיִן.</p>\n<p>וַיַּעַשׂ גַּם הוּא מַטְעַמִּים וְגוֹ'. יָקוּם אָבִי - דִּבּוּרוֹ הָיָה בְּעַזּוּת, בְּתַקִּיפוּת הָרוּחַ, דָּבָר שֶׁאֵין בּוֹ טַעַם, יָקוּם אָבִי. בּא רְאֵה מַה בֵּין יַעֲקֹב לְעֵשָׂו. יַעֲקֹב אָמַר בְּבוּשָׁה שֶׁל אָבִיו, בַּעֲנָוָה. מַה כָּתוּב? וַיָּבֹא אֶל אָבִיו וַיֹּאמֶר אָבִי. מַה בֵּין זֶה לָזֶה? אֶלָּא שֶׁלֹּא רָצָה לְזַעֲזֵעַ אוֹתוֹ, דִּבֵּר בִּלְשׁוֹן תַּחֲנוּנִים: קוּם נָא שְׁבָה וְאָכְלָה מִצֵּידִי. וְעֵשָׂו אָמַר: יָקוּם אָבִי, כְּמִי שֶׁלֹּא דִבֵּר עִמּוֹ.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּכְנַס עֵשָׂו - נִכְנַס עִמּוֹ גֵּיהִנֹּם. הִזְדַּעֲזַע יִצְחָק וּפָחַד, שֶׁכָּתוּב וַיֶּחֱרַד יִצְחָק חֲרָדָה גְּדלָה עַד מְאֹד. כֵּיוָן שֶׁכָּתוּב וַיֶּחֱרַד יִצְחָק חֲרָדָה גְּדלָה - דַּי. מַה זֶּה (גדלה) עַד מְאֹד? אֶלָּא שֶׁלֹּא הָיְתָה יִרְאָה וְאֵימָה גְּדוֹלָה שֶׁנָּפְלָה עַל יִצְחָק מִיּוֹם שֶׁנִּבְרָא. וַאֲפִלּוּ בַּשָּׁעָה הַהִיא שֶׁנֶּעֱקַד יִצְחָק עַל גַּבֵּי הַמִּזְבֵּחַ וְרָאָה (שכינה) סַכִּין עָלָיו, לֹא הִזְדַּעֲזַע כַּשָּׁעָה הַהִיא שֶׁנִּכְנַס עֵשָׂו וְרָאָה גֵיהִנֹּם שֶׁנִּכְנַס עִמּוֹ. אָז אָמַר, בְּטֶרֶם תָּבֹא וַאֲבָרֲכֵהוּ גַּם בָּרוּךְ יִהְיֶה, מִשּׁוּם (שראתה) שֶׁרָאִיתִי שְׁכִינָה שֶׁמּוֹדָה עַל אוֹתָן הַבְּרָכוֹת.</p>\n<p>דָּבָר אַחֵר, יִצְחָק אָמַר וַאֲבָרֲכֵהוּ, יָצָא קוֹל וְאָמַר גַּם בָּרוּךְ יִהְיֶה. רָצָה יִצְחָק לְקַלֵּל אֶת יַעֲקֹב, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: יִצְחָק, אֶת עַצְמְךְ אַתָּה מְקַלֵּל, שֶׁהֲרֵי כְּבָר אָמַרְתָּ לוֹ אֹרֲרֶיךְ אָרוּר וּמְבָרֲכֶיךְ בָּרוּךְ.</p>\n<p>בֹּא רְאֵה, כֻּלָּם הוֹדוּ עַל אוֹתָן הַבְּרָכוֹת, עֶלְיוֹנִים וְתַחְתּוֹנִים, וַאֲפִלּוּ חֵלֶק גּוֹרָלוֹ שֶׁל עֵשָׂו הוֹדָה עֲלֵיהֶם, וְהוּא בֵּרַךְ אוֹתוֹ, וְהוֹדָה עַל אוֹתָן הַבְּרָכוֹת, וְהֶעֱלָהוּ עַל רֹאשׁוֹ לְמַעְלָה.</p>\n<p>מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר וַיֹּאמֶר לֹא אֲשַׁלֵּחֲךְ כִּי אִם בֵּרַכְתָּנִי. וַיֹּאמֶר שַׁלְּחֵנִי - מִשּׁוּם שֶׁהֶחֱזִיק בּוֹ יַעֲקֹב. וְכִי אֵיךְ יָכוֹל אָדָם, שֶׁהוּא גוּף וּבָשָׂר, לְהַחֲזִיק בְּמַלְאָךְ שֶׁהוּא רוּחַ מַמָּשׁ, שֶׁכָּתוּב (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לֹהֵט?</p>\n<p>אֶלָּא, מִכָּאן שֶׁמַּלְאָכִים שְׁלוּחֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּשֶׁיּוֹרְדִים לָעוֹלָם הַזֶּה, גְּלוּמִים וּמִתְגַּלְּמִים, וּמִתְלַבְּשִׁים בְּגוּף כְּמוֹ שֶׁל הָעוֹלָם הַזֶּה, מִשּׁוּם שֶׁכָּךְ רָאוּי שֶׁלֹּא לְשַׁנּוֹת מִמִּנְהַג אוֹתוֹ הַמָּקוֹם שֶׁהוֹלְכִים לְשָׁם.</p>\n<p>וְהִנֵּה נֶאֱמַר, שֶׁכַּאֲשֶׁר עָלָה מֹשֶׁה לְמַעְלָה מַה כָּתוּב? (שמות לד) וַיְהִי שָׁם עִם ה' אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה לֶחֶם לֹא אָכַל וּמַיִם לֹא שָׁתָה, מִשּׁוּם הַמִּנְהָג, שֶׁלֹּא לְשַׁנּוֹת מֵהַמָּקוֹם הַהוּא שֶׁהָלַךְ לְשָׁם. וְאוֹתָם הַמַּלְאָכִים, כְּשֶׁיָּרְדוּ לְמַטָּה, כָּתוּב (בראשית יח) וְהוּא עֹמֵד עֲלֵיהֶם תַּחַת הָעֵץ וַיֹּאכֵלוּ. וְכֵן כָּאן, כְּשֶׁיָּרַד לְמַטָּה הַמַּלְאָךְ הַזֶּה, לֹא נֶאֱבַק עִם יַעֲקֹב אֶלָּא מִתּוֹךְ שֶׁהָיָה מְלֻבָּשׁ בְּגוּף כְּמוֹ שֶׁל הָעוֹלָם הַזֶּה, וְעַל כֵּן נֶאֱבַק עִמּוֹ כָּל אוֹתוֹ הַלַּיְלָה.</p>\n<p>בֹּא רְאֵה, מִשּׁוּם שֶׁהַשִּׁלְטוֹן שֶׁל אֵלּוּ אֵינוֹ אֶלָּא בַּלַּיְלָה וַדַּאי, וּמִשּׁוּם כָּךְ הַשְּׁלִיטָה שֶׁל עֵשָׂו אֵינָהּ אֶלָּא בַּגָּלוּת, שֶׁהִיא הַלַּיְלָה, וְעַל כֵּן בַּלַּיְלָה הִתְחַזֵּק עִם יַעֲקֹב וְנֶאֱבַק עִמּוֹ. וּכְשֶׁבָּא הַבּקֶר, נֶחֱלַשׁ כֹּחוֹ וְלֹא יָכֹל, וְאָז הִתְגַּבֵּר יַעֲקֹב, מִשּׁוּם שֶׁשִּׁלְטוֹנוֹ שֶׁל יַעֲקֹב בַּיּוֹם.</p>\n<p>וּמִשּׁוּם כָּךְ כָּתוּב, (ישעיה כא) מַשָּׂא דּוּמָה אֵלַי קֹרֵא מִשֵּׂעִיר שֹׁמֵר מַה מִּלַּיְלָה שֹׁמֵר מַה מִּלֵּיל. שֶׁהֲרֵי אָז הַשִּׁלְטוֹן הוּא שֶׁל עֵשָׂו, שֶׁהוּא שֵׂעִיר, הוּא בַּלַּיְלָה. וּמִשּׁוּם כָּךְ נֶחֱלַשׁ כְּשֶׁבָּא הַבֹּקֶר, וְאָז וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר.</p>\n<p>וַיֹּאמֶר לֹא אֲשַׁלֵּחֲךְ כִּי אִם בֵּרַכְתָּנִי. כִּי אִם בֵּרַכְתָּנִי? כִּי אִם תְּבָרְכֵנִי הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה כִּי אִם בֵּרַכְתָּנִי? אִם תּוֹדֶה עַל אוֹתָן הַבְּרָכוֹת שֶׁבֵּרַךְ אוֹתִי אַבָּא וְלֹא תִהְיֶה מְקַטְרֵג עָלַי בִּגְלָלָם. מַה כָּתוּב? וַיֹּאמֶר לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךְ כִּי אִם יִשְׂרָאֵל וְגוֹ'. לָמָּה יִשְׂרָאֵל? אָמַר לוֹ, בְּעַל כָּרְחִי יֵשׁ לִי לְשַׁמֵּשׁ אוֹתְךְ, שֶׁהֲרֵי אַתָּה הִתְעַטַּרְתָּ בְּכֹחֲךְ לְמַעְלָה בְּדַרְגָּה עֶלְיוֹנָה, וַדַּאי יִשְׂרָאֵל יִהְיֶה שִׁמְךְ.</p>\n<p>כִּי שָׂרִיתָ עִם אֱלֹהִים. מַה זֶּה עִם אֱלֹהִים? וְכִי תַעֲלֶה עַל הַדַּעַת שֶׁעָלָיו הָיָה אוֹמֵר? אֶלָּא אָמַר לוֹ, שָׂרִיתָ לְהִתְחַבֵּר וּלְהִזְדַּוֵּג עִם אֱלֹהִים בְּחִבּוּר, בַּזִּוּוּג שֶׁל הַשֶּׁמֶשׁ עִם הַלְּבָנָה. וְעַל כֵּן לֹא כָּתוּב עַל (את) אֱלֹהִים, אֶלָּא עִם אֱלֹהִים, בְּחִבּוּר וְזִוּוּג אֶחָד.</p>\n<p>דָּבָר אַחֵר וַיֹּאמֶר, כְּמוֹ שֶׁנֶּאֱמַר (שמות טו) וַיֹּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע לְקוֹל ה' אֱלֹהֶיךְ. אַף כָּאן, וַיֹּאמֶר לֹא יֵאָמֵר עוֹד שִׁמְךְ יַעֲקֹב כִּי אִם יִשְׂרָאֵל. וְאָז הִתְעַטֵּר יַעֲקֹב בְּדַרְגָּתוֹ לִהְיוֹת הַכְּלָל שֶׁל הָאָבוֹת. מַה כָּתוּב? וַיְבָרֶךְ אֹתוֹ שָׁם. מַה זֶּה וַיְבָרֶךְ אֹתוֹ שָׁם? שֶׁהוֹדָה לוֹ עַל כָּל הַבְּרָכוֹת שֶׁבֵּרַךְ אוֹתוֹ אָבִיו.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (משלי טז) בִּרְצוֹת ה' דַּרְכֵי אִישׁ גַּם אוֹיְבָיו יַשְׁלִם אִתּוֹ בֹּא רְאֵה כַּמָּה יֵשׁ לְאָדָם שֶׁיְּתַקֵּן אֶת שְׁבִילָיו עִם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי לַעֲשׂוֹת אֶת מִצְווֹת הַתּוֹרָה, שֶׁהֲרֵי פֵּרְשׁוּהָ, שֶׁוַּדַּאי שְׁנֵי מַלְאָכִים שְׁלִיחִים יֵשׁ לָאָדָם מִלְמַעְלָה לְהִזְדַּוֵּג עִמּוֹ, אֶחָד לְיָמִין וְאֶחָד לִשְׂמֹאל, וְהֵם מְעִידִים עַל הָאָדָם בְּכָל מַה שֶּׁהוּא עוֹשֶׂה, הֵם נִמְצָאִים שָׁם, וְקוֹרְאִים לָהֶם יֵצֶר טוֹב וְיֵצֶר רַע.</p>\n<p>בָּא הָאָדָם לְהִטַּהֵר וּלְהִשְׁתַּדֵּל בְּמִצְווֹת הַתּוֹרָה - אוֹתוֹ יֵצֶר הַטּוֹב שֶׁהִזְדַּוֵּג עִמּוֹ, כְּבָר הִתְגַּבֵּר עַל אוֹתוֹ יֵצֶר הָרָע וְהִשְׁלִים עִמּוֹ וְהִתְהַפֵּךְ לוֹ לְעֶבֶד. וּכְשֶׁאָדָם הוֹלֵךְ לְהִטַּמֵּא, אוֹתוֹ יֵצֶר הָרָע מִתְחַזֵּק וּמִתְגַּבֵּר עַל אוֹתוֹ יֵצֶר טוֹב, וַהֲרֵי בֵּאַרְנוּ, וַדַּאי כְּשֶׁאוֹתוֹ הָאָדָם בָּא לִטַּהֵר, בְּכַמָּה כֹּחַ הִתְחַזֵּק הָאָדָם כְּשֶׁהִתְגַּבֵּר אוֹתוֹ יֵצֶר טוֹב, אָז אוֹיְבָיו יַשְׁלִם אִתּוֹ, שֶׁאוֹתוֹ יֵצֶר הָרָע נִכְנָע לִפְנֵי הַיֵּצֶר הַטּוֹב. וְעַל זֶה אָמַר שְׁלֹמֹה, (משלי יב) טוֹב נִקְלֶה וְעֶבֶד לוֹ. מַה זֶּה וְעֶבֶד לוֹ? זֶה יֵצֶר הָרָע. וְאָז כְּשֶׁאָדָם הוֹלֵךְ בְּמִצְווֹת הַתּוֹרָה, אָז גַּם אוֹיְבָיו יַשְׁלִם אִתּוֹ, זֶה יֵצֶר הָרָע וּמַה שֶּׁבָּא מִצִּדּוֹ.</p>\n<p>בֹּא רְאֵה, מִשּׁוּם שֶׁיַּעֲקֹב בָּטַח בַּקָּבָּ\"ה וְכָל דְּרָכָיו הָיוּ לִשְׁמוֹ, עַל כֵּן אוֹיְבָיו יַשְׁלִים אִתּוֹ. וְזֶה (זה) סמא\"ל, הַכֹּחַ וְהַחֹזֶק שֶׁל עֵשָׂו, שֶׁהִשְׁלִים עִם יַעֲקֹב. וּמִשּׁוּם שֶׁהִשְׁלִים עִם יַעֲקֹב וְהוֹדָה לוֹ עַל אוֹתָן הַבְּרָכוֹת, אֲזַי הִשְׁלִים עִמּוֹ עֵשָׂו. (אז הודה לו עשו, שכתוב יש לי רב אחי יהי לך אשר לך, שהרי הודה לו על אותן הברכות שלו בחרב) וְעַד שֶׁלֹּא הִשְׁלִים יַעֲקֹב עִם אוֹתוֹ הַמְמֻנֶּה שֶׁנִּתְמַנָּה עָלָיו, לֹא הִשְׁלִים עִמּוֹ עֵשָׂו. מִשּׁוּם כָּךְ, בְּכָל מָקוֹם הַכֹּחַ שֶׁל מַטָּה תָּלוּי בַּכֹּחַ שֶׁל מַעְלָה.</p>\n<p>וַיֶּחֱרַד יִצְחָק חֲרָדָה גְּדֹלָה עַד מְאֹד וַיֹּאמֶר מִי אֵפוֹא. מִי אֵפוֹא - מַה זֶּה מִי אֵפוֹא? הָיָה צָרִיךְ לִהְיוֹת מִי הוּא זֶה! אֶלָּא מִי אֵפוֹא - שֶׁשָּׁם עָמְדָה הַשְּׁכִינָה כְּשֶׁבֵּרַךְ יִצְחָק אֶת יַעֲקֹב, וְעַל כֵּן אָמַר מִי אֵפוֹא, מִי הוּא שֶׁעוֹמֵד כָּאן וּמוֹדֶה עַל אוֹתָן הַבְּרָכוֹת שֶׁבֵּרַכְתִּי אוֹתוֹ? וַדַּאי גַּם בָּרוּךְ יִהְיֶה! שֶׁהִנֵּה הַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים לְאוֹתָן הַבְּרָכוֹת.</p>\n<p>רַבִּי יְהוּדָה אָמַר, מִשּׁוּם אוֹתָהּ הַחֲרָדָה שֶׁהֶחֱרִיד יַעֲקֹב אֶת יִצְחָק אָבִיו, נֶעֱנַשׁ יַעֲקֹב בָּעֹנֶשׁ שֶׁל יוֹסֵף שֶׁחָרַד חֲרָדָה כָּזוֹ בְּשָׁעָה שֶׁאָמְרוּ לוֹ זֹאת מָצָאנוּ. יִצְחָק אָמַר מִי אֵפוֹא - בְּאֵיפֹה נֶעֱנַשׁ יַעֲקֹב, שֶׁכָּתוּב אֵיפֹה הֵם רֹעִים, וְשָׁם יוֹסֵף נֶאֱבַד, וְנֶעֱנַשׁ יַעֲקֹב. וְאַף עַל גַּב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עַל יָדוֹ בְּאוֹתָן הַבְּרָכוֹת, הוּא נֶעֱנַשׁ בְּאֵיפֹה, שֶׁכָּתוּב אֵיפֹה הֵם רֹעִים, וּמִשָּׁם נֶאֱבַד מִמֶּנּוּ וְנֶעֱנַשׁ כָּל אוֹתוֹ הָעֹנֶשׁ.</p>\n<p>וַיֶּחֱרַד יִצְחָק חֲרָדָה גְּדלָה. מַה זֶּה גְּדֹלָה? כָּתוּב כָּאן גְּדֹלָה, וְכָתוּב שָׁם (דברים יח) וְאֶת הָאֵשׁ הַגְּדלָה הַ את וְגוֹ'. שֶׁנִּכְנַס עִמּוֹ גֵּיהִנֹּם. עַד מְאֹד - מַה זֶּה עַד מְאֹד? כָּתוּב כָּאן מְאֹד, וְכָתוּב שָׁם (בראשית א) וְהִנֵּה טוֹב מְאֹד. זֶה מַלְאַךְ הַמָּוֶת. אָז אָמַר מִי אֵפוֹא.כִּשְׁמֹעַ עֵשָׂו אֶת דִּבְרֵי אָבִיו וְגוֹ'.</p>\n<p>אָמַר רַבִּי חִיָּיא, כַּמָּה רָעוֹת עָשׂוּ אוֹתָן דְּמָעוֹת שֶׁבָּכָה וְהוֹצִיא עֵשָׂו לִפְנֵי אָבִיו כְּדֵי שֶׁיִּתְבָּרֵךְ מִמֶּנּוּ, מִשּׁוּם שֶׁהָיָה מַחְשִׁיב דְּבַר אָבִיו יוֹתֵר. הֲכִי קָרָא שְׁמוֹ יַעֲקֹב. (ובארוהו) הֲכִי קָרָא שְׁמוֹ - קָרָא שְׁמוֹ אוֹתוֹ שֶׁקָּרָא לוֹ. הוֹצִיא הַשְׁמָעַת קוֹל שֶׁל רֹק בִּשְׁבִיל קָלוֹן. לֹא כָתוּב הֲכִי נִקִרָא שְׁמוֹ, אֶלָּא קָרָא שְׁמוֹ.</p>\n<p>וַיַּעִִקְֹבֵנִי זֶה פַעֲמַיִם. זֶה - מַה הוּא זֶה? (אלא) וַיַּעְקְבֵנִי פַעֲמַיִם הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא דָּבָר אֶחָד הָיָה פַּעֲמַיִם - בְּכֹרָתִי, הֶחֱזִיר לוֹ פַּעַם אַחֶרֶת בִּרְכָתִי. זֶהוּ פַּעֲמַיִם. כְּמוֹ כֵן (בראשית מג) כִּי עַתָּה שַׁבְנוּ זֶה פַעֲמָיִם. דָּבָר אֶחָד פַּעֲמַיִם. אֶחָד שֶׁהִנֵּה הֶחֱזַרְתִּי לוֹ, וְלֹא נִהְיֶה בְּבוּשָׁה לִפְנֵי אוֹתוֹ אָדָם. שַׁבְנוּ - בּשְׁנוּ. אָנוּ בְּבוּשָׁה מִמֶּנּוּ, וּכְבָר הֶחֱזַרְנוּ.</p>\n<p>כְּמוֹ זֶה אָמַר אִיּוֹב, (איוב יג) וְתַחְשְׁבֵנִי לְאוֹיֵב לָךְ. חָזַר אִיּוֹב - אוֹיֵב. וּפֵרְשׁוּהָ שֶׁכָּתוּב אֲשֶׁר בִּשְׂעָרָה יְשׁוּפֵנִי וְגוֹ'. אָמַר לְפָנָיו: רִבּוֹנוֹ שֶׁל עוֹלָם, שֶׁמָּא רוּחַ סְעָרָה עָבְרָה לְפָנֶיךְ? וְכָאן בְּכֹרָתִי לָקַח, וְהִנֵּה עַתָּה חָזַר הַדָּבָר וְנָטַל בִּרְכָתִי.</p>\n<p>הֵן גְּבִיר שַׂמְתִּיו לָךְ וְגוֹ', וּלְךְ אֵפוֹא מָה אֶעֱשֶׂה בְּנִי. וּלְךְ אֵפוֹא - אֵין עוֹמֵד פֹּה מִי שֶׁיַּסְכִּים עָלֶיךְ. מָה אֶעֱשֶׂה בְּנִי. אָז בֵּרַךְ אוֹתוֹ בָּעוֹלָם הַזֶּה, וְהִסְתַּכֵּל בְּדַרְגָּתוֹ וְאָמַר וְעַל חַרְבְּךְ תִחְיֶה, שֶׁהֲרֵי כָּךְ רָאוּי לְךְ לִשְׁפֹּךְ דָּמִים וְלַעֲשׂוֹת קְרָבוֹת, וְעַל כֵּן אָמַר מָה אֶעֱשֶׂה בְּנִי.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, וּלְךְ אֵפוֹא מָה אֶעֱשֶׂה - כֵּיוָן שֶׁאָמַר אֶת זֶה, לָמָּה בְּנִי? אֶלָּא אָמַר לוֹ, וּלְךְ אֵפוֹא מָה אֶעֱשֶׂה שֶׁאַתָּה בְּדִין וּבְחֶרֶב וּבְדָם אֲנִי רוֹאֶה אוֹתְךְ, וְאֶת אָחִיךְ בְּדֶרֶךְ שְׁלֵמָה. אֶלָּא בְּנִי, בְּנִי וַדַּאי. אֲנִי גָּרַמְתִּי לְךְ מִשּׁוּם שֶׁאַתָּה בְּנִי, וְעַל כֵּן וְעַל חַרְבְּךְ תִחְיֶה וְאֶת אָחִיךְ תַּעֲבד. וַעֲדַיִן לֹא הִתְקַיֵּם, שֶׁהֲרֵי לֹא עָבַד עֵשָׂו אֶת יַעֲקֹב, מִשּׁוּם שֶׁיַּעֲקֹב לֹא רָצָה אוֹתוֹ עַכְשָׁו, וְהוּא חָזַר וְקָרָא לוֹ אֲדוֹנִי כַּמָּה פְעָמִים, מִשּׁוּם שֶׁהִסְתַּכֵּל לְמֵרָחוֹק וְהֶעֱלָה אוֹתוֹ לְסוֹף הַיָּמִים, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. בְּעוֹדָם הוֹלְכִים רָאוּ אֶת רַבִּי יוֹסֵי הַזָּקֵן שֶׁהָיָה הוֹלֵךְ אַחֲרֵיהֶם. יָשְׁבוּ עַד שֶׁהִגִּיעַ אֲלֵיהֶם. כֵּיוָן שֶׁהִגִּיעַ אֲלֵיהֶם, אָמְרוּ, עַכְשָׁו הַדֶּרֶךְ מְתֻקֶּנֶת לְפָנֵינוּ. הָלְכוּ. אָמַר רַבִּי חִיָּיא, עֵת לַעֲשׂוֹת לַה'. פָּתַח רַבִּי יוֹסֵי וְאָמַר, (משלי לא) פִּיהָ פָּתְחָה בְּחָכְמָה וְתוֹרַת חֶסֶד עַל לְשׁוֹנָהּ. פִּיהָ פָּתְחָה בְּחָכְמָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְתוֹרַת חֶסֶד עַל לְשׁוֹנָהּ - אֵלּוּ הֵם יִשְׂרָאֵל, שֶׁהֵם לְשׁוֹן הַתּוֹרָה שֶׁמְּדַבְּרִים בָּהּ יָמִים וְלֵילוֹת.</p>\n<p>פִּיהָ פָּתְחָה בְחָכְמָה - זוֹ ב' שֶׁל בְּרֵאשִׁית, וּפֵרְשׁוּהָ. וְתוֹרַת חֶסֶד עַל לְשׁוֹנָהּ - זֶה אַבְרָהָם, שֶׁבּוֹ בָּרָא אֶת הָעוֹלָם וּבוֹ מְדַבֵּר תָּמִיד. ב' סְתוּמָה מִצַּד זֶה, וּפְתוּחָה מִצַּד זֶה. סְתוּמָה מִצַּד זֶה, כְּמוֹ שֶׁנֶּאֱמַר וְרָאִיתָ אֶת אֲחֹרָי. פְּתוּחָה מִצַּד זֶה כְּדֵי לְהָאִיר (להדר) פָּנֶיהָ כְּלַפֵּי מַעְלָה, וּפְתוּחָה מִצַּד זֶה כְּדֵי לְקַבֵּל מִלְמַעְלָה, וְהִיא אַכְסַדְרָה לְקַבֵּל. וּמִשּׁוּם כָּךְ עוֹמֶדֶת בְּרֹאשׁ הַתּוֹרָה וּמִתְמַלֵּאת אַחַר כָּךְ. פִּיהָ פָּתְחָה בְחָכְמָה, בְּחָכְמָה וַדַּאי, שֶׁכָּתוּב בְּרֵאשִׁית בָּרָא אֱלֹהִים, כְּתַרְגּוּמוֹ. וְתוֹרַת חֶסֶד עַל לְשׁוֹנָהּ - שֶׁהֲרֵי אַחַר כָּךְ מְסַפֵּר וְאוֹמֵר, וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. פִּיהָ פָּתְחָה בְחָכְמָה - זוֹ ה' (הראשונה) שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁהַכֹּל בָּהּ, וְהִיא סְתוּמָה וּגְלוּיָה, כְּלוּלָה מִמַּעְלָה וּמַטָּה, הַסּוֹד שֶׁל מַעְלָה וּמַטָּה.</p>\n<p>פִּיהָ פָּתְחָה בְחָכְמָה - מִשּׁוּם שֶׁהִיא סְתוּמָה שֶׁאֵין נוֹדַעַת כְּלָל, שֶׁכָּתוּב וְנֶעֶלְמָה מֵעֵינֵי כָל חָי וּמֵעוֹף הַשָּׁמַיִם נִסְתָּרָה. וּכְשֶׁמַּתְחִילָה לְהִתְפַּשֵּׁט בַּחָכְמָה שֶׁנִּדְבְּקָה בָּהּ, וְהִיא בְּתוֹכָהּ, (והיא) מוֹצִיאָה קוֹל, שֶׁהִיא תּוֹרַת חֶסֶד.</p>\n<p>פִּיהָ פָּתְחָה בְחָכְמָה - זוֹ הֵ\"א הָאַחֲרוֹנָה שֶׁהִיא דִבּוּר, וְהַדִּבּוּר תָּלוּי בַּחָכְמָה. וְתוֹרַת חֶסֶד עַל לְשׁוֹנָהּ - זֶה הַקּוֹל שֶׁעוֹמֵד עַל הַדִּבּוּר לְהַנְהִיגוֹ. וְתוֹרַת חֶסֶד - זֶה יַעֲקֹב, שֶׁהוּא עַל לְשׁוֹנָהּ, לְהַנְהִיג הַדָּבָר וְלֶאֱחֹז אוֹתוֹ, שֶׁהֲרֵי אֵין דִּבּוּר בְּלִי קוֹל, וּבֵאֲרוּהָ.</p>\n<p>פָּתַח רַבִּי חִיָּיא אַחֲרָיו וְאָמַר, (משלי ח) אֲנִי חָכְמָה שָׁכַנְתִּי עָרְמָה וְדַעַת מְזִמּוֹת אֶמְצָא. אֲנִי חָכְמָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל. שָׁכַנְתִּי עָרְמָה - זֶה יַעֲקֹב שֶׁהוּא חָכָם. וְדַעַת מְזִמּוֹת אֶמְצָא - זֶה יִצְחָק, שֶׁהָיְתָה לוֹ דַּעַת מְזִמּוֹת לְבָרֵךְ אֶת עֵשָׂו. וּמִשּׁוּם שֶׁחָכְמָה הִשְׁתַּתְּפָה עִם יַעֲקֹב, שֶׁהוּא עָרְמָה - וְדַעַת מְזִמּוֹת אֶמְצָא, שֶׁהִתְבָּרֵךְ יַעֲקֹב מֵאָבִיו, וְשָׁרוּ עָלָיו כָּל הַבְּרָכוֹת, וְהִתְקַיְּמוּ בוֹ וּבְבָנָיו לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>מֵהֶן הִתְקַיְמוּ בָּעוֹלָם הַזֶּה, וְכֻלָּן יִתְקַיְּמוּ לִזְמַן מֶלֶךְ הַמָּשִׁיחַ, שֶׁאָז יִהְיוּ יִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ וְעַם אֶחָד לַקָּדוֹשׁ-בָּרוּךְ-הוּא. זֶהוּ שֶׁכָּתוּב וְעָשִׂיתִי אֹתָם לְגוֹי אֶחָד בָּאָרֶץ. וְיִשְׁלְטוּ לְמַעְלָה וּלְמַטָּה, שֶׁכָּתוּב (דניאל ז) וְהִנֵּה עִם עַנְנֵי הַשָּׁמַיִם כְּבֶן אָדָם בָּא. זֶה מֶלֶךְ הַמָּשִׁיחַ, שֶׁכָּתוּב (שם ב) וּבִימֵיהֶם שֶׁל אֵלּוּ הַמְּלָכִים יַעֲמִיד אֱלֹהֵי הַשָּׁמַיִם מַלְכוּת. וְעַל כֵּן רָצָה יַעֲקֹב שֶׁיַּעַבְרוּ בִרְכוֹתָיו לְאוֹתוֹ עָתִיד לָבֹא, וְלֹא נָטַל אוֹתָם לְאַלְתַּר.</p>\n<p>פָּתַח רַבִּי יֵיסָא אַחֲרָיו וְאָמַר, (ירמיה ל) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב נְאֻם ה' וְאַל תֵּחַת יִשְׂרָאֵל וְגוֹ'. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ. אֲבָל בַּשָּׁעָה הַהִיא שֶׁיָּצָא יַעֲקֹב מִלִּפְנֵי אָבִיו עִם אוֹתָן הַבְּרָכוֹת, הִסְתַּכֵּל בְּעַצְמוֹ וְאָמַר: הִנֵּה הַבְּרָכוֹת הַלָּלוּ אֲנִי רוֹצֶה לְהַעֲבִירָן לְאַחַר כָּךְ, לְאֹרֶךְ הַיָּמִים. וְהָיָה יָרֵא וּפוֹחֵד. יָצָא קוֹל וְאָמַר: וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב נְאֻם ה' כִּי אִתְּךְ אָנִי. לֹא אֶעֱזֹב אוֹתְךְ בָּעוֹלָם הַזֶּה. כִּי הִנְנִי מוֹשִׁיעֲךְ מֵרָחוֹק, לְאוֹתוֹ הַזְּמַן שֶׁאַתָּה מַעֲבִיר אוֹתָן, אֶת אוֹתָן הַבְּרָכוֹת.</p>\n<p>וְאֶת זַרְעֲךְ מֵאֶרֶץ שִׁבְיָם, שֶׁאַף עַל גַּב שֶׁעַכְשָׁו נוֹטֵל עֵשָׂו בִּרְכוֹתָיו וְיִשְׁתַּעְבְּדוּ בְּבָנֶיךְ, אֲנִי אוֹצִיא אוֹתָם מִיָּדָיו, אָז בָּנֶיךְ יִשְׁתַּעְבְּדוּ בוֹ. וְשָׁב יַעֲקֹב, לְאוֹתָן הַבְּרָכוֹת. וְשָׁב יַעֲקֹב - זוֹ הַשְּׁכִינָה (שהיא עם י קב). וְשָׁב יַעֲקֹב וַדַּאי. וְשָׁקַט וְשַׁאֲנַן, כְּמוֹ שֶׁבֵּאֲרוּהָ, מֵאוֹתָן מַלְכֻיּוֹת: מִבָּבֶל, וּמָדַי, וּמִיָּוָן, וּמֵאֱדוֹם. שֶׁהֵם הָיוּ שֶׁהִשְׁתַּעְבְּדוּ בְּיִשְׂרָאֵל. וְאֵין מַחֲרִיד - לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>הָלְכוּ, בְּעוֹדָם הוֹלְכִים אָמַר רַבִּי יוֹסֵי, וַדַּאי כָּל מַה שֶּׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ, הַכֹּל הָיָה בְּסוֹד הַחָכְמָה, וְהַכֹּל כְּדֵי לְהַרְאוֹת אֶת הַחָכְמָה הָעֶלְיוֹנָה לִבְנֵי הָאָדָם כְּדֵי שֶׁיִּלְמְדוּ מֵהַמַּעֲשֶׂה הַהוּא אֶת סוֹדוֹת הַחָכְמָה, וְהַכֹּל הֵם כָּרָאוּי, וְכָל מַעֲשָׂיו דַּרְכֵי הַתּוֹרָה, מִשּׁוּם שֶׁדַּרְכֵי הַתּוֹרָה הֵם דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֵין דָּבָר קָטָן שֶׁאֵין בּוֹ כַּמָּה דְרָכִים וּשְׁבִילִים וְסוֹדוֹת שֶׁל חָכְמָה עֶלְיוֹנָה.</p>\n<p>בֹּא רְאֵה, שֶׁהֲרֵי רַבִּי יוֹחָנָן בֶּן זַכַּאי הָיָה אוֹמֵר שְׁלֹשׁ מֵאוֹת הֲלָכוֹת פְּסוּקוֹת בְּסוֹד הַחָכְמָה הָעֶלְיוֹנָה בְּפָסוּק וְשֵׁם אִשְׁתּוֹ מְהֵיטַבְאֵל בַּת מַטְרֵד בַּת מֵי זָהָב, וְלֹא גִלָּה אוֹתָם אֶלָּא לְרַבִּי אֱלִיעֶזֶר שֶׁהָיָה עִמּוֹ, כְּדֵי לָדַעַת שֶׁכַּמָּה סוֹדוֹת עֶלְיוֹנִים הֵם בְּכָל מַעֲשֶׂה וּמַעֲשֶׂה, שֶׁהוּא בַּתּוֹרָה, וּבְכָל דָּבָר וְדָבָר, הִיא חָכְמָה וְתוֹרַת אֱמֶת. מִשּׁוּם כָּךְ דִבְרֵי הַתּוֹרָה הֵם דְּבָרִים קְדוֹשִׁים לְהַרְאוֹת מִמֶּנָּה נִפְלָאוֹת, כְּמוֹ שֶׁנֶּאֱמַר גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךְ.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁעִקֵּם הַנָּחָשׁ הַהוּא אֶת אָדָם וְאֶת אִשְׁתּוֹ, שֶׁקָּרַב לָאִשָּׁה וְהִטִּיל בָּהּ זֻהֲמָא, וְהִתְפַּתָּה בּוֹ אָדָם, אָז נִטְמָא הָעוֹלָם, וְהִתְקַלְּלָה בִּשְׁבִילוֹ הָאֲדָמָה, וְגָרַם מָוֶת לְכָל הָעוֹלָם, וְעָמַד הָעוֹלָם לְהִפָּרַע מִמֶּנּוּ, עַד שֶׁבָּא עֵץ הַחַיִּים וְכָפָה (וכפר) עַל אָדָם, וְהִכְנִיעַ אוֹתוֹ הַנָּחָשׁ שֶׁלֹּא יִשְׁלֹט לְעוֹלָמִים עַל זַרְעוֹ שֶׁל יַעֲקֹב.</p>\n<p>שֶׁהֲרֵי בִּזְמַן שֶׁהִקְרִיבוּ יִשְׂרָאל שָׂעִיר, הָיָה נִכְנָע אוֹתוֹ הַנָּחָשׁ וְהִתְהַפֵּךְ לְעֶבֶד, כְּמוֹ שֶׁנֶּאֱמַר, וְעַל כֵּן הִקְרִיב יַעֲקֹב לְאָבִיו שְׁנֵי שְׂעִירִים. אֶחָד לְהַכְנִיעַ אֶת עֵשָׂו, שֶׁהוּא שָׂעִיר, וְאֶחָד בִּשְׁבִיל הַדַּרְגָּה שֶׁהָיְתָה תְלוּיָה בְּעֵשָׂו וְנִדְבַּק בּוֹ וְנִתְבָּאֵר.</p>\n<p>וּמִשּׁוּם כָּךְ עָמַד הָעוֹלָם עַד שֶׁתָּבֹא אִשָּׁה כְּמוֹ חַוָּה, וּבֶן אָדָם כְּמוֹ אָדָם, וְיַעַקְמוּ וְיַחְכִּימוּ אֶת אוֹתוֹ הַנָּחָשׁ הָרָע וְאוֹתוֹ שֶׁרוֹכֵב עָלָיו, וְהַכֹּל נִתְבָּאֵר.</p>\n<p>פָּתַח וְאָמַר, וַיְהִי עֵשָׂו אִישׁ יֹדֵעַ צַיִד אִישׁ שָׂדֶה, וַהֲרֵי נֶאֱמַר וְיַעֲקֹב אִישׁ תָּם יֹשֵׁב אֹהָלִים. אִישׁ תָּם - גֶּבֶר שָׁלֵם, כְּתַרְגּוּמוֹ. יֹשֵׁב אֹהָלִים - לָמָּה הוּא תָּם? מִשּׁוּם שֶׁהוּא יֹשֵׁב אֹהָלִים, שֶׁאוֹחֵז אֶת שְׁנֵי הַצְּדָדִים, אֶת אַבְרָהָם וְאֶת יִצְחָק. וְעַל כֵּן יַעֲקֹב בְּצִדּוֹ שֶׁל יִצְחָק בָּא אֶל עֵשָׂו, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב עִם חָסִיד תִּתְחַסָּד וְעִם עִקֵּשׁ תִּתְפַּתָּל. וּכְשֶׁבָּא עִם בְּרָכוֹת - עִם סִיּוּעַ שֶׁלְּמַעְלָה הוּא בָּא, עִם סִיּוּעַ שֶׁל אַבְרָהָם וְיִצְחָק, וּמִשּׁוּם כָּךְ זֶה הָיָה בְּחָכְמָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, כְּשֶׁיַּעֲקֹב הִתְעוֹרֵר אֶל סמא\"ל, דַּרְגָּתוֹ שֶׁל עֵשָׂו, וְקִבֵּל עָלָיו אֶת יַעֲקֹב, וְיַעֲקֹב נִצַּח אוֹתוֹ בְּכַמָּה צְדָדִים - נִצַּח אֶת הַנָּחָשׁ בְּחָכְמָה וְעַקְמוּמִיּוּת, וְלֹא נֻצַּח, רַק מֵהַשָּׂעִיר. וְאַף עַל גַּב שֶׁהַכֹּל אֶחָד, נִצַּח כְּמוֹ כֵן אֶת סמא\"ל בְּנִצָּחוֹן אַחֵר וְנִצַּח אוֹתוֹ. זֶהוּ שֶׁכָּתוּב וַיֵּאָבֵק אִישׁ עִמּוֹ עַד עֲלוֹת הַשָּׁחַר. וַיַּרְא כִּי לֹא יָכֹל לוֹ.</p>\n<p>בֹּא רְאֵה כַּמָּה הָיְתָה זְכוּתוֹ שֶׁל יַעֲקֹב, שֶׁהוּא בָּא וְרָצָה לְהַעֲבִירוֹ מִן הָעוֹלָם, וְאוֹתוֹ הַלַּיְלָה הָיָה הַלַּיְלָה שֶׁנִּבְרְאָה בּוֹ הַלְּבָנָה, וְיַעֲקֹב נִשְׁאַר לְבַדּוֹ, שֶׁלֹּא הָיָה מִישֶׁהוּ אַחֵר עִמּוֹ. שֶׁשָּׁנִינוּ, אַל יֵצֵא אָדָם יְחִידִי בַּלַּיְלָה, וְכָל שֶׁכֵּן בְּלַיְלָה שֶׁנִּבְרְאוּ בוֹ הַמְּאוֹרוֹת, שֶׁהֲרֵי הַלְּבָנָה חֲסֵרָה, שֶׁכָּתוּב יְהִי מְאֹרֹ\"ת חָסֵר. וְאוֹתוֹ הַלַּיְלָה נִשְׁאַר לְבַדּוֹ, מִשּׁוּם שֶׁכַּאֲשֶׁר הַלְּבָנָה בְּחֶסְרוֹנָהּ, הַנָּחָשׁ הָרָע מִתְגַּבֵּר וְשׁוֹלֵט, וְאָז בָּא סמא\"ל וְקִטְרֵג עָלָיו, וְרָצָה לְהַאֲבִידוֹ מִן הָעוֹלָם.</p>\n<p>וְיַעָקֹב הָיָה חָזָק בְּכָל הַצְּדָדִים, בַּצַּד שֶׁל יִצְחָק וּבַצַּד שֶׁל אַבְרָהָם, שֶׁהֵם הָיוּ חָזְקוֹ שֶׁל יַעֲקֹב. בָּא לְיָמִין, וְרָאָה אֶת אַבְרָהָם חָזָק בְּחֹזֶק הַיּוֹם, בְּצַד הַיָּמִין שֶׁל הַחֶסֶד. בָּא לִשְׂמֹאל, רָאָה אֶת יִצְחָק חָזָק בַּדִּין הַקָּשֶׁה. בָּא לַגּוּף, רָאָה אֶת יַעֲקֹב חָזָק מִשְּׁנֵי הַצְּדָדִים הַלָּלוּ שֶׁמַּקִּיפִים אוֹתוֹ אֶחָד מִכָּאן וְאֶחָד מִכָּאן. אֲזַי, וַיַּרְא כִּי לֹא יָכֹל לוֹ וַיִּגַּע בְּכַף יְרֵכוֹ, שֶׁהוּא מָקוֹם מִחוּץ לַגּוּף, וְהוּא עַמּוּד אֶחָד שֶׁל הַגּוּף. אֲזַי, וַתֵּקַע כַּף יֶרֶךְ יַעֲקֹב בְּהֵאָבְקוֹ עִמּוֹ וְגוֹ'.</p>\n<p>כֵּיוָן שֶׁהִתְעוֹרֵר הַבֹּקֶר וְעָבַר הַלַּיְלָה, הִתְגַּבֵּר יַעֲקֹב, וְנֶחֱלַשׁ כֹּחוֹ שֶׁל סמא\"ל, אָז אָמַר שַׁלְּחֵנִי, שֶׁהִגִּיעַ הַזְּמַן לוֹמַר אֶת שִׁירַת הַבֹּקֶר. וְרָצָה לָלֶכֶת, וְהוֹדָה לוֹ עַל אוֹתָן הַבְּרָכוֹת, וְהוֹסִיף לוֹ בְּרָכָה אַחֶרֶת, שֶׁכָּתוּב וַיְבָרֶךְ אֹתוֹ שָׁם.</p>\n<p>בֹּא רְאֵה כַּמָּה בְּרָכוֹת הִתְבָּרֵךְ יַעֲקֹב: אַחַת שֶׁל אָבִיו בְּאוֹתָהּ הִתְעַקְּמוּת, וְהִרְוִיחַ אֶת כָּל אוֹתָן הַבְּרָכוֹת. וְאַחַת שֶׁל הַשְּׁכִינָה, שֶׁבֵּרַךְ אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁהָיָה בָּא מִלָּבָן, שֶׁכָּתוּב וַיְבָרֶךְ אֱלֹהִים אֶת יַעֲקֹב. וְאַחַת שֶׁבֵּרַךְ אוֹתוֹ הַמַּלְאָךְ הַהוּא, הַמְמֻנֶּה שֶׁל עֵשָׂו. וְאַחַת בְּרָכָה אַחֶרֶת שֶׁבֵּרַךְ אוֹתוֹ אָבִיו כְּשֶׁהָלַךְ לְפַדַּן אֲרָם, שֶׁכָּתוּב וְאֵל שַׁדַּי יְבָרֵךְ אֹתְךְ וְגוֹ'.</p>\n<p>בַּזְּמַן הַהוּא שֶׁרָאָה יַעֲקֹב אֶת עַצְמוֹ בְּכָל הַבְּרָכוֹת הַלָּלוּ, אָמַר, בְּאֵיזוֹ בְּרָכָה מֵהֶם אֶשְׁתַּמֵּשׁ כָּעֵת? אָמַר, כָּעֵת אֶשְׁתַּמֵּשׁ בַּחַלָּשָׁה שֶׁבָּהֶן, וּמִי הִיא? זוֹ הָאַחֲרוֹנָה, שֶׁבֵּרַךְ אוֹתוֹ אָבִיו. וְאַף עַל גַּב שֶׁהִיא חֲזָקָה, אָמַר, אֵינָהּ חֲזָקָה בְּשִׁלְטוֹן הָעוֹלָם הַזֶּה כָּרִאשׁוֹנָה.</p>\n<p>אָמַר יַעֲקֹב, אֶטֹּל עַכְשָׁו אֶת זוֹ וְאֶשְׁתַּמֵּשׁ בָּהּ, וְאַעֲבִיר אֶת כָּל אוֹתָן הָאֲחֵרוֹת לִזְמַן שֶׁאֶצְטָרֵךְ לִי וּלְבָנַי אַחֲרַי, מָתַי? בִּזְמַן שֶׁיִּתְכַּנְּסוּ כָּל הָעַמִּים לְהַאֲבִיד אֶת בָּנַי מִן הָעוֹלָם, שֶׁכָּתוּב כָּל גּוֹיִם סְבָבוּנִי בְּשֵׁם ה' כִּי אֲמִילַם. סַבּוּנִי גַם סְבָבוּנִי וְגוֹ'. סַבּוּנִי כִדְבֹרִים וְגוֹ'. הִנֵּה כָּאן שְׁלֹשָׁה, כְּלַפֵּי שְׁלֹשָׁה שֶׁנִּשְׁאֲרוּ. אַחַת - אוֹתָן הַבְּרָכוֹת הָרִאשׁוֹנוֹת שֶׁל אָבִיו. שְׁתַּיִם - אוֹתָן בְּרָכוֹת שֶׁבֵּרַךְ אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא. שָׁלֹשׁ - אוֹתָן הַבְּרָכוֹת שֶׁבֵּרַךְ אוֹתוֹ הַמַּלְאָךְ הַהוּא.</p>\n<p>אָמַר יַעֲקֹב, לְשָׁם צָרִיךְ אוֹתָן, אֶל הַמְּלָכִים וְכָל הָעַמִּים שֶׁל כָּל הָעוֹלָם, וְאַעֲבִיר אוֹתָן לְשָׁם, וְכָעֵת כְּלַפֵּי עֵשָׂו דַּי לִי בָּזֶה. לְמֶלֶךְ שֶׁהָיוּ לוֹ כַּמָּה לִגְיוֹנוֹת חֲזָקִים, כַּמָּה בַּעֲלֵי לוֹחֲמֵי קְרָבוֹת לְהִלָּחֵם בַּקְּרָבוֹת, שֶׁמְּזֻמָּנִים כְּלַפֵּי מְלָכִים חֲזָקִים לְהִלָּחֵם בָּהֶם קְרָבוֹת. בֵּינְתַיִם שָׁמַע עַל שׁוֹדֵד אֶחָד רוֹצֵחַ. אָמַר, בְּנֵי הַשְּׁעָרִים הַלָּלוּ יֵלְכוּ לְשָׁם. אָמְרוּ לוֹ, מִכָּל הַלִּגְיוֹנוֹת שֶׁלְּךְ אֵינְךְ שׁוֹלֵחַ לְשָׁם אֶלָּא אֵלּוּ? אָמַר, כְּלַפֵּי אוֹתוֹ הַשּׁוֹדֵד דַּי בְּאֵלּוּ, שֶׁהֲרֵי כָּל לִגְיוֹנוֹתַי וּבַעֲלֵי הַקְּרָב אַעֲבִיר אוֹתָם לְאוֹתָם הַמְּלָכִים הַחֲזָקִים. בְּיוֹם הַקְּרָב כְּשֶׁיִּצְטָרְכוּ לִי, יִהְיוּ.</p>\n<p>אַף כָּךְ יַעֲקֹב אָמַר כְּלַפֵּי עֵשָׂו, דַּי לִי כָּעֵת בַּבְּרָכוֹת הַלָּלוּ. אֲבָל לַזְּמַן הַהוּא שֶׁיֻּצְרְכוּ לְבָנַי כְּלַפֵּי כָּל הַמְּלָכִים וְהַשַּׁלִּיטִים שֶׁל כָּל הָעוֹלָם, אַעֲלֶה אוֹתָם.</p>\n<p>כְּשֶׁיַּגִּיעַ אוֹתוֹ הַזְּמַן, יִתְעוֹרְרוּ אוֹתָן הַבְּרָכוֹת מִכָּל הַצְּדָדִים, וְיִתְקַיֵּם הָעוֹלָם עַל קִיּוּמוֹ כָּרָאוּי. וּמֵהַיּוֹם הַהוּא וָהָלְאָה תָּקוּם הַמַּלְכוּת הַזּוֹ עַל כָּל שְׁאָר מַלְכוּת אַחֶרֶת, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (דניאל ב) תְּכַתֵּת וּתְכַלֶּה כָּל אֵלּוּ הַמַּלְכֻיּוֹת וְהִיא תָקוּם לְעוֹלָם. וְהַיְנוּ הָאֶבֶן הַהִיא שֶׁנִּגְזֶרֶת מִן הָהָר וְלֹא בַּיָּדַיִם, כְּמוֹ שֶׁנֶּאֱמַר מִשָּׁם רֹעֶה אֶבֶן יִשְׂרָאֵל. מִי הָאֶבֶן הַזּוֹ? זוֹ כְּנֶסֶת יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר וְהָאֶבֶן הַ את אֲשֶׁר שַׂמְתִּי מַצֵּבָה וְגוֹ'.</p>\n<p>רַבִּי חִיָּיא אָמַר, מִכָּאן, (ישעיה י) שְׁאָר יָשׁוּב שְׁאָר יַעֲקֹב - אֵלּוּ הַבְּרָכוֹת הָאֲחֵרוֹת שֶׁנִּשְׁאֲרוּ. וְכָתוּב (מיכה ה) וְהָיָה שְׁאֵרִית יַעֲקֹב בַּגּוֹיִם בְּקֶרֶב עַמִּים רַבִּים. (אלו ברכות אחרות, כתוב והיה שארית יעקב) בַּגּוֹיִם כֻּלָּם, וְלֹא רַק בְּעֵשָׂו. וְכָתוּב וְהָיָה שְׁאֵרִית וְגוֹ' כְּטַל מֵאֵת ה'.</p>\n<p>פָּתַח רַבִּי יֵיסָא וְאָמַר, (מלאכי א) בֵּן יְכַבֵּד אָב וְעֶבֶד אֲדנָיו. בֵּן זֶה עֵשָׂו, שֶׁלֹּא הָיָה אָדָם בָּעוֹלָם שֶׁיְּכַבֵּד אֶת אָבִיו כְּמוֹ שֶׁעֵשָׂו כִּבֵּד אֶת אָבִיו, וְאוֹתוֹ הַכָּבוֹד שֶׁכִּבֵּד אוֹתוֹ הִשְׁלִיט אוֹתוֹ בָּעוֹלָם הַזֶּה.</p>\n<p>וְעָבֶד אֲדנָיו - זֶה אֱלִיעֶזֶר עֶבֶד אַבְרָהָם, וּבֵאֲרוּהָ. שֶׁהֲרֵי אָדָם שֶׁהָיָה בָּא לְחָרָן בְּכַמָּה עֹשֶׁר וְכַמָּה מַתָּנוֹת וְאוֹצָרוֹת וּגְמַלִּים טְעוּנִים, שֶׁלֹּא אָמַר לִבְתוּאֵל וְלָבָן שֶׁהוּא אוֹהֲבוֹ שֶׁל אַבְרָהָם אוֹ אִישׁ אַחֵר שֶׁבָּא עִם פִּיּוּס שֶׁל אַבְרָהָם, אֶלָּא טֶרֶם יְדַבֵּר אֶת דְּבָרוֹ מַה כָּתוּב? וַיֹּאמַר עֶבֶד אַבְרָהָם אָנֹכִי, וְאַחַר כָּךְ אֲדנִי אֲדנִי, כְּדֵי שֶׁיְּכַבֵּד אֶת אַבְרָהָם, אוֹתוֹ הַכָּבוֹד וְאוֹתוֹ הַחֶסֶד הֶאֱרִיךְ לוֹ לְכַמָּה פְעָמִים.</p>\n<p>כָּךָ עֵשָׂו, הַכָּבוֹד הַהוּא שֶׁכִּבֵּד אֶת אָבִיו הֶאֱרִיךְ לוֹ כָּל הַפְּעָמִים הַלָּלוּ שֶׁיִּשְׁלֹט בָּעוֹלָם הַזֶּה, וְאוֹתָן הַדְּמָעוֹת הוֹרִידוּ אֶת יִשְׂרָאֵל לְשִׁעְבּוּדוֹ עַד שֶׁיָּשׁוּבוּ יִשְׂרָאֵל לַקָּדוֹשׁ-בָּרוּךְ-הוּא בִּבְכִיָּה וּבִדְמָעוֹת, שֶׁכָּתוּב (ירמיה לא) בִּבְכִי יָבֹאוּ וְגוֹ', וְאָז כָּתוּב (עובדיה א) וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפֹּט אֶת הַר עֵשָׂו וְהָיְתָה לַה' הַמְּלוּכָה. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522011298,"<p>וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה. רַבִּי חִיָּיא פָּתַח וְאָמַר, (קהלת א) וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ וְאֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ הוּא שָׁם. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, אֲבָל וְזָרַח הַשֶּׁמֶשׁ - זֶה יַעֲקֹב כְּשֶׁהָיָה בִּבְאֵר שֶׁבַע. וּבָא הַשָּׁמֶשׁ - כְּשֶׁהָלַךְ לְחָרָן, שֶׁכָּתוּב וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ. וְאֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ, שֶׁכָּתוּב וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא.</p>\n<p>וּבֹא וּרְאֵה, אַף עַל גַּב שֶׁהַשֶּׁמֶשׁ מֵאִיר לְכָל הָעוֹלָם, מַסְעוֹתָיו הֵם בִּשְׁנֵי צְדָדִים, כְּמוֹ שֶׁנֶּאֱמַר הוֹלֵךְ אֶל דָּרוֹם וְסוֹבֵב אֶל צָפוֹן, מִשּׁוּם שֶׁזֶּה יָמִין וְזֶה שְׂמֹאל. (ומשום) וְשׁוֹפֵעַ וְיוֹצֵא כָּל יוֹם מִצַּד הַמִּזְרָח, וְהוֹלֵךְ לְצַד הַדָּרוֹם (של מערב), וְאַחַר כָּךְ לְצַד הַצָּפוֹן, וּמִצַּד הַצָּפוֹן לְצַד הַמַּעֲרָב, וְאָז הַשֶּׁמֶשׁ מִתְכַּנֵּס וְיוֹצֵא לְצַד מַעֲרָב. יוֹצֵא מִמִּזְרָח, שֶׁכָּתוּב וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע. וְהוֹלֵךְ לַמַּעֲרָב, שֶׁכָּתוּב וַיֵּלֶךְ חָרָנָה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, יוֹצֵא מִכְּלַל אֶרֶץ יִשְׂרָאֵל, שֶׁכָּתוּב וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע, וְהוֹלֵךְ לִרְשׁוּת אַחֶרֶת, שֶׁכָּתוּב וַיֵּלֶךְ חָרָנָה. (יוצא ממזרח, שכתוב ויצא יעקב מבאר שבע, זו השמטה שנוטלת מהעמק העליון האור שמאיר, והולכת למערב, שכתוב וילך חרנה, המקום שהדין והרגז שם,</p>\n<p>רבי יוסי מבאר את הפסוק הזה בגלות, בראשונה היה יורד אור מן העמק העליון, ויעקב היה נוטל אותו והולך לבאר שבע, הבאר שחפרוה שרים, שהיה מאיר משם, והשלים אותה הבאר בכל השלמות, ובימי הגלות נסע מבאר שבע הזו והלך לחרנה, שכתוב וילך חרנה, כלומר חרון אף, ומה הוא חרון אפו של הקדוש ברוך הוא? הדרגה הרעה, הארץ של רשות אחרת)</p>\n<p>אָמַר רַבִּי חִיָּיא, כְּשֶׁהוֹלֵךְ הַשֶּׁמֶשׁ לְמַעֲרָב, הַמַּעֲרָב הַזֶּה נִקְרָא מְקוֹמוֹ שֶׁל הַשֶּׁמֶשׁ, הַכִּסֵּא שֶׁלּוֹ, מָקוֹם שֶׁשּׁוֹלֵט עָלָיו. זֶהוּ שֶׁכָּתוּב אֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ הוּא שָׁם. שֶׁהוֹלֵךְ אֵלָיו לְהָאִיר עָלָיו, וְנוֹטֵל אֶת כָּל הָאוֹרוֹת וְכוֹנֵס אוֹתָם אֵלָיו.</p>\n<p>וְהַיְנוּ כְּמוֹ שֶׁשָּׁנִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵנִיחַ תְּפִלִּין, (ס\"א ולמדנו, הקדוש ברוך הוא מניח תפלין, שכתוב נשבע ה' בימינו ובזרוע עזו, ושנינו, ימינו זו התורה, שכתוב מימינו אש דת למו, ובזרוע עזו אלו תפלין, וכלם נטל יעקב ומאסף לצד מערב, והלבנה אוספת לבסוף כל אותם האורות והנרות שנוטל יעקב, שהוא נותן לה ומאיר לה, וזה ששנינו הקדוש ברוך הוא מניח תפלין) מִשּׁוּם שֶׁנּוֹטֵל אֶת כָּל הַכְּתָרִים הָעֶלְיוֹנִים, וּמִי הֵם? הַסּוֹד שֶׁל הָאָב הָעֶלְיוֹן וְסוֹד הָאֵם הָעֶלְיוֹנָה, וְהֵם הַתְּפִלִּין שֶׁבָּרֹאשׁ, כְּמוֹ שֶׁשָּׁנִינוּ, כֹּהֵן גָּדוֹל נוֹטֵל בָּרֹאשׁ. וְאַחַר שֶׁנּוֹטֵל הָאָב וְהָאֵם, נוֹטֵל הַיָּמִין וְהַשְּׂמֹאל, וְנִמְצָא (שהקדוש ברוך הוא) שֶׁנּוֹטֵל הַכֹּל.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, תִּפְאֶרֶת יִשְׂרָאֵל נוֹטֵל הַכֹּל, וּכְשֶׁנִּמְשֶׁכֶת כְּנֶסֶת יִשְׂרָאֵל לְמַעְלָה, נוֹטֶלֶת אַף כָּאן הַכֹּל, עוֹלַם הַזָּכָר שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֵן עוֹלַם הַנְּקֵבָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. כְּמוֹ שֶׁיּוֹצְאִים כָּל הָאוֹרוֹת מִן הָעוֹלָם הַזֶּה, כָּךְ גַּם נוֹטֵל הַכֹּל הָעוֹלָם הַזֶּה, שֶׁהֲרֵי זֶה כְּמוֹ זֶה, וּמִשּׁוּם כָּךְ בְּאֵר שֶׁבַע זֶה הַיּוֹבֵל, בְּאֵר (שבע) זוֹ הַשְּׁמִטָּה. (שהרי זה כמו זה) (הכל לקדושברוךהוא) וְהַשֶּׁמֶשׁ (הזה) אֵינוֹ מֵאִיר אֶלָּא מִן הַיּוֹבֵל, (והוא נוטל לתוך האורות ומכניס תוך השמטה) וּמִשּׁוּם כָּךְ וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה, זֶה הַמַּעֲרָב שֶׁהִיא הַשְּׁמִטָּה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע - זֶה הַמַּעֲרָב, שְׁנַת הַשְּׁמִטָּה. וַיֵּלֶךְ חָרָנָה - זוֹ שְׁנַת הָעָרְלָה, מִשּׁוּם שֶׁיָּצָא מֵרְשׁוּת הַקְּדֻשָּׁה לִרְשׁוּת אַחֶרֶת, שֶׁהָיָה בּוֹרֵחַ מֵאָחִיו, כְּמוֹ שֶׁנִּתְבָּאֵר. וְכַאֲשֶׁר הִגִּיעַ לְבֵית אֵל, שֶׁהִיא בִּרְשׁוּת הַקְּדֻשָּׁה, מַה כָּתוּב? וַיִּפְגַּע בַּמָּקוֹם.</p>\n<p>מִי הַמָּקוֹם? רַבִּי חִיָּיא אָמַר, זֶהוּ מְקוֹמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב וְאֶל מְקוֹמוֹ שׁוֹאֵף (זורח הוא שם). וַיָּלֶן שָׁם כִּי בָא הַשָּׁמֶשׁ, כְּמוֹ שֶׁנֶּאֱמַר שׁוֹאֵף זוֹרֵחַ הוּא שָׁם, שֶׁהֲרֵי הוּא בָּא כְּדֵי לְהָאִיר לוֹ.</p>\n<p>וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. לֹא כָתוּב אַבְנֵי הַמָּקוֹם אֶלָּא מֵאַבְנֵי הַמָּקוֹם. אֵלּוּ הֵם אֲבָנִים יְקָרוֹת מַרְגָּלִיּוֹת טוֹבוֹת שֶׁהֵן שְׁתֵּים עֶשְׂרֵה אֲבָנִים עֶלְיוֹנוֹת, כַּכָּתוּב שְׁתֵּים עֶשְׂרֵה אֲבָנִים. וְתַחַת אֵלּוּ שְׁנֵים עָשָׂר אֶלֶף וּרְבָבוֹת אֲבָנִים פְּסוּלוֹת, וְכֻלָּן נִקְרָאוֹת אֲבָנִים, וּמִשּׁוּם כָּךְ מֵאַבְנֵי הַמָּקוֹם וְלֹא אַבְנֵי (המקום), זֶה הַמָּקוֹם שֶׁאָמַר.</p>\n<p>וַיָּשֶׂם מְרַאֲשּתָיו. מְרַאֲשֹׁתָיו שֶׁל מִי? אֶלָּא מְרַאֲשּתָיו שֶׁל הַמָּקוֹם הַהוּא. מַה זֶּה מְרַאֲשּתָיו? אִם תֹּאמַר כְּמִי שֶׁשָּׂם תַּחַת רֹאשׁוֹ - לֹא. אֶלָּא מְרַאֲשּתָיו - לְאַרְבָּעָה (ראשי) צִדְדֵי הָעוֹלָם. שָׁלֹשׁ אֲבָנִים לְצַד צָפוֹן, וְשָׁלֹשׁ לְצַד מַעֲרָב, וְשָׁלֹשׁ לְצַד דָּרוֹם, וְשָׁלֹשׁ לְצַד מִזְרָח. וְהַמָּקוֹם הַהוּא עֲלֵיהֶם לְהִתַּקֵּן בָּהֶם.</p>\n<p>וְאָז וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא. (וישכב, י\"ב מרגליות למטה, וכל אותן הדרגות שהן על המקום הזה הרי הן כ\"ב,) כֵּיוָן שֶׁנִּתְקְנָה הַמִּטָּה, שָׁכַב בָּהּ. מִי שָׁכַב בָּהּ? הַשֶּׁמֶשׁ. וְעַל כֵּן כָּתוּב בְּיַעֲקֹב וַיֵּשֶׁב עַל הַמִּטָּה, שֶׁהֲרֵי לוֹ רְאוּיָה וְלֹא לְאַחֵר. וְעַל כֵּן וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, וּמִשּׁוּם כָּךְ כָּתוּב וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ.</p>"],[9522011299,"<p>וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ. מָה רָאָה שְׁלֹמֹה הַמֶּלֶךְ שֶׁרֵאשִׁית סֵפֶר הַחָכְמָה שֶׁלּוֹ הוּא מִכָּאן? אֶלָּא, אָמַר רַבִּי אֶלְעָזָר, הַמֶּלֶךְ שְׁלֹמֹה הֵקִים אֶת הַסֵּפֶר הַזֶּה עַל שִׁבְעָה הֲבָלִים, וְהָעוֹלָם עוֹמֵד עֲלֵיהֶם. וְהֵם הָעַמּוּדִים וְהַתּוֹמְכִים, קִיּוּם הָעוֹלָם. שֶׁמִּשּׁוּם כָּךְ נִקְרְאוּ הֲבָלִים: (ס\"א בהבל זה שיוצא מפיו של אדם ומתקים בו, והתעוררו החברים אין העולם מתקים אלא בהבל פיהם של תינוקות של בית רבן, דבר אחר, על שלשה דברים העולם עומד, על התורה ועל העבודה ועל גמילות חסדים, התורה זה יעקב, העבודה זה יצחק, גמילות חסדים זה אברהם, שלשה דברים אלו הם עמודים עליונים, שלשה מן שבעה הבלים) מָה הַגּוּף אֵינוֹ מִתְקַיֵּם בְּלִי הֶבֶל - אַף כָּךְ הָעוֹלָם אֵינוֹ מִתְקַיֵּם אֶלָּא עַל הַהֲבָלִים שֶׁאָמַר שְׁלֹמֹה הַמֶּלֶךְ, וְהֵם שִׁבְעָה, שֶׁכָּתוּב הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת הֲבֵל הֲבָלִים הַכֹּל הָבֶל. הֲרֵי שִׁבְעָה.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ שֶׁאוֹתָן מַרְגָּלִיּוֹת טוֹבוֹת שֶׁהָעוֹלָם עוֹמֵד עֲלֵיהֶם, הִנֵּה בְּמָקוֹם אַחֵר כָּתוּב הֲבָלִים רָעִים, וְהֵן חֻרְבַּן הָעוֹלָם, כְּמוֹ (קהלת ו) זֶה הֶבֶל וָחֳלִי רָע הוּא. זֶה הֶבֶל וּרְעוּת רוּחַ. אֶלָּא וַדַּאי (אלו), אַף עַל גַּב שֶׁשִּׁבְעָה הַהֲבָלִים הַלָּלוּ, שֶׁהֵם קְדוֹשִׁים, קִיּוּם הָעוֹלָם, יֵשׁ כְּנֶגֶד אֵלּוּ שִׁבְעָה הֲבָלִים שֶׁכָּל דִּינֵי הָעוֹלָם יוֹצְאִים וּמֵהֶם מִתְפַּשְּׁטִים (הבלים אחרים, והכל קיום של הגלות (של העולם), משום שיש באלו שבעה הבלים שכל דיני העולם יוצאים ומתפשטים ממנו) וְנִקְרָאִים הֲבָלִים אֲחֵרִים לְהַלְקוֹת בְּנֵי אָדָם וּלְתַקְּנָם שֶׁיֵּלְכוּ בְּדֶרֶךְ יְשָׁרָה, וְנִקְרָאִים הֶבֶל שֶׁשּׁוֹרֶה בָהֶם חֳלִי רָע, הֶבֶל שֶׁהוּא רְעוּת רוּחַ. וְהֵם הַקִּיּוּם (של העולם) שֶׁבִּגְלָלָם בְּנֵי אָדָם הוֹלְכִים בְּדֶרֶךְ יָשָׁר וּפוֹחֲדִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל כֵּן רַבִּים הֵם הַהֲבָלִים שֶׁמִּתְפַּשְּׁטִים מִשִּׁבְעָה הַלָּלוּ.</p>\n<p>וְהָרֵאשִׁית שֶׁהוּא אָמַר, סוֹד הַשֶּׁמֶשׁ, שֶׁהוּא הֶבֶל שֶׁמְּקַיֵּם אֶת הָעוֹלָם, וְהוּא הַסּוֹד לְהַכְנִיס אֶת הָאָדָם לְתוֹךְ הָאֱמוּנָה הָעֶלְיוֹנָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם כָּךְ, כָּל מַה שֶּׁתַּחַת הַדַּרְגָּה הַזּוֹ אֵינוֹ סוֹד הָאֱמוּנָה, וְעַל כֵּן כָּתוּב (שם ב) וְאֵין יִתְרוֹן תַּחַת הַשָּׁמֶשׁ, בְּכָל אֲשֶׁר נַעֲשָׂה תַּחַת הַשֶּׁמֶשׁ, שֶׁהֲרֵי מִתַּחַת לְזֶה לֹא צָרִיךְ לְהִדָּבֵק.</p>\n<p>הַשֶּׁמֶשׁ וְהַלְּבָנָה הֵם אֶחָד בְּלִי פֵרוּד. וְאַף עַל גַּב שֶׁהַלְּבָנָה הִיא תַחַת הַשֶּׁמֶשׁ, הַכֹּל הוּא שֶׁמֶשׁ בְּלִי פֵרוּד, וְתַחַת לָזֶה הַכֹּל הוּא רְעוּת רוּחַ וְאָסוּר לְהִדָּבֵק בּוֹ.</p>"],[9522011300,"<p>וַיֵּצא יַעֲקֹב, בַּקֶּשֶׁר שֶׁל הַסָּתוּם, מִתּוֹךְ הַסֵּתֶר הַסָּתוּם יוֹצֵא, זֹהַר הָאַסְפַּקְלַרְיָה הַמְּאִירָה כְּלוּלָה מִשְּׁנֵי גְוָנִים שֶׁמִּתְחַבְּרִים יַחַד. כֵּיוָן שֶׁאֵלּוּ נִכְלְלוּ זֶה עִם זֶה, נִרְאִים בּוֹ כָּל הַגְּוָנִים. הוּא אַרְגָּמָן. כָּל מַרְאֵה הָאוֹרוֹת כְּלוּלִים בּוֹ. רָצוֹא וָשׁוֹב, אוֹתָם הָאוֹרוֹת לֹא מִתְעַכְּבִים לִרְאוֹת, חִבּוּר אֶחָד הֵם מִתְחַבְּרִים בַּזֹּהַר הַהוּא.</p>\n<p>בַּזֹּהַ\"ר הַזֶּה שׁוֹרֶה מִי שֶׁשּׁוֹרֶה, הוּא שֵׁם לְאוֹתוֹ הַנִּסְתָּר שֶׁלֹּא יָדוּעַ כְּלָל, נִקְרָא קוֹל יַעֲקֹב, בָּזֶה נִרְאֵית הָאֱמוּנָה שֶׁל הַכֹּל. אוֹתוֹ נִסְתָּר שֶׁלֹּא יָדוּעַ כְּלָל, בָּזֶה שׁוֹרֶה יהו\"ה. הוּא הַשְּׁלֵמוּת שֶׁל כָּל הַצְּדָדִים, הָעֶלְיוֹן וְהַתַּחְתּוֹן נִמְצָא כָּאן, יַעֲקֹב הַשְּׁלֵמוּת שֶׁל הָאָבוֹת שֶׁאָחוּז מִכָּל הַצְּדָדִים. הַזֹּהַר הַזֶּה עַל בְּחִירַת הַשֵּׁם הַזֶּה נִקְרָא, שֶׁכָּתוּב יִשְׂרָאֵל אֲשֶׁר בְּחַרְתִּיךְ. שְׁנֵי שֵׁמוֹת נִקְרָא - יַעֲקֹב וְיִשְׂרָאֵל. בָּרִאשׁוֹנָה יַעֲקֹב, וְאַחַר כָּךְ יִשְׂרָאֵל.</p>\n<p>הַסֵּתֶר שֶׁל הַסֵּתֶר הַזֶּה, כְּשֶׁהָיָה בַּהַתְחָלָה בַּסּוֹף הַזֶּה שֶׁל הַמַּחֲשָׁבָה, שֶׁהוּא הַפֵּרוּשׁ שֶׁל תּוֹרָה שֶׁבִּכְתָב, וְהִיא הַתּוֹרָה שֶׁבְּעַל פֶּה. וְעַל כֵּן נִקְרָא בְּאֵר, שֶׁנֶּאֱמַר (דברים א) הוֹאִיל מֹשֶׁה בֵּאֵר אֶת הַתּוֹרָה. בֵּאֵ\"ר הוּא לְאוֹתוֹ שֶׁנִּקְרָא שֶׁבַע, שֶׁכָּתוּב וַיִּבְנֵהוּ שֶׁבַע שָׁנִים. וְהַיְנוּ קוֹל גָּדוֹל.</p>\n<p>וְסוֹף הַמַּחֲשָׁבָה הַזֶּה הוּא בְּאֵ\"ר שָׁבַע. וְיַעֲקֹב נִכְנַס בָּרֹאשׁ הַזֶּה לָאֱמוּנָה. כֵּיוָן שֶׁנִּדְבַּק בָּאֱמוּנָה הַזּוֹ, הֻצְרַךְ לוֹ לְהִבָּחֵן בְּאוֹתוֹ הַמָּקוֹם שֶׁנִּבְחֲנוּ אֲבוֹתָיו, שֶׁנִּכְנְסוּ בְשָׁלוֹם וְיָצְאוּ בְשָׁלוֹם.</p>\n<p>אָדָם נִכְנַס וְלֹא נִשְׁמַר, וְהִתְפַּתָּה אַחֲרֶיהָ, וְחָטָא בְּאוֹתָהּ אֵשֶׁת זְנוּנִים, הַנָּחָשׁ הַקַּדְמוֹנִי. נֹחַ נִכְנַס וְלֹא נִשְׁמַר, וְהִתְפַּתָּה אַחֲרֶיהָ וְחָטָא, שֶׁכָּתוּב וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה. אַבְרָהָם נִכְנַס וְיָצָא, שֶׁכָּתוּב וַיֵּרֶד אַבְרָם מִצְרַיְמָה, וְכָתוּב וַיַּעַל אַבְרָם מִמִּצְרָיִם. יִצְחָק נִכְנַס וְיָצָא, שֶׁכָּתוּב וַיֵּלֶךְ יִצְחָק אֶל אֱבִימֶלֶךְ מֶלֶךְ פְּלִשְׁתִּים גְּרָרָה, וִכָתַב וַיַּעַל מִשָּׁם בְּאֵר שָׁבַע.</p>\n<p>יַעָֹקֹב, כֵּיוָן שֶׁנִּכְנַס בָּאֱמוּנָה, הִצְטָרֵךְ לְהַכְנִיס מִנְחָה לַצַּד הַהוּא, מִשּׁוּם שֶׁמִּי שֶׁנִּצַּל מִשָּׁם הוּא אָהוּב וְנִבְחָר שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מַה כָּתוּב? וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע, הַסֵּתֶר שֶׁל סוֹד הָאֱמוּנָה. וַיֵּלֶךְ חָרָנָה - הַצַּד שֶׁל אֵשֶׁת זְנוּנִים, אִשָּׁה מְנָאֶפֶת.</p>"],[9522011301,"<p>סֵתֶר הַסְּתָרִים מִתּוֹךְ הַתֹּקֶף שֶׁל אוֹרוֹ שֶׁל יִצְחָק (יצא) מִתּוֹךְ שִׁמְרֵי הַיַּיִן, יָצְאָה צוּרָה מֻרְכֶּבֶת אַחַת כּוֹלֶלֶת אֶחָד זָכָר וּנְקֵבָה, אֲדֻמָּה כְּמוֹ שׁוֹשַׁנָּה, נִפְרָדִים לְכַמָּה צְדָדִים וּשְׁבִילִים. הַזָּכָר נִקְרָא סמא\"ל, וּנְקֵבָתוֹ כְּלוּלָה בְּתוֹכוֹ תָּמִיד. כְּמוֹ שֶׁהוּא בְּצַד הַקְּדֻשָּׁה, כָּךְ גַּם בַּצַּד הָאַחֵר זָכָר וּנְקֵבָה כְּלוּלִים זֶה עִם זֶה. הַנְּקֵבָה עִם סמא\"ל, נָחָשׁ, נִקְרֵאת אֵשֶׁת זְנוּנִים, קֵץ כָּל בָּשָׂר, קֵץ הַיָּמִים.</p>\n<p>שְׁתֵּי רוּחוֹת רָעוֹת נִדְבָּקוֹת יַחַד. רוּחַ הַזָּכָר דַּקָּה. רוּחַ הַנְּקֵבָה בְּכַמָּה דְרָכִים וּשְׁבִילִים נִפְרֶדֶת, וְנִדְבֶּקֶת בְּאוֹתָהּ הָרוּחַ שֶׁל הַזָּכָר. מְקַשֶּׁטֶת אֶת עַצְמָהּ בְּכַמָּה תַכְשִׁיטִים, כְּמוֹ זוֹנָה, מְרֻחֶקֶת, עוֹמֶדֶת בְּרֹאשׁ הַדְּרָכִים וְהַשְּׁבִילִים לְפַתּוֹת בְּנֵי אָדָם.</p>\n<p>הַשּׁוֹטֶה שֶׁקָּרֵב אֵלֶיהָ, מַחֲזִיקָה בּוֹ וּמְנַשֶּׁקֶת אוֹתוֹ, מוֹזֶגֶת לוֹ יַיִן הַמְשֻׁמָּר שֶׁל מְרוֹרַת פְּתָנִים. כֵּיוָן שֶׁשּׁוֹתֶה, סוֹטֶה אַחֲרֶיהָ. אַחַר שֶׁרוֹאָה אוֹתוֹ סוֹטֶה אַחֲרֶיהָ מִדֶּרֶךְ הָאֱמֶת, מַפְשִׁיטָה אֶת עַצְמָהּ מִכָּל אוֹתָם הַתִּקּוּנִים שֶׁהָיְתָה מְתֻקֶּנֶת לַשּׁוֹטֶה הַזֶּה.</p>\n<p>הַתִּקּוּנִים שֶׁלָּהּ לְפַתּוֹת בְּנֵי אָדָם: שַׂעֲרוֹתֶיהָ מְתֻקָּנִים אֲדֻמִּים כַּשּׁוֹשַׁנָּה, פָּנֶיהָ לְבָנִים וַאֲדֻמִּים, בְּאָזְנֶיהָ תְּלוּיִים שִׁשָּׁה תִקּוּנִים שֶׁל אֲטוֹן מִצְרַים, תְּלוּיִים עַל צַוָּארָהּ כָּל חֵילוֹת אֶרֶץ קֶדֶם, פִּיהָ מְתֻקָּן כִּפְתִיחָה דַקָּה יָפָה בְּתִקּוּנֶיהָ, לָשׁוֹן חַדָּה כַּחֶרֶב, דְּבָרֶיהָ חֲלָקִים כַּשֶּׁמֶן, שִׂפְתוֹתֶיהָ יָפוֹת אֲדֻמּוֹת כַּשּׁוֹשַׁנָּה מְתוּקוֹת בְּכָל הַמְּתִיקוּת שֶׁל הָעוֹלָם, לְבוּשָׁהּ אַרְגָּמָן, מְתֻקֶּנֶת בְּאַרְבָּעִים תִּקּוּנִים חָסֵר אֶחָד.</p>\n<p>שׁוֹטֶה (זה) שֶׁסּוֹטֶה אַחֲרֶיהָ וְשׁוֹתֶה מִכּוֹס הַיַּיִן וְעוֹשֶׂה עִמָּהּ נִאוּפִים וְסוֹטֶה אַחֲרֶיהָ, מָה הִיא עוֹשָׂה? מַשְׁאִירָה אוֹתוֹ יָשֵׁן בַּמִּטָּה, וְעוֹלָה לְמַעְלָה וּמַלְשִׁינָה עָלָיו, וְנוֹטֶלֶת רְשׁוּת וְיוֹרֶדֶת. מִתְעוֹרֵר הַשּׁוֹטֶה הַהוּא, וְחוֹשֵׁב לִצְחוֹק עִמָּהּ כְּמוֹ בָּרִאשׁוֹנָה, וְהוּא מְסִירָה אֶת תִּקּוּנֶיהָ מִמֶּנָּה, וְחוֹזֶרֶת לְגִבּוֹר חָזָק שֶׁעוֹמֵד כְּנֶגְדּוֹ, לָבוּשׁ בִּלְבוּשׁ שֶׁל אֵשׁ לוֹהֶטֶת, בְּפַחַד חָזָק מְרַתֵּת עַצְמָהּ וְנַפְשָׁהּ עֲרֻמָּה, מְלֵאָה בְּעֵינַיִם מַפְחִידוֹת, חֶרֶב שְׁנוּנָה בְּיָדוֹ (בידה). טִפּוֹת מְרִירוֹת תְּלוּיוֹת מֵהַחֶרֶב הַהִיא. הוֹרֵג אֶת הַשּׁוֹטֶה הַהוּא, וְזוֹרֵק אוֹתוֹ לְתוֹךְ גֵּיהִנֹּם.</p>\n<p>יַעָקֹב יָרַד אֵלֶיהָ וְהָלַךְ לִמְקוֹמָהּ, שֶׁנֶּאֱמַר וַיֵּלֶךְ חָרָנָה, וְרָאָה אֶת כָּל תִּקּוּן הַבַּיִת, וְנִצַּל מִמֶּנָּה. הַזָּכָר שֶׁלָּהּ סמא\"ל, הֵרַע לְפָנָיו, וְיָרַד לַעֲרֹךְ בּוֹ קְרָב וְלֹא יָכֹל לוֹ, שֶׁכָּתוּב וַיֵּאָבֵק אִישׁ עִמּוֹ וְגוֹ'. אֲזַי נִצַּל מִן הַכֹּל, וְהִשְׁתַּלֵּם בִּשְׁלֵמוּת, וְהִתְעַלָּה בְּדַרְגָּה שְׁלֵמָה וְנִקְרָא יִשְׂרָאֵל. אָז עָלָה לְדַרְגָּה עֶלְיוֹנָה וְנִשְׁלַם בַּכֹּל וְנִהְיָה הָעַמּוּד הָאֶמְצָעִי, וְעָלָיו כָּתוּב וְהַבְּרִיחַ הַתִּיכֹן וְגוֹ'.</p>\n<p>מַהוּ וַיִּגַּע בְּכַף יְרֵכוֹ? לוֹ לֹא יָכֹל, אֲבָל נָגַע בְּכַף יְרֵכוֹ שֶׁהֵם נָדָב וַאֲבִיהוּא שֶׁיָּצְאוּ מִירֵכוֹ שֶׁל אַהֲרֹן, (בסבת אש זרה, והרי התעוררו לשמרך מאשה זרה וגו', ותפסה אותם ברשותה, בא ראה מה כתוב ביעקב השלם) (ועל יעקב כתוב) וְהַבְּרִיחַ הַתִּיכֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִחַ מִן הַקָּצֶה אֶל הַקָּצֶה.</p>"],[9522011302,"<p>בְּנֵי הָעוֹלָם, אֲהוּבֵי עֶלְיוֹן, בְּחִירֵי הַמֶּמְשָׁלָה, קִרְבוּ שִׁמְעוּ. מִי חָכָם בָּכֶם, בַּעֲלֵי הָעֵינַיִם בְּהַשְׂכֵּל, יָבֹא וְיֵדַע. בְּשָׁעָה שֶׁהָרֹאשׁ הַלָּבָן נָטַל שָׁלֹשׁ אוֹתִיּוֹת וְחָקַק אוֹתָם בַּחֲקִיקַת הַחֲקִיקוֹת, אַחַת א', אַחַת י', וְאַחַת ן', וְנֶחְקַק אי\"ן - הָא' הָרֹאשׁ הָעֶלְיוֹן שֶׁל הַכֹּל טָמוּן שֶׁל כָּל הַטְּמוּנִים, י' הוּא עֲלִיַּת הָרָצוֹן, נִתְקַן מִן הָרֹאשׁ לְמַעְלָה, וְיָרַד לְמַטָּה. יָצָא וְהוֹצִיא שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים, עַד שֶׁנֶּחְקְקוּ בַּאֲבָנִים יְקָרוֹת שֶׁלּוֹהֲטוֹת, וְנִקְשְׁרוּ עִם הָאוֹת נוּ\"ן, שֶׁהִיא זָכָר וּנְקֵבָה, שְׁנֵי אוֹהֲבִים. קֶשֶׁר חָזָק, בָּהֶם נִתְקְנוּ, וְהַשֵּׁם הַקָּדוֹשׁ נִקְשָׁר בָּהֶם, מֵהֶם נִמְצָא הַמָּזוֹן לַכֹּל (בהם), נִתְקְנוּ הָעוֹלָמוֹת.</p>\n<p>וְעַל כֵּן נֶחְקְקָה ן' פְּשׁוּטָה, הַכְּלָל שֶׁל שְׁתַּיִם: נ' כְּפוּפָה נְקֵבָה אַחַת, י' שֶׁהִיא הָרָצוֹן שֶׁמּוֹצִיא שְׁבִילִים הִכָּה בֵּין הָאוֹתִיּוֹת וְעָשָׂה אֶת הָרָקִיעַ שֶׁל יַעֲקֹב בֵּין שְׁתֵּי רוּחוֹת, וְהִטִּיל בֵּין הָאֵיבָרִים דִּבּוּרִים. עַד שֶׁיָּרַד לַנ' הַזּוֹ, שֶׁהִיא כְּפוּפָה, וְחִבְּרוּ אוֹתָהּ יַחַד, צָפוֹן וְדָרוֹם, אַחַר כָּךְ נִקְשְׁרוּ יַחַד. הַנ' הַכְּפוּפָה הַזּוֹ נִקְרֵאת בְּאֵר שֶׁבַע וּמִתְמַלֵּאת מִיַּעֲקֹב לְהַשְׁקוֹת אֶת כָּל עֶדְרֵי הַצֹּאן, וְעַל כֵּן וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה. עוֹד, מִבְּאֵר שֶׁבַע לְמַעְלָה, שֶׁהֲרֵי מִמֶּנָּה יוֹצֵא אַחַר כָּךְ לְהַשְׁקוֹת אֶת חָרָנָה, שֶׁהִיא הַבְּאֵר שֶׁלְּמַטָּה, חֲרוֹן אַף ה', חֶרֶב ה', דִּין, בֵּית הַדִּין, אֱלֹהִים. וְעַל כֵּן אֱלֹהִים בָּאוּ גוֹיִם בְּנַחֲלָתֶךְ. עד כאן התוספתא.</p>\n<p>רַבִּי יִצְחָק הָיָה יוֹשֵׁב יוֹם אֶחָד לִפְנֵי מְעָרַת אֲפִיקוּתָא. עָבַר אִישׁ אֶחָד וּשְׁנֵי בָנִים עִמּוֹ, וְהָיָה אֶחָד לְאֶחָד אוֹמֵר, חֹזֶק הַשֶּׁמֶשׁ הַזֶּה הוּא מִצַּד הַדָּרוֹם, וְאֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא עַל הָרוּחַ, מִשּׁוּם שֶׁהָרוּחַ הִיא קִיּוּם הַשְּׁלֵמוּת שֶׁל כָּל הַצְּדָדִים, וְאִלְמָלֵא שֶׁהוּא עוֹמֵד בִּשְׁלֵמוּת, אֵין הָעוֹלָם יָכוֹל לְהִתְקַיֵּם.</p>\n<p>אָמַר לוֹ אָחִיו הַקָּטָן, אִלְמָלֵא יַעֲקֹב, לֹא הִתְקַיֵּם הָעוֹלָם. בֹּא רְאֵה, בְּשָׁעָה שֶׁיִּחֲדוּ בָנָיו אֶת הַיִּחוּד שֶׁלְּמַעְלָה וְאָמְרוּ (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, זוֹהִי הַשְּׁלֵמוּת הָעֶלְיוֹנָה לְהִתְיַחֵד בְּיִחוּד אֶחָד, אֲזַי הִתְחַבֵּר יַעֲקֹב אֲבִיהֶם, וְנָטַל אֶת בֵּיתוֹ, וְיָשַׁב בּוֹ בְּחִבּוּר אֶחָד עִם הָאָבוֹת, לְהִתְחַבֵּר זָכָר וּנְקֵבָה יַחַד.</p>"],[9522011303,"<p>אָמַר רַבִּי יִצְחָק, אֶשְׁתַּתֵּף עִמָּהֶם וְאֶשְׁמַע מָה הֵם אוֹמְרִים. פָּתַח אוֹתוֹ הָאִישׁ וְאָמַר, קוּמָה ה' לִמְנוּחָתֶךְ אַתָּה וַאֲרוֹן עֻזֶּךְ. קוּמָה ה' לִמְנוּחָתֶךְ - כְּמִי שֶׁאוֹמֵר יָקוּם הַמֶּלֶךְ לְבֵית מְנוּחַת מִשְׁכָּנוֹ.</p>\n<p>שְׁנַיִם הֵם הָיוּ שֶׁאָמְרוּ קוּמָה ה' - מֹשֶׁה וְדָוִד. מֹשֶׁה אָמַר, (במדבר י) קוּמָה ה' וְיָפֻצוּ אֹיְבֶיךְ. וְדָוִד אָמַר (תהלים קלב) קוּמָה ה' לִמְנוּחָתֶךְ. מָה הַהֶבְדֵּל בֵּינֵיהֶם? אֶלָּא מֹשֶׁה, כְּמוֹ מִי שֶׁמְּצַוֶּה אֶת בֵּיתוֹ הוּא אָמַר. מֹשֶׁה צִוָּה אוֹתָהּ לְהִלָּחֵם קְרָב כְּנֶגֶד שׂוֹנְאָיו, וְדָוִד הִזְמִין אוֹתָהּ לִמְנוּחָה. כְּמוֹ שֶׁמַּזְמִין (לו) אֶת רַבּוֹ, מַזְמִין אֶת הַמֶּלֶךְ וְהַגְּבִירָה עִמּוֹ. זֶהוּ שֶׁכָּתוּב קוּמָה ה' לִמְנוּחָתֶךְ אַתָּה וַאֲרוֹן עֻזֶּךְ, כְּדֵי שֶׁלֹּא לְהַפְרִידָם.</p>\n<p>כֹּהֲנֶיךָ יִלְבְּשׁוּ צֶדֶק וַחֲסִידֶיךְ יְרַנֵּנוּ. מִכָּאן לָמַדְנוּ, שֶׁמִּי שֶׁמַּזְמִין אֶת הַמֶּלֶךְ, יְשַׁנֶּה אֶת מַעֲשָׂיו כְּדֵי לָתֵת שִׂמְחָה לַמֶּלֶךְ. אִם דֶּרֶךְ הַמֶּלֶךְ שֶׁמְּשַׂמְּחִים אוֹתוֹ בַּדְּחָנִים פְּשׁוּטִים - יְסַדֵּר לְפָנָיו בַּדְּחָנִים נִכְבָּדִים וְשָׂרִים גְּדוֹלִים, וְאִם לֹא - זוֹ לֹא (משום) שִׂמְחַת הַמֶּלֶךְ.</p>\n<p>בֹּא רְאֵה, דָּוִד הִזְמִין אֶת הַמֶּלֶךְ וְהַגְּבִירָה לִמְנוּחָה, מֶה עָשָׂה? שִׁנָּה אֶת בַּדְּחָנֵי הַמֶּלֶךְ בִּשְׁבִיל שָׂרִים וְנִכְבָּדִים, וּמִי הֵם? שֶׁכָּתוּב כֹּהֲנֶיךְ יִלְבְּשׁוּ צֶדֶק וַחֲסִידֶיךְ יְרַנֵּנוּ. וַחֲסִידֶיךְ יְרַנֵּנוּ? הָיָה צָרִיךְ לִהְיוֹת לְוִיֶּיךְ יְרַנֵּנוּ! שֶׁהֲרֵי הַלְוִיִּים הֵם בַּדְּחָנֵי הַמֶּלֶךְ, וְכָעֵת דָּוִד שֶׁהִזְמִין אוֹתוֹ לִמְנוּחָה, עָשָׂה אֶת הַכֹּהֲנִים וְהַחֲסִידִים שֶׁיִּהְיוּ הֵם בַּדְּחָנֵי הַמֶּלֶךְ.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, דָּוִד, אֵינִי רוֹצֶה לְהַטְרִיחַ עָלֶיךְ. (אלו) (אמר לו הקדוש ברוך הוא, דוד, לא כך) אָמַר לוֹ דָּוִד, רִבּוֹנִי, (לא כך, אלא) כְּשֶׁאַתָּה בְּהֵיכָלְךְ, אַתָּה עוֹשֶׂה רְצוֹנְךְ. כָּעֵת שֶׁהִזְמַנְתִּי אוֹתְךְ, הַדָּבָר עוֹמֵד בִּרְצוֹנִי לְקָרֵב אֶת אֵלּוּ, שֶׁהֵם יוֹתֵר חֲשׁוּבִים, אַף עַל גַּב שֶׁאֵין דַּרְכָּם בָּזֶה.</p>\n<p>מִכָּאן לָמַדְנוּ, שֶׁמִּי שֶׁהוּא בְּבֵיתוֹ, יְסַדֵּר דַּרְכּוֹ וּמַעֲשֵׂהוּ כִּרְצוֹנוֹ. אִם מַזְמִינִים אוֹתוֹ, יַעֲשֶׂה אֶת רְצוֹנוֹ שֶׁל מְאָרְחוֹ כְּמוֹ שֶׁמְּסַדֵּר עָלָיו, שֶׁהֲרֵי דָּוִד הֶחְלִיף לְוִיִּים וְסִדֵּר כֹּהֲנִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֵקִים אֶת הַדָּבָר כִּרְצוֹנוֹ.</p>\n<p>אָמַר דָּוִד, בַּעֲבוּר דָּוִד עַבְדֶּךְ אַל תָּשֵׁב פְּנֵי מְשִׁיחֶךְ. הַסִּדּוּר שֶׁסִּדַּרְתִּי לֹא יָשׁוּב אָחוֹר. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, דָּוִד, חַיֶּיךְ, אֲפִלּוּ בַּכֵּלִים שֶׁלִּי לֹא אֶשְׁתַּמֵּשׁ, אֶלָּא בַּכֵּלִים שֶׁלְּךְ. וְלֹא זָז הַקָּדוֹשׁ בָּרוּךְ הוּא מִשָּׁם עַד שֶׁנָּתַן לוֹ אוֹצָרוֹת וּמַתָּנוֹת, שֶׁכָּתוּב נִשְׁבַּע ה' לְדָוִד אֱמֶת לֹא יָשׁוּב מִמֶּנָּה מִפְּרִי בִטְנְךְ אָשִׁית לְכִסֵּא לָךְ. בָּא רַבִּי יִצְחָק וְנָשַׁק לוֹ. אָמַר, אִם לֹא בָאתִי לַדֶּרֶךְ הַזּוֹ אֶלָּא לִשְׁמֹעַ אֶת זֶה - דַּי לִי.</p>"],[9522011304,"<p>פָּתַח בֵּן אֶחָד שֶׁלּוֹ וְאָמַר, וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה, הַיְנוּ שֶׁכָּתוּב (בראשיתב) עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְדָבַק בְּאִשְׁתּוֹ. דָּבָר אַחֵר וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה - רֶמֶז כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִבֵּית הַמִּקְדָּשׁ וְהֻגְלוּ בֵּין הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (איכה א) וַיֵּצֵא מִן בַּת צִיּוֹן כָּל הֲדָרָהּ, וְכָתוּב גָּלְתָה יְהוּדָה מֵעֹנִי וְגוֹ'.</p>\n<p>פָּתַח הָאַחֵר הַקָּטָן וְאָמַר, וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ וְגוֹ'. מַה זֶּה וַיִּפְגַּע בַּמָּקוֹם? לְמֶלֶךְ שֶׁהוֹלֵךְ לְבֵית הַגְּבִירָה, צָרִיךְ לִפְגֹּשׁ אוֹתָהּ וּלְבַשֵּׂם אוֹתָהּ בִּדְבָרִים כְּדֵי שֶׁלֹּא תִמָּצֵא אֶצְלוֹ כְּהֶפְקֵר, וְלֹא עוֹד, אֶלָּא שֶׁאֲפִלּוּ יֵשׁ לוֹ מִטָּה שֶׁל זָהָב וּכְסָתוֹת מְרֻקָּמוֹת מַעֲשֵׂה רוֹקֵם לִישֹׁן בָּהֶם, וְהִיא מְתַקֶּנֶת לוֹ מִטָּתוֹ מֵאֲבָנִים בָּאָרֶץ, וּבְחֶדֶר שֶׁל תֶּבֶן. יַעֲזֹב אֶת שֶׁלּוֹ וְיָלוּן בָּהֶם, לָתֵת לָהּ נַחַת, וּכְדֵי שֶׁיִּהְיֶה הָרָצוֹן שֶׁלָּהֶם יַחַד בְּלִי אֹנֶס. כְּמוֹ שֶׁלָּמַדְנוּ כָּאן, שֶׁכֵּיוָן שֶׁהָלַךְ אֵלֶיהָ, מַה כָּתוּב? (וילן שם כי בא השמש, להראות שאסור לו לאדם לשמש מטתו ביום) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מְרַאֲשּתָיו וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, כְּדֵי לָתֵת לָהּ נַחַת שֶׁאֲפִלּוּ אַבְנֵי הַבַּיִת אֲהוּבִים לְפָנָיו לָלוּן בָּהֶם (שכתוב וישכב במקום ההוא).</p>\n<p>בָּכָה רַבִּי יִצְחָק, (וחיך) וְשָׂמַח. אָמַר, אֵלּוּ הַמַּרְגָּלִיּוֹת תַּחַת יְדֵיכֶם, וְלֹא אֵלֵךְ אַחֲרֵיכֶם? אָמְרוּ לוֹ, אַתָּה תֵּלֵךְ לְדַרְכְּךְ, וְאָנוּ נִכָּנֵס לָעִיר לַהִלּוּלָא שֶׁל בְּנִי זֶה. אָמַר רַבִּי יִצְחָק, עַכְשָׁו יֵשׁ לִי לָלֶכֶת לְדַרְכִּי. הָלַךְ לוֹ וְסִדֵּר אֶת הַדְּבָרִים לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי יָפֶה אָמְרוּ, וְהַכֹּל נֶאֱמַר בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. אָמַר, הַדְּבָרִים הַלָּלוּ הֵם מִבְּנֵי בָנָיו שֶׁל רַבִּי צָדוֹק הַחַלָּשׁ הֵם. מָה הַטַּעַם נִקְרָא חַלָּשׁ? מִשּׁוּם שֶׁאַרְבָּעִים שָׁנָה הִתְעַנָּה עַל יְרוּשָׁלַיִם שֶׁלֹּא תֵחָרֵב בְּיָמָיו, וְהָיָה מְפָרֵשׁ עַל כָּל דָּבָר וְדָבָר שֶׁל הַתּוֹרָה סוֹדוֹת עֶלְיוֹנִים וְנוֹתֵן בָּהֶם דֶּרֶךְ לִבְנֵי הָעוֹלָם לְהִתְנַהֵג בָּהֶם.</p>\n<p>אָמַר רַבִּי יִצְחָק, לֹא הָיוּ (אלא) יָמִים מוּעָטִים עַד שֶׁפָּגַשְׁתִּי אוֹתוֹ הָאִישׁ, וּבְנוֹ הַקָּטָן עִמּוֹ. אָמַרְתִּי לוֹ, אֵיפֹה בִּנְךְ הָאַחֵר? אָמַר לִי, עָשִׂיתִי לוֹ הִלּוּלָא, וְנִשְׁאַר עִם אִשְׁתּוֹ. כֵּיוָן שֶׁהִכִּיר אוֹתִי, אָמַר לִי, חַיֶּיךְ שֶׁלֹּא הִזְמַנְתִּי אוֹתְךְ לַחֲתֻנַּת בְּנִי מִשּׁוּם שְׁלֹשָׁה דְבָרִים: אֶחָד - שֶׁלֹּא יָדַעְתִּי בְךְ וְלֹא הִכַּרְתִּי אוֹתְךְ, שֶׁכָּךְ מַזְמִינִים אֶת הָאָדָם - כְּפִי כְבוֹדוֹ, וְאוּלַי אַתָּה אִישׁ גָּדוֹל וְיִפָּגֵם כְּבוֹדְךְ. וְאֶחָד - אוּלַי אַתָּה הוֹלֵךְ לְדַרְכְּךְ בְּחִפָּזוֹן וְלֹא אַטְרִיחַ עָלֶיךְ. וְאֶחָד - שֶׁלֹּא תִתְבַּיֵּשׁ לִפְנֵי אַנְשֵׁי הַחֲבוּרָה, שֶׁדַּרְכֵּנוּ - שֶׁכָּל אוֹתָם שֶׁאוֹכְלִים עַל שֻׁלְחַן חָתָן וְכַלָּה, כֻּלָּם נוֹתְנִים לָהֶם אוֹצָרוֹת וּמַתָּנוֹת. אָמַרְתִּי לוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא יָדוּן אוֹתְךְ לְטוֹב. אָמַרְתִּי לוֹ, מַה שִּׁמְךְ? אָמַר לִי, צָדוֹק הַקָּטָן. בְּאוֹתָהּ שָׁעָה לָמַדְתִּי מִמֶּנּוּ שְׁלֹשָׁה עָשָׂר (תריסר) סוֹדוֹת עֶלְיוֹנִים בַּתּוֹרָה, וּמִבְּנוֹ שְׁלֹשָׁה, אֶחָד בִּנְבוּאָה, וְאֶחָד (ושנים) בַּחֲלוֹם.</p>"],[9522011305,"<p>וְאָמַר, מַה בֵּין נְבוּאָה לַחֲלוֹם? נְבוּאָה בָּעוֹלָם הִיא שֶׁל זָכָר, וְהַחֲלוֹם בְּעוֹלַם הַנְּקֵבָה, וּמִזֶּה לָזֶה בְּשֵׁשׁ דְּרָגוֹת יוֹרֵד. הַנְּבוּאָה בְּיָמִין וּבִשְׂמֹאל, וְהַחֲלוֹם בִּשְׂמֹאל. וְהַחֲלוֹם נִפְרָד לְכַמָּה דְרָגוֹת לְמַטָּה, מִשּׁוּם כָּךְ הַחֲלוֹם הוּא בְּכָל הָעוֹלָם, אֲבָל כְּפִי דַרְגָּתוֹ. כָּךְ נִרְאֶה, כְּפִי הָאָדָם כָּךְ דַּרְגָּתוֹ, הַנְּבוּאָה אֵינָהּ מִתְפַּשֶּׁטֶת אֶלָּא בִּמְקוֹמָהּ.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וַיַּחֲלֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ. פָּתַח וְאָמַר, (יחזקאל א) הָיֹה הָיָה דְבַר ה' אֶל יְחֶזְקֵאל בֶּן בּוּזִי הַכֹּהֵן בְּאֶרֶץ כַּשְׂדִּים עַל נְהַר כְּבָר וַתְּהִי עָלָיו שָׁם יַד ה'. הָיֹה הָיָה - נְבוּאָה לְשָׁעָה הָיְתָה, שֶׁהִצְטָרְכָה עַל הַגָּלוּת מִשּׁוּם שֶׁהַשְּׁכִינָה יָרְדָה עִם יִשְׂרָאֵל לַגָּלוּת, וְרָאָה יְחֶזְקֵאל מַה שֶּׁרָאָה לְפִי שָׁעָה. וְאַף עַל גַּב שֶׁאוֹתוֹ הַמָּקוֹם לֹא רָאוּי לָזֶה, מִשּׁוּם כָּךְ הָיֹה הָיָה. מַה זֶּה הָיֹה הָיָה? אֶלָּא הָיֹה לְמַעְלָה - הָיָה לְמַטָּה, שֶׁכָּתוּב סֻלָּם מֻצָּב אַרְצָה וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה. נוֹטֵל (אותו) לְמַעְלָה וְנוֹטֵל (אותו) לְמַטָּה. הָיֹה הָיָה - אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה.</p>\n<p>בֹּא רְאֵה, הַסֻּלָּם הַזֶּה מַחֲזִיק בִּשְׁנֵי עוֹלָמוֹת - בְּמַעְלָה וּמַטָּה. בְּאֶרֶץ כַּשְׂדִּים עַל נְהַר כְּבָר. בְּאֶרֶץ כַּשְׂדִּים - בְּמָקוֹם שֶׁהַגָּלוּת שׁוֹרָה בּוֹ, וְעִם כָּל זֶה, עַל נְהַר כְּבָר. מַה זֶּה נְהַר כְּבָר? אֶלָּא שֶׁהָיָה כְּבָר מִקֹּדֶם לָכֵן, שֶׁהַשְּׁכִינָה שׁוֹרָה עָלָיו, שֶׁכָּתוּב וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ'. וְזֶה הוּא נָהָר אֶחָד מֵאוֹתָם אַרְבָּעָה הַנְּהָרוֹת. וּמִשּׁוּם שֶׁשָּׁרָה עָלָיו מִקֹּדֶם לָכֵן וְהָיָה עָלָיו כְּבָר - שׁוֹרֶה בּוֹ עַכְשָׁו, וְהִתְגַּלָּה לִיחֶזְקֵאל.</p>\n<p>בֹּא רְאֵה, וַיַּחֲלֹם, וְכִי יַעֲקֹב הַקָּדוֹשׁ, שֶׁהוּא הַשָּׁלֵם שֶׁל הָאָבוֹת, הִתְגַּלָּה עָלָיו בַּחֲלוֹם, וּבַמָּקוֹם הַקָּדוֹשׁ הַזֶּה לֹא רָאָה (לו) אֶלָּא בַּחֲלוֹם? אֶלָּא יַעֲקֹב בַּזְּמַן הַהוּא לֹא הָיָה נָשׂוּי, וְיִצְחָק הָיָה קַיָּם. וְאִם תֹּאמַר שֶׁהִנֵּה אַחַר כָּךְ, כְּשֶׁנִּשָּׂא, כָּתוּב וָאֵרֶא בַּחֲלוֹם? שָׁם הַמָּקוֹם גָּרַם, וְיִצְחָק הָיָה קַיָּם, וְעַל כֵּן כָּתוּב בּוֹ חֲלוֹם.</p>\n<p>וְאַחַר שֶׁבָּא לָאָרֶץ הַקְּדוֹשָׁה עִם הַשְּׁבָטִים, וְנִשְׁלְמָה (בהם) לָהֶם עֲקֶרֶת הַבַּיִת וְאֵם הַבָּנִים שְׂמֵחָה, כָּתוּב וַיֵּרָא אֱלֹהִים אֶל יַעֲקֹב וְגוֹ', וְכָתוּב (בראשית מו) וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאֹת הַלַּיְלָה. כָּאן לֹא כָתוּב בּוֹ חֲלוֹם, שֶׁהֲרֵי הָיָה מִדַּרְגָּה אַחֶרֶת עֶלְיוֹנָה.</p>\n<p>בֹּא רְאֵה, הַחֲלוֹם הוּא עַל יְדֵי גַבְרִיאֵל, שֶׁהוּא לְמַטָּה, בַּדַּרְגָּה הַשִּׁשִּׁית מִנְּבוּאָה. מַרְאֶה - עַל יְדֵי הַדַּרְגָּה הַהִיא שֶׁל הַחַיָּה הַהִיא שֶׁשּׁוֹלֶטֶת בַּלַּיְלָה. וְאִם תֹּאמַר, הִנֵּה כָּתוּב (דניאל ח) גַּבְרִיאֵל הָבֵן לְהַלָּז אֶת הַמַּרְאֶה - כָּךְ זֶה וַדַּאי, שֶׁמַּרְאֶה דְּבָרָיו יוֹתֵר סְתוּמִים, וּבַחֲלוֹם מְפֹרָשׁ יוֹתֵר, וּמְפָרֵשׁ אֶת הַסְּתוּמִים שֶׁל הַמַּרְאֶה. וְעַל כֵּן נִפְקָד גַּבְרִיאֵל, שֶׁיְּפָרֵשׁ אֶת דִּבְרֵי הַמַּרְאֶה, שֶׁהוּא יוֹתֵר סָתוּם.</p>\n<p>וְעַל כֵּן כָּתוּב בְּמַרְאֶה - וַיֵּרָא, וָאֵרָא. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא מַרְאֶה, כְּמוֹ הַמַּרְאֶה הַזֶּה שֶׁנִּרְאִים בְּתוֹכוֹ כָּל הַדְּמֻיּוֹת, וּמִשּׁוּם כָּךְ וָאֵרָא, רָאִיתִי דְמוּתוֹ. בְּאֵל שַׁדַּי, שֶׁהוּא הַמַּרְאֶה, שֶׁנִּרְאֵית בְּתוֹכוֹ דְּמוּת אַחֶרֶת, וְכָל הַדְּמֻיּוֹת הָעֶלְיוֹנוֹת נִרְאוֹת בּוֹ.</p>\n<p>מִשּׁוּם כָּךְ, יַעֲקֹב בְּאוֹתוֹ הַזְּמַן, כָּתוּב וַיַּחֲלֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה (וראשו). מַה זֶּה סֻלָּם? הַדַּרְגָּה שֶׁשְּׁאָר הַדְּרָגוֹת תְּלוּיוֹת בָּהּ, וְהוּא יְסוֹד הָעוֹלָם. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה, כָּךְ הוּא לְהִתְקַשֵּׁר עִמּוֹ. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה, מִי רֹאשׁוֹ? רֹאשׁוֹ שֶׁל אוֹתוֹ סֻלָּם. וּמִי הוּא? זֶה שֶׁכָּתוּב בּוֹ (בראשית מז) רֹאשׁ הַמִּטָּה. מִשּׁוּם שֶׁהוּא רֹאשׁ לַמִּטָּה הַזּוֹ וּמִמֶּנָּה מֵאִיר. מַגִּיעַ הַשָּׁמָיְמָה, מִשּׁוּם שֶׁהוּא סִיּוּם הַגּוּף, וְעוֹמֵד בֵּין עֶלְיוֹן וְתַחְתּוֹן, כְּמוֹ שֶׁהַבְּרִית הוּא סִיּוּם הַגּוּף וְעוֹמֵד בֵּין הַיְרֵכַיִם וְהַגּוּף, וְעַל זֶה מַגִּיעַ הַשָּׁמָיְמָה.</p>\n<p>וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ, אֵלּוּ הַמְמֻנִּים שֶׁל כָּל הָעַמִּים, שֶׁהֵם עוֹלִים וְיוֹרְדִים בַּסֻּלָּם הַזֶּה. כְּשֶׁיִּשְׂרָאֵל חוֹטְאִים, נִשְׁפָּל הַסֻּלָּם הַזֶּה, וְעוֹלִים אוֹתָם הַמְמֻנִּים. וּכְשֶׁיִּשְׂרָאֵל מַכְשִׁירִים אֶת מַעֲשֵׂיהֶם, מִתְעַלֶּה הַסֻּלָּם הַזֶּה, וְכָל הַמְמֻנִּים יוֹרְדִים לְמַטָּה וְעוֹבֵר שִׁלְטוֹנָם. הַכֹּל עוֹמֵד בַּסֻּלָּם הַזֶּה. כָּאן רָאָה יַעֲקֹב בַּחֲלוֹמוֹ אֶת שִׁלְטוֹנוֹ שֶׁל עֵשָׂו וְאֶת שִׁלְטוֹן שְׁאָר הָעַמִּים.</p>\n<p>דָּבָר אַחֵר וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ, בְּמִי? בְּאוֹתוֹ רֹאשׁוֹ שֶׁל אוֹתוֹ סֻלָּם. שֶׁכְּשֶׁמִּסְתַּלֵּק רֹאשׁוֹ מִמֶּנּוּ - הַסֻּלָּם נִכְנָע, וְעוֹלִים כָּל הַמְמֻנִּים. וּכְשֶׁמִּתְחַבֵּר רֹאשׁוֹ בְּאוֹתוֹ סֻלָּם - מִתְעַלֶּה, וְכָל הַמְמֻנִּים יוֹרְדִים. וְהַכֹּל דָּבָר אֶחָד.</p>\n<p>כָּתוּב (מלכים א ג) נִרְאָה ה' אֶל שְׁלֹמֹה בַּחֲלוֹם הַלָּיְלָה וַיֹּאמֶר אֱלֹהִים שְׁאַל מָה אֶתֶּן לָךְ. וְאִם תֹּאמַר, כָּאן בַּחֲלוֹם, וְכִי אֵיזוֹ רְשׁוּת יֵשׁ לַחֲלוֹם בָּזֶה? אֶלָּא כָּאן נִכְלֶלֶת דַּרְגָּה בְּדַרְגָּה, הַדַּרְגָּה הָעֶלְיוֹנָה עִם הַדַּרְגָּה הַתַּחְתּוֹנָה. מִשּׁוּם שֶׁעַד עַכְשָׁו שְׁלֹמֹה לֹא הָיָה שָׁלֵם. כֵּיוָן שֶׁנִּשְׁלַם, כָּתוּב (שם ה) וַה' נָתַן חָכְמָה לִשְׁלֹמֹה, וְכָתוּב (שם) וַתֵּרֶב חָכְמַת שְׁלֹמֹה. שֶׁעָמְדָה הַלְּבָנָה בִּשְׁלֵמוּתָהּ, וּבֵית הַמִּקְדָּשׁ נִבְנָה, וְאָז הָיָה רוֹאֶה שְׁלֹמֹה אֶת הַחָכְמָה עַיִן בְּעַיִן, וְלֹא הִצְטָרֵךְ לַחֲלוֹם.</p>\n<p>אַחַר שֶׁחָטָא, הִצְטָרֵךְ לַחֲלוֹם כְּבָרִאשׁוֹנָה, וְעַל כֵּן כָּתוּב (שם יא) הַנִּרְאָה אֵלָיו פַּעֲמָיִם. וְכִי פַּעֲמַיִם הָיָה וְלֹא יוֹתֵר? אֶלָּא צַד הַחֲלוֹם הָיָה לוֹ פַּעֲמַיִם, וְצַד הַחָכְמָה הָיָה בְּכָל יוֹם.</p>\n<p>וְעִם כָּל זֶה הַצַּד שֶׁל הַחֲלוֹם הָיָה יוֹתֵר עַל כָּל שְׁאָר בְּנֵי הָאָדָם, מִשּׁוּם שֶׁנִּכְלְלָה דַּרְגָּה עִם דַּרְגָּה, מַרְאֶ\"ה בְּמַרְאֶ\"ה. וְהִנֵּה כָּאן בְּסוֹף יָמָיו יוֹתֵר חָשׁוּךְ, וְזֶה מִשּׁוּם שֶׁחָטָא, וְהַלְּבָנָה עָמְדָה לְהִפָּגֵם. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא שָׁמַר אֶת בְּרִית הַקֹּדֶשׁ בְּהִתְעַסְּקוּתוֹ עִם נָשִׁים נָכְרִיּוֹת, וְזֶה הַתְּנַאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה עִם דָּוִד, שֶׁכָּתוּב (תהלים קלב) אִם יִשְׁמְרוּ בָנֶיךְ בְּרִיתִי וְגוֹ', גַּם בְּנֵיהֶם עֲדֵי עַד יֵשְׁבוּ לְכִסֵּא לָךְ.</p>\n<p>מַה זֶּה עֲדֵי עַד? הַיְנוּ שֶׁכָּתוּב (דברים יא) כִּימֵי הַשָּׁמַיִם עַל הָאָרֶץ. וּמִשּׁוּם שֶׁשְּׁלֹמֹה לֹא שָׁמַר אֶת הַבְּרִית הַזּוֹ כָּרָאוּי, הִתְחִילָה הַלְּבָנָה לְהִפָּגֵם, וְעַל כֵּן בַּסּוֹף הִצְטָרֵךְ אֶת הַחֲלוֹם, וְכֵן יַעֲקֹב הִצְטָרֵךְ אֶת הַחֲלוֹם, כְּמוֹ שֶׁבִּאַרְנוּ. רַעְיָא מְהֵימְנָא</p>"]]});
